window.HARDTRP.receive("142532",[[142583,"2026-08-06T16:28:41",9,"Начало темы.\n\nHard Master — Дм этой темы.",142532,null],[142626,"2026-08-06T16:39:44",9,"\"Общее о игре\"\n\n🎮Игроки, начальный состав: @PaIIasCat @QURTZZ @dunchev @cirson \n\n🕰Время: Ориэнтируемся на 9.00 до 17.00 по мск. Постараюсь вести активно в это время когда не занят, в остальное по ситуации.\n\n🗣Флуд: не оч люблю его, го если не по делу начнем усиленно что-то обсуждать в основу во флуд или обсуждение квестов.\n\n📚Опыт: после продолжительного выдаётся опыт.\n\nМожет дополнится.\n\nPs: Пока что всё приятной нам игры! 🥳🎉",142583,null],[142632,"2026-08-06T16:41:19",9,"Запас",142532,null],[142633,"2026-08-06T16:41:22",9,"Запас",142532,null],[142634,"2026-08-06T16:41:29",9,"ХХХХХХХХХХХХХХХХХХХХХХХХХХ",142532,null],[142692,"2026-08-06T16:55:46",9,"*Рабы? Преступники? Казнь? Вы не знаете о своей судьбе, лишь то что вас не собираются убивать. Привезённые на границу, к заставе.*",142532,null],[142700,"2026-08-06T16:58:25",31,"Скайримом пахнет/",142532,null],[142702,"2026-08-06T16:58:43",20,"/и готикой",142532,null],[142705,"2026-08-06T16:59:28",27,"//И надеюсь не смутой",142532,null],[142741,"2026-08-06T17:05:38",9,"*В темницах заставы было пусто, мокро. Старая кладка говорила о древности этого места, может это уцелевшая часть замка?*\n\n*Снаружи пробивается свет, слышны голоса людей, там идёт жизнь, жизнь свободных но не ваша.*\n\n*Четверых пленников в одних обносках привезли несколько часов назад и кинули в темницу. Больше здесь небыло никого.*\n\n*Пленники могли бы протянуть руки сквозь старые, тяжёлые и всё ещё надёжные прутья в коридор. Примерно раз в час на них приходил посмотреть стражник, он ушёл совсем недавно.*\n\n*Смотря сквозь решётку пленники смогли бы рассмотреть товарищей по несчастью, в тусклом свете темницы. Но не все, на одном был плотный кожанный колпак закрывающий глаза, почему? Не известно.*",142532,null],[142748,"2026-08-06T17:07:24",9,"// @PaIIasCat @QURTZZ @dunchev @cirson по сути начали, вы в темнице а на \"Сайне\", персонаже Михи кожанный колпак который не снять. Можете повзаемодействовать друг с другом и все такое, вы сейчас одни в старой темнице.",142532,null],[142760,"2026-08-06T17:09:10",9,"*Преступников кормили скудно, никто не видел и крошки со вчерашнего дня. Лишь сегодня когда доставили в камеры дали напиться воды перед тем как оставить.*",142741,null],[142802,"2026-08-06T17:18:48",47,"/там ещё и кляп... Ебааа",142532,null],[142806,"2026-08-06T17:19:50",9,"//Не, рот и нос открыты, а так ты в одиночку не снимешь. Как помню в туманном надо \"видеть\" точку перемещения",142532,null],[142812,"2026-08-06T17:20:15",9,"//Каждый в своей отдельной камере, да",142532,null],[142832,"2026-08-06T17:24:45",17,"Тощий но жилистый мужчина методично бьёт кулаком о стену. Это не ярость. Это тренировка воли. Способ успокоиться.\n\nОн молчит и пытается не морщиться от боли когда костяшки ударяются о камень.",142741,null],[142848,"2026-08-06T17:26:03",31,"Жилистый парень, в обносках которого кто очень внимательный может опознать монашеское одеяние безучастно сидит и обдумывает, ка кон вообще дошёл до дизни такой и оказался в темнице",142532,null],[142851,"2026-08-06T17:26:34",17,"/ Жилистые одни)))",142532,null],[142852,"2026-08-06T17:26:49",31,"Жизнь такая/",142851,null],[142853,"2026-08-06T17:26:59",17,"Люпен",142532,null],[142859,"2026-08-06T17:27:30",31,"Мне лень делать картинку в темнице/",142532,null],[142864,"2026-08-06T17:29:43",17,"Закончив ритуал Люпен подошел к решетке разглядывает товарищей по несчастью напротив.\n\nКогда стражник отходит он хриплым голосом произносит\n\n— Есть там кто живой?",142532,null],[142877,"2026-08-06T17:31:41",31,"Конрад услышал вопрос, и сбросил оцепенение. Точно, он же не один тут. Нужно подать голос\n\n- есть, если это можно назвать жизнью",142532,null],[142909,"2026-08-06T17:36:06",17,"— Придётся выкручиваться. Я Люпен. Но лучше зови меня Крыса. Эта кличка мне больше подходит. \n\nОборачиваясь Люпен внимательно считывает всё что  есть в доступе в своей камере.",142532,null],[142916,"2026-08-06T17:36:41",17,"/r +2 Выживание",142532,null],[142920,"2026-08-06T17:37:00",31,"- я Конрад, приятно познакомится, Крыса",142532,null],[142922,"2026-08-06T17:38:03",20,"*Из одной камеры доносится шорох, за которым следует слабый  детский голос*\n\n- Х-хей...Меня...меня слышно?",142532,null],[142927,"2026-08-06T17:39:14",17,"— Угу. Что у тебя там есть? Осмотрись, может завалялся какой нибудь гвоздь\n\nОтветил он Конраду и сразу услышал еще голосок\n\n— Да, еще один смертник. Ты тоже там пошарь у себя... Не время сопли жевать.",142532,null],[142934,"2026-08-06T17:40:29",17,"Осматриваясь он лазил по полу на корточках, вглядываясь в каждый дюйм своей камеры.",142532,null],[142948,"2026-08-06T17:41:57",31,"/roll d20 выживание, выискиваю хоть что то, чтобы исправить свое положение",142532,null],[142957,"2026-08-06T17:42:54",17,"— Малой, тебе сколько лет? Больно уж голосок тонкий у тебя. И как звать?",142532,null],[142968,"2026-08-06T17:44:22",9,"*Несколько щепок из старой деревянной кровати, солома и грязная простынь, надколотая миска. Возможно из стены можно вытащить расшатавшийся кирпич, хозяева темницы постарались чтобы не давать пленникам и шанса.*",142918,null],[142980,"2026-08-06T17:46:01",17,"Посмотрев на скудный улов Люпен тут же принялся мастерить сумку из простыни\n\nЩепки взял чтобы попробовать поковырять ими в замке, авось, что и получится.\n\nКирпич пока подождет.",142968,null],[142981,"2026-08-06T17:46:15",17,"/ Могу записать небольшую сумку через плечо?",142532,null],[142982,"2026-08-06T17:46:31",9,"*У Конрада в камере в углу есть нора помимо того же что в камере Люпена.*",142949,null],[142987,"2026-08-06T17:47:03",20,"- М-мне тринадцать м-мистер Крыса... *все так же слаьо отвечает голос под шорох из камеры. Похоже ребенок тоже осматривается*",142957,null],[142988,"2026-08-06T17:47:03",9,"//Из простыни запиши если хочешь",142981,null],[142992,"2026-08-06T17:47:48",9,"//Ну, проверку мож кинуть, ловкость рук, сложность крит)",142980,null],[142994,"2026-08-06T17:48:06",17,"— Давай без мистера, пока будешь меня звать на выручку сдохнешь пока мистера выговариваешь, будь проще парень. И не вешай нос. Порыскай у себя там, мне нужно что нибудь получше щепок...",142987,null],[142998,"2026-08-06T17:48:47",20,"/r d20+2 на внимание",142532,null],[143000,"2026-08-06T17:48:59",17,"Люпен подошел к замку камеры, присел и сунул в него две щепки, он понимал как взламывать замки отмычками, но щепками пробовал впервые.",142532,null],[143001,"2026-08-06T17:49:05",17,"/r +4 Ловкость рук",142532,null],[143004,"2026-08-06T17:49:13",17,"/ Жаль",142532,null],[143006,"2026-08-06T17:49:22",31,"- у меня тут какая то нора в камере",142532,null],[143008,"2026-08-06T17:49:38",17,"— Если можешь поймай крысу, мясо лишним не бывает.",142532,null],[143014,"2026-08-06T17:50:18",17,"Щепки сломались, замок остался заперт\n\n— Черт...",142532,null],[143019,"2026-08-06T17:50:54",31,"- ты там пытаешься щепкой дверь открыть?",142532,null],[143022,"2026-08-06T17:51:20",17,"— Пытался, не получилось, мне бы гвоздь, а лучше два",142532,null],[143023,"2026-08-06T17:51:20",31,"Я тут тоже парочку нашел, но кажется, это бессмысленно",142532,null],[143024,"2026-08-06T17:51:41",17,"— Попробуй кинь их мне. Я всё же попытаюсь",142532,null],[143028,"2026-08-06T17:52:19",31,"/roll d20+2 ловкость рук, бросая Крысе свои щепки",142532,null],[143030,"2026-08-06T17:52:33",17,"/r +4 Ловлю",142532,null],[143036,"2026-08-06T17:53:35",9,"*Всё подчистую то же самое, лишь кажется один из прутьев у выхода шатается.*",142999,null],[143039,"2026-08-06T17:54:22",20,"/могу проверить, смогу ли я протиснуться туда учитывая что я пипец щуплый?",143036,null],[143042,"2026-08-06T17:55:10",31,"А я хочу сунуть руку в нору и поискать что там ечть. Или кто",142532,null],[143043,"2026-08-06T17:55:16",9,"//Ну, зачем бросок на такую мелочь хз, вы не так далеко через коридор перекинуть что-то бнз проблем",143031,null],[143045,"2026-08-06T17:56:02",31,"Будем считать что передали)/",142532,null],[143046,"2026-08-06T17:56:31",17,"/ Значит это был бросок чтобы вскрыть ещё раз)",143043,null],[143047,"2026-08-06T17:56:40",9,"*Решётки всё равно слишком узкие для тебя, хотя если старшие едва протиснут руку то Рен может протиснуть и плечо.*",143039,null],[143048,"2026-08-06T17:56:58",31,"Башка не пускает, головастый пацан/",143047,null],[143049,"2026-08-06T17:57:11",9,"*Замок забился стружкой, руками не достать.*",143046,null],[143051,"2026-08-06T17:57:40",17,"Снова попытка вскрыть щепками, снова неудача, заноза в пальце. \n\n— Отлично, кажется я забил замок. Когда придут меня запирать знайте, они будут возится с ним дольше обычного. Вдруг вам это как то поможет...",142532,null],[143052,"2026-08-06T17:57:41",9,"//Туловище и голова не пролезет, да",143048,null],[143054,"2026-08-06T17:57:47",20,"/расшатать потихоньку ещё не получится?",143047,null],[143057,"2026-08-06T17:58:09",31,"Моя завка еще есть, на засовывание руки в нору/",142532,null],[143058,"2026-08-06T17:58:11",9,"//Пробуйте, чё",142532,null],[143060,"2026-08-06T17:58:36",9,"/roll 1d4 исхода в норе",142532,null],[143067,"2026-08-06T17:59:28",17,"Люпен отошёл к решеткам у оконного проема и посмотрел наружу. Что же там?",142532,null],[143073,"2026-08-06T18:00:06",9,"*Рука пролазит в нору легко, почти по локоть, пальцы нащупывпют что-то мягкое, раздается писк.*",143057,null],[143074,"2026-08-06T18:00:17",9,"/roll 1d20+2 кусь",142532,null],[143078,"2026-08-06T18:00:29",9,"/roll 1d4 урон",142532,null],[143080,"2026-08-06T18:00:30",31,"Руку отхуярила(/",142532,null],[143085,"2026-08-06T18:00:56",9,"*Крыса намертво вцепилась в руку.*",142532,null],[143087,"2026-08-06T18:01:35",31,"С криком вырываю руку из норы, на руке висит крыса, бью крысой о стену",142532,null],[143090,"2026-08-06T18:01:53",20,"/обед подъехал",142532,null],[143092,"2026-08-06T18:02:03",31,"Крыса так и подумала/",143090,null],[143093,"2026-08-06T18:02:05",9,"*Люпен видит заставу, становится пасмурно, кажеься дождь совирается. А так на аванпосте много стражи.*",142692,null],[143095,"2026-08-06T18:02:19",9,"//Го",143087,null],[143098,"2026-08-06T18:02:36",31,"Урон кидать?/",143095,null],[143099,"2026-08-06T18:02:38",17,"— Не упусти!",142532,null],[143108,"2026-08-06T18:03:18",9,"//Попади сначала, или оторви ее и кинь о стену нанеся 1д6 от падения, бросок на атаку все равно надо",143098,null],[143110,"2026-08-06T18:04:12",31,"/roll d20+3 на атаку (3 от ловкости, правильно же?)",142532,null],[143112,"2026-08-06T18:04:32",9,"//Описывай как крысу прибил",142532,null],[143113,"2026-08-06T18:04:33",31,"/roll d6 крыса шмякается о пол",142532,null],[143115,"2026-08-06T18:04:48",31,"- урысинное пюре готово",142532,null],[143118,"2026-08-06T18:05:06",31,"- пища богов, мать ее",142532,null],[143121,"2026-08-06T18:05:39",17,"— Лучше чем ничего...\n\nЛюпен дёргает решетки на огне проверяя на прочность",142532,null],[143123,"2026-08-06T18:05:48",31,"Рвы крысу на части передаю пацану и Крысе (каннибал, блин)",142532,null],[143124,"2026-08-06T18:05:50",9,"//Опыт и прочее буду давать после продолжительных отдыхов",142532,null],[143127,"2026-08-06T18:06:12",9,"*Решётки у Люпена крепкие.*",143121,null],[143128,"2026-08-06T18:06:50",31,"Окно только у Люпена?/",142532,null],[143129,"2026-08-06T18:06:53",20,"- ...спасибо... *мальчик ловит кусок плоти, аккуратно откладывая его и продолжает пытаться раскачать решетку*",143123,null],[143130,"2026-08-06T18:07:03",20,"/r d20 -1",142532,null],[143133,"2026-08-06T18:07:23",20,"/ну ожидаемо, хоть не крит 1",142532,null],[143137,"2026-08-06T18:07:48",31,"/roll d20 на атлетику, тоже решил проверить крепость решетки",142532,null],[143139,"2026-08-06T18:07:54",9,"//Это моё проклятье, ждите много выпадений \"2\"",142532,null],[143141,"2026-08-06T18:08:32",17,"Люпен смотрит на сумку простынь и вспоминает одну хитрость. Если намочить простынь и обернуть между двух прутьев решетки и скручивать это может чуть погнуть их... \n\n/ мастер делаем?",142532,null],[143144,"2026-08-06T18:08:37",9,"*Не дается, слегка двигаются прутья у стен, но похоже они уходят глубоко.*",143138,null],[143149,"2026-08-06T18:09:05",9,"//Делай я опишу результат",143141,null],[143154,"2026-08-06T18:09:44",20,"/а на самих стенах есть что-то до чего смогу дотянуться, если вытянуться по плечо?",143144,null],[143169,"2026-08-06T18:11:24",9,"*Лишь один потушенный факел на стене, дотянутся к нему не сможет никто из вас. Рядом с твоей решеткой есть старый держатель факела, но он пустой, с чего бы.*",143154,null],[143173,"2026-08-06T18:11:59",17,"Он решается попытаться. Любой ценой нужно выжить.\n\nКидает простынь на пол в углу и мочится на нее. \n\nПоднимает и идёт к длинным прутьям у входа в камеру. Чем длиннее прут тем проще его гнуть.\n\nОборачивает два рядом стоящих прутка мокрой протынью и закручивает, продолжает крутить\n\nСначало идёт легко\n\nНо становится все тяжелее и тяжелее \n\nЛюпен прилагает все свои силы стискивая зубы",142532,null],[143174,"2026-08-06T18:12:03",9,"//Попробуй в след раз как перс смотреть",143154,null],[143183,"2026-08-06T18:13:37",9,"*Прутья слишком толстые, прогнулись едва едва. Одной тряпкой и голыми руками их согнуть дело неблагодерное.*",143173,null],[143184,"2026-08-06T18:13:52",17,"Да, нужна палка",142532,null],[143191,"2026-08-06T18:14:14",31,"Или факел/",142532,null],[143194,"2026-08-06T18:14:24",17,"Идёт к койке. Будет пытаться отломать ножку",142532,null],[143195,"2026-08-06T18:14:48",31,"/roll d20 на внимательность, оцениваю коридор, кчть ли что до чего я могу дотянуться?",142532,null],[143200,"2026-08-06T18:15:13",9,"*Рен отлично помнит как часто ходит мимо стражник. Кажется он скоро прийдёт вас проверять.*\n\n// @PaIIasCat",142532,null],[143201,"2026-08-06T18:15:33",20,"/ура, наконец-то социалка",143200,null],[143203,"2026-08-06T18:15:51",17,"— Конрад, мне нужна палка. Помоги",142532,null],[143204,"2026-08-06T18:15:55",9,"*Ты без труда отламываешь самую крепкую из них, но древесина старая и протрухшая.*",143194,null],[143207,"2026-08-06T18:16:23",31,"- а может, нам не пытаться сломать решетки? Проще охранника прижать, когда мимо пойдет. Сделать удавку из простыни, поймать, удавить и вытащить ключ",142532,null],[143209,"2026-08-06T18:16:38",20,"- Х-хей...Скоро придет стража, думаю стоит пока не шуметь, чтобы подозрение не вызвать... *Рен задумывается*\n\n/Ещё сколько минут точно?",142532,null],[143210,"2026-08-06T18:16:42",31,"- правда, это план сработает только если повезет поймать мужика",142532,null],[143212,"2026-08-06T18:17:01",9,"*Нет такого, единственный факел далеко.*",143196,null],[143213,"2026-08-06T18:17:02",17,"Закручиваю палку в мокрую простынь и кручу что есть сил. Ускоряя движения из за предупреждения паренька",142532,null],[143216,"2026-08-06T18:17:24",9,"/roll 1d20-4 крепкость палки",142532,null],[143218,"2026-08-06T18:17:36",31,"Конрад рвет простыню и делает импровизированную веревку-удавку",142532,null],[143229,"2026-08-06T18:18:36",9,"*Похоже эту ножку делали на славу, со скрипом и треском, решётки кое как гнутся. *",143213,null],[143230,"2026-08-06T18:19:02",9,"*Слышутся шаги по ступеням в темницу.*",142532,null],[143236,"2026-08-06T18:19:52",17,"— Есть!\n\nСлышит шаги \n\n— Черт... Чтоб вас....\n\nЛюпен отходит к стене понимая, что времени протискиваться нет",142532,null],[143239,"2026-08-06T18:19:58",9,"*Страж, мужик лет 30-35, уставший идет по центру коридора.*\n\n//Как то подготовдиваетесь к его приходу?",142532,null],[143249,"2026-08-06T18:20:29",17,"Люпен садится подальше от входа и прячет палку около себя. Так же прячет мокрую простынь",142532,null],[143252,"2026-08-06T18:20:56",31,"Чтоб возле прутьев, руки за спиной, в них веревка-удавка",142532,null],[143254,"2026-08-06T18:21:06",20,"*Рен делает максимально жалкий вид, начиная трестись и всхлипывает, прижавшись к решетке.*",142532,null],[143256,"2026-08-06T18:21:15",20,"*И ждёт*",142532,null],[143258,"2026-08-06T18:21:24",31,"Могу обратится к стражнику?/",142532,null],[143264,"2026-08-06T18:22:06",9,"/roll 1d20+2 внимательность стражника, заметит ли погнутые решётки",142532,null],[143269,"2026-08-06T18:22:36",31,"- эй ты, смерд! Подойди как сюда! По какому праву вы держите взаперти барона Фон Шатенхауса?",142532,null],[143270,"2026-08-06T18:22:40",9,"*Лишь вскользь взглянул на Люпена, на месте ли тот, топает дальше.*",143265,null],[143272,"2026-08-06T18:22:49",31,"Стараюсь оовьттт командным голосом аристократа/",142532,null],[143282,"2026-08-06T18:25:25",9,"*Застыл перед твоей камерой в коридоре, близко не подходит. По его лицу можно с уверенность сказать что он повидал дерьма, человек которому катигорически похуй.*\n\nТюремный страж — Берегите силы милорд, вам завтра в путь. Карету уже пригнали.",143269,null],[143287,"2026-08-06T18:26:13",9,"*Старается быть вежливым, но не очень старается.*",143282,null],[143295,"2026-08-06T18:26:59",20,"- С-сэр...п-пожалуйста ...*из камеры рядом раздается детский жалкий всхлип*\n\n/Одновременно с этим с помощью обнаружения мыслей читаю поверхностные мысли стражника - поверхстное чтение незаметно для жертвы",142532,null],[143296,"2026-08-06T18:27:09",31,"Высокомерно:\n\n- это не ответ на мой вопрос",142532,null],[143304,"2026-08-06T18:28:04",9,"Тюремный страж — Спросите тюремщика милорд, я ничего не решаю.",143296,null],[143308,"2026-08-06T18:28:26",31,"- будь добр, позови его",143304,null],[143316,"2026-08-06T18:29:45",9,"Тюремный страж — Займусь как закончу обход.",143308,null],[143318,"2026-08-06T18:29:52",47,"- Прошу прощения, а я слышал что у смертников есть последнее желание, это правда? - раздаётся хриплый голос из угла",142532,null],[143327,"2026-08-06T18:32:02",9,"*Хочет выпить после смены, думает о детях и жене, а ещё когда взглянул на Рена было смятениеи сочувствие, он не понимал почему здесь ребёнок. Хочет поскорее просто закончить обход и дальше отдыхать до конца смены, какой-то долг Водисею, на вопросы других ему самую малость плевать.*\n\nТюремный страж — Всё хотел спросить пацан, как попал сюда?",143295,null],[143332,"2026-08-06T18:33:27",9,"Тюремный страж — Смертников вешают без разговоров у стен. Вы не смертники, вас завтра ждёт повозка.",143318,null],[143336,"2026-08-06T18:33:51",47,"Ладно, раз на Сайна не обращали внимания он аккуратно шарит по полу тюремного помещения и ищет что-то достаточно плотное, чтобы могло резать",142532,null],[143339,"2026-08-06T18:34:47",9,"//Ловкость рук с помехой, на ощупь ищешь",143336,null],[143340,"2026-08-06T18:34:54",20,"- Я...я просто был слугой...я ничего не делал, правда... Но им было все равно, они схватили того, кто был ближе... *тихий всхлип*\n\n- А нас… нас казнят?Я клянусь, я просто стоял рядом, правда! Я не хочу умирать…\n\n*Он поднимает глаза на стражника*\n\n-...тут очень темно... сэр, я знаю что вы не в силах помочь...но могли бы вы хотя бы...оставить факел? Всего один, рядом...",143327,null],[143342,"2026-08-06T18:35:12",47,"Сайн промолчал. Он то знал, что за то, что он своровал ту книжку у жреца его ждёт только казнь. Но если он сбежит... Он обязательно найдёт способ её толкнуть",142532,null],[143344,"2026-08-06T18:35:28",47,"/r -d20+4",143339,null],[143346,"2026-08-06T18:35:34",47,"Юзаю везунчика",142532,null],[143347,"2026-08-06T18:35:38",47,"/r d20+4",142532,null],[143349,"2026-08-06T18:35:45",47,"23 итоговая",142532,null],[143369,"2026-08-06T18:38:41",9,"*Находишь всё то же что и у других, на маске что у тебя один из тоненьких железных прутков с затылка плохо закрутили, шатается.*",143349,null],[143374,"2026-08-06T18:39:13",47,"/я его таким результатом расшатал и вытащил?",143369,null],[143376,"2026-08-06T18:39:42",47,"/выше только Крит тип",142532,null],[143381,"2026-08-06T18:40:06",9,"*Достать его займёт некоторое время.*\n\n//20 минут минимум потратить, все же старались",143374,null],[143385,"2026-08-06T18:40:26",47,"Трачу. Времени у меня много в принципе",142532,null],[143400,"2026-08-06T18:43:03",47,"От других заявок нет?",142532,null],[143402,"2026-08-06T18:43:21",47,"Если нет, предлагаю пождать пока он уйдёт и попиздеть",142532,null],[143403,"2026-08-06T18:43:33",47,"@PaIIasCat @QURTZZ @dunchev",142532,null],[143404,"2026-08-06T18:43:40",9,"Тюремный страж — Факел не могу, заключенные его постоянно пытаются постоянно взять. — *Видно сомнение в его глазах мысли о семье и смысле жизни.* — У меня сын такой как ты, пару годиков и скоро догонит тебя.\n\n*Думает как-то помочь немного, нг в то же время скован свои положением.*",143340,null],[143409,"2026-08-06T18:45:05",47,"- Честно говоря мне тоже страшно... Причём страшнее чем ему. Я чувствую только запах гавна, гнили и сырости... И холодный пол... - намекает на маску",142532,null],[143421,"2026-08-06T18:46:29",9,"Тюремный страж — Мне сказали не снимать с тебя маску парень, а то сбежишь фейским колдунством.",143409,null],[143430,"2026-08-06T18:47:01",47,"- Что бля? - максимально играю ахуй. К слову реально в ахуе",142532,null],[143432,"2026-08-06T18:47:51",31,"Прислушиваюсь, колдовство значит?",142532,null],[143441,"2026-08-06T18:48:15",17,"/ У меня щас времени не очень много. Активная игра с 9 до 17",142532,null],[143442,"2026-08-06T18:48:17",20,"- Повезло вашему сыну...*тихо говорит мальчик, опуская глаза в пол*\n\n- наверное будь у меня отец он бы меня тоже в обиду не давал...\n\n*Он немного молчит, прежде чем снова спросить*\n\n- А так повозка...куда она нас увезет? *В его голосе звучит страх неизвестности*\n- ...нас убью...продадут...?",143404,null],[143443,"2026-08-06T18:48:33",47,"/я 137 сообщений пропустил кажется",143441,null],[143445,"2026-08-06T18:48:45",17,"/ Это да. Наверстываем",142532,null],[143446,"2026-08-06T18:48:54",9,"Тюремный страж — Да милорд, феи исчезают и появляются в других местах. У меня так племяшь умеет, со спрайтом подружился.",143432,null],[143447,"2026-08-06T18:48:58",47,"/обещаю, как только начнём продумывать план, тормозим и ждём тебя",143441,null],[143448,"2026-08-06T18:49:14",17,"/ Я щас включусь",142532,null],[143453,"2026-08-06T18:49:37",47,"- Я ни с кем не дружил! Я хрен знает откуда та пыльца оказалась у меня! - вспомнил тётку у которой спиздил фейскую пыльцу а потом продал её",142532,null],[143455,"2026-08-06T18:49:39",9,"Тюремный страж — В Внспираль скорей всего, а судьба мне ваша дальше неизвестна.",143442,null],[143456,"2026-08-06T18:49:52",47,"Сайн побледнел",142532,null],[143458,"2026-08-06T18:50:07",9,"//У него знакомый затронут феями",143446,null],[143459,"2026-08-06T18:50:25",47,"/так и понял",142532,null],[143464,"2026-08-06T18:51:17",9,"*Уже не слушает оправдания, не интересно ему.*",143453,null],[143472,"2026-08-06T18:52:57",47,"- Эу, чего молчите. Мне страшно! - чуть ли не плачет Сайн",142532,null],[143473,"2026-08-06T18:53:04",17,"/ можно щас страда не отводить от пацана. Пишу заявку",142532,null],[143475,"2026-08-06T18:53:42",9,"//Го",143473,null],[143476,"2026-08-06T18:53:57",17,"/ Страж к моей камере сейчас спиной?",142532,null],[143479,"2026-08-06T18:54:19",20,"- Веспииаль...? *Мальчик не понимающе наклоняет голову*\n\n- А г-где это?\n\n/Ладно, чёт забалтывать плохо получается - сорян",143455,null],[143480,"2026-08-06T18:54:35",17,"/ Давай давай не сдавайся я ща поползу за спину ему",142532,null],[143481,"2026-08-06T18:55:27",9,"//Твоя камера напротив камеры конрада, чуть дальше камера Рена а напротив рена сбоку от тебя Сайн которого не видишь",143476,null],[143482,"2026-08-06T18:55:40",9,"//Зади стража Сайн",142532,null],[143483,"2026-08-06T18:55:41",20,"/как будто план сбежать по пути из кареты пока надёжней звучит🤔",142532,null],[143486,"2026-08-06T18:56:08",17,"Люпен техонько встал и мягкой поступью подошёл к решетке которую удалось погнуть \n\nВыглядывает из за угла и оценивает как хорошо стражник сейчас мог бы видит его боковым зрением если бы он полез через решетку",142532,null],[143487,"2026-08-06T18:56:18",17,"/r -1 Анализ",142532,null],[143491,"2026-08-06T18:57:18",17,"\"Нет... Слишком рискованно...\"\n\nЛюпен отходит назад и садится",142532,null],[143492,"2026-08-06T18:57:52",9,"Тюремный страж — Я бы не хотел туда попасть. — *Качает головой.* — Это стодица беззакония и мёртвых.\n\n*Уверен что не пугает а скорей даёт подготовиться пацану к реальности.*\n\n//Я вродь описываю его мысли из за обнаружения, правильно же?",143479,null],[143493,"2026-08-06T18:58:13",9,"//Ты не пролезешь, щас нарисую",143491,null],[143495,"2026-08-06T18:58:38",17,"/ Хорошо",142532,null],[143497,"2026-08-06T19:00:01",9,"//Соседние согнёшь чтобы с обеих сторон, тогда хватит пролезть",143496,null],[143498,"2026-08-06T19:01:05",9,"//Щас пацан чет ответит и я стража уношу наверное, по ситуацит",142532,null],[143502,"2026-08-06T19:02:09",17,"/ да, понял. Так и хотел",142532,null],[143503,"2026-08-06T19:12:16",20,"*Малчик кивает головой*\n\n-...понятно... *Понурым голосом отвечает он* \n\n*Понимая что вряд сможет ещё чего-то добиться он решает пока отступить. Нужно придумать что-то получше*\n\n- Спасибо, сэр. Я постараюсь выжить... *Последний раз всхлипывает он, утирая слезы в попытке взять себя в руки*",143492,null],[143504,"2026-08-06T19:13:04",9,"Тюремный страж — Слушай пацан, я бы помог и может забрал тебя, но ничего не решаю, прости. — *Он уходит с мыслью что о пареньке мелком спросит, жалко мужику тебя, дети у самого.*",143503,null],[143505,"2026-08-06T19:15:21",20,"/бедный мужик(",143504,null],[143506,"2026-08-06T19:17:12",20,"*Рен тут же перестает всхлипывать, затихая в своей камере и обдумывая все, что успел услышать в слух и в мыслях*\n\n/Пока действует обнаружение мыслей в 60 ф поищу ещё существ, у которых можно послушать",142532,null],[143507,"2026-08-06T19:18:05",20,"/если нет, то прислушаюсь поверхностно к мыслям человека в колпаке на глазах - он пока самый странный",142532,null],[143508,"2026-08-06T19:19:04",17,"Люпен думает\n\n\"Скорее бы он уже свалил, ещё есть надежда согнуть решетку рядом и выбраться. В Веспераль я не хочу, что б это ни было\"",142532,null],[143509,"2026-08-06T19:19:35",9,"*Достанет ко всем своим если у решёток они.*",143506,null],[143510,"2026-08-06T19:22:07",20,"/ну извиняюсь тогда - потому что буду щупать ваши мозги за неимением других",142532,null],[143511,"2026-08-06T19:22:25",20,"/познай друга своего так сказать",142532,null],[143512,"2026-08-06T19:23:31",9,"*Снаружи, меж прутьями решётки Рену в его часть темницы падает что то.*",142532,null],[143513,"2026-08-06T19:23:52",9,"*Платок, а в нем что-то завёрнуто.*",143512,null],[143514,"2026-08-06T19:23:58",47,"Сайн падает на землю и бьётся в судорогах (выступление?)",142532,null],[143515,"2026-08-06T19:24:21",47,"/хочу чтобы страж залез ко мне в камеру",142532,null],[143516,"2026-08-06T19:24:36",9,"//Он ушёл,",143514,null],[143517,"2026-08-06T19:24:54",47,"Лады",143516,null],[143518,"2026-08-06T19:25:07",47,"Но я дергаюсь всё ещё так как не знаю этого",142532,null],[143519,"2026-08-06T19:25:38",47,"Как другие реагируют на припадок?",142532,null],[143520,"2026-08-06T19:25:50",31,"- эй, как там тебя, парень с мешком на голове, успокойся, ушёл стражник",143518,null],[143521,"2026-08-06T19:26:04",47,"Пускаю пену изо рта",142532,null],[143522,"2026-08-06T19:27:38",20,"*Рен протягивает руку, осторожно беря свёрток и разворачивая его*",143512,null],[143523,"2026-08-06T19:28:24",20,"*Смотря о чем ты думаешь 👀*",143519,null],[143524,"2026-08-06T19:28:46",47,"/ну тип припадок как у больных людей",143523,null],[143525,"2026-08-06T19:29:06",20,"/не, о чем персонаж думает, изображая это",143524,null],[143526,"2026-08-06T19:29:12",47,"Может сделать его клаустрофобом? Хм",142532,null],[143527,"2026-08-06T19:29:25",47,"Боится",143525,null],[143528,"2026-08-06T19:31:00",9,"*Три пирожка и фляга с водой в платке. Похоже сторожа мучает совесть и он так решил от неё немного откупиться.*",143522,null],[143529,"2026-08-06T19:31:19",47,"/я смог скрутить шуруп к этому моменту?",142532,null],[143530,"2026-08-06T19:31:57",47,"/могу снять маску?",143529,null],[143531,"2026-08-06T19:32:25",9,"*Несколько дюймов тонкой проволоки.*",143529,null],[143532,"2026-08-06T19:33:17",9,"*В маске таких проволочек под сотню, их закручивали щипцами, осьальные закоученны туго.*",143530,null],[143533,"2026-08-06T19:33:28",47,"Сукааа",143532,null],[143534,"2026-08-06T19:33:59",20,"*Рен ломает пирожки на равные части, передавая другим по кусочкам*\n\n- Вот... Ты ведь тоже делился *говорит он Конраду, слабо улыбаясь*\n\n- Вы тоже поеште, мистер Маска, может быть вам станет чуть лучше",143528,null],[143535,"2026-08-06T19:34:15",47,"В таком случае ищу на полу достаточно плотную соломинку",142532,null],[143536,"2026-08-06T19:34:39",47,"Чтобы не порвалась при резком движении",143535,null],[143538,"2026-08-06T19:35:21",9,"*Есть и дряхлая и свежая, ещё щепки от старой кровати.*",143535,null],[143539,"2026-08-06T19:35:23",47,"Не так. Ищу щепку",142532,null],[143540,"2026-08-06T19:35:25",47,"Да",142532,null],[143541,"2026-08-06T19:35:30",47,"Максимально похожую на иголку",142532,null],[143542,"2026-08-06T19:35:48",9,"//Да их полно, нашел",142532,null],[143543,"2026-08-06T19:36:15",47,"Хочу продырявить места с глазамм аккуратно оттягивая кожаную маску",143542,null],[143544,"2026-08-06T19:36:39",31,"/извините, я спать/",142532,null],[143545,"2026-08-06T19:36:46",47,"/эх",143544,null],[143546,"2026-08-06T19:37:00",47,"/ладно я как раз закончу свою, фигню. У меня много ремесленных заявок",142532,null],[143547,"2026-08-06T19:38:02",47,"Он нащупывает еду, кладёт рядом но пока не ест",143534,null],[143548,"2026-08-06T19:39:01",9,"*Маска жёсткая и плотная, дубленая. Это не сыромятные штаны, скорее жёсткий кожак, нужно что-то поострее чтобы его проковырять, или, можно остаться без глаза, если не повезёт.*",142532,null],[143549,"2026-08-06T19:46:54",47,"/блять.я в ахуе. Лучше ноги связали. Нахуй глаза то(",142532,null],[143550,"2026-08-06T19:48:06",9,"//Потому и связали, ты с телепортом",142532,null],[143557,"2026-08-06T20:11:13",17,"/ Обсудите во флуде",142532,null],[143580,"2026-08-06T20:26:50",47,"Hard",142532,null],[143583,"2026-08-06T20:27:21",47,"Я один в камере?",142532,null],[143598,"2026-08-06T20:34:19",47,"Сука(",142532,null],[143606,"2026-08-06T20:36:16",47,"Лады. Делаю при помощи проволоки дырку в щепке, чтобы была для нитки. Сразу после начинаю шлифовать этой же проволокой, не торопясь, аккуратно (но всё ещё с помехой",142532,null],[143608,"2026-08-06T20:36:30",9,"//Вот, говорил",143481,null],[143614,"2026-08-06T20:40:33",20,"*Рен откусывает кусок от пирожка, передовая оставшуующя порцию Люпену*\n\n- Мисте-...то есть, Крыса, ты случайно не знаешь о месте, в которое нас завтра увезут? Веспераль... там действительно так плохо?  *Слегка наивно (наиграно или нет, кто знает), спрашивает мальчик*",142532,null],[143619,"2026-08-06T20:42:03",9,"//Кто где, красным не горящий факел, а зелёным решётки, те что наружу помелче то окошки с решотками, у вас солома, кровати старые из дерева, по простыне + нора крысиная у Конрада, одна клеточка это 5 футоа",142532,null],[143621,"2026-08-06T20:44:56",47,"Сайн спрашивает вслух:\n- Кто рядом со мной?",142532,null],[143622,"2026-08-06T20:46:01",47,"- Мне нужна помощь. Необходимо снять маску. Я очень тяжело себя ощущаю. Дышать тяжело",142532,null],[143624,"2026-08-06T20:49:43",47,"Так, ладно, есть ли у меня наволочка/простыня, подобное?",142532,null],[143625,"2026-08-06T20:50:56",47,"Если могу нахожу. При помощи проволоки нарезаю на аккуратные ровные квадратики, которые позднее использую на карманы",142532,null],[143626,"2026-08-06T20:50:58",20,"- Я бы хотел вам помочь, мистер Маска, но боюсь не смогу дотянуться...",143622,null],[143627,"2026-08-06T20:51:00",47,"/кидаю?",142532,null],[143628,"2026-08-06T20:51:33",47,"Вы слышите треск ткани и видите, что он рвёт свою наволочку. Он сходит с ума видимо...",142532,null],[143629,"2026-08-06T20:53:20",47,"Hard шо кинуть?",142532,null],[143630,"2026-08-06T20:53:30",47,"И на 1 заявку и на потайные карманы?",142532,null],[143631,"2026-08-06T20:58:21",9,"//Я не понимаю что хочет миха, обьясняй)",142532,null],[143632,"2026-08-06T20:59:10",47,"/я хочу порвать наволочку. А затем использовать, чтобы нашить с обратной стороны балахона второй слой и получить потайные карманы в которых можно хранить вскую хуйню",142532,null],[143633,"2026-08-06T21:00:29",47,"Hard",142532,null],[143634,"2026-08-06T21:06:40",17,"— Щас, мужик погоди, попробую как то выбраться и посмотрю что с тобой можно сделать...\n\nКогда стражник покинул помещение...\n\nЛюпен достал из под гонки мокрую наволочку и решительно шагнул к своей решетке. Он перекинул на два соседних прутка эту наволочку и поставил палку. Снова начал крутить \n\n\"Я не поеду никуда, я сбегу\"",143622,null],[143635,"2026-08-06T21:07:37",17,"/ Я тоже сделал себе сумку из наволочки, но потом пришлось ее обоссать",143632,null],[143636,"2026-08-06T21:07:39",9,"//Обноски и так такие себе, да и ты в маске. Наощупь да потайных карманов нашить, кинь ловкость рук сл 19",143632,null],[143638,"2026-08-06T21:09:11",9,"*Решётка едва едва, но поддалась и тоже согнулась. Люпен сможет пролезть кое как.*",143634,null],[143640,"2026-08-06T21:10:07",17,"Выбравшись Люпен сразу же бежит к факелу и снимает его со стены\n\n— Пацан, зачем тебе нужен был факел?",142532,null],[143641,"2026-08-06T21:10:15",17,"/ Отыгрываю 8 интеллекта",142532,null],[143642,"2026-08-06T21:11:37",47,"/r -d20+4",142532,null],[143644,"2026-08-06T21:11:50",47,"/r d20+4 везунчик",142532,null],[143646,"2026-08-06T21:11:56",47,"Ебать, ровно!!!",142532,null],[143647,"2026-08-06T21:12:01",17,"/ Везучий сукин сын",142532,null],[143648,"2026-08-06T21:12:07",47,"/везунчик ведь",142532,null],[143649,"2026-08-06T21:12:15",20,"- Ну...огонь всегда создаёт хаос. *Отвечает мальчик, невинно хлопая глазами*\n\n- Все бегают, отвлечены, паникуют...им явно будет не до нескольких заключённых, которые выбрались из камеры, так?",143640,null],[143651,"2026-08-06T21:14:07",17,"\"Хаос?\"",142532,null],[143652,"2026-08-06T21:15:18",17,"Люпен подходит к камере пацана\n\nОн знает что при взломе замков есть хитрость\n\nЕсли замок нагреть металл расширяется и отмычкой его в таком состоянии легче вскрыть \n\n— Отойди чутка и дай мне несколько крепких щепок, посмотри у шконки",142532,null],[143653,"2026-08-06T21:15:38",17,"/ Все ещё 8 интеллекта",142532,null],[143654,"2026-08-06T21:15:43",47,"Едва заметно на эти слова вздрогнул Сайн. Встречался он с такими... Деревню сжёг... Псих \"Надеюсь, что ошибаюсь таки\"",142532,null],[143655,"2026-08-06T21:15:54",9,"*Кое как нашиваешь скрытых карманов, нашьёшь за пол часа, но без нормальных нитей долго они не продержаться.*",143645,null],[143656,"2026-08-06T21:16:08",47,"Нити делаю из той же наволочки",143655,null],[143657,"2026-08-06T21:16:22",17,"— Поджечь все тут идея не плохая. Но пока вы в камерах сгорите вместе с тюрьмой",142532,null],[143658,"2026-08-06T21:16:34",47,"/тип нити, только в одежде и в наволочке есть, я ни чем иным зашить не мог",142532,null],[143659,"2026-08-06T21:16:37",20,"*Мальчик собирает щепки, передавая их Люпену*\n\n*Он с лёгкой настороженностью набоюдает за действиями мужчины*",142532,null],[143660,"2026-08-06T21:16:54",17,"Я передаю пацану факел через прутья и ковыряю замок разогретый",142532,null],[143661,"2026-08-06T21:16:57",17,"/r +4",142532,null],[143663,"2026-08-06T21:17:03",17,"/ Анлак",142532,null],[143664,"2026-08-06T21:17:06",9,"//Да, но эт впритык, сними маску и без проверок будет",143658,null],[143665,"2026-08-06T21:17:23",47,"/по идее преимущество можно. За правильные действия типо",143660,null],[143666,"2026-08-06T21:18:00",20,"*Рен держит осторожно факел и разглядывает то, что находится снаружи за окном*\n\n/Какие там внизу постройки/здания вблизи",142532,null],[143667,"2026-08-06T21:18:23",47,"Хочу",143664,null],[143668,"2026-08-06T21:18:36",17,"— Не вышло пацан. Погоди поищу тут что нибудь вне камер... Ты можешь предупредить через сколько обход будет? Стражник приходит через одно и тоже время вроде как",142532,null],[143669,"2026-08-06T21:19:07",20,"- Помещение поджигать опасно, да и сбегаться все буду туда, где огонь ...вот если наружу получится задженую щепку кинуть...",142532,null],[143670,"2026-08-06T21:19:31",17,"— Ну... Пробуй. Отговаривать не стану, факел я тебе добыл, дерзай",142532,null],[143671,"2026-08-06T21:19:39",20,"- Да, я предупрежу *Он кивает*",143668,null],[143672,"2026-08-06T21:19:55",47,"Как только закончу нашивки делать, дополнительным слоем положу остатки ткани в балахон, немного щепок, которые подойдут для розжига, кидаю туда проволоку и ищу по полу в камере что нибудь ещё. Вдруг просто что-то валяется",142532,null],[143673,"2026-08-06T21:20:13",17,"Люпен отходит от камеры пацана и рыскает вне камер в коридоре между ними в поисках гвоздей или чего то крепкого, полезного",142532,null],[143674,"2026-08-06T21:20:21",17,"/r +2 Выживание",142532,null],[143676,"2026-08-06T21:20:23",9,"//Эх, я бы алексея ждал",142532,null],[143677,"2026-08-06T21:20:42",9,"//Моё, сюда",143675,null],[143678,"2026-08-06T21:20:43",17,"/ Да мы щас ему собьем замок и стопнемся",142532,null],[143679,"2026-08-06T21:20:45",47,"Я действую так, чтобы не мешать другим. Чисто набиваю карманы",143676,null],[143680,"2026-08-06T21:21:05",47,"- Эй, вы что там делаете? - слышать звон и шорохи спросил Сайн",142532,null],[143681,"2026-08-06T21:21:18",17,"— Зачем тебе мешок на голову нацепили мужик? Как тебя кстате?",142532,null],[143682,"2026-08-06T21:21:19",20,"/я пока тоже без обсуждения ничего жечь не буду",143676,null],[143683,"2026-08-06T21:21:32",9,"*Ничего особенного, второй факел рядом со ступенями наверх на стене.*",143675,null],[143684,"2026-08-06T21:21:58",17,"— Пацан дай на время факел тут темно, я ничего не могу найти во тьме.\n\n/ повторный поиск со светом могу?",142532,null],[143685,"2026-08-06T21:22:06",47,"- Про магию сказали какую-то. Сам в шоке - к слову, отыгрываю интелект 14.",143681,null],[143686,"2026-08-06T21:22:20",47,"/?",143680,null],[143687,"2026-08-06T21:22:23",47,"/не ответишь?",142532,null],[143688,"2026-08-06T21:22:25",20,"/факел передан",143684,null],[143689,"2026-08-06T21:22:34",17,"— Пффф магия, была б у тебя магия ты бы уже пуф и из этой камеры испарился бы...",143685,null],[143690,"2026-08-06T21:22:55",9,"//Чем вы факел подожгли? Они не горели, оба)",143684,null],[143691,"2026-08-06T21:23:02",17,"— Я ищу что то, чтобы вас вытащить",143680,null],[143692,"2026-08-06T21:23:14",17,"/ Не горели? Ты сказал один горел в конце",143690,null],[143693,"2026-08-06T21:23:19",47,"- У меня есть железная проволока - говорит Сайн",142532,null],[143694,"2026-08-06T21:23:21",17,"/ Ну я думал один горел окей",142532,null],[143695,"2026-08-06T21:23:36",9,"//Не горят",142532,null],[143696,"2026-08-06T21:23:40",17,"— Мягкая наверное, ну-ка дай мне",143693,null],[143697,"2026-08-06T21:24:08",17,"/ Про нагрев тогда это ну... Этого не было выходит и про пожар",142532,null],[143698,"2026-08-06T21:24:16",47,"С тяжёлым вздохом теряя единственное что-то полезное здесь, передаю товарищу. Всё же он не сбежал и не кинул, а попробовал вытащить нас",142532,null],[143699,"2026-08-06T21:24:23",17,"— Чем бы нам вот ещё факел запалить?",142532,null],[143700,"2026-08-06T21:25:17",47,"/мастер, какое преимущество в случае чего мне даст владением инструментом взломщика, или портного?",142532,null],[143701,"2026-08-06T21:25:53",47,"/в общем передал проволоку. Помогаю товарищу во взломе замка, рассказывая полезную информацию  о взломе",142532,null],[143702,"2026-08-06T21:25:54",17,"/ Кстате я типо тоже владею инструментами взломщика",142532,null],[143703,"2026-08-06T21:27:28",47,"- Я с этими замками знаком. Чтобы его вскрыть, тебе нужно в момент, когда ты приподнимаешь пружину, толкнуть отмычку чуть  сильнее и дальше чем обычно, а после стукнуть по нему, это заставит цилиндр по центру дернуться и поднимет наверх и его и остальные по цепочке - пояснил Сайн",142532,null],[143704,"2026-08-06T21:28:10",17,"— Звучит разумно, ты тоже из наших?\n\nПоказываю знак на языке воров",142532,null],[143705,"2026-08-06T21:28:17",47,"/я в маске",142532,null],[143706,"2026-08-06T21:28:43",47,"/не вижу",142532,null],[143707,"2026-08-06T21:30:01",47,"- Это деревенский стандартный замок, их зачастую проще с кулака вскрыть, чем ключом пользоваться - слегка пожаловался Сайн - не понимаю о ком ты говоришь, но я из своих собственных. \n О замках папа рассказывал зачастую. Кузнецом был",142532,null],[143708,"2026-08-06T21:30:34",9,"//От ситуации смотреть буду, но с маской у тебя помеха, а с везунчиком это выбор куба уже 1 из 3, имба",143700,null],[143709,"2026-08-06T21:30:53",47,"/мне нравится живость моего перса. Давно такое не чувствовал. Спасибо. \n Я спать!",142532,null],[143710,"2026-08-06T21:31:38",47,"/я имею ввиду общее преимущество, не как игромех, а как к примеру я вот разбираюсь в них значит могу взломать тише, или не сломать ничего и так далее",143708,null],[143711,"2026-08-06T21:31:53",47,"/нравится взаимодействие с другими персами",142532,null],[143712,"2026-08-06T21:31:58",47,"Общая проблема сближает /",142532,null],[143713,"2026-08-06T21:35:24",9,"//Вместе разбираетесь, вместе делаете. Воровскими инструментами ещё ловушки делают, так что два вора могут пипец устроить если есть время подготовить територию, да да 😏👌",143710,null],[143714,"2026-08-06T21:35:49",20,"/а что сделают три вора...🤔",143713,null],[143715,"2026-08-06T21:42:13",9,"//Три хз, а два...\n\n\"... два вора, тихо скрывшись от погони, делить украденное золото решили...*\n\nhttps://youtu.be/XzM3luv_xxM?si=okcdbFsMKQeauI5v",143714,null],[143725,"2026-08-06T22:09:13",20,"- Э...Крыса? *Зовёт мальчик из своей камеры, с чем-то возясь у решетки*\n\n- Мне кажется этот прут шатается...я пробовал его выгнуть сам, но... *Он неловко указывает на свою детскую тщедушность* - ...сил немного не хватает",142532,null],[143730,"2026-08-06T22:20:24",17,"— Молоток, щас мы его вдвоем с тобой согнем и ты вылезешь!\n\nВот тебе факел, попробуй его как рычаг, а я буду всем весом тянуть\n\nЛюпен передает факел мальчику и упирается ногой в соседний прут обхватывает тот что шатается всем весом и уперевщись ногой он пытается согнуть прут чтобы освободить мальца\n\nПоверхностные мысли:\n\n\"Этот малец возраста моего сына, как он там без меня...\"",143725,null],[143733,"2026-08-06T22:22:53",20,"*Рен перехватывает факел и зажимает его между прутом и стеной, стараясь надавить на него всем весом как на рычаг*",143730,null],[143739,"2026-08-06T22:25:35",20,"*Параллельно он все ещё прислушивается к мыслям своих невольных товарищей по несчастью, хоть и не пытается забраться глубоко*\n\n*Семья...как много людей думают об одном и том же. От благородных лордов до обычных стражников и заключённых...*",142532,null],[143753,"2026-08-06T22:30:38",9,"*Прут удалось выломать относительно легко, пацан теперь пролезет легко и сам.*",142532,null],[144040,"2026-08-07T01:16:03",17,"— Ну вот, давай теперь остальных вытаскивать. Сколько у нас времени до очередного обхода?\n\nЛюпин присел к замку и начал складывать и проволочки подобие отмычек, чтобы вскрыть замка остальных",142532,null],[144048,"2026-08-07T06:31:56",47,"/с помощью от меня. Я там типо рассказал как и что надо, засчитайте за помощь пж",142532,null],[144049,"2026-08-07T06:56:41",9,"//Ну, я не знаю на счет печи как помощь. Ты даже тип замка на решетке не видел, кто-то может в след раз задушнить по этому поводу и поэтому я тож задушню, просто словами помощь не дам когда замка в глаза не видел.",144048,null],[144050,"2026-08-07T06:59:13",47,"/я его нащупал",142532,null],[144051,"2026-08-07T07:00:05",47,"Мне и так неуютно в маске. Я слепой. Это ужасное ощущение /",142532,null],[144052,"2026-08-07T07:05:36",31,"Учёные скрестили кролика с кротом. Животинка получилась слепая, но уж если нащупает....///",144050,null],[144053,"2026-08-07T07:14:01",9,"//Го проверку на вскрыть сложность 15, уже не крит потому что с проволочкой легче чем чёртовыми колючками и щепками из дерева",144040,null],[144054,"2026-08-07T07:18:19",17,"/r +3 Ловкость рук",142532,null],[144056,"2026-08-07T07:18:25",17,"/ Неа",142532,null],[144057,"2026-08-07T07:19:11",17,"— Не выходит, нужно что то потверже. Проволока сильно мягкая... Такс, пацан что у нас ещё есть?",142532,null],[144058,"2026-08-07T07:19:19",9,"*Темница старая, но замки похоже здесь поддерживают в хорошем состоянии.*",144055,null],[144059,"2026-08-07T07:19:31",31,"- а крысиная кость не пойдет?",144057,null],[144060,"2026-08-07T07:20:21",17,"— Надо бы попробовать.",142532,null],[144061,"2026-08-07T07:20:44",31,"Передаю обглоданную крысиную тушку",142532,null],[144062,"2026-08-07T07:22:05",17,"/ Ты уже жрал сырую крысу?",142532,null],[144063,"2026-08-07T07:22:09",17,"/ Вот это да",142532,null],[144064,"2026-08-07T07:22:52",9,"//Повезло что без болячки, уже хорошо",142532,null],[144065,"2026-08-07T07:23:10",31,"Я крепкий, выдержу/",144064,null],[144067,"2026-08-07T07:28:59",17,"— Ничего острого нет? Шкуру голыми руками не получится содрать, мне бы может были полезны лучевые и плечевые косточки, они тонкие и длинные. А ещё реберные. Но как бы до них ещё добраться",142532,null],[144068,"2026-08-07T07:29:37",31,"- Самое острое что есть это зубы",142532,null],[144070,"2026-08-07T07:30:22",31,"Зубами опять через проверку атлетики/",142532,null],[144071,"2026-08-07T07:33:28",17,"Вспомнив как Конрад выпалил тираду на стражника, притворялся важной шишкой \n\n— Хех, как ты там говорил \"Смерд по  какому праву запер дворянина Фон Мон чето там\" А жить захочешь и кожу с крысы зубами сдирать будешь. Правда жизни.",142532,null],[144073,"2026-08-07T07:37:34",31,"- гу так и него и правда нет права меня тут держать, я не преступник. И нет урона для дворянской чести в том чтобы выйти из несправедливого заключения. Любыми способами",142532,null],[144077,"2026-08-07T07:51:42",17,"— А... Так ты серьезно голубых кровей. Удивительно.",142532,null],[144078,"2026-08-07T07:52:32",47,"- А меня растили три бабушки - непонятно, сарказмировал, или честно сказал Сайн",142532,null],[144081,"2026-08-07T08:21:14",47,"/кинь атлетику, чтобы мастер среагировал",144070,null],[144082,"2026-08-07T08:22:03",31,"/roll d20 на атлетику, разгрызаю крысу чтобы добыть нужные косточки",142532,null],[144084,"2026-08-07T08:29:06",17,"— Пацан. Пока я тут вожусь с замком, попробуй снять мешок с того парня. \n\nОбернулся на Сайна\n\n— Или тебе нравится в нем щеголять?",142532,null],[144085,"2026-08-07T08:30:40",17,"Потом принимает ободраную тушку у Конрада,\n\n— Хорошо сработано, у вас крепкие зубы милорд.\n\nЛюпен дёргает тонкие длинные косточки из тушки крысы и зубами так же помогает себе оторвать их от сухожилий, чтобы получить снова подобие отмычек",142532,null],[144086,"2026-08-07T08:31:14",31,"*Сплевываю шерсть*",142532,null],[144087,"2026-08-07T08:31:34",20,"- Хм...я попробую *Мальчик подбирается поближе*\n\n/Так, что так нужно было на откручивание винтиков",144084,null],[144088,"2026-08-07T08:31:55",17,"/ Я так и не представил что там за мешок такой",142532,null],[144089,"2026-08-07T08:32:45",20,"/r d20+2 пробуем ловкость рук",142532,null],[144091,"2026-08-07T08:33:43",47,"- Вообще нет. Снимите его скорее. Заебало",144084,null],[144092,"2026-08-07T08:34:30",47,"Кожаная плотная маска, плотная, с вырезами для рта и носа, скрепленная позади стальной проволокой",144088,null],[144093,"2026-08-07T08:36:18",17,"Достав кости из тушки крысы Люпен тяжело выдохнул\n\n— Времени почти не осталось. Возможен это последняя попытка. \n\nСнова присаживается к замку на корточки, если получится Конрад будет свободен\n\n— Ладно, приступим",142532,null],[144094,"2026-08-07T08:36:27",17,"/ Время обосраться снова на проверке взлома",142532,null],[144095,"2026-08-07T08:36:31",17,"/ Чеееек",142532,null],[144096,"2026-08-07T08:36:40",17,"/r +3 Пошла вода горячая",142532,null],[144098,"2026-08-07T08:36:41",47,"/пускай он действие помощь окажет, что-ли",142532,null],[144099,"2026-08-07T08:36:44",17,"/ Туда",142532,null],[144100,"2026-08-07T08:36:59",47,"/сцуко",142532,null],[144101,"2026-08-07T08:37:08",47,"/ну окажите вы помощь, вас вытащить пытаются ебать",142532,null],[144103,"2026-08-07T08:41:33",17,"/ Да расслабься, щас чето придумаем. Там типо просто физически не понятно как оказать помощь во взломе, они же с другой стороны от замка",142532,null],[144104,"2026-08-07T08:41:37",31,"могу только потрясти дверь, чтобы отмычка в пазы попала/",142532,null],[144105,"2026-08-07T08:41:54",17,"/Ну звучит приемлимо вроде, подождем харда",144104,null],[144106,"2026-08-07T08:42:02",47,"/банально ухо приставил и говоришь, что-то щёлкнуло, свистнуоо ебанулось",142532,null],[144107,"2026-08-07T08:42:20",47,"Hard",142532,null],[144110,"2026-08-07T09:21:25",17,"/ Когда снова провалил взлом",142532,null],[144125,"2026-08-07T09:35:56",9,"*Нужны щепцы или хотя бы что-то жёсткое, ты может и вытянешь еще пару прутиков, но другие закрепленны надёжно, незачто залепиться.*\n\n//Я тут",144087,null],[144127,"2026-08-07T09:37:20",9,"//Ну, Конрад хотя бы без маски, пробуй с преимуществом.",142532,null],[144130,"2026-08-07T09:38:12",17,"/ Судьбу не изменить",142532,null],[144132,"2026-08-07T09:39:59",20,"- Прости, Маска но тут похоже мало что голыми руками сделаешь.... *Извиняющимся тоном говорит ребенок*\n\n- ...у тебя же есть имя? Странно тебя Мистером Маской все время называть\n\n/Хоть убейте не помню момент, называл ли Сайне свое имя(",144125,null],[144134,"2026-08-07T09:40:21",20,"/ура телега и классическое начало",144130,null],[144141,"2026-08-07T09:46:16",9,"*Замок совсем новый, не поддается падла.*",144129,null],[144146,"2026-08-07T09:48:52",17,"— Пацан сколько осталось времени до обхода?\n\n— Я облажался, замки не поддаются, их будто тут недавно поставили новенькие, черт побери.\n\nПодходит к пацану и человеку в мешке и попутно выдивает у крысы еще пару острых костей\n\n— Давай попробуем мешок порвать этими костяшками, только повернись к нам задом, если не успеем, чтобы стражник не заподозрил неладное.\n\nПередаю пацану пару мерзких костей крысы. Руки все перепачканы в крови грызуна, рот вытер рукавом",142532,null],[144151,"2026-08-07T09:50:40",9,"// @PaIIasCat чек, ещё 30-35 минут примернг до обхода, внеигровая, обыгрывай как хочешь",142532,null],[144152,"2026-08-07T09:51:00",17,"/ Мы можем успеть помочь снять мешок?",142532,null],[144153,"2026-08-07T09:51:15",20,"- Ещё около получаса",142532,null],[144156,"2026-08-07T09:52:05",20,"/мешок вроде кожаный - получится ли такое костями пробить",144146,null],[144161,"2026-08-07T09:52:34",20,"/хотя попытка не пытка",142532,null],[144165,"2026-08-07T09:53:05",9,"//Я раз 10 обьяснил что там не мешок а плотная кожаная маска стянутая проволокой, даже со щипцами займёт час, а голыми ручками ковырятся минимум день",142532,null],[144166,"2026-08-07T09:53:06",47,"- Дай мне проволоку. Я с закрытыми глазами и то лучше справлюсь - ругается из-за решётки Сайн слыша щелчок сломанных, костей снаружи",142532,null],[144172,"2026-08-07T09:54:30",17,"— Держи. Ты бы не выпендривался, мы то уже снаружи и бросить тебя нам ничего не стоит. Уж будь повежливее мужик.",144166,null],[144173,"2026-08-07T09:54:48",17,"Передал обратно ему его проволоку",142532,null],[144198,"2026-08-07T10:16:46",47,"/r -d20+4 взламываем нах. Крайний везунчик видимо",142532,null],[144201,"2026-08-07T10:17:07",47,"/r d20+4 везунчик",142532,null],[144203,"2026-08-07T10:17:12",47,"Итого 18",142532,null],[144204,"2026-08-07T10:17:24",47,"Помогаю себе там щепками и проволокой",142532,null],[144207,"2026-08-07T10:19:14",9,"*Не сразу но замок поддается и слышится характерный щелчок открытой решетчатой двери.*",144203,null],[144209,"2026-08-07T10:19:52",47,"- Я извиняюсь, но просто я же пояснил как вскрывать, чуть сильнее надавливаем, толкаем, ждём маленько и открываем - повторяет он слова сказанные ранее - ладно. Пусть я ещё не вижу, но по крайней мере я частично свободен. Подведите меня к тому, кто ещё нет. И помогите пожалуйста, ничерта не вижу - ноет Сайн, но его нытьё кажется можно и стерпеть, всё же он и вправду эксперт... Наверное",142532,null],[144210,"2026-08-07T10:20:05",47,"@dunchev @PaIIasCat поможете?",142532,null],[144212,"2026-08-07T10:20:16",47,"@dunchev или наоборот, я помогу Люпену?",142532,null],[144216,"2026-08-07T10:20:30",17,"/Наша помощь убирает минус 1 кубик у тебя",142532,null],[144217,"2026-08-07T10:20:37",17,"/ Их станет 2 с везунчиком",142532,null],[144218,"2026-08-07T10:20:40",47,"- Я Сайн представился он",144132,null],[144220,"2026-08-07T10:20:52",47,"/у меня везунчики кончились",144217,null],[144221,"2026-08-07T10:21:03",17,"/ Ну мы уже пытались, повторять одно и тоже не буду",142532,null],[144222,"2026-08-07T10:21:07",47,"/я думал мы спать будем",142532,null],[144223,"2026-08-07T10:21:13",47,"С моей помощью, давай/",144221,null],[144224,"2026-08-07T10:21:19",47,"/тебе эксперт помогать будет",142532,null],[144225,"2026-08-07T10:21:35",47,"/по теории вероятности ща всё ок будет",142532,null],[144226,"2026-08-07T10:21:49",20,"/это уже спам проверками, там замок уже должен быть в шепках весь",142532,null],[144228,"2026-08-07T10:22:23",47,"Хм/...",144226,null],[144229,"2026-08-07T10:22:26",20,"/как по мне честно по одной попытке на каждый замок",142532,null],[144230,"2026-08-07T10:22:28",31,"- замку кабзда. похоже придется вам ждать тюремщика с ключом",142532,null],[144233,"2026-08-07T10:22:40",47,"- Предлагаешь его вырубить и забрать ключи?",142532,null],[144235,"2026-08-07T10:22:46",17,"// Я согласен с паллас",142532,null],[144236,"2026-08-07T10:22:47",31,"- ну да",144233,null],[144238,"2026-08-07T10:22:53",47,"- А потом переодеться в его форму и выйти?",142532,null],[144239,"2026-08-07T10:23:24",17,"— Снимать с него одёжу будет долго, могут загрести. Лучше наверное сразу валить",142532,null],[144240,"2026-08-07T10:23:28",47,"- Я могу только помочь тем, что повалю его наземь... - обозначил границы возможностей Сайн",142532,null],[144241,"2026-08-07T10:23:29",31,"- ну для меня или Крысы это выход, а вот для твоего образа и для пацана врядли",144238,null],[144242,"2026-08-07T10:24:06",47,"- Я под конвоем. И всё",144241,null],[144243,"2026-08-07T10:24:09",20,"- И людей очень много снаружи...даже если выскользнем из камеры, не уверен что сможем сбежать из самого форта",142532,null],[144245,"2026-08-07T10:24:18",47,"/r d20+2 анализ типо",142532,null],[144248,"2026-08-07T10:24:28",47,"Не додумался. Бля(/",142532,null],[144249,"2026-08-07T10:24:44",20,"- Если нас завтра повезут в телеге, на дороге сбежать будет намного проще",142532,null],[144250,"2026-08-07T10:24:47",47,"- Я умею всякое. Главное снять маску с меня!",142532,null],[144251,"2026-08-07T10:24:49",17,"— Не думаю, что там одни идиоты",144242,null],[144252,"2026-08-07T10:25:17",47,"- Военный и идиот - слова синонимы - фыркает Сайн",144251,null],[144253,"2026-08-07T10:25:19",20,"- Сэр страж даже про магию фей знает *согласно кивает мальчик*",144251,null],[144254,"2026-08-07T10:25:29",47,"- Пф",142532,null],[144258,"2026-08-07T10:26:22",17,"— Они бы не нацепили на тебя этот мешок, если бы были совсем тугодумы",142532,null],[144260,"2026-08-07T10:26:51",17,"— Давайте все сместе попробуем разогнуть пруться камеры Конрада, нас всё же теперь тут четверо",142532,null],[144262,"2026-08-07T10:27:19",17,"— Как ты кстате вообще видишь куда идёшь?",142532,null],[144263,"2026-08-07T10:27:23",47,"- Ладно - пожимаю плечами - ещё бы вытащить пару прутов...",142532,null],[144264,"2026-08-07T10:27:28",17,"/Мешок же глаза закрывает да?",142532,null],[144265,"2026-08-07T10:27:52",47,"/я не знаю к чему вопрос, потому что я всю игру даю заявки: на ощупь, прошу подвести и так далее",144262,null],[144266,"2026-08-07T10:28:04",9,"//На разогнуть прутья без помехи, у него все что со зрением связанно с помехой или невозможно",142532,null],[144268,"2026-08-07T10:28:24",47,"- Я и не вижу. Я в этой камере весь день всё подряд щупал. Кажется проживи ещё день и я могу даже не ощупывая пол доползти куда угодно в своей комнате",142532,null],[144269,"2026-08-07T10:29:08",47,"/ебать, а что за жесть мастер? В чем проблема не видя прутья просто нащупать и начать тянуть? Я всё понимаю, но на такое помеху давать это уже ну тип... Фигня",144266,null],[144270,"2026-08-07T10:29:31",9,"//Так тяни, там видеть не надо",144269,null],[144271,"2026-08-07T10:29:51",47,"Ну тяну",142532,null],[144272,"2026-08-07T10:29:53",9,"//Наоборот говорю что это грубая сила, по идее никаких помех",142532,null],[144273,"2026-08-07T10:29:55",47,"/r d20-1",142532,null],[144275,"2026-08-07T10:31:19",47,"/а нахуя я кинул... Я видимо за прут своей решётки потянул",142532,null],[144276,"2026-08-07T10:31:22",9,"*Кое как общими усилиями вам удаётся разогнуть прутья чтобы Конрад мог протиснуться, один из прутьев даже изломился, тюрьма старая, его можно отломить.*",142532,null],[144277,"2026-08-07T10:31:38",31,"- о да, свобода все ближе",142532,null],[144278,"2026-08-07T10:31:42",47,"/я же не знаю где его клетка, я слепой",142532,null],[144279,"2026-08-07T10:31:58",9,"//Думаю вы просто в троём решётки гнули, хз, подведите слепого и сделайте",144276,null],[144280,"2026-08-07T10:32:15",47,"/ок.пойдет. кстати, прут мы вытащили? Это важно",142532,null],[144281,"2026-08-07T10:32:42",9,"//Его можно отломить, сами решайте, бещ проверок",144280,null],[144283,"2026-08-07T10:33:15",47,"/делаю конечно, ебать, первое оружие, в будущем ещё и для других нужд пригодится",142532,null],[144286,"2026-08-07T10:35:34",9,"Получен: Железный прут\n\n//Вы не описываете как отламываете, я хз, делайте за персонажей пж в след раз",142532,null],[144289,"2026-08-07T10:37:31",31,"осматриваю дверь, заперта ли она?",142532,null],[144290,"2026-08-07T10:37:54",9,"//Какую и где",144289,null],[144291,"2026-08-07T10:38:51",17,"Люпен помог отломить прут\n\n— Кто будет железякой орудовать? Мне не с руки, тяжелый",142532,null],[144293,"2026-08-07T10:39:37",31,"входную в темницу, через которую заходил стражник/",144290,null],[144295,"2026-08-07T10:39:56",31,"- могу я наверное",144291,null],[144297,"2026-08-07T10:40:32",9,"//Импровизированное 1д4 от силы без бм на попадание если нет владения импровизированным от черты или чёт такого",142532,null],[144299,"2026-08-07T10:41:29",17,"/ У тебя кулаки мощнее",144295,null],[144300,"2026-08-07T10:41:35",9,"*Дверь в темницу вверх по ступенькам не заперта, видна небольшая щель.*",144293,null],[144302,"2026-08-07T10:42:47",47,"/буквально вытягиваю",144286,null],[144304,"2026-08-07T10:43:27",47,"Прячу в балахон",144302,null],[144305,"2026-08-07T10:44:02",17,"— Ты уверен что хочешь слепо махать железякой?",142532,null],[144307,"2026-08-07T10:45:08",47,"- Я её не для того выломал. Она сгодится как рычаг, она может пригодится там, где руками не достать. Да мало ли - явно синдром плюшкина",142532,null],[144320,"2026-08-07T10:48:46",47,"- Что вокруг нас? Что вы видите? Расскажите - просит Сайн",142532,null],[144331,"2026-08-07T10:57:03",31,"- коридор, клетки, лестница наверх, к выходу",144320,null],[144333,"2026-08-07T10:58:26",9,"*Глубь темницы ещё несколько пустых камер и глухая стена.*",142532,null],[144335,"2026-08-07T11:03:36",47,"- Так чего мы ждём? Идём?",142532,null],[144337,"2026-08-07T11:03:46",31,"- ладно, нужно решать как будем выбираться. Дверь не заперта, уходим всей толпой или отправим разведчика?",142532,null],[144339,"2026-08-07T11:04:15",17,"Люпен пробует дверцы пустых камер, может есть октрытые в а камерах есть, что то полезное",144333,null],[144340,"2026-08-07T11:04:26",17,"/r +2 Выживание поиск полезностей если есть открытые камеры",142532,null],[144341,"2026-08-07T11:04:26",47,"/люблю",144339,null],[144343,"2026-08-07T11:04:38",31,"Крысинное дерьмо, чтобы бомбы делать/",144339,null],[144344,"2026-08-07T11:04:42",17,"/ Четвёрки это моё проклятье",142532,null],[144347,"2026-08-07T11:07:36",9,"*Самые крайние камеры вглубь темницы открыты, их время покоробило сильнее всего, да и похоже пользуются всей темницей крайне редко.*\n\n*В одной из ни в углу воняет дохлая крыса, решетки на окнах и дверях старые и ржавые, даже гнилых кроватей нет как в предыдущих.*",144339,null],[144348,"2026-08-07T11:09:50",20,"/когда нас вели в камеры, я мог запомнить расположение коридоро и выход?",142532,null],[144352,"2026-08-07T11:12:19",9,"*Вас вели с мешками на голове, по ощущением там всего пару небольших помещений прежде чем выбраться наружу.*",144348,null],[144353,"2026-08-07T11:13:09",47,"/окна и решётки крупные? Есть вариант выбить и вылезти?",142532,null],[144354,"2026-08-07T11:13:21",47,"/как перс не знаю, для товарища уточняю",142532,null],[144355,"2026-08-07T11:15:42",9,"//Нсли осмотрит, потрогает и тд — узнает",144353,null],[144362,"2026-08-07T11:26:44",47,"- ну что там? Ребят я всё понимаю, но говорите со мной, я в темноте уже сутки!",142532,null],[144368,"2026-08-07T11:30:05",31,"ну, я закинул вопрос о том, как будем выбираться, толпой или отправим сначала кого то разведать дорогу, жду реакций/",142532,null],[144375,"2026-08-07T11:38:13",20,"- Посмотреть что впереди пригодилось бы... только лучше чтоб вперед пошел кто-то более скрытный",144337,null],[144376,"2026-08-07T11:38:55",20,"/эх жаль что уже чтение мыслей использовала",142532,null],[144381,"2026-08-07T11:48:04",17,"Люпен сдирает простынь, снова делает небольшую заплечную сумку и суёт туда дохлую крысу, а так же потрошеную тушку ранее пойманой Конрадом.\n\n— Еще одна крыса. Больше ничего",144347,null],[144382,"2026-08-07T11:48:32",17,"— Давайте держаться вместе, или вы хотите успеть сдриснуть обратно в камеры, если кого то заметут?",144368,null],[144383,"2026-08-07T11:49:02",17,"— Ничего острого к сожалению, потерпи, снимем с тебя этот мешок скоро",144362,null],[144384,"2026-08-07T11:49:15",17,"— Пацан, факел еще у тебя?",142532,null],[144385,"2026-08-07T11:49:24",20,"- Ага",144384,null],[144386,"2026-08-07T11:49:51",17,"— Не потеряй, он промаслен, если выберемся может нам жизнь спасти в лесу.",142532,null],[144387,"2026-08-07T11:50:08",20,"- Я могу тоже пойти с кем-то одним вперёд - я не очень громкий, а в крайнем случае смогу попробовать заговорить стражников, если попадемся",142532,null],[144388,"2026-08-07T11:51:39",17,"— Давай со мной, но далеко уходить не будем. Если что заболтаешь их какой нибудь ахерительной историей, о том что у тебя оказался расшатыный прут и ты вылез чтобы им сообщить об этом, хаха",142532,null],[144389,"2026-08-07T11:53:04",17,"Люпен и пацан (БОООООЙ) потехоньку идут вперёд\n\nЛюпен присел на корты чтобы быть ниже и менее заметным, ведь все знают одну истину, если присел - ты невидим",142532,null],[144390,"2026-08-07T11:54:17",20,"*Пацан тоже старается двигаться тихо за старшим, в уме уже перебирая варианты, если попадуться*",144389,null],[144392,"2026-08-07T11:55:23",20,"/101 способ разжалобить взрослых мужиков молющими детскими глазами 🥺",142532,null],[144393,"2026-08-07T11:55:33",17,"/ У них нет шансов",142532,null],[144394,"2026-08-07T11:59:17",9,"//Ну, вы идёте за дверь ведущую из темницы по ступеням? Описывайте как и что)",142532,null],[144395,"2026-08-07T11:59:48",20,"/кродемся",142532,null],[144396,"2026-08-07T11:59:54",20,"/как крысы",142532,null],[144397,"2026-08-07T12:00:38",17,"Мягкой поступью (цариц) Люпен перед пацаном кродётся вперёд прислушиваясь к каждому шороху, в темноте нихера не видать",142532,null],[144398,"2026-08-07T12:00:47",17,"/r +2 Выживание",142532,null],[144401,"2026-08-07T12:03:10",9,"*Осторожно идете за дверь, стараясь быть скрытными. Когда дверь начали открывать она заскрипела сука, громко. Петли не смазывали очень давно. Но снаружи никакого звука или реакции.*",142532,null],[144402,"2026-08-07T12:03:25",9,"//Открываете дверь полностью?",142532,null],[144403,"2026-08-07T12:03:26",47,"Какая это 4 по счету? /",142532,null],[144404,"2026-08-07T12:03:33",47,"Мастер, дай ему криты на 4 😂😂😂",142532,null],[144405,"2026-08-07T12:03:38",47,"Крит провалы) /",142532,null],[144406,"2026-08-07T12:03:53",9,"//У меня 2 часто падают и 22",142532,null],[144407,"2026-08-07T12:04:04",9,"//У каждого свой рак кубов",142532,null],[144408,"2026-08-07T12:04:35",17,"Люпен скорчил такую рожу будто бы только что зажевал кислый лимон целиком, когда дверь заскрипела и замер смотря на пацана с таким лицом всё время пока скрип не закончился",142532,null],[144409,"2026-08-07T12:05:09",20,"*Переглядывается с ним*\n\n-...\n\n*Настоящие мастера скрытности*",144408,null],[144410,"2026-08-07T12:05:16",17,"Дверь открыта и скрит прекратился наконец, вытер пот рукавом со лба и улыбнулся",142532,null],[144411,"2026-08-07T12:05:31",17,"Наклоном головы показал \"Мол продолжаем\"",142532,null],[144412,"2026-08-07T12:06:49",17,"И всё в том же неспешном темпе прислушиваясь двое разветчиков аккуратно продвигались по этой тюремной кишке, пытаясь найти что то полезное или выход",142532,null],[144413,"2026-08-07T12:07:12",17,"Шепотом \n\n— Пацан, не забывай осматриваться, любой маленький гвоздь может спасти наши задницы",142532,null],[144414,"2026-08-07T12:07:18",17,"/Давай ты",142532,null],[144419,"2026-08-07T12:08:16",9,"*Из темницы дверь вела в небольшую комнату, тут стол, лежанка и проход в вашу темницу и второй из этой комнаты, у потолка из крошечного окошка пробивается свет. Тут сторож должен отдыхать, не сильно уютно но раз в 10 лучше чем в ваших камерах.*",142532,null],[144421,"2026-08-07T12:08:26",20,"*Следует за старшим, осматривая все на пути на предмет полезных мелочей*",142532,null],[144422,"2026-08-07T12:08:52",20,"/r d20+2",142532,null],[144425,"2026-08-07T12:09:05",20,"/на внимание",142532,null],[144426,"2026-08-07T12:10:29",9,"*Лежанка крепкая, застелена. На столе несколько свечей и трут, чтобы ночью подсветить себе, так же пару факелов. Немного полежавший хлеб и сало, нож, дубинка которой скорей всего гоняли крыс.*",144421,null],[144428,"2026-08-07T12:11:33",9,"*Кувшин с водой у кровати, вода немного пахнет алкоголем.*",142532,null],[144431,"2026-08-07T12:17:18",20,"/лутаем в мешок к люпену?",142532,null],[144432,"2026-08-07T12:19:29",17,"— Кувшик не бери, стражник туда ссал. Хотя, как элемент внезапности...",142532,null],[144433,"2026-08-07T12:39:26",20,"*Пацан кивает, складывая все остальное в мешок к Люпену.*",144432,null],[144434,"2026-08-07T12:39:56",17,"— У нас есть чем зажечь факел, что нам это даст?",142532,null],[144435,"2026-08-07T12:45:06",20,"- Можно было бы устроить поджог для отвлечения внимания, но это немного рискованно. *Предлагает Рен*",144434,null],[144436,"2026-08-07T12:46:02",17,"— Я так понимаю поджигать нужно, когда выберемся, да?",142532,null],[144437,"2026-08-07T12:46:11",20,"- Думаю пока лучше осмотреться и попробовать найти выход - если получится уйти тихо и так, то сохраним ресурс",142532,null],[144438,"2026-08-07T12:46:49",20,"- Да, желательно что-то что привлечет внимание, но не будет на пути побега. Склад какой-нибудь...",144436,null],[144439,"2026-08-07T12:47:24",20,"- Саму тюрьму поджечь вряд ли получится, тут один сырой камень да решетки",142532,null],[144440,"2026-08-07T12:48:23",17,"— Говоришь не как тринадцателетний ребёнок, многое уже повидал, да?",144437,null],[144441,"2026-08-07T12:49:11",17,"/ @QURTZZ @cirson Догоняйте нас",142532,null],[144442,"2026-08-07T12:49:47",20,"- Наблюдал ...*Рен быстро опускает глаза, смущённо признаваясь* \n\n- пока прислуживал, да и пока на улице был...всякое болтали...\n\n- Сам я мало в таком разбираюсь\n\n/Можешь проницательность",144440,null],[144443,"2026-08-07T12:52:27",17,"— Воровской карман имеется?\n\nЛюпен начал разговаривать на воровском жаргоне с пацаном\n\n— Понимаешь о чем я?",142532,null],[144444,"2026-08-07T12:52:41",17,"/r +1 Проницаю",144442,null],[144446,"2026-08-07T12:53:28",31,"*прислушиваюсь, вроде наших товарищей не обнаружили, можно выдвигаться*\n\n- эй, Сейн, давай руку, прогуляемся",142532,null],[144448,"2026-08-07T12:54:51",47,"- Сайн я. Газ! - соглашается он и рука Сайна чуть ли не отрывает рукав балахона товарища лишь бы не потеряться",142532,null],[144452,"2026-08-07T12:55:18",20,"/r +d20+3",142532,null],[144454,"2026-08-07T12:55:50",17,"/ Это обманус",142532,null],[144457,"2026-08-07T12:56:56",20,"*Пацан вроде говорит убедительно, но ты замечаешь что тот, как он описывал план звучит больше как холодный расчет, а не предложение наблюдательного ребенка. Да и голову он опустил, будто забылся и резко одернул себя*",144445,null],[144460,"2026-08-07T12:57:18",20,"/пиздит короче слегка",142532,null],[144463,"2026-08-07T12:58:39",31,"/roll d20 выходим в коридор, прислушиваемся, где наши товарищи шуршат",144448,null],[144465,"2026-08-07T12:58:41",20,"/2 и 4...ваши проклятия заразны",144453,null],[144467,"2026-08-07T12:59:07",31,"- Сайн, слышишь что нибудь?",142532,null],[144469,"2026-08-07T13:00:01",9,"//Вы выходите из комнаты сторожа?",144463,null],[144470,"2026-08-07T13:00:33",9,"//Да, два проклятых рака кубов дают комбо, хотя бы не еденицы",144465,null],[144471,"2026-08-07T13:00:49",31,"нет, из темницы, в комнате стражи Крыса и пацан/",144469,null],[144472,"2026-08-07T13:00:50",17,"/ они ещё нас не догнали. Мы в этой комнате с пацаном ждём их",144469,null],[144475,"2026-08-07T13:02:34",20,"/мне нравится что все зовут Рена просто пацан(бооой)\n/чисто У мальчика нет имени 😶",142532,null],[144477,"2026-08-07T13:02:59",20,"/надо будет ему мини рапиру найти для полной картины",142532,null],[144482,"2026-08-07T13:05:58",17,"/ Это Арья Старк",142532,null],[144486,"2026-08-07T13:07:53",31,"то есть пацан у нас с нюансом?/",142532,null],[144487,"2026-08-07T13:08:18",20,"/)))",144486,null],[144488,"2026-08-07T13:08:37",31,"@cirson помогай найти напарников, я ничего не услышал",142532,null],[144491,"2026-08-07T13:10:52",17,"/ Пасхалка на это кстате была в названии темы перса",144486,null],[144494,"2026-08-07T13:14:35",47,"/еба.у меня уши под маской",144488,null],[144495,"2026-08-07T13:14:40",47,"/шансов ещё меньше",142532,null],[144496,"2026-08-07T13:14:57",47,"- Погоди, тут же один коридор, разве нет? - чуть громче чем надо... Глухой",142532,null],[144498,"2026-08-07T13:16:11",31,"походу я что то загнался. судя по описанию там путь один в комнату стражи",142532,null],[144499,"2026-08-07T13:16:17",31,"пиздуем туда/",142532,null],[144503,"2026-08-07T13:19:23",17,"Когда приходят еще двое, Люпен шепотом произносит\n\n— Пока тихо, нашли трут, можем поджечь факел. Больше особенно ничего полезного, ссаная водичка в вазе",142532,null],[144505,"2026-08-07T13:21:11",47,"Кивок от глухого, будто что-то понял",142532,null],[144510,"2026-08-07T13:22:27",31,"- ну, пожар можно устроить, чтобы по тихой свалить",142532,null],[144512,"2026-08-07T13:24:13",17,"— Да, пацан уже предложил найти склад или типо того, но сперва надо выбраться из этих казематов.\n\nЛюпен разворачивается, садится на корты и снова начинает двигаться вперёд\n\n— Двинули.",142532,null],[144522,"2026-08-07T13:24:55",31,"- сколько у нас времени до следующего обхода?",142532,null],[144528,"2026-08-07T13:25:52",20,"/думаю осталось минут 20, учитывая что мы ещё прутья ломали",142532,null],[144530,"2026-08-07T13:26:21",31,"- ладно, тогда двигаемся побыстрее",142532,null],[144562,"2026-08-07T13:34:48",31,"Я на час за рулем/",142532,null],[144568,"2026-08-07T13:39:51",9,"*За дверью из комнаты охранника слышно как кто-то разговаривает неподалёку. Слышно плохо, но можно прислонить ухо к двери и попытаться подслушать.*",142532,null],[144570,"2026-08-07T13:40:39",17,"Люпен заглядывает в замочную скважину",142532,null],[144571,"2026-08-07T13:40:44",17,"/r +1 Внимание",142532,null],[144574,"2026-08-07T13:41:03",47,"Что за калека? /",142532,null],[144575,"2026-08-07T13:41:34",20,"/r d20+2 пацап пытается прислушаться",142532,null],[144578,"2026-08-07T13:41:49",17,"/Обыватель)",144574,null],[144590,"2026-08-07T13:46:17",9,"*Обрывки разговора который вы уловили:*\n\n\" ... так и знал ... и она? ... ну думаю тут всё понятно ... чёрт, а я думал ... \"",142532,null],[144591,"2026-08-07T13:46:26",20,"/кстати 2, 4, теперь 8...мне кажется на нас проклятие двойки в степени",142532,null],[144594,"2026-08-07T13:46:55",17,"/ Скоро 16 и 24 а дальше...",142532,null],[144595,"2026-08-07T13:47:14",20,"/дай бог",144594,null],[144596,"2026-08-07T13:48:36",17,"Шепотом остальным\n\n— Там минимум двое, что делать будем? Думаю нужно подождать одного и подловить на обходе... С двумя нам точно не справиться быстро. И... Нам нужен кляп, сгоняйте за простынью наверное, ну как вам план? Или есть получше?",142532,null],[144598,"2026-08-07T13:49:35",20,"/на каком у нас примерно расстоянии эти двое? В пределах 60ф?",142532,null],[144601,"2026-08-07T13:50:27",20,"/есть одна идея у меня, если они достаточно близко",142532,null],[144604,"2026-08-07T13:51:58",9,"*Разговаривающие примерно 30-60 футов от двери, инача бы даже обрывки разговора было сложно услышать.*",144598,null],[144605,"2026-08-07T13:53:25",20,"/могу ли я телепатией в их головах через обман+подражание голосу создать иллюзию, что кричать зовут с улицы?",144604,null],[144606,"2026-08-07T13:53:25",17,"/ Сияй БОООООЙ",142532,null],[144610,"2026-08-07T13:54:33",20,"/голоса стражников/смотрителя я должен был уже пары услышать за минуту запомнить",142532,null],[144611,"2026-08-07T13:54:43",20,"/могу подражать уже",142532,null],[144614,"2026-08-07T13:55:34",20,"/+ вроде должно сработать преимущество на бросок, когда выдаю себя за другого",142532,null],[144618,"2026-08-07T13:58:42",9,"//Щас черту гляну, но скорей всего да",142532,null],[144620,"2026-08-07T13:59:34",9,"//Можешь вродь, давай)",142532,null],[144626,"2026-08-07T14:03:10",47,"Я простынь брал. Заявлял что беру полезное всякое",144596,null],[144627,"2026-08-07T14:03:31",20,"- Подождите, возможно сейчас нам...'повезет' *Тихо говорит мальчик, приседая у замочной скважины*\n\n*Рен сосредотачивается, формирую образ голоса и точную фразу. Надо попробовать...*\n\n*Внезапно стражником слышится очень рассерженный голос смотрителя*\n\n\"КТО ПРОПУСТИЛ ЭТУ БЛЯДЬ НА СКЛАД?!! ВЫ ДВОЕ, ХВАТИТ ЛЯСЫ ТОЧИТ, ЖИВО СЮДА!!!\"\n\n/а вот слышится им издалека с улицы или не получился трюк сейчас и узнаем ...",142532,null],[144628,"2026-08-07T14:03:59",20,"/r +d20+3",142532,null],[144630,"2026-08-07T14:04:07",20,"/сюда",142532,null],[144631,"2026-08-07T14:04:52",47,"/19/18 ты что за везучий сук? Я в шоке. Мне везунчика приходилось ебашиться, иначе хреново всё(",142532,null],[144632,"2026-08-07T14:05:12",17,"/ Всё нормально, раз в год и БООООЙ делает грязь",142532,null],[144633,"2026-08-07T14:05:12",20,"/ты вообще видел все предыдущие броски?)",144631,null],[144634,"2026-08-07T14:05:29",47,"/да",142532,null],[144641,"2026-08-07T14:11:24",9,"//22 выпало, говортл же, двойки",142532,null],[144645,"2026-08-07T14:14:40",9,"*Слышится топот ног.*\n\nОдин голос — Стоп, какой склад, где Фалкон, он же говорил.\n\nВторой — Наверное в оружейном, пошли проверим, я тоде его слышал, точно не показалось.\n\n*Слышится топот ног в другию сторону и затихает.*",142532,null],[144649,"2026-08-07T14:16:33",20,"- Говорил же повезёт.. *На секунду на лице мелькает острая самодовольная усмешка, мало подходяшая зашуганому пацану, прежде чем мальчик оборачивается к вам с прежним нерешительным видом ребенка*\n\n- К-кажется они ушли...нам нужно спешить!",142532,null],[144651,"2026-08-07T14:17:13",20,"/ждём всех и побег?",142532,null],[144652,"2026-08-07T14:17:23",17,"/ Ждём и побег!",142532,null],[144656,"2026-08-07T14:34:03",17,"Крадёмси",142532,null],[144657,"2026-08-07T14:35:37",47,"/ну шагаю держась за Конрада",142532,null],[144661,"2026-08-07T14:45:16",17,"/Куда",144657,null],[144662,"2026-08-07T14:45:24",17,"/Мы ждём чтобы выбежать все у двери уже",142532,null],[144663,"2026-08-07T14:45:31",17,"/ Когда все будут тикаем",142532,null],[144669,"2026-08-07T14:49:36",31,"Я вернулся/",142532,null],[144670,"2026-08-07T14:49:52",17,"/ Hard",142532,null],[144671,"2026-08-07T14:50:11",17,"Люпен открывает дверь рывком\n\n— ВАЛИМ!",144649,null],[144672,"2026-08-07T14:53:03",31,"Тащу Сайна на себе, бежим за Люпеном",142532,null],[144674,"2026-08-07T14:54:04",20,"*Пацан тикает вместе со всеми. На улице прям быстро осмотреться бы*",142532,null],[144689,"2026-08-07T15:24:22",47,"/не мешаю, помогаю наоборот, как могу",142532,null],[144741,"2026-08-07T16:19:13",31,"Хард писал что пока занят ИРЛ/",142532,null],[144756,"2026-08-07T17:05:13",20,"/с лёгким запозданием - морочим головы работягам стражникам",142532,null],[144757,"2026-08-07T17:06:54",9,"//Всё, тоно доигрался пацан, слишком близко он и похож. Я скоро освобожусь вести, но перед этим.",144756,null],[144758,"2026-08-07T17:08:01",9,"*Рен чувствует на мгновение взгляд на себе изниоткуда, в момент когда он обманул стражу. Это ощущение как появилось так и исчезло за мгновение.*",142532,null],[144759,"2026-08-07T17:08:27",31,"Это был взгляд ТПК/",142532,null],[144761,"2026-08-07T17:09:02",20,"/страшно очень страшно...",142532,null],[144763,"2026-08-07T17:09:48",17,"// Он и твою жену заберёт, это точно он",142532,null],[144764,"2026-08-07T17:11:03",47,"/вау",142532,null],[144765,"2026-08-07T17:11:16",47,"/как же похуй. Лишь бы щас нож найти и снять маску в ближайшее время",142532,null],[144768,"2026-08-07T17:14:05",31,"Бля, я прямо вижу, находишь нож, кидаешь на ловкость рук, выпадет 1, и Хард со смаком описывает как ты себе срезаешь лицо//",144765,null],[144771,"2026-08-07T17:15:35",47,"/так делать буду не я",144768,null],[144772,"2026-08-07T17:15:38",47,"/я чо, псих",142532,null],[144774,"2026-08-07T17:15:44",47,"У меня вы есть/",142532,null],[144803,"2026-08-07T17:24:20",9,"//Нож был на столе, хороший",142532,null],[144804,"2026-08-07T17:24:49",9,"//Но не кинджал, кожу дублёную с трудом, нож как нож",142532,null],[144811,"2026-08-07T17:30:45",47,"/но считается при использовании так, будто я им владею, верно?",142532,null],[144812,"2026-08-07T17:30:49",47,"Ножи, кинжалы/",142532,null],[144813,"2026-08-07T17:30:59",47,"Так, на всякий",142532,null],[144816,"2026-08-07T17:31:15",17,"/Я это не заметил",144803,null],[144818,"2026-08-07T17:31:50",31,"Только если ты его себе во владение прописал обыватель может владеть одним ростым оружием, например кинжалом/",144811,null],[144819,"2026-08-07T17:32:01",17,"Люпен возвращается перед этим назад и берёт нож со стола\n\n— Парень, стой не дергайся ножик нашел, давай сниму эту маску с тебя",142532,null],[144821,"2026-08-07T17:33:32",20,"/тебе его пацан вместе с лутом остальным его в сумку положил",144816,null],[144822,"2026-08-07T17:35:35",17,"/ А че пацан не сказал)))",142532,null],[144823,"2026-08-07T17:36:07",20,"/я думала ты видел что он в сумку клал)))",144822,null],[144825,"2026-08-07T17:36:53",17,"/ Hard нужно что то кидать чтобы ножиком снять кожаную маску с нашего друга?",142532,null],[144836,"2026-08-07T17:39:01",47,"/тогда я бы ножами владел, как вор, я просто не видел в оружии вкладки Ножи. Только кинжалы",144818,null],[144840,"2026-08-07T17:39:15",17,"/ Всё верно кинжалы = ножи",144836,null],[144843,"2026-08-07T17:39:32",47,"- Помогите ему пожалуйста. Чтобы аккуратно было! - умоляет Сайн",142532,null],[144844,"2026-08-07T17:39:38",17,"/ Владение даёт добавить +1 БМ как будто бы на это фулл похуй",142532,null],[144845,"2026-08-07T17:39:53",47,"/3+1= 4 . Для обывателя как будто дохуя",142532,null],[144846,"2026-08-07T17:39:53",17,"— Не ссы, сделаю всё в лучшем виде, тут проволоки дохера",144843,null],[144847,"2026-08-07T17:40:08",17,"/ Ну хз у меня -1 на метком стрелке планируется)))",144845,null],[144852,"2026-08-07T17:41:54",20,"*Пацан готов помочь, будет страховать*",142532,null],[144854,"2026-08-07T17:43:40",47,"/приступайте!",142532,null],[144974,"2026-08-07T18:26:23",31,"Hard играть то будем? А то я через часика полтора спать пойду/",142532,null],[144975,"2026-08-07T18:26:32",31,"Hard",142532,null],[144977,"2026-08-07T18:28:01",47,"/так может он ждёт пока Коля ловкость кинет?",142532,null],[144978,"2026-08-07T18:28:04",47,"С преимуществом/",142532,null],[144980,"2026-08-07T18:28:40",9,"//Го тогда, но кожа дублёная",142532,null],[144981,"2026-08-07T18:29:00",9,"//Так что считайте броню кромсаете)",142532,null],[144982,"2026-08-07T18:29:16",47,"/то есть кд 12?",142532,null],[144983,"2026-08-07T18:30:01",9,"// 12 минимум, 15 чтобы тебя не порезать при этом",142532,null],[144988,"2026-08-07T18:32:17",9,"*За дверью небольшой зал, столы, лестница на верх, знамёна. Вы не поросто в темнице, она была под казармой стражи! Повезло что на этот момент здесь были ток двое и их удалось обмануть, но кто-то может прийти в любой момент.*",142532,null],[144989,"2026-08-07T18:32:50",47,"@dunchev ждём твоего Мега броска",142532,null],[144990,"2026-08-07T18:33:09",31,"У меня есть владение кинжалом, могя я попробовать/",142532,null],[144994,"2026-08-07T18:33:29",9,"/roll 1d5 кину на вашу удачу, определить исход что будет где, пять вариантов",142532,null],[144997,"2026-08-07T18:34:00",47,"Обычно минимальный плохо, максимальный идеально...",142532,null],[144998,"2026-08-07T18:34:12",47,"Кинь ты",144990,null],[145000,"2026-08-07T18:34:22",9,"*Кажется сейчас час пик, стража занята своими делами.*",144988,null],[145003,"2026-08-07T18:34:36",47,"/уху!",142532,null],[145004,"2026-08-07T18:34:42",31,"/roll d20+4 3 от ловкости, 1 от владения",142532,null],[145007,"2026-08-07T18:34:52",31,"Зарезал(((//",142532,null],[145008,"2026-08-07T18:34:57",20,"/преимущество",142532,null],[145010,"2026-08-07T18:35:01",20,"/от помощи",142532,null],[145012,"2026-08-07T18:35:11",31,"/roll d2+4",142532,null],[145014,"2026-08-07T18:35:15",9,"//Преимущество давали, пацан помогает, а Люпен наверное на стрёме",142532,null],[145016,"2026-08-07T18:35:21",31,"/roll d20+4",142532,null],[145018,"2026-08-07T18:35:25",47,"Ура! /",142532,null],[145019,"2026-08-07T18:35:35",31,"Урон кидать?/",142532,null],[145021,"2026-08-07T18:35:45",9,"//Описывай как маску срезал не поранив чувака",145017,null],[145022,"2026-08-07T18:35:47",47,"- Я... Вижу? - видео лицо Сайна",142532,null],[145025,"2026-08-07T18:36:15",31,"Быстрыми ловкими движениями Конрад срезает маску с Сайна. Нож уж больно хорошо наточен",142532,null],[145028,"2026-08-07T18:36:51",31,"Смотрю на лицой Сайна\n\n- да, братец, в маске ты был симпатичее",142532,null],[145030,"2026-08-07T18:36:56",47,"Лицо выражает счастье",142532,null],[145032,"2026-08-07T18:37:40",17,"/ Сори в меня инет говна. Я врятли сногу щас быть активным",142532,null],[145033,"2026-08-07T18:38:27",47,"Не обращая внимание на Конрада, Сайн ощупывает себя. Он явно рад видеть. Хлопает по спине друга и говорит:\n- Всё, теперь я не помеха! По-быстрому обыскиваем помещение на жрачку и что-то полезное и сьебываем - напоминаю, час пик, все заняты. Пару минут надеюсь успею",145028,null],[145034,"2026-08-07T18:38:36",47,"@QURTZZ поможешь?",142532,null],[145035,"2026-08-07T18:38:40",17,"/r +d20+3 Это ловкость",142532,null],[145038,"2026-08-07T18:38:47",47,"/ну или наоборот, я помогу в вопросе внимательности",142532,null],[145040,"2026-08-07T18:39:55",20,"/r +d20+2 внимание очень быстро",142532,null],[145043,"2026-08-07T18:40:15",31,"У меня внимательность не очень))//",142532,null],[145045,"2026-08-07T18:40:25",47,"/мальчугану короче помог",142532,null],[145046,"2026-08-07T18:40:32",47,"Hard",142532,null],[145047,"2026-08-07T18:40:51",47,"Надо будет пообщаться персам, узнать у кого, что хорошо получается... /",142532,null],[145048,"2026-08-07T18:41:13",47,"/но это на коротком отдыхе",142532,null],[145049,"2026-08-07T18:41:24",9,"*Снаружи какой-то шум, возможно сюда возвращаются те двоя.*",145041,null],[145050,"2026-08-07T18:41:32",47,"/я владею, портняжным, ядоварением и взломом... Хм",142532,null],[145051,"2026-08-07T18:41:47",47,"/мы нашли что-то? В помещение? Хотя бы ещё один нож",145049,null],[145052,"2026-08-07T18:42:04",20,"- Нужно спешить, быстрее! Они сейчас вернуться\n\n*Мальчик вам всех торопит к двери*",145049,null],[145053,"2026-08-07T18:42:18",47,"Провожу пальцем по шее намекая на то, чтобы неплохо было прижать стражников",142532,null],[145054,"2026-08-07T18:42:20",20,"/Нет времени на лут",142532,null],[145055,"2026-08-07T18:42:35",9,"*На столе кружки, миски, пустые подносы, но немного. Похоже уже отобедали, это просто зал. Вы находите кусок сыра который не тронули.*",142532,null],[145056,"2026-08-07T18:42:45",47,"Спиздил",145055,null],[145059,"2026-08-07T18:43:02",47,"Сыр/",142532,null],[145060,"2026-08-07T18:43:16",20,"- слишком рискованно*пацан быстрее торопит вас всех к двери*",145053,null],[145063,"2026-08-07T18:43:45",47,"Тяжкий вздох, бегу за мальчуганом. Наготове вьебать по горлу, чтобы чувак сказать нихера не мог крикнуть",142532,null],[145064,"2026-08-07T18:43:48",9,"*Выходнаружу, несколько дверей вдругие помещения помимо сторожки и лесница на верх. Шум снаружи, туда и ушли те двоя.*",145052,null],[145065,"2026-08-07T18:43:59",47,"/думаю интелект +2 позволяет знать базовую анатомию",142532,null],[145067,"2026-08-07T18:44:07",20,"/есть окна?",145064,null],[145069,"2026-08-07T18:44:53",9,"*Пара небольших бойниц на одной из стен, туда не пролезет взрослый. Рен? Да, пролезет.*",145067,null],[145071,"2026-08-07T18:45:22",20,"/пу пу пу",145069,null],[145073,"2026-08-07T18:45:43",9,"//Моральные деллемы, да, они",145071,null],[145074,"2026-08-07T18:46:15",20,"/насколько быстро я могу вылезти и обратно залезть в окно?\n/За ход справлюсь?",145073,null],[145075,"2026-08-07T18:46:40",20,"/или хотя бы 2",142532,null],[145076,"2026-08-07T18:47:01",47,"/я могу просто сьебать. Пох вобще",142532,null],[145077,"2026-08-07T18:47:06",9,"//Два, они узковаты",142532,null],[145078,"2026-08-07T18:47:10",47,"/никаких моральных диллем",142532,null],[145083,"2026-08-07T18:47:42",20,"/ну в целом 12 секунд. Пойдет",145077,null],[145091,"2026-08-07T18:48:38",20,"- Факел, быстро *Рен хватает из сумки Люпена факел и трутницу, спеша к бойницы*\n\n/Какие здания там поблизости и есть там кто рядом?",142532,null],[145104,"2026-08-07T18:51:29",47,"- Может хлопнем их и думать нехрен? Пока их хватятся... А? - Сайн смотрит на реакцию. И если никто не согласен, то Сайн похуистично побежит нп 2 этаж",142532,null],[145109,"2026-08-07T18:53:25",9,"*Вроде нет никого прям рядом, но не видно что по бокам, надо высунуть голову и посмотреть.*",145091,null],[145115,"2026-08-07T18:54:14",20,"/может тогда уже завтра продолжим? А то наверное для такого нужны все",142532,null],[145117,"2026-08-07T18:54:29",47,"/согласен",142532,null],[145126,"2026-08-07T18:57:08",9,"//Ну, бой или вы избежите его, за треню навыков не волнуйтесь, я вам дам что логичнее в зависимости от действий когда сменится сцена. Как если бы кто учил вас, тоесть умения/владения/спасы будущего класса. Я щитаю пропущенные дни.",142532,null],[145136,"2026-08-07T19:01:35",31,"- не думаю что это хорошая идея. С голыми руками на воорженных охранников лезть это глупо.",145104,null],[145221,"2026-08-07T19:53:06",17,"/ а у самого д4+ ловкость азахах",145136,null],[145224,"2026-08-07T19:53:16",17,"/ я в бассейне сори",142532,null],[145228,"2026-08-07T19:54:48",47,"/ 1-1 сила 😁",145221,null],[145244,"2026-08-07T20:04:21",9,"🎺🪉ВДОХНОВЕНИЯ🪇🥁\n\n— Люпен 2д4\n\n— Рен 4д4\n\n— Конрад 1д4\n\nЭти вдохновения — это доп кубы. Вы можете докинуть эти д4 к любому броску, будь то атака, спас, проверка и так далее, но они тратятся, тратьте с умом. На один бросок — один куб. (Говорите когда их добавляете)",142532,null],[145253,"2026-08-07T20:06:35",9,"//Так, накинул вам чутка, думал по 4д4 дать, но многие из вас делали крутое или мне помогли так что у вас на куб больше. У меня такие вдохновы. Ну и да, короче, не хочу чтобы вы померли простос поэтому дяржитя",142532,null],[145375,"2026-08-07T20:48:52",17,"Люпен видя этот жест\n\n— Нельзя, надо валить, ввяжесмся нас как свинец заколят!",145053,null],[145378,"2026-08-07T20:50:20",17,"— Нет, Сайн, я против попытки накуканить вооруженных стражников, нам очевидно пиздец. Не глупи...",145104,null],[145381,"2026-08-07T20:51:15",20,"- Я смогу вылезти в бойницу - если не попадусь удастся поджечь что-то рядом и быстро вернуться, это отвлечет их. Это план 1.\n- План второй. Сейчас разгар дня - на втором этаже может никого не быть - если отступить туда с большой вероятностью эти двое пройдут мимо обратно на свои места. Мы успеем спуститься и сбежать",142532,null],[145382,"2026-08-07T20:51:20",17,"— Действуй пацан. Мы пока тут заныкаемся. Подпали чё нибудь рядом но в стороне ....",142532,null],[145388,"2026-08-07T20:52:14",17,"— Со второго этажа выше прыгать, и ножки точно переломаем, давайте лучше как то как ужики раз раз по травке",145381,null],[145394,"2026-08-07T20:53:19",20,"/как интересно может сработать помощь на скрытность...",142532,null],[145395,"2026-08-07T20:53:35",20,"/преимущество с +2 на проверку не помешало бы",142532,null],[145397,"2026-08-07T20:54:12",20,"/хотя может вдохновение сможет зарешит",142532,null],[145398,"2026-08-07T20:54:22",17,"— Стой пацан. Давай вот\n\nЛюпен с пола собирает пылищу и грязь. Мажет пацану лицо.",142532,null],[145400,"2026-08-07T20:54:37",17,"— Может подумают ты... Э... Нищий",142532,null],[145401,"2026-08-07T20:54:50",17,"/ Помощь",142532,null],[145409,"2026-08-07T20:56:10",20,"- ...близко к правде *Кивает пацан и готовится провернуть план с бойницей. А заодно прокручивает отговорки, если поцмают*\n\n- Если меня поймают - возвращайтесь в камеры как можно скорее. Я уж отговорюсь",145400,null],[145415,"2026-08-07T20:56:45",20,"/r +d20+1 скрытно, помолимся",142532,null],[145417,"2026-08-07T20:56:53",20,"/еба",142532,null],[145419,"2026-08-07T20:57:12",20,"/я походу только 2 и 19 кидать буду в этой кампании",142532,null],[145425,"2026-08-07T20:58:39",9,"//Думаю алексея ждать, сорян",142532,null],[145427,"2026-08-07T20:59:22",20,"/вообще без вопросов",142532,null],[145428,"2026-08-07T20:59:39",20,"/задел на завтрашний эпик побег пусть будет",142532,null],[146621,"2026-08-08T09:53:33",47,"Hard",142532,null],[146622,"2026-08-08T09:53:39",47,"@PaIIasCat @dunchev @QURTZZ",142532,null],[146623,"2026-08-08T09:53:51",47,"Поставьте + и время со скольки до скольки удобно, пожалуйста",142532,null],[146624,"2026-08-08T09:54:09",47,"+ с текущего и до вечера. Перерыв в 12-13:00 только",142532,null],[146625,"2026-08-08T09:54:20",47,"И +- пока шагать по 10 минут туда сюда буду",142532,null],[146626,"2026-08-08T09:55:04",17,"Я в выходные могу быть занят и времени точного не знаю извини\n\nЯ с семьёй туда сюда развлекаться и отдыхать в будни у меня четко только",142532,null],[146627,"2026-08-08T09:56:22",47,"Печально(",146626,null],[146628,"2026-08-08T09:56:36",20,"/я по времени в выходные могу весь день с непредвиденными перерывами",142532,null],[146629,"2026-08-08T09:59:53",47,"/давайте тогда по возможности, сейчас ждём кого? Конрада?",142532,null],[146630,"2026-08-08T10:00:34",47,"/я предлагаю пост от него и слегка продолжить, как только будет момент: \"хотим двигаться дальше\" Ждём того, кого не было он говорит: \"А я в это время делаю\"",142532,null],[146636,"2026-08-08T10:27:01",31,"Я тоже в выходные больше занят домом и семьёй. Думаю где-то с 15-00 по Москве буду более менее доступен",142532,null],[146643,"2026-08-08T11:27:15",47,"/тогда очень жду от тебя поста",146636,null],[146679,"2026-08-08T15:05:59",31,"@cirson @dunchev Hard @cirson парни, я тут, готов продолжить))//",142532,null],[146681,"2026-08-08T15:10:09",31,"А, ну да, и не парни///",142532,null],[146684,"2026-08-08T15:34:28",17,"/ Леша мы ждём твоего поста",142532,null],[146685,"2026-08-08T15:34:35",17,"/ у меня есть часа 2-3",142532,null],[146686,"2026-08-08T15:34:40",17,"/ готов жёстко поиграть",142532,null],[146687,"2026-08-08T15:35:14",31,"Да какой пост, я так понял что мы ждём пока Рен вылезет из бойницы и не отсвечиваем, разве нет?/",142532,null],[146688,"2026-08-08T15:36:27",20,"/я прокинула скрытность, ждём что из этого вышло",142532,null],[146689,"2026-08-08T15:39:00",17,"/ Давайте так. Каждый опишет что делает когда пацан полез наружу поджигать склады",142532,null],[146690,"2026-08-08T15:39:32",17,"— Если сюда зайдут, лучше чеб нас не заметили сразу, прячьтесь!\n\nЛюпен прячется в темном углу под кроватью стражника",142532,null],[146691,"2026-08-08T15:39:45",17,"/ Hard жив?",142532,null],[146692,"2026-08-08T15:40:58",31,"Конрад встает за дверью, если кто зайдет, уебу с кулака по черепушке/",142532,null],[146693,"2026-08-08T15:41:24",31,"А, у меня же еще и нож есть, который с Сайна маску срезал/",142532,null],[146694,"2026-08-08T15:41:51",17,"/ Дай мне пожалуйста",146693,null],[146695,"2026-08-08T15:42:06",17,"— Ножик верните кстате! Катайте под кровать!",142532,null],[146696,"2026-08-08T15:42:14",31,"Передаю нож Крысе",142532,null],[146721,"2026-08-08T17:00:32",9,"//Такс, собираемся и кто чего делает, может. Но михи нет, похоже.",142532,null],[146722,"2026-08-08T17:01:03",31,"Рен бросал на скрытность, мы с Крысой затаились/",146721,null],[146724,"2026-08-08T17:04:29",20,"/у меня вот заявка висит, бросок был с модификатором 20 на скрытность",145409,null],[146728,"2026-08-08T17:10:23",17,"/ Заявка от пацана щас в приоритете мы все спрятались отыграй с паллас сцену сольную",146721,null],[146730,"2026-08-08T17:11:52",9,"//Скрытность 20 выглянуть из бойницы?",142532,null],[146736,"2026-08-08T17:13:18",20,"/Выглянуть и если никого нет выбраться",146730,null],[146740,"2026-08-08T17:14:36",9,"*Перед бойницей здания, слышны разговоры людей, строевые шаги и точно ли Рен выглядывает слыша всё это?*",142532,null],[146743,"2026-08-08T17:16:16",20,"/так разговоры вроде были перед дверью...\n/Ладно, надеюсь скрытности хватит на это",146740,null],[146744,"2026-08-08T17:16:25",20,"/да, выглядываю немного",142532,null],[146750,"2026-08-08T17:18:49",47,"На 2 этаж - съебал осмотреться",142532,null],[146751,"2026-08-08T17:19:00",47,"/r d20-1 eнах помеху",142532,null],[146753,"2026-08-08T17:19:05",47,"Угу",142532,null],[146754,"2026-08-08T17:19:09",9,"/roll 1d2 учача твоя",146744,null],[146756,"2026-08-08T17:19:14",47,"/есть желающие помочь?",142532,null],[146757,"2026-08-08T17:19:47",31,"Помогу, чем?/",146756,null],[146758,"2026-08-08T17:20:27",9,"*Выглянув Рен увидел месных, шагающих солдат по делам и все такое, людей много и все в делах, иначе бы они легко его заметили, торчащую мнгновение из бойницы голову пацана.*",146754,null],[146764,"2026-08-08T17:22:19",20,"/короче незаметно не выбраться чтобы поджог провернуть?",146758,null],[146773,"2026-08-08T17:24:24",9,"*Просто коридор с десятками комнат по обеи стороны, с одной стороны конца коридора окно и с другой тоже. Есть подсвечник на тумбе по пути, пару полок но на них всякий хлам, как ткани знамен, и кажется раскрашенный щит с двумя рапирами на стене? Точно две рапиры.*",146752,null],[146774,"2026-08-08T17:24:31",47,"/Крит провал отменить",146757,null],[146777,"2026-08-08T17:25:22",47,"Ткани беру! Подсвечник - беру! Рапиры и щит не беру. Кажется страшно и бесполезно",146773,null],[146782,"2026-08-08T17:26:44",9,"//Ну ладно, не зочешь как хош",142532,null],[146783,"2026-08-08T17:26:47",17,"/ Хард у меня вопрос, мы были на 1 этаже? Рен может вылезти через бйоницу и спустится на землю и потом залезть вообще? Этио возможно? Может мы не поняли",142532,null],[146784,"2026-08-08T17:27:39",20,"/я так поняла что мы на первом, пролезть могу но там слишком дофига народу, чтобы прокрасться сработало",142532,null],[146785,"2026-08-08T17:27:42",9,"//Он может выглянуть, может выбраться, может пробежать 50-60 футов к ближайшим домам почти перед людьми вылезши из бойниц казармы и так далее",142532,null],[146786,"2026-08-08T17:28:17",20,"/бросок Скрытности на это ещё будет работать или по новой?",146785,null],[146787,"2026-08-08T17:28:21",9,"//Его не заметили когда он высунул голову осмотреться и понять что народу много, повезло что не заметили",142532,null],[146790,"2026-08-08T17:29:04",17,"/ Народу много, ммм",142532,null],[146791,"2026-08-08T17:29:06",9,"//Скрытность на открытой местности? Это как, вродь не работает она в чистом поле",146786,null],[146792,"2026-08-08T17:29:21",17,"/ Бочку надо))",142532,null],[146793,"2026-08-08T17:29:25",47,"Высота второго этажа, окна есть? Из знамен можно связаться верёвку? Есть выходящие за гарнизон окна?",142532,null],[146796,"2026-08-08T17:29:55",47,"/подхожу к окнам и проверяю",142532,null],[146797,"2026-08-08T17:30:05",17,"— Пацан, ну че там? Может кинуть факел отсюда в соседний дом? на крышу! Или далековато?\n\nЛюпен из под кровати окликает парня",142532,null],[146799,"2026-08-08T17:30:07",20,"*Рен быстро оглядывается по сторонам, запоминая расположение зданий и людей.*\n\n- слишком много...не вариант",142532,null],[146801,"2026-08-08T17:30:52",20,"*Засовывает голову обратно, пока не заметили*",142532,null],[146802,"2026-08-08T17:31:00",20,"/сколько минут до обхода?",142532,null],[146803,"2026-08-08T17:32:42",9,"*Со второго этажа более десяти футов высоты, можноспрыгнуть но будет больно, использовать знамя чтобы спуститься безопасно? Возможно, но много народу с одной стороны селения, на противоположном окне коридора стена с охраной. И ты видишь как кажется ко входу идут 3 человека.*",146793,null],[146804,"2026-08-08T17:33:10",9,"//Так @dunchev и @QURTZZ вы где и что сейчас это важно",142532,null],[146805,"2026-08-08T17:34:42",17,"/Я лежу под кроватью стражника около ночного горшка",142532,null],[146806,"2026-08-08T17:35:31",47,"Хм... Делаю пока верёвку, стена это внутренность гарнизона ещё, или уже свобода? Сколько до стены +-?",146803,null],[146807,"2026-08-08T17:35:51",31,"Прячусь за дверью в той же комнате что и Крыса под кроватью/",146804,null],[146808,"2026-08-08T17:36:32",9,"*До стены 50-60 футов на глаз, на стене стражи, меж стеной и твоим положением снуют люди.*",146806,null],[146811,"2026-08-08T17:40:09",47,"\"Бля, надо было просто их ебнуть. Переодеться и сбежать под шумок\" Думает Сайн.",142532,null],[146812,"2026-08-08T17:40:27",47,"Прячусь на 2 этаже готовый бить ножом",142532,null],[146813,"2026-08-08T17:40:33",47,"Ладно рапиру снял",142532,null],[146814,"2026-08-08T17:40:49",9,"//Оба с преимуществом скрытность киньте, могди друг другу преим нарешать так что без тумба юмба киньте",146807,null],[146816,"2026-08-08T17:41:41",31,"/roll +d20+3",146814,null],[146818,"2026-08-08T17:42:04",9,"*Рапиры снята с другой рапирой и сщитом, это настенное украшение, сплавленно частичнг в кучу. Можно попытаться отлимить рапиру.*\n\n//Проверка силы 12 чтобы оторвать припаянную к щиту рапиру",146813,null],[146819,"2026-08-08T17:42:18",47,"/r d20-1",142532,null],[146822,"2026-08-08T17:42:26",47,"- Не могу, поможешь?",142532,null],[146827,"2026-08-08T17:44:08",20,"/там вроде на втором этаже он один",146822,null],[146830,"2026-08-08T17:45:13",17,"/r +d20+4 Скрытность Люпена",146814,null],[146833,"2026-08-08T17:45:44",9,"//Ты где щас",146827,null],[146836,"2026-08-08T17:47:09",20,"/был у окна, но если успеваю тоже пытаюсь спрятаться под кроватью, раз на улицу выбраться не вариант",146833,null],[146837,"2026-08-08T17:47:26",47,"Конрад вроде что-то там нет?",146827,null],[146838,"2026-08-08T17:47:52",20,"/он под кроватямт вместе с Люпеном",146837,null],[146839,"2026-08-08T17:48:53",31,"За дверью, а не под кроватью/",146838,null],[146841,"2026-08-08T17:49:27",17,"Шепотом\n\n— Что полезного увидал пацан? Зря мы сунулись посреди дня, да? Эх идиоты, надо было ночи ждать...",142532,null],[146844,"2026-08-08T17:50:22",9,"//Тож скрыт, хотя пусть 20 будет",146838,null],[146846,"2026-08-08T17:51:37",20,"*Рен юркает рядом под соседнюю кровать*\n\n- Очень много людей, явно есть строгие патрули...я примерно запомнил расположение зданий, но, скоро обход - заметят что нас нет. И вещи пропали ...",146841,null],[146847,"2026-08-08T17:52:09",17,"— Да, какие мысли? Нападём на обходчика? А если он не один?",142532,null],[146848,"2026-08-08T17:52:10",47,"Тогда прячусь где-нибудь здесь. На втором этаже. В виде рычага, чтобы отлепить, использую трубу снятую ранее (знал же, что пригодится)",142532,null],[146849,"2026-08-08T17:52:13",9,"*В здание  приходят 4ре охранника.*\n\nСтраж темницы — Я щас своих проверю.\n\nВетеран — Не гоже, не чистое что-то тут, я с тобой. А вы двоя наверх!\n\n*Двое топают по ступеням, и двое идут в сторожку, дверь распахивается её будто с ноги выбили, Конрада немного ей ударили но не заметили как и двоих под кроватью.*\n\n//Конраду 1 дробящего дверью за которой прятался",142532,null],[146852,"2026-08-08T17:52:53",9,"//В двери по бокам или за тумбу?",146848,null],[146853,"2026-08-08T17:53:18",17,"Глазами пацану демонстрирую \"нам пиздец\"",142532,null],[146854,"2026-08-08T17:53:54",47,"А я отломал с трубой?",146852,null],[146856,"2026-08-08T17:54:30",9,"//Где труба",146854,null],[146858,"2026-08-08T17:55:26",9,"*Двоя идут мимо вас внищ по ступеням проверять. Один ваш охранник которого уже видели а второй гремит колючугой и железными сапогами.*",146853,null],[146861,"2026-08-08T17:55:40",17,"Наблюдаю внимательно куда ветеран пойдет\n\nЛюпен понимал, что осталась может быть минута до того, как стражник не обнаружит их в камерах и не заорёт \"Тревога\"\n\nОн пытался найти какойто выход\n\nВ мыслях крутилось отвлечь ветерана и выбежать через дверь наружу",142532,null],[146864,"2026-08-08T17:56:07",17,"/ Ааа ветеран тоже ушел вниз",146858,null],[146865,"2026-08-08T17:56:21",17,"/ Ну че Пацан, Конрад, Тикаем, Сайну соболезную",142532,null],[146866,"2026-08-08T17:56:26",20,"/ага, телепатический трюк не сработает уже (",146864,null],[146869,"2026-08-08T17:56:42",17,"/ Сайн телепорт вроде имеет, удачи братан",142532,null],[146870,"2026-08-08T17:56:51",17,"/ А нас снаружи ждут еще 10 стражников у двери))",142532,null],[146871,"2026-08-08T17:56:56",31,"Надо вырубить того что у нас в комнате, а тех двоих закрыть в темнице. На ту же железяку, что мы выломали/",146858,null],[146873,"2026-08-08T17:57:20",17,"Когда они начинают спускаться в казекматы шепотом пацану\n\n— Последний шанс, валим!",142532,null],[146874,"2026-08-08T17:57:22",20,"/мне кажется нас отпизьдят сапогами",146871,null],[146876,"2026-08-08T17:57:33",31,"Скорее всего/",146874,null],[146877,"2026-08-08T17:57:36",9,"//Я не могу понять откуда труба?",142532,null],[146878,"2026-08-08T17:57:48",9,"//И типа, прут у вас, это не он",142532,null],[146879,"2026-08-08T17:58:18",20,"*Пацан кивает, готовый следовать за старшим*",146873,null],[146880,"2026-08-08T17:58:20",17,"— Давай тут нашумим и выбежим за дверь? Может разбить вазу?",142532,null],[146881,"2026-08-08T17:58:38",17,"— Это чуть оттянет момент... Наверно",142532,null],[146882,"2026-08-08T17:58:45",9,"//Вы их пропускаете мимо вас и ничего не делаете пока мимо идут?",142532,null],[146883,"2026-08-08T17:58:55",17,"/ Дыа",142532,null],[146884,"2026-08-08T17:59:02",20,"- Поджечь",146880,null],[146885,"2026-08-08T17:59:16",9,"*Шаги исчезли внизу, несколько мгновений тишины.*",142532,null],[146886,"2026-08-08T17:59:27",20,"/просто бежим",142532,null],[146887,"2026-08-08T17:59:30",9,"//У ход перед...",142532,null],[146889,"2026-08-08T18:00:14",20,"/короче я действие трачу на факел и поджог, кто-нибудь хватайте пацана на буксир и рывком бежим",142532,null],[146890,"2026-08-08T18:00:31",9,"//Кровать поджигаешь?",142532,null],[146891,"2026-08-08T18:00:36",31,"Хватаю пацана после того как он бросил факел и валим",146889,null],[146893,"2026-08-08T18:03:14",9,"//Перемещение осталось, 15 встать, и 15 пробежать но да, несут похоже",146890,null],[146895,"2026-08-08T18:04:32",9,"//Вы подскажите что за труба и где Сайн достал её",142532,null],[146896,"2026-08-08T18:04:47",20,"/он про прут клетки",146895,null],[146899,"2026-08-08T18:06:13",9,"//Так он у вас? Или у него, наверное у него тогда",142532,null],[146902,"2026-08-08T18:07:16",9,"//Я щас вам дам магический предмет обычный. \"Этот прут может быть в 2 разных местах одновременно\" чисто по приколу если онг раздвоилось",142532,null],[146905,"2026-08-08T18:08:00",9,"//Но нет, у кого прут понять бы",142532,null],[146906,"2026-08-08T18:08:08",17,"/ у меня нож и Рема факел у Конрада кулаки",142532,null],[146907,"2026-08-08T18:08:15",17,"/ Прут у Сайна",142532,null],[146909,"2026-08-08T18:09:09",9,"//Опишите момент ваш в троём, хватаете пацана и бяжите?",142532,null],[146912,"2026-08-08T18:09:18",20,"/факел я так полагаю остался гореть на кровати, но у нас ещё там пара в мешке",146906,null],[146923,"2026-08-08T18:10:21",17,"Люпен вылазит из под кровати и шепчет конраду\n\n— Тикаем. Пацан под дом можно влезть где то иди кусты, что то!?",142532,null],[146926,"2026-08-08T18:10:35",17,"/ Давайте не будем брать на плечи пацана",142532,null],[146927,"2026-08-08T18:10:36",47,"Из тюрьмы, вырвали",146856,null],[146928,"2026-08-08T18:10:39",17,"/ он норм бегает",142532,null],[146931,"2026-08-08T18:11:04",47,"Ну прут",146878,null],[146932,"2026-08-08T18:11:10",17,"/ Идеальная память позволит нам точно найти место куда сразу рвануть?",142532,null],[146933,"2026-08-08T18:11:14",17,"/ пацан помнит все",142532,null],[146934,"2026-08-08T18:11:35",20,"/по идеи должна, он специально оглядывался запоминал",146932,null],[146937,"2026-08-08T18:11:42",9,"//Помнит что из бойниц, а из дверей не выглядывал",146932,null],[146945,"2026-08-08T18:12:32",17,"/ Да там же угол обзора норм позволяет",142532,null],[146947,"2026-08-08T18:12:46",17,"/ Ладно хард есть там кусты из обзора бойницы? Пацан щас скажет куда и мы туда",142532,null],[146949,"2026-08-08T18:12:54",9,"*Трио почти добежало до двери, как слышите громкий голос из темницы, командирский.*\n\n\"Всем подьём! Пленники сбежали!!!\"",142532,null],[146950,"2026-08-08T18:13:05",17,"/ Да не могли они так быстро))",142532,null],[146951,"2026-08-08T18:13:08",17,"/ Ладно",142532,null],[146952,"2026-08-08T18:13:11",9,"//Щас вам покажу чё куда",146947,null],[146967,"2026-08-08T18:15:36",9,"Бойницы зеленые, синий выход + -",142532,null],[146976,"2026-08-08T18:16:48",17,"/ Бежим налево там хоть видели что то?",142532,null],[146979,"2026-08-08T18:17:06",47,"Я отломал рапиру?",142532,null],[146982,"2026-08-08T18:17:21",20,"/стены внешние получается направо?",142532,null],[146988,"2026-08-08T18:18:11",9,"//Это же бросок? Но у тебя есть время ещё попытаться раз, может вторая не так припаяна",146820,null],[146991,"2026-08-08T18:18:30",47,"О",142532,null],[146994,"2026-08-08T18:18:52",17,"/ направо да перепутал",146982,null],[146995,"2026-08-08T18:19:01",9,"*Вторую не сильно приплавили и оторвать её вышло относительно легко!*\n\n//Получена \"Рапира -1\"",142532,null],[146996,"2026-08-08T18:19:24",47,"/-1?",146995,null],[146998,"2026-08-08T18:19:47",9,"//Её попортили делая украшения, чё хош, но остальное все как есть в оригинальной, кривая чуть да",146996,null],[147006,"2026-08-08T18:21:03",47,"Плохо(/",142532,null],[147016,"2026-08-08T18:26:48",9,"*Ты слышишь как по ступеням идут, либо в окно, либо за тумбу, либо рискнуть и в одну из дверей.*",147006,null],[147017,"2026-08-08T18:27:00",47,"Один человек?",147016,null],[147018,"2026-08-08T18:27:25",9,"*Скорей всего два, по ощущениям.*",147017,null],[147019,"2026-08-08T18:27:46",47,"Тогда прячусь. Сбоку",142532,null],[147022,"2026-08-08T18:28:37",9,"//Тумба, на скрыт кидай",142532,null],[147028,"2026-08-08T18:29:16",47,"/r d20+4",142532,null],[147030,"2026-08-08T18:29:23",47,"Хуево прячусь",142532,null],[147031,"2026-08-08T18:29:31",47,"Заготовил действие",142532,null],[147044,"2026-08-08T18:32:42",9,"*Идут шагают и ты слышишь шум снизу что заключённые сбежали, побег вскрылся! Двое что рядом с тобой на 10 и на 15 футов от тебя, они через мгновение осознают ситуацию, ты можешь что-то сделать перед этим.*\n\n//Даже ебануть внещапно пока тебя не успели спалить, или другое",146949,null],[147054,"2026-08-08T18:36:58",47,"/их там двое. Шансов нет",142532,null],[147058,"2026-08-08T18:38:05",17,"— Пацан направо или налево?\n\nЛюпен открывает дверь и бежит туда куда пацан сказал ищет место куда можно сигануть чтобы спрятаться",142532,null],[147067,"2026-08-08T18:40:19",9,"/roll 1d2 ваше везение парни",147058,null],[147079,"2026-08-08T18:41:56",9,"*Вы выбегаете, кажется снаружи о вашем побеге ещё не услышали, сража на стене слева не смотрит в вашу сторону, и в этот момент никого из месных нет. Перед вами ящики немного к ним добежать, есть далее пару зданий и бочек, у самой стены ток стража патрулирует.*",142532,null],[147083,"2026-08-08T18:42:16",9,"//Да, стражи с лева",142532,null],[147086,"2026-08-08T18:43:06",20,"- Н-на право!",147058,null],[147091,"2026-08-08T18:44:56",31,"- может в бочки?",142532,null],[147094,"2026-08-08T18:45:50",17,"— К ящикам быстрее!",142532,null],[147099,"2026-08-08T18:46:30",31,"Ховаемся в Ящиках",142532,null],[147100,"2026-08-08T18:46:35",9,"//Лебедь рак и щука",142532,null],[147110,"2026-08-08T18:48:15",9,"//Куда все же",142532,null],[147116,"2026-08-08T18:49:13",17,"— Да! Ты прав, бочки!",142532,null],[147117,"2026-08-08T18:49:17",9,"//Ну что-то делать надо, иначе я щас иню сам кину и будет сражение сразу, а так даю что-то сделать перед этим",147054,null],[147118,"2026-08-08T18:49:35",17,"Люпен добегая до бочки срывает крышку и переворачивает ее надевает на себя",142532,null],[147119,"2026-08-08T18:49:47",17,"/ Пошеееел дивинити",142532,null],[147121,"2026-08-08T18:50:15",9,"//Укрытие и тут хлама местами много, всех троих скрытность с преимуществом, вы могли помочь друг другу поэтому так",142532,null],[147124,"2026-08-08T18:50:58",9,"*В бочке есть дырка от пробки, тебе через неё видно что твориться снаружи хоть и плохо.*\n\n// скок там бонус от укрытия на 3/4 к кд напомните заодно",147118,null],[147125,"2026-08-08T18:51:44",31,"/roll +d20+3",147121,null],[147128,"2026-08-08T18:51:52",20,"/r +d20+1",142532,null],[147130,"2026-08-08T18:51:54",47,"Я уже связал верёвки из знамен. Вылажу со стороны стены. Отрезаю остатки",147117,null],[147131,"2026-08-08T18:51:57",47,"Риск",142532,null],[147132,"2026-08-08T18:52:04",31,"Бочки сука прозрачные что ли?/",142532,null],[147135,"2026-08-08T18:52:25",9,"//Перед ними выпрыгиыаешь тоесть и бежишь?",147130,null],[147138,"2026-08-08T18:52:52",17,"/ Плюс 5",147124,null],[147139,"2026-08-08T18:53:11",47,"Провоцирки если не будет, то да",147135,null],[147140,"2026-08-08T18:53:13",9,"//Вот в бочке он, но ты ток на ножках ходить мож",147138,null],[147141,"2026-08-08T18:53:17",47,"/и без верёвки тогда",142532,null],[147143,"2026-08-08T18:53:43",17,"/r +d20+4 Скрытность",147121,null],[147145,"2026-08-08T18:53:48",9,"//Опиши как круто ты это сделал, у тебя дествие + скорость твоя, скорости к окну хватит",147139,null],[147146,"2026-08-08T18:53:48",47,"Прыгаю, с 10 футов",142532,null],[147148,"2026-08-08T18:54:41",47,"Мимо стражи проскочила серая тень. Прыжок. Схватился за край балкона, прячусь под балконом, оказываясь на уровне первого этажа прячусь, чтобы успеть оглядеться",147145,null],[147152,"2026-08-08T18:55:18",20,"/докину тогда в скрытность вдохновение, а то чёт вообще грустно",142532,null],[147153,"2026-08-08T18:55:24",17,"Люпен внутри бочки движется вперёд и смотрит через отверстие пробки",142532,null],[147154,"2026-08-08T18:55:25",20,"/может прокатит",142532,null],[147156,"2026-08-08T18:55:28",17,"/ я тоже докину",142532,null],[147157,"2026-08-08T18:55:33",17,"/ Хард посчитаешь нам среднее?",142532,null],[147158,"2026-08-08T18:55:37",17,"/r d4",142532,null],[147162,"2026-08-08T18:55:42",9,"//10-13 футов эт немного, чтобы не получить урона можно извернуться, акробатика сложностью 12 чтобы в воздухе скооперироваться, если владеешь акробатикой",147146,null],[147163,"2026-08-08T18:55:51",17,"/ у меня в сумме 20",142532,null],[147164,"2026-08-08T18:55:51",20,"/r d4",142532,null],[147166,"2026-08-08T18:56:05",20,"/в сумме 10",142532,null],[147170,"2026-08-08T18:56:42",31,"/roll d4",142532,null],[147172,"2026-08-08T18:56:54",31,"У меня 13/",142532,null],[147174,"2026-08-08T18:57:03",9,"/roll (10+18+6+2+3+4)÷3",142532,null],[147177,"2026-08-08T18:57:14",17,"/ Норма",142532,null],[147178,"2026-08-08T18:57:16",9,"//Четырнадцать среднее вам",142532,null],[147179,"2026-08-08T18:57:23",17,"/ У них пасивка 13 ))",142532,null],[147180,"2026-08-08T18:57:26",9,"//Спишу по кубику вдохновы",142532,null],[147183,"2026-08-08T18:59:33",9,"*Два стража протупили мгновение, и тут же повытаскивали короткие мечи, они подбежали к окну и смотрят куда пропал беглец, а он кадется уже смылся.*",147148,null],[147186,"2026-08-08T19:00:33",9,"//Щас с михой решим что куда, от него на акробатику проверку чтобы от падения не получить и наверное скрыт если он хочет попытаться спрятаться",142532,null],[147193,"2026-08-08T19:03:00",9,"//Так эпично у меня никто не сбегал, надеюсь получится у вас всё ❤️‍🔥 а так будут еще проблемы, побег из Шоушенка кажись проходит по маслу 😏👌",142532,null],[147208,"2026-08-08T19:09:30",47,"/r d20+3",147162,null],[147213,"2026-08-08T19:10:41",47,"Ловкие привычные движения, Сайн даже не напрягается, он уже размялся. Сколько раз он так бегал? Эх надо было ночью сбегать, спиздил бы тогда всякое и испарился. И к чёрту стражу",142532,null],[147227,"2026-08-08T19:13:23",9,"*На стене стоят скцяающие стражи, кое где слишком даже опасно глядя примерно в твою сторонус надо не спалиться чтобы тебя не увидели.*\n\n//Скрыт го",147213,null],[147242,"2026-08-08T19:15:13",9,"*В досягаемости есть места, куст, несколько ящиков у стены, бочки, но тут лишь проходят патрули у стены, к домам и более безопасным укрытиям надо бежать и те два стража могут через мгновение выглянуть в окно и понять где ты.*\n\n//Ну, считай у тебя ещё ход чтобы не спалиться",142532,null],[147263,"2026-08-08T19:18:01",47,"/r d20+4 гоу",142532,null],[147270,"2026-08-08T19:18:20",47,"Одним ловким движением становлюсь за висящий герб",142532,null],[147286,"2026-08-08T19:19:55",9,"//Ничего лучше не нашёл",142532,null],[147292,"2026-08-08T19:21:04",9,"— Чёрт где он пропал!?\n\n— Я не вижу... быстрее вниз а то уйдет!\n\n*Сражи выглядующие из окна не увидели Сайна и побежали вниз.*",142532,null],[147306,"2026-08-08T19:22:46",9,"*Все слышат звук тревоги, командир поднялся из подвала и трубит в него извещая всех кто слышит.*",142532,null],[147315,"2026-08-08T19:24:12",47,"Классная мелодия. Идёт/",142532,null],[147317,"2026-08-08T19:24:18",9,"*Сайн где спрятался может видеть как стража на стенах резко переключилась мониторить эту сторону стены, о их побеге если не знают все, то скоро узнают. Вскоре слышаться другие рожки далее, новость быстро передаётся, стража зашевелились.*",142532,null],[147319,"2026-08-08T19:24:23",47,"Я пока сижу по кайфу за знаменем",142532,null],[147322,"2026-08-08T19:25:05",9,"/roll 1d20+3 активный поиск взглядом, ток один куб но могут заметить",142532,null],[147326,"2026-08-08T19:25:25",9,"//Хм, вот так выходит",142532,null],[147333,"2026-08-08T19:26:43",9,"*Сайн видит как кто то его заметил и говорит на стене своему другу, его маскировка вскрылась, тому парню подают лук, явно не в птиц стрелять.*\n\n//Сайн, действия",142532,null],[147334,"2026-08-08T19:26:54",47,"/я могу сейчас вдохновение кинуть, чтобы не было взгляда?",142532,null],[147335,"2026-08-08T19:27:15",47,"Потому что обычно проверка на проверку к слову. Обычно выигрывает тот, у кого модификатор выше/",142532,null],[147336,"2026-08-08T19:27:25",47,"Выше вообще он у меня (+4)",142532,null],[147339,"2026-08-08T19:28:00",9,"//Я лумал это как с кд, мы не соревнуемся, а ты уже спрятался и установил сложность 17+?",142532,null],[147343,"2026-08-08T19:28:49",9,"//Лан, но в след раз кидайте вдохновы когда вас ещё не заметили",142532,null],[147347,"2026-08-08T19:29:04",47,"/хорошо",142532,null],[147348,"2026-08-08T19:29:04",9,"//Докинь д4",142532,null],[147349,"2026-08-08T19:29:10",47,"/r d4",142532,null],[147351,"2026-08-08T19:29:14",47,"21/",142532,null],[147359,"2026-08-08T19:30:32",9,"*Выстрел куда то в сторону, тишина, тот часовой кажется ошибся местом и пошёл вдоль стены смотреть немного разочарованно. Наверное хотел прибавку к жалованию, старается.*",142532,null],[147365,"2026-08-08T19:31:41",9,"*Стража начинает активно шастать по городу, шаги отрядов, команды, разьяснения, они заглядывают под каждый камень и вас найдут рано или поздно как хорошо бы вы не спрятались.*",142532,null],[147366,"2026-08-08T19:32:13",9,"//Скрытно кидаю 2д10 для сайна и для пати, сколько у вас времени в игре до того как ваше место найдут",142532,null],[147368,"2026-08-08T19:32:21",47,"/в часах?",142532,null],[147371,"2026-08-08T19:32:51",9,"//В минутах",142532,null],[147372,"2026-08-08T19:33:17",9,"//Вы все понимаете что вас активно ищут, вы слышите это",142532,null],[147373,"2026-08-08T19:33:17",47,"Я жду момента, когда у меня будет возможность пробежать, так, чтобы никто на меня не смотрел, стража на стене была повёрнута в другую сторону, только после этого побегу (чтобы враги с помехой кидали свою хуйню, или не кидали вовсе, так как не смотрят и пошли нахуй)",142532,null],[147385,"2026-08-08T19:34:45",9,"// @dunchev @QURTZZ @PaIIasCat вы понимаете что вас точно рано или поздно найдут если на месте сидеть, что вы делаете",142532,null],[147389,"2026-08-08T19:37:26",31,"- парни, этот кипиш не к добру. Давайте глянем во все стороны, может есть какой то коридор для отхода?\n\n\n/предлагаю всем троим кинуть на внимательность, может кому то повезет увидеть более или менее свободный коридор//",142532,null],[147390,"2026-08-08T19:38:12",31,"/roll d20 выживание как дикий зверь ищу пространство для побега",142532,null],[147392,"2026-08-08T19:39:09",20,"/r d20+2 ищем пути, вспоминаю примерное расположение которое видел из бойниц",142532,null],[147418,"2026-08-08T19:52:15",20,"/ладно, помогаю кому-нибудь из старших тогда, говоря что помню из увиденного",142532,null],[147479,"2026-08-08T20:05:30",17,"/ Кровать была подожжена в комнате стражи, дым пошел? Мешает им? Рем поджигал на отходе",147317,null],[147486,"2026-08-08T20:06:49",17,"— Ищите водный канал, свалим по нему в бочках, хоть бы он сука был!",142532,null],[147487,"2026-08-08T20:06:57",17,"/r +2 Выживание",142532,null],[147493,"2026-08-08T20:07:14",17,"/ Я хочу докинуть ещё вдохновение и найти хороший путь отхода",142532,null],[147494,"2026-08-08T20:07:20",17,"/направить остальных",142532,null],[147495,"2026-08-08T20:07:24",17,"/r d4",142532,null],[147497,"2026-08-08T20:07:31",17,"/ У меня 16",142532,null],[147502,"2026-08-08T20:09:50",9,"*Дома, проскользнуть дальше к домам где Рен осматривался из бойницы, единственная возможность. Но стража везде и с вашего положения всего не видно, это будет риск, удача, лишь бы подобрать момент.*",147497,null],[147510,"2026-08-08T20:11:07",20,"/хочу попробовать провернуть тот же трюк с обманом телепатией - дать стражникам иллюзию звука побега/голосов в противоположном направлении, чтобы они отошли проверить",147502,null],[147511,"2026-08-08T20:11:14",9,"*Мимо тебя прошли пару караулов, они осмотрелись у стены и пока не нашли Сайна. Сейчас у стены никого и есть момент, шанс нырнуть под саму стену когда никто из караульных на верху не видит, они под ней не смотрят.*",147373,null],[147516,"2026-08-08T20:11:49",9,"//Да, это всё?",147510,null],[147520,"2026-08-08T20:12:39",47,"Гоу",147511,null],[147521,"2026-08-08T20:12:41",20,"/у меня да - попытаюсь создать нам шанс проскользнуть",147516,null],[147525,"2026-08-08T20:13:24",47,"Мастер, отниму три минуты?",142532,null],[147529,"2026-08-08T20:13:55",47,"Hard",142532,null],[147533,"2026-08-08T20:14:12",47,"Высота стены?",142532,null],[147551,"2026-08-08T20:16:36",17,"— Ничего толком нет, нужно дальше направо к домам, где пацан высмотрел постройки.",147502,null],[147557,"2026-08-08T20:17:35",9,"*Стена высотой 40 футов, башни ато выше.*",147533,null],[147569,"2026-08-08T20:18:12",47,"Пупу. Есть вариант залезть слегка?",147557,null],[147570,"2026-08-08T20:18:14",9,"//Пордоньте, или к стене",147551,null],[147573,"2026-08-08T20:18:22",47,"Или у самой верхушки?",142532,null],[147574,"2026-08-08T20:18:44",9,"*Есть вариант пойди под стеной, но что там? Черт знает, риск.*",147551,null],[147580,"2026-08-08T20:19:13",9,"//Лазать же можно с половиной скорости",147569,null],[147583,"2026-08-08T20:19:41",9,"*Стена достаточно старая, местами есть за что ухватиться чтобы залезть.*",147569,null],[147584,"2026-08-08T20:19:46",47,"Всё, лезу",147580,null],[147585,"2026-08-08T20:20:03",9,"//Такс, наши герои что решили",142532,null],[147586,"2026-08-08T20:20:31",47,"На стене есть знамёна или тряпки? Если нет, то при помощи прута устанавливаю одно и прячусь за ним прям на стене за 10 футов до верхушки!",142532,null],[147587,"2026-08-08T20:20:37",9,"*Люпен со стороны стены замечает их знакомого, он подбежал к стене и лезет по ней!*",142532,null],[147594,"2026-08-08T20:21:29",20,"/сейчас тогда с сайном закончите я попробую обманку провернуть",147585,null],[147595,"2026-08-08T20:21:30",17,"/ Пацан может отвлечь стражу телепатическим блефом чтобы создать нам совет бежать к стене и направо?",142532,null],[147596,"2026-08-08T20:21:33",9,"*Удается спрятаться и просто у края.*",147586,null],[147601,"2026-08-08T20:21:59",17,"— Сайн выбрался, и кажется его даже ещё не подстрелили, везучий сукин сын",147587,null],[147602,"2026-08-08T20:22:01",47,"Ок/",147596,null],[147603,"2026-08-08T20:22:19",47,"/бля. Везучий\nДайте титул везунчик!",142532,null],[147615,"2026-08-08T20:28:21",9,"//ну, пусть основная команда опишет действия",142532,null],[147618,"2026-08-08T20:29:23",9,"*Мимо вас идет стража, в сторону стены. Еще немного они точно увидят сайнас хотя смотрят пока преимущественео по сторонам.*",147601,null],[147619,"2026-08-08T20:29:46",17,"/ @PaIIasCat  сделай и бежим",142532,null],[147633,"2026-08-08T20:34:54",9,"//Шёл 3й день игры, они уже вге камер, пока что",142532,null],[147635,"2026-08-08T20:35:07",20,"/все, вернулась - сейчас попробуем",147619,null],[147648,"2026-08-08T20:37:02",20,"*Рен снова сосредотачивается на страже. Ну же...ещё разок...*\n\n*В из головах раздается сначала звук опрокидывания чего-то, ударом, шагов и громкий крик одного из других стражников*\n\n\"ВОТ ОНИ!!! БЫСТРЕЕ, ЛОВИТЕ ИХ!!!\"\n\n*Звук будто идёт с противоположной стороны, откуда-то из-за зданий*",142532,null],[147652,"2026-08-08T20:37:49",20,"/r +d20+3 🙏",142532,null],[147655,"2026-08-08T20:38:00",20,"/Гоооол",142532,null],[147657,"2026-08-08T20:38:52",17,"Люпен быстрым семенящим шагом видя что стражники рванули куда то в сторону понёсся вперёд к свободе\n\nНаправо вдоль стены\n\nБочка на нем могла в теории не дать пробить его стрелой насквозь, что давало немного храбрости",142532,null],[147668,"2026-08-08T20:40:03",17,"/ ГОООООООООЛ",147655,null],[147670,"2026-08-08T20:40:30",9,"*Все рванули туда не оглядываясь, искатб откуда, где и кого.*",147648,null],[147671,"2026-08-08T20:40:58",9,"//Чётка",142532,null],[147675,"2026-08-08T20:41:35",9,"//К стене? Это наыерное уже с Алексеем надо",142532,null],[147676,"2026-08-08T20:41:48",17,"/ погоди",142532,null],[147678,"2026-08-08T20:41:59",17,"/ Были варианты куда.\n\n1. К стене\n\n2... ?",142532,null],[147679,"2026-08-08T20:42:01",20,"*Рен выдыхает, унимая дрож, золотая вспышка в глазах гаснет, когда он не секунд не медля бежит за Люпеном. Повезло. На этот раз*",142532,null],[147680,"2026-08-08T20:42:03",17,"/ К домам?",142532,null],[147688,"2026-08-08T20:43:23",20,"/я думала к стене, чтоб прям сбежать уже",142532,null],[147694,"2026-08-08T20:44:16",9,"//У нас 1 чел из глубинки, с трудом в лесу прокормит вас",142532,null],[147695,"2026-08-08T20:44:25",17,"/ Я думаю лучше к домам",142532,null],[147700,"2026-08-08T20:44:45",9,"//А стражу куда,на люпена к стене?)",147695,null],[147703,"2026-08-08T20:45:00",17,"/ Ну погоди щас разобраться нало",142532,null],[147707,"2026-08-08T20:45:24",9,"//Моральная диллемас вы, или он, или вместе, но меж домами шароёбица ещё",142532,null],[147709,"2026-08-08T20:45:47",9,"//Вот вам время до завтра подумать, как Алексей будет тут",142532,null],[147710,"2026-08-08T20:45:47",17,"/ Я не думаю что пос тене мы залезем",142532,null],[147711,"2026-08-08T20:45:51",17,"/ давайте по домам",142532,null],[147714,"2026-08-08T20:46:26",9,"//Лазанье тратит скорость ×2 если вы не имеете черту \"Атлетичный\" или скорость лазанья откуда-то. Если правильно помню",142532,null],[147724,"2026-08-08T20:48:22",17,"/ да нас расстреляют",142532,null],[147728,"2026-08-08T20:48:56",17,"/ Ну модем пробовать у меня скорость 35\n\nБочку снял и с нее оттолкнулся полез",142532,null],[147730,"2026-08-08T20:49:12",17,"/ за стену перелезть. В лесу спрятаться",142532,null],[147757,"2026-08-08T20:53:31",47,"/тоже 35",142532,null],[147770,"2026-08-08T20:57:14",9,"//У Люпена еще кусок следака крошечный + доп макс хиты +1 каждый лвл, чел из глубинки, это вам не метки странные, грубо и четко)",142532,null],[147771,"2026-08-08T20:58:08",20,"/ну у меня 30",142532,null],[147782,"2026-08-08T21:01:32",31,"Я тут, задремал, но снова проснулся/",142532,null],[147783,"2026-08-08T21:01:38",31,"У меня скорость 30/",142532,null],[147785,"2026-08-08T21:01:44",17,"/ Бежим к стене и лезем.",142532,null],[147789,"2026-08-08T21:01:59",17,"— Конрад подсади пацана! Лезем по стене! Сейчас!",142532,null],[147792,"2026-08-08T21:02:28",17,"Люпен добегает до стены скидывает бочку и запрыгивает на нее начинает пытаться лезть по стене ища уступы\n\n/ ну рывок очевидно юзаю",142532,null],[147797,"2026-08-08T21:03:44",20,"/тикаем",142532,null],[147805,"2026-08-08T21:04:43",31,"Подбегаю к стене, вскиваю на бочку, делаю из рук подставку чтобы кинуть пацана в руки Крысы, затем лезу сам",142532,null],[147806,"2026-08-08T21:04:45",9,"*Вы лезите по стене, но заметили ли вас?*",142532,null],[147807,"2026-08-08T21:05:08",9,"/roll 1d2 ваша удача",142532,null],[147811,"2026-08-08T21:05:42",9,"*Кто то со стены вас заметил и неклонился через неё, и удивился когда увидел не только вас но и Сайна!*",142532,null],[147812,"2026-08-08T21:06:10",9,"// @cirson Рядом с тобой чел впритыкс он спалил остальных щас закричит",147811,null],[147813,"2026-08-08T21:06:29",20,"/можно попробовать его телепатией запугать/зашанить голову?",142532,null],[147816,"2026-08-08T21:07:09",20,"/чтоб время выиграть",142532,null],[147822,"2026-08-08T21:08:50",9,"//Я ничего не запрещаю, пробуй",142532,null],[147825,"2026-08-08T21:09:04",9,"//В досягаемости? Делайс пробуй",142532,null],[147826,"2026-08-08T21:09:23",20,"/60ф если есть то да",147825,null],[147827,"2026-08-08T21:09:39",9,"//Стена 40 высотой + - да",142532,null],[147829,"2026-08-08T21:09:54",20,"/r +d20+3 🙏",142532,null],[147831,"2026-08-08T21:10:03",47,"В горло ебашу",147812,null],[147832,"2026-08-08T21:10:14",47,"/r +d20+2 вгезапно",142532,null],[147834,"2026-08-08T21:10:24",47,"Вместо урона хочу чтобы он не мог говорить!",142532,null],[147837,"2026-08-08T21:11:07",20,"*в голове стражника раздаются жуткие крики, один голос перекрикивает другой*\n\n\"Б҈҇‌‌‌‌‌‌‌‌‌‌‌Е‌‌‌‌‌‌‌‌‌Г‌‌‌‌‌‌‌‌‌‌‌‌И‌‌‌‌‌‌‌‌‌‌ Б‌‌‌‌‌‌‌‌‌‌Е‌‌‌‌‌‌‌‌‌‌‌‌Г‌‌‌‌‌‌‌‌‌‌‌И‌‌‌‌‌‌‌‌‌‌ Б҈‌‌‌‌‌‌‌‌‌Е‌‌‌‌‌‌‌‌‌‌‌Г҉‌‌‌‌‌‌‌‌И҈‌‌‌‌‌‌‌‌‌‌!\"",147830,null],[147838,"2026-08-08T21:11:08",9,"//Урон тож неси",142532,null],[147861,"2026-08-08T21:18:47",17,"— Ускоряемся!\n\nЛюпен достал нож и зажал его в зубах пока лезет",142532,null],[147862,"2026-08-08T21:19:06",17,"/ Высоту говорили стены, сколько?",142532,null],[147865,"2026-08-08T21:19:20",17,"/ Я хочу когда залезу подтянуть пацана и Конрада",142532,null],[147869,"2026-08-08T21:20:23",9,"// 40 футов высота, и мне бы снйчас охранника описать",147862,null],[147872,"2026-08-08T21:20:58",31,"Кидаю тебе веревку которую я сделал из простыни и так с собой и таскал, как пояс",147865,null],[147875,"2026-08-08T21:23:02",17,"Поймал верёвку и надел через плечо\n\nКак только Люпен забрался \n\nОн верёвку спустил вниз и упёрся ногой в край начал тянуть по одному других беглецов",147872,null],[147877,"2026-08-08T21:23:17",17,"/ Стражника напугал пацан вроде у нас на стене?",147869,null],[147881,"2026-08-08T21:26:59",9,"//Я пытаюсь понять что мне описыаать, урона нет от рапиры",147877,null],[147882,"2026-08-08T21:27:20",17,"/ А ну Мишу ждем @cirson",142532,null],[147883,"2026-08-08T21:27:59",31,"Гу он же писал что хочет лишить голоса, то есть не летально бил. Явно попал, типа эфесом в горло/",142532,null],[147884,"2026-08-08T21:30:14",9,"//Попал да, как именно он это сдедал не описал, даже если эфесом то это скорее импровизированна или попытка в особую, тогда в случае особой страж делает ответную проверку и все такое, я поэтому хз если честно, но он заявил это как атаку рапирой значит полоснул по горлу а это урон",142532,null],[147885,"2026-08-08T21:30:18",47,"/r d8+3",142532,null],[147887,"2026-08-08T21:31:18",47,"Тонкий клинок рапиры достаёт горло стражника, что собирался закричать! А после залазит к нему на стену",142532,null],[147888,"2026-08-08T21:31:49",9,"*Стражнику режет горло, ох хватается за него пытаясь закричать, что то сказать, он отходит.*\n\n//Можешь провоцирку если хочешь",142532,null],[147889,"2026-08-08T21:31:49",47,"/что вообще сейчас происходит?",142532,null],[147890,"2026-08-08T21:32:08",47,"Подсечку могу провоцированным, чтобы он упал?",147888,null],[147891,"2026-08-08T21:32:13",9,"//Под стеной свои, тоже лезут, пусть опишут",147889,null],[147892,"2026-08-08T21:32:30",9,"//Го, это начало, импровизируй",147890,null],[147893,"2026-08-08T21:32:39",47,"/r d20+3 акробатика",142532,null],[147895,"2026-08-08T21:32:45",9,"//Как наемник в будущем сможешь менять типы атак",142532,null],[147896,"2026-08-08T21:32:52",47,"За стену падает?)",142532,null],[147897,"2026-08-08T21:33:01",31,"Крыса уже на стене, тянет нас с Рнном на веревке наверх/",147891,null],[147898,"2026-08-08T21:33:03",9,"//Опиши как что",142532,null],[147899,"2026-08-08T21:33:18",9,"/roll 1d20+1 атлетика вдруг не вфйдет",142532,null],[147901,"2026-08-08T21:33:28",9,"//Пиши",147900,null],[147902,"2026-08-08T21:33:58",47,"Когда стражник поражённый в горло начал отходить, резким движением сайн запрыгнул на стену и сделал подсечку, лишь гулкий звук падения был доказательством смерти стражника",142532,null],[147903,"2026-08-08T21:34:21",9,"/roll 1d2 ваша удача",142532,null],[147905,"2026-08-08T21:34:39",9,"//Конечно бля, 2 выпадет в 90% случаях у меня",142532,null],[147906,"2026-08-08T21:34:48",17,"Люпен вытащил пацана\n\nИ помогает Конраду так же забраться быстрее",142532,null],[147907,"2026-08-08T21:36:14",9,"*Стража расстредоточенна, на стене, если вы не стараетесь сильно шуметь у вас есть ещё несколько мгновений. Ближайший страж на вышке занят и только подходит всматриваться на шум упавшего.*",142532,null],[147908,"2026-08-08T21:36:23",47,"Теперь верёвка из знамени. Беру по центру. Закрепляю, но не завязываю, и быстро спускаюсь, придерживаю снизу, чтобы не упала, а после того, как всё спустятся, заберу",142532,null],[147909,"2026-08-08T21:36:27",9,"//У вас ход перед палевом считайте",142532,null],[147910,"2026-08-08T21:36:45",47,"Тогда отбой. Половину веревки",142532,null],[147911,"2026-08-08T21:36:51",47,"Другую отрезал.",142532,null],[147912,"2026-08-08T21:36:54",47,"И убежал в лес",142532,null],[147913,"2026-08-08T21:37:04",9,"//Это 10 ходов?)",142532,null],[147915,"2026-08-08T21:37:29",17,"Когда все твое наверху мы пкрекидывем верёвку вниз и чтобы сэкономить ее кому то нужно остаться и держать остальных для спуска",142532,null],[147916,"2026-08-08T21:37:32",9,"//Успеешь лишь закрепит веревку и по ней сползти футов на 20 вниз стены",142532,null],[147918,"2026-08-08T21:37:45",17,"— Конрад... Подержишь нас?",142532,null],[147919,"2026-08-08T21:37:53",31,"Да, идите",142532,null],[147920,"2026-08-08T21:38:08",47,"Я буквально падаю. Не трачу движение. Слегка сотру руки об ткань",147916,null],[147921,"2026-08-08T21:38:19",9,"//Акробатику",142532,null],[147922,"2026-08-08T21:38:27",47,"Отрезать не буду. Действие потратил на завязку. И убегаю",142532,null],[147923,"2026-08-08T21:38:32",47,"/r d20+3 Боже упаси",142532,null],[147924,"2026-08-08T21:38:33",9,"//Или рук ловкость",142532,null],[147926,"2026-08-08T21:38:39",47,"22 если второе",142532,null],[147927,"2026-08-08T21:39:02",9,"//Так, другие",142532,null],[147928,"2026-08-08T21:39:50",31,"Мы перекинули веревку по которой поднялись и начали спуск, я держу пока Крыса и Рен спускаются",142532,null],[147929,"2026-08-08T21:40:37",47,"А нафиг моя висит. /",142532,null],[147930,"2026-08-08T21:40:55",47,"Забирайте эту и так же как я спускайтесь/",142532,null],[147931,"2026-08-08T21:40:57",31,"Ты вроде в другой точке перебираешься, как я понял/",147929,null],[147932,"2026-08-08T21:41:03",47,"Мастер?",142532,null],[147933,"2026-08-08T21:41:12",9,"//Вы примерно в одном месте же",142532,null],[147934,"2026-08-08T21:41:34",31,"Тогда еще лучше, валим все по той же веревке и по той же схеме",142532,null],[147935,"2026-08-08T21:41:40",9,"//Ьам туда сюда они же к тебе вродь бежали, да даже если чуть сбоку ,10 футов не зарешают",142532,null],[147936,"2026-08-08T21:42:46",31,"Всем кто спускается бросать на акробатику?/",142532,null],[147937,"2026-08-08T21:43:05",20,"/наверно только тем кто прыгает с веревки",142532,null],[147938,"2026-08-08T21:43:39",9,"*Вы слышите звук рожка, кто-то на стене вас заметил! Потоже именно тот что смотрел куда упал воин.*\n\n*С другой вышки в вас стреляют, но вы лезите по стене, сложнее попасть и далеко, а вот Сайн уже внизу.*",142532,null],[147939,"2026-08-08T21:43:43",47,"Блять\n.. А я могу тело стражника телепортировать с собой туманным шагом и дальше тащить его?",142532,null],[147940,"2026-08-08T21:44:16",47,"У меня ещё бонусное действие!",142532,null],[147941,"2026-08-08T21:44:29",9,"//Ну да в теории, щас вы слышите рожок",147939,null],[147942,"2026-08-08T21:44:48",47,"Поехали. Теп",147941,null],[147943,"2026-08-08T21:44:53",9,"/roll -d20+5 в Сайно даж если тепнулся еще в досягаемости",142532,null],[147945,"2026-08-08T21:45:35",47,"Сайн видя арбалет. Исчезает в короткое мгновение и оказывается сильно дальше с телом стражника в руках. Он показывает фак дебилоиду, который промахнулся",142532,null],[147946,"2026-08-08T21:45:45",47,"И тащит тело к деревьям!",142532,null],[147947,"2026-08-08T21:45:47",47,"И кустам",142532,null],[147950,"2026-08-08T21:46:04",31,"Консерва?/",147946,null],[147951,"2026-08-08T21:46:13",47,"/шмотки!",142532,null],[147952,"2026-08-08T21:46:22",47,"Лут!",142532,null],[147953,"2026-08-08T21:46:26",9,"*Стражи на стенах подходят ближе и поднимаю луки, перед стеной чисто поле, лишь бы уйти из зоны поражения.*",142532,null],[147954,"2026-08-08T21:46:27",47,"Сухпаек у стражи! /",142532,null],[147955,"2026-08-08T21:46:33",9,"//Ваш ход тогда",142532,null],[147956,"2026-08-08T21:46:37",47,"/не понял",142532,null],[147957,"2026-08-08T21:47:22",47,"Вот это/",147953,null],[147958,"2026-08-08T21:47:32",9,"//У вас был ход, я не описывал что за стеной, там поле чтобы противников сдерживать на открытой, ты ходил а потом бонуской тепнулся, они слазят",142532,null],[147959,"2026-08-08T21:47:47",9,"//Вот протрубил рог и будут стрелять",142532,null],[147960,"2026-08-08T21:47:50",47,"Ага/. И рядом вроде как перелесок, да?",142532,null],[147961,"2026-08-08T21:47:52",31,"Сколько до леса?/",142532,null],[147962,"2026-08-08T21:48:22",9,"*К лесу пару миль, но сейчас бы выйти из зоны поражения луков.*",147961,null],[147963,"2026-08-08T21:48:30",47,"/ну ок",142532,null],[147964,"2026-08-08T21:48:31",47,"Гоу!",142532,null],[147965,"2026-08-08T21:48:42",9,"//Ход ваш, го го го",142532,null],[147966,"2026-08-08T21:48:44",47,"Бегу на свои 35 футов! С рывка/",142532,null],[147967,"2026-08-08T21:48:51",9,"//Бегитес вы почти же",142532,null],[147968,"2026-08-08T21:49:15",31,"Тоже бегу, хули делать. Рывком",142532,null],[147969,"2026-08-08T21:49:26",47,"Помогаешь тащить? /",147968,null],[147970,"2026-08-08T21:49:33",20,"/рывок, что ещё делать",142532,null],[147971,"2026-08-08T21:49:41",9,"//Ему бы добежатьс ты дальше их",142532,null],[147972,"2026-08-08T21:50:01",31,"Я отстаю и ты быстрее на 5 футов за ход",147969,null],[147973,"2026-08-08T21:50:09",47,"- Помогите, он тяжёлый. Пончики сука переел! - кричит сайн таща реально консерву с полезностями",142532,null],[147974,"2026-08-08T21:50:10",9,"//Они даж с рывклм футов 20 к тебе не дотянут",142532,null],[147975,"2026-08-08T21:50:26",47,"Только вот рывок у вас *2 скорость, а моя лишь стандарт, так как тащу",147972,null],[147976,"2026-08-08T21:50:32",9,"//В след раунде уже помогутс го го, бежим",142532,null],[147977,"2026-08-08T21:50:54",47,"Бегу",142532,null],[147979,"2026-08-08T21:52:58",9,"// @dunchev ток тебя нет",142532,null],[147980,"2026-08-08T21:54:07",17,"/ Я домой еду",142532,null],[147981,"2026-08-08T21:54:28",17,"/ Бегу ребят с рывком в лес",142532,null],[147982,"2026-08-08T21:54:36",17,"/ Что куинуть?",142532,null],[147983,"2026-08-08T21:54:55",9,"//Пока ничё, вы бегите а теперь моя очередь",142532,null],[147984,"2026-08-08T21:55:21",31,"Сейчас Хард нас расстреляет и все три дня пообегатпг пмзде пойдут/",142532,null],[147985,"2026-08-08T21:55:36",9,"*Стража подключается, вы слышите свист стрел, вы все еще в зоне поражения луков, беглецы.*",142532,null],[147986,"2026-08-08T21:56:13",9,"Использую этот порядок для рандома",145244,null],[147987,"2026-08-08T21:56:39",9,"/roll 3d4 в кого стрелы",142532,null],[147989,"2026-08-08T21:56:45",47,"В меня одна/",142532,null],[147990,"2026-08-08T21:56:48",47,"Ау",142532,null],[147991,"2026-08-08T21:57:00",9,"//В рена нет стрелы ток",142532,null],[147992,"2026-08-08T21:57:22",9,"/roll -d20+5 конрад\n/roll -d20+5 люпен\n/roll -d20+5 сайн",142532,null],[147994,"2026-08-08T21:57:32",47,"И опять 3/19/)",142532,null],[147995,"2026-08-08T21:57:42",31,"В меня попало/",142532,null],[147996,"2026-08-08T21:57:57",9,"/roll 1d6+3 в конрада",142532,null],[147998,"2026-08-08T21:58:16",47,"Следующим ходом я взвалю тело стражника, чтобы у меня было укрытие 3/4. И бегом дальше на рывке! Пофиг, уже не попадут и не догонят. Даже лошадьми",142532,null],[147999,"2026-08-08T21:58:32",9,"*Стрела прошила спину убегающему конраду.*\n\n//Ваш ход",142532,null],[148000,"2026-08-08T21:58:56",31,"Нормально, у меня осталось 6 хп//",142532,null],[148001,"2026-08-08T21:58:56",47,"Вот/",147998,null],[148002,"2026-08-08T21:59:41",20,"*продолжаю бежать, молча молясь что они решат стрелять в ребенка в последнюю очередь...*",142532,null],[148004,"2026-08-08T22:00:14",31,"Отхаркиваю кровь и бегу, молясь Аскелатору о спасении",142532,null],[148005,"2026-08-08T22:00:18",47,"/как игроку стражника жаль. Как вору... Мне одежда норм нужна!",142532,null],[148006,"2026-08-08T22:00:20",9,"//Как персонаж пж, это внеигровое, хотя бы скобку убери",148002,null],[148007,"2026-08-08T22:01:13",31,"Коля, полагаю, тоже бежит?/",142532,null],[148008,"2026-08-08T22:01:28",31,"Давайте уже добежим и спать/",142532,null],[148009,"2026-08-08T22:01:56",9,"//Наверное, но он занят, если у него нет заявок особых то могу след раунд, он последний 😈",142532,null],[148010,"2026-08-08T22:03:03",47,"Давайте уже",142532,null],[148011,"2026-08-08T22:03:22",9,"/roll 5d4 стрелы по вам в кого куда",142532,null],[148013,"2026-08-08T22:03:53",9,"// две в конрада, две в мальца и одна в люпена щас",142532,null],[148014,"2026-08-08T22:04:24",31,"Вот ты какая, смерть/",142532,null],[148015,"2026-08-08T22:04:34",20,"/ага...",142532,null],[148016,"2026-08-08T22:04:36",9,"/roll -d20+5 Конрад\n/roll -d20+5 Конрад\n/roll -d20+5 Рен\n/roll -d20+5 Рен\n/roll -d20+5 Люпен",142532,null],[148018,"2026-08-08T22:05:05",9,"//По кому чё там попало",142532,null],[148019,"2026-08-08T22:05:08",31,"Меня пронесло, Аскелатор защитил",142532,null],[148020,"2026-08-08T22:05:09",20,"/по пацану 1 попала",142532,null],[148021,"2026-08-08T22:05:13",47,"Сайн скотина. Я могу так сказать/",142532,null],[148022,"2026-08-08T22:05:30",9,"/roll 1d6+3 стрела в пацана",142532,null],[148024,"2026-08-08T22:05:34",31,"Люпена вроде тоже пронесло/",142532,null],[148025,"2026-08-08T22:05:46",20,"/ровно в 0...",148023,null],[148026,"2026-08-08T22:05:59",20,"/подхватите его пж",142532,null],[148027,"2026-08-08T22:06:13",31,"На бегу подхватываю пацана потерявшего сознание и бегу двльше",148025,null],[148028,"2026-08-08T22:06:21",9,"*Прямо перед Конрадом в пацана попадает стрела тот делает еще пару шагов и падает без сознания.*",142532,null],[148029,"2026-08-08T22:07:17",9,"*Несколько стрел все еще летели в след, но вы уже слишком далеко.*\n\n//Пацан лёгкий, без штрафа понёс. Но он пропустил 1 спас смерти, не кидай пока",142532,null],[148030,"2026-08-08T22:07:21",20,"/вот она, кость к4 сука ...",142532,null],[148031,"2026-08-08T22:07:40",20,"/нарративная",142532,null],[148032,"2026-08-08T22:07:45",9,"//Вы вне зоны досягаемости уже, Рен умирает, описывайте",142532,null],[148033,"2026-08-08T22:07:57",47,"/я говорил, что необходим хоть какой-то, бонус за это",142532,null],[148034,"2026-08-08T22:08:34",9,"//Го действия у вас умирающий пацан на руках)",142532,null],[148035,"2026-08-08T22:08:34",47,"Сайн тащит тушку до самых кустов и обыскивает. Может найдётся зелье лечения. Страже иногда выдавали всё же",142532,null],[148036,"2026-08-08T22:08:36",17,"/ по мне мимо КД 13",142532,null],[148037,"2026-08-08T22:09:15",31,"Осматриваю пацана, пытаюсь понять насколько все серьезно и хватит ли моих позгагиц в медицине чтобы его стабилизировать",142532,null],[148038,"2026-08-08T22:09:27",47,"/r d20-1  внимательность? Сейчас будет что-то около 6",142532,null],[148040,"2026-08-08T22:09:36",47,"Ебать я угадал",142532,null],[148041,"2026-08-08T22:09:51",9,"//Конрад, делай чет",142532,null],[148042,"2026-08-08T22:09:55",31,"/roll d20+1 на анализ состояния",148037,null],[148043,"2026-08-08T22:10:02",9,"//Люпен, я за вас болею",142532,null],[148045,"2026-08-08T22:10:28",47,"/лучше бы на внимательность так падало(",142532,null],[148046,"2026-08-08T22:10:32",9,"// @PaIIasCat кинь два броска от смерти",142532,null],[148047,"2026-08-08T22:10:47",20,"/уже два?",148046,null],[148048,"2026-08-08T22:10:48",9,"//К ним благо вдохнову д4 можно докинуть",142532,null],[148049,"2026-08-08T22:10:58",9,"//Ну они не лечат а осматривабт",142532,null],[148050,"2026-08-08T22:10:58",31,"Анализа хватит чтобы СЛ на медицину понять?",148044,null],[148051,"2026-08-08T22:11:08",9,"// 10 база",148050,null],[148052,"2026-08-08T22:11:22",31,"Ща опишу и бросок будет",142532,null],[148053,"2026-08-08T22:11:44",9,"//Щас его состоянте поймёшь, 2 броска от паллас д20",142532,null],[148054,"2026-08-08T22:12:01",20,"/r d20 🙏",142532,null],[148056,"2026-08-08T22:12:07",47,"/ска",142532,null],[148057,"2026-08-08T22:12:13",9,"//Докинь д4 и успех",148055,null],[148058,"2026-08-08T22:12:22",47,"/не кидай. Ща вылечим",142532,null],[148059,"2026-08-08T22:12:28",20,"/спиши одно, трачу",148057,null],[148060,"2026-08-08T22:12:38",9,"//Второй бросок",142532,null],[148061,"2026-08-08T22:12:45",47,"/ну ладно. Тогда не вылечим. Сам встанешь",142532,null],[148062,"2026-08-08T22:13:11",20,"/да не, это чисто чтоб я не здох пока вы пытаетесь стабилизировать",148061,null],[148063,"2026-08-08T22:13:24",47,"Ещё кинь",148062,null],[148064,"2026-08-08T22:13:25",20,"/r d20 🥲",142532,null],[148066,"2026-08-08T22:13:43",31,"/roll d20-1+d4 бросок на медицину и один бонус вдохновения. Вытаскиваю стрелу, протыкая тело насквозь, обламываю острие и вытаскиваю вторую часть, после чего кое как чищу рану и накладываю повязку из кусков своего тряпья",142532,null],[148068,"2026-08-08T22:13:53",9,"*Пацан еще не стабилен, вряд ли но может помереть.*",142532,null],[148069,"2026-08-08T22:14:17",47,"Бля, я дибил. У меня к акробатике бонус д4/",142532,null],[148070,"2026-08-08T22:14:28",9,"//Ебать что за агрессивная медецина",148066,null],[148071,"2026-08-08T22:14:40",20,"/все по канону",142532,null],[148072,"2026-08-08T22:14:51",20,"/так стрелы обычно и вытаскивают",142532,null],[148073,"2026-08-08T22:14:55",31,"Так и делали, жиза суровая/",148070,null],[148074,"2026-08-08T22:15:32",31,"Если просто тянуть, то рваная рана и кровотечение убьет быстро/",142532,null],[148075,"2026-08-08T22:15:46",9,"//Кинь д4+1, столько ты в отключке плюс лишний час за агрессив медецину",148072,null],[148076,"2026-08-08T22:16:05",20,"/r d4+1",142532,null],[148078,"2026-08-08T22:16:17",20,"/ну поспим...",142532,null],[148079,"2026-08-08T22:16:42",47,"Нормуль",142532,null],[148080,"2026-08-08T22:16:53",20,"/жив и ладно",142532,null],[148081,"2026-08-08T22:16:59",9,"*Парня кажется удалось спасти, он дышит, но ели ели. Ищдалека видно как сража движется по стене, вас мониторят и кажется за вами пошлют, нельзя тут задерживаться. К лесу не много ни мало полторы мили, асейчас вы как на ладони.*",142532,null],[148082,"2026-08-08T22:17:05",31,"- вроде выживет. Надо уходить дальше и путать следы",142532,null],[148083,"2026-08-08T22:17:20",47,"- Конрад, придержи стражника, я его обычно и пойдём дальше без туши",142532,null],[148084,"2026-08-08T22:17:27",17,"/ Жаль я не смог отыграть нормально в планах было накрывать пацана и давать ему укрытие своим телом",142532,null],[148085,"2026-08-08T22:17:28",17,"/ Ну ладно. Я щас ещё пока занял попозже включусь",142532,null],[148086,"2026-08-08T22:17:45",31,"Я уже скоро отключусь/",142532,null],[148087,"2026-08-08T22:17:53",31,"Полчасика может еще тут/",142532,null],[148088,"2026-08-08T22:17:55",9,"//Лут?",148083,null],[148089,"2026-08-08T22:18:10",31,"Ага, держу, обыскивай",148083,null],[148090,"2026-08-08T22:18:24",47,"/r +d20-1",142532,null],[148092,"2026-08-08T22:18:29",9,"//Го я лут со стража дам и пока всё на седня",142532,null],[148093,"2026-08-08T22:18:37",47,"16",142532,null],[148094,"2026-08-08T22:19:05",47,"Всё живы все",148084,null],[148097,"2026-08-08T22:22:14",9,"*На стражнике \"бригантина\", под ним \"дорожная одёжка\" военная. На поясе \"короткий меч\" и \"ручной арбалет\", стлел к арбалету нет, остались лежать где-то на стене. На руке \"медное старое выцвевшее кольцо\", \"фляга с водой\" в кармане. Немного денег и не съеденный обед (один рацион).*",142532,null],[148099,"2026-08-08T22:22:51",9,"/roll 1d4 золото\n/roll 2d4 серебро\n/roll 3d4 медь",142532,null],[148101,"2026-08-08T22:23:11",47,"Всё забираю. Фига везёт",142532,null],[148102,"2026-08-08T22:23:19",9,"//Ахахах, везде почти макс",142532,null],[148103,"2026-08-08T22:23:21",47,"Денег максимум /",142532,null],[148104,"2026-08-08T22:25:16",31,"Все, думаю до завтра расходимся, я спать хочу/",142532,null],[148105,"2026-08-08T22:26:10",47,"Мастер, дай титул везунчика",148102,null],[148106,"2026-08-08T22:31:32",17,"/ Ну вот тут я бы бежал прямо за пацаном и прикрывал его, специально чуть медленнее чем мог бы",148009,null],[148107,"2026-08-08T22:35:34",20,"/эх жаль не сработало, наративно круто было бы",148106,null],[148108,"2026-08-08T22:35:45",17,"/ Я бы от 7 урона не сдох",148043,null],[148109,"2026-08-08T22:36:15",17,"/ Ну спасли пацана Конрад красава. Я щас опишу чето чтоб повысить нашу незаметность  в поле мб",142532,null],[148110,"2026-08-08T22:43:05",17,"Люпен обернулся и пацана пробило стрелой, он начал заваливаться вперёд.\n\nКрыса подскочил и поймал его\n\nКонрад тут же четко сработал стелу толкнул дальше на выход из тела и обломал остриё\n\n— Четко сработано. Ты какой то полевой медик в прошлом? \n\nОн осёкся понимая что сейчас не тот момент\n\nПомог наложить повязку на рану пацану чтоб тот не истёк кровью\n\nПодоспел Майн с трофейным стражником\n\n— Я не понял... Ты его скинул со стены и потом подобрал и потащил? Ну ты псих, мужик.\n\nС улыбкой произнес Крыса \n\nПока Конрад держал стражника Люпен взял пацана на руки и продолжил с ним бежать.\n\n— Не отставацте! Они сейчас выпустят конных! Валим, валим!\n\nВзглянул на парня сблизи он вгляделся в глаза, на стене их точно заметили но стражник по какой то причине убежал, а глаза пацана блеснули жёлтым\n\nОн точно видел\n\nКолдовство\n\nОдно из таких, что отняло у него семью, дом и даже имя.\n\nНо даже так, бросать ребенка Люпен был не намерен. Он занимался разбоем и воровством не из за прихоти и удовольствия. Все чтобы заработать средств и вернуть себе своё...",142532,null],[148118,"2026-08-08T23:19:52",20,"/латаем пацана на последок",142532,null],[148163,"2026-08-09T05:58:48",31,"Пока бежим, вспоминаю как можно скрыться в лесу. Отец учил меня охотится в наших родовых лесах, и каждый раз егеря говорили, что найти звер, что ушел по реке сложнее всего, потому что поток воды смывает запахи для собак. Прислушиваюсь, не шумит ли где хотя бы ручей",142532,null],[148164,"2026-08-09T06:00:01",31,"/roll d20 на выживание, слушаю нет ли где шума текущей воды",142532,null],[148166,"2026-08-09T06:00:14",31,"Если кто может помочь, помогите/",142532,null],[148167,"2026-08-09T06:30:18",17,"— Конрад, пара трюков есть. Привяжем к ногам пучки травы чтобы следы затирались. \n\n— Нужно быстрее добраться до леса, там конница не пройдет.\n\n— Искать ручей или мелководье чтобы точно след потеряли.\n\n— Но ещё... Если они выпустят гончих нужно запах отбить, как вариант искать ил или болотную жижу. А если повезёт - говно лося, это идеально было бы.",142532,null],[148168,"2026-08-09T06:30:39",17,"/ Это помощь и в том числе варианты для дальнейшего отыгрыша если хотите",142532,null],[148169,"2026-08-09T06:31:00",17,"/r +2 Выживание",142532,null],[148176,"2026-08-09T07:47:58",9,"*В момент когда вы, беглецы, почти добежали к лесу можно было заметить как идут первые конные от стен, это за вами.*",142532,null],[148177,"2026-08-09T07:48:50",9,"//А сейчас вы можете просто в лесу скрываться, или придумать крутой способ, сами смотрите, пацан в отключке, решайте)",142532,null],[148178,"2026-08-09T07:49:58",17,"— Бежим к бурелому, там точно не проедут!\n\nИщите сразу источники воды, нам понадобятся когда сбросим хвост... И сторониться можно в канавах и под корнями! В общем не щелкайте, а смотрите по сторонам!",142532,null],[148179,"2026-08-09T07:50:14",17,"/r +2 Выживание поиск чего то вроде бурелома, или заметить воду",142532,null],[148181,"2026-08-09T07:58:29",9,"*Лес видимо частично подлежит вырубке, но он стар, очень стар. Ещё до того момента кау вас настигли удалось приметить те самые поваленные стволы, буреломы, приметить старые деревья меж корнями которых можно спрятаться, да и местность была не очень ровная, холмы, рытвины, ямы. Родные для Люпена леса, как дома. Воды пока нет, сложно найти её за такое короткое время.*\n\n*Этот лес ощущался по другому, чем глубже тем он плотнее и мрачнее. Деревья выше, скрыченны и покорёженны, местность хуже проходима. Смена происходила не резко, но с видимой для опытного лесника скоростью.*",142532,null],[148183,"2026-08-09T08:14:53",17,"— Черт, место где спрятаться есть с запахом надо что то решить! Если там псы, нам нельзя останавливаться и прятаться!\n\nМужчина начал стягивать с себя рубаху и закинул ее на ветку дерева\n\n— Может моя потная рубашка чучуть заржит псов",142532,null],[148184,"2026-08-09T08:15:20",17,"— Ищем Ил болта или говно лося, надо обмазываться!",142532,null],[148199,"2026-08-09T10:05:43",47,"Hard",142532,null],[148200,"2026-08-09T10:21:21",17,"/ Блять что это за мясник из блавикена",142532,null],[148201,"2026-08-09T10:27:17",47,"/вор, сирота, стандартный плут",142532,null],[148202,"2026-08-09T10:27:39",17,"/ Нет нормальный человек не будет резать на куски тело",142532,null],[148203,"2026-08-09T10:27:43",17,"/ В моем понимании",142532,null],[148204,"2026-08-09T10:27:54",17,"/ Да и это пиздец долго",142532,null],[148205,"2026-08-09T10:28:03",47,"/так я и не говорил, что он нормальный... Однако согласен, зашквар",142532,null],[148206,"2026-08-09T10:28:53",47,"/но в любом случае тело стража должно их отвлечь. Тем более под моими обмотками вонючими и санными",142532,null],[148207,"2026-08-09T10:29:03",17,"/ из за такой хуйни будет тяжело дальше общаться нормально персами просто",142532,null],[148208,"2026-08-09T10:29:15",17,"/ Ну ты делай чё хочешь конечно",142532,null],[148209,"2026-08-09T10:31:29",47,"/не не",142532,null],[148210,"2026-08-09T10:31:34",47,"/согласен",142532,null],[148211,"2026-08-09T10:35:50",31,"Тоже кажется что перебор, но спишем на стресс//",142532,null],[148299,"2026-08-09T12:09:10",47,"Тэкс. Так что, бежим?",142532,null],[148300,"2026-08-09T12:09:17",47,"@QURTZZ @dunchev @PaIIasCat ?",142532,null],[148301,"2026-08-09T12:09:19",47,"Hard",142532,null],[148302,"2026-08-09T12:09:33",47,"Мы бежим и следы путаем",142532,null],[148303,"2026-08-09T12:10:11",31,"Да, бежим/",142532,null],[148399,"2026-08-09T14:17:53",9,"*Вам на пути встречается углубление, тут лужа? Скорее крохотное вонючее болотце, ил, жабы и почти засохшие камыши.*",142532,null],[148430,"2026-08-09T14:25:06",31,"Отлично, мажем в этом иле свою обувь, чтобы собакам осложнить жизнь",142532,null],[148446,"2026-08-09T14:41:12",9,"//Да да, делай а не говори, остальных тож жду что они",142532,null],[148454,"2026-08-09T14:45:14",9,"// @dunchev йоу, нужны все трое в сознании, играем",142532,null],[148455,"2026-08-09T14:45:23",31,"Так я сделал, видишь же что от лица персонажа писал/",148446,null],[148457,"2026-08-09T14:45:51",9,"//Раз ты делаешь",148455,null],[148459,"2026-08-09T14:46:23",47,"Я переоделся. Они ищут по запаху тюремному, а у меня теперь запах стражника!",142532,null],[148461,"2026-08-09T14:46:50",47,"Ну съебываю я по деревьям нафиг. Задачу и прыгаю как сайгак. Кидаю акробатику значится",142532,null],[148462,"2026-08-09T14:46:58",47,"/r d20+3+1d4",142532,null],[148464,"2026-08-09T14:47:30",47,"/если не хватает, докину вдохновение",142532,null],[148465,"2026-08-09T14:47:43",47,"Д4 за счёт рассовой абилки",142532,null],[148466,"2026-08-09T14:49:13",17,"/ Я тут",148454,null],[148469,"2026-08-09T14:49:59",17,"Люпен прыгает в болото и перекатывнтся там как гусеничка, рубаху он уже выкинул так что быстро покрывает тело илом\n\n— Удача!",148399,null],[148471,"2026-08-09T14:50:36",17,"— Сайн, нахера ты на дерево полез? Так же медленнее!",142532,null],[148472,"2026-08-09T14:51:34",17,"Конрад подержи парня, его тоже надо обмазать\n\nЛюпен садится на колени и набирает в ладони кучку ила\n\nНесёт в Рему и мажет его лицо волосы, одежду и кожу\n\nШею, запястия, голени",142532,null],[148473,"2026-08-09T14:51:55",17,"/ На качество маскировки запаха кидать?",142532,null],[148474,"2026-08-09T14:53:36",9,"*Вы слышите в голове недовольный голос.*\n\n\"Это... моё... болото...\"",142532,null],[148477,"2026-08-09T14:55:02",9,"*Гигансткая жаба поднимается из грязи с легкой коркой земли, её глаза красные, вертикальные.*\n\n\"Идите... отсюда...\"",142532,null],[148482,"2026-08-09T14:57:25",17,"Люпен протирает глаза. На его лице ужас, он думает что это все дурной сон. Но сразу же бьёт тебя по щеке, сильнр\n\n— Нечисть! Бегите!",142532,null],[148487,"2026-08-09T15:00:01",9,"//Другие что?",142532,null],[148491,"2026-08-09T15:01:37",31,"Валим, не хватало еще дюжабьим обедом стать",142532,null],[148492,"2026-08-09T15:01:50",31,"Тащу Рена на себе",142532,null],[148493,"2026-08-09T15:03:06",9,"*Жаба вас провожает недовольным взглядом, она была не в настроении и не голодна, иначе...*\n\n\"Шшшшшшшшш...\" — *Все слышат недовольный звук ворчания, даба снова зарывается в грязь, а вместе с ней вырываются кости разных животных, и человеческие.*",142532,null],[148494,"2026-08-09T15:03:30",9,"//Хотя что там Сайн делает?",142532,null],[148495,"2026-08-09T15:03:45",31,"Он как Тарзан по деревьям херачит/",142532,null],[148496,"2026-08-09T15:03:53",31,"На лианах качается/",142532,null],[148498,"2026-08-09T15:05:12",9,"*Чем дальше лес, тем он дремучее. Но вы не всемогущи. Можно рискнуть и отдохнуть, или идти вперёд не останавливаясь? Так глубоко за вами не должны идти.*",142532,null],[148504,"2026-08-09T15:08:01",17,"— Надо бежать! Чем дальше йжем тем спокойнее будет дклать привал! Терпите друзья.\n\nЛюпен запыхался уже и сам, грязь и ил, смываемые потом, застилают глаза\n\nОн протирает их тыльной стороной ладони которую намерено оставил чистой",142532,null],[148505,"2026-08-09T15:08:24",17,"— И ищите воду, без воды нам все равно смерть! Желательно без жаб.",142532,null],[148506,"2026-08-09T15:08:37",17,"/r +2 Выживание на поиск источника питьевой воды",142532,null],[148515,"2026-08-09T15:15:13",9,"*Здесь нет чистых источников, лишь грязные лужи встречаются иногда, в некоторых вода достаточно прозрачна. Пить её? Не то чтобы хорошая идея.*\n\n//Помню как минимум одному из вас давал флягу с водой, но тип того, тоесть вы совершаете марш бросок?",148507,null],[148516,"2026-08-09T15:15:38",17,"/ Фляга у Сайна он думал стража",142532,null],[148517,"2026-08-09T15:15:53",17,"/ Я предлагаю бежать дальше не останавливаясь. Жду реакты остальных",142532,null],[148518,"2026-08-09T15:16:05",17,"/ @QURTZZ @cirson @PaIIasCat",142532,null],[148519,"2026-08-09T15:16:14",31,"- да, лучше отойти подальше, пока силы есть",142532,null],[148528,"2026-08-09T15:20:05",20,"/у нас их две - одну дали пацану ещё в тюрьме, вторая с трупа",148515,null],[148529,"2026-08-09T15:20:13",9,"//Миха файтится)))",142532,null],[148530,"2026-08-09T15:25:40",47,"Я тут, что надо от меня? /",142532,null],[148536,"2026-08-09T15:26:48",17,"/ ты по идее сильно медленне нас передвигаешься",142532,null],[148537,"2026-08-09T15:26:52",17,"/ По деревьям",142532,null],[148538,"2026-08-09T15:26:54",47,"Да нифига",148536,null],[148539,"2026-08-09T15:26:56",17,"/ Решай что то",142532,null],[148540,"2026-08-09T15:27:06",17,"/ Ну мастер скажет я бы сказал в 2 раза точно",142532,null],[148542,"2026-08-09T15:27:25",47,"/если без броска навыка, то да. Если с броском то обычно риск",148540,null],[148545,"2026-08-09T15:31:29",9,"*Деревья не сильно плотно меж собой, местами это риск. Ещё надо за остальными поспевать, что трудно.*",148542,null],[148546,"2026-08-09T15:31:49",47,"Ну ок. Тогда не лезу... Я думал плотный лес",148545,null],[148547,"2026-08-09T15:31:54",47,"Бежим, бегом",142532,null],[148548,"2026-08-09T15:31:59",9,"//Если бы у него был атлетичный я бы ток один бросок потребовал, а так да",142532,null],[148549,"2026-08-09T15:32:20",9,"*Вы бежали пока могли, в тёмный и дремучий лес.*",142532,null],[148550,"2026-08-09T15:32:30",9,"/roll 1d2 везение ваше",142532,null],[148552,"2026-08-09T15:32:45",9,"/roll 1d5 насколько вам не повезло",142532,null],[148554,"2026-08-09T15:33:41",31,"Описывай в чем наш пиздец и видимо будем завтра играть, Коля уезжает//",142532,null],[148555,"2026-08-09T15:35:26",9,"*Вы бежали и за очередным холмом, под сумерки, почти лицом к лицу встречаетесь с бурым медведем, он завидел вас и встал на задние лапы. Вы выскочили так внезапно что он насторожился.*\n\n//Меж вами 50 футов",142532,null],[148556,"2026-08-09T15:36:04",31,"То есть это второй уровень неплвезло. Кто был на пятом, тараск?/",142532,null],[148557,"2026-08-09T15:39:43",47,"/наоборот, ниже значение - всё хуже",142532,null],[148558,"2026-08-09T15:40:19",47,"- Мишка, мишка. Там есть еда. Заходишь за угол и лежит тело - пиздит Сайн высматривая возможность сьебать",142532,null],[148559,"2026-08-09T15:40:34",9,"//Сорян, я буду бесстрастным и ориэнтироваться на рандом",142532,null],[148560,"2026-08-09T15:41:00",47,"Иду по кругу отдаляясь от холмика. Если это мамка, то главное быть подальше от логова с медвежатами... А батя бы просто вьебал",142532,null],[148561,"2026-08-09T15:41:10",9,"*Михалыч не ведет ухом, он не понимает тебя, но все еще думает, оценивает вас.*",148558,null],[148562,"2026-08-09T15:41:14",47,"Уклонение юзаю и отвлекаю внимание на себя. Взял щит ещё",142532,null],[148563,"2026-08-09T15:41:24",9,"//Щит?",142532,null],[148564,"2026-08-09T15:41:27",47,"/что было в сух пайке?",142532,null],[148565,"2026-08-09T15:41:34",47,"Да, украшенный рапирой",148563,null],[148566,"2026-08-09T15:41:50",9,"//А, ты его стырил!)))",148565,null],[148567,"2026-08-09T15:41:55",47,"Ну конечно!",142532,null],[148568,"2026-08-09T15:41:58",9,"//Ай какой молодец",142532,null],[148569,"2026-08-09T15:42:04",47,"/конечно!",142532,null],[148570,"2026-08-09T15:42:21",47,"/одну отломал, ещё одну союзнику отдам",142532,null],[148571,"2026-08-09T15:42:25",9,"//Добавлю тебе 1д4 в вдохнову",142532,null],[148572,"2026-08-09T15:42:37",47,"?",148564,null],[148573,"2026-08-09T15:43:20",9,"//Хлеб с салом и луком, и так капчёностей немного",148572,null],[148574,"2026-08-09T15:43:51",47,"Тогда кидаю это медведю",142532,null],[148575,"2026-08-09T15:43:55",9,"//Тоесть резкое движение или просто готов уклоняться?",148562,null],[148576,"2026-08-09T15:44:00",47,"Готов/",148575,null],[148577,"2026-08-09T15:44:10",47,"/я нэ дибил",142532,null],[148578,"2026-08-09T15:44:23",47,"- за мной - шёпотом",142532,null],[148579,"2026-08-09T15:45:48",47,"/как реагирует медведь на запах сала и копченостей?",142532,null],[148580,"2026-08-09T15:45:52",9,"*Медведь немного дёрнулся когда в него кинули чем то. Все еще стоит но запах капченостей показался ему привлекательным. Так продолжалось ещё пол минуты пока он медленно не стал на передние, с любопытством пошёл немного вперёд и понюхал еду, кажется запах ему понравился и он начал есть.*",142532,null],[148581,"2026-08-09T15:45:59",31,"Съебываем за Свйном пока Мишка ужинает. Не нами",142532,null],[148582,"2026-08-09T15:46:07",9,"//Меж вами и медведем 40 футов",142532,null],[148583,"2026-08-09T15:47:04",9,"//И ждем николая выходит как после юбилея воротится или уже завтра",142532,null],[148584,"2026-08-09T15:50:54",47,"Сайн на опыте)",142532,null],[148585,"2026-08-09T15:51:03",47,"Почему-то Свейном стал)",142532,null],[148586,"2026-08-09T15:51:29",31,"Очепятка/",142532,null],[148850,"2026-08-09T17:47:02",17,"/r +2 Природа на повадки медведей. Чтобы вспомнить как лучше себя вести при встрече с этим опасным хищником",142532,null],[148859,"2026-08-09T17:48:26",9,"//Мне накинуть инфы или сам + - понимаешь?",148851,null],[148915,"2026-08-09T18:00:35",9,"*Никаких резких двидений, медведь немного тоже боится, с меньшим шансом нападет на того кто кажется выше. Если не голоден может уйти, главное не убегать от него пока он вас видит инсктинты его погонят за вами. Хорошо что вас много, на одного больше шансов что нападёт.*",148851,null],[148920,"2026-08-09T18:09:51",17,"Шепотом \n\n— Сайн прав, главное не делайте резких движений идём плавно",142532,null],[148925,"2026-08-09T18:13:06",31,"тихо валим пока миша кушает",142532,null],[148928,"2026-08-09T18:14:49",9,"*Тишком нышком вам удаётся скрыться из его зоны видимости, он уже сьёл сало и капчености к этому чремени, сейчас пробовал хлеб.*",142532,null],[148961,"2026-08-09T18:21:54",17,"— Жаль мясо и хлеб, еды у нас не много... Но ты правильном сделал Сайн, спас нас возможно. Спасибо.",142532,null],[148966,"2026-08-09T18:22:38",17,"— Давайте ещё немного пробежим и устроим привал, найдем место где сторониться пока последователи устанут",142532,null],[148998,"2026-08-09T18:28:19",9,"*Медведь кажется не стал вас преследовать. Вглубь чащи много хороших мест для лагеря, но сыро и становится потихоньку холодно.* \n\n//Всем троим спас тела за марш бросок, сл 10 или 1 истощение + Рен думаю к этому времени может очнутся",142532,null],[149002,"2026-08-09T18:28:54",31,"/roll d20+2",148998,null],[149022,"2026-08-09T18:31:37",17,"/r +2 Тело",148998,null],[149027,"2026-08-09T18:32:37",47,"Прошёл",142532,null],[149029,"2026-08-09T18:32:41",47,"Я",142532,null],[149032,"2026-08-09T18:34:04",20,"*Пацан слегка шевелится на руках у Конрада, морщась от раны. Но молчит и даже не всхлипывает, оглядываясь вокруг и пытаясь понять ситуацию*",142532,null],[149034,"2026-08-09T18:35:00",17,"— О, очнулся. Да это не рай, ты опять на бренной земле пацан. Мы все ещё пытается сбежать как можно дальше. Не дергайся, рана будет долго болеть.\n\nПо отечески Люпен сжал ладонь парня. Жест обозначал явно, \"ты не один\"\n\n— Не боись, приглядим за тобой.",149032,null],[149044,"2026-08-09T18:39:05",20,"- Хорошо \n\n*Рен кивает, послушно оставаясь максимально неподвижным. На удивление в отличие от того, как он вел себя в камере и перед стражниками он даже не всхлипывает.*\n\n- спасибо что не бросили...",142532,null],[149046,"2026-08-09T18:39:27",47,"/вопрос, а мы понимаем, что это он колдовал?",142532,null],[149051,"2026-08-09T18:42:12",20,"/ну, наверное пока только Люпен догадывается, так как он за ним наблюдал да и на проницательность пробросил раз",149046,null],[149052,"2026-08-09T18:42:25",9,"//Решите сами, но скорей вот так",149051,null],[149066,"2026-08-09T18:47:00",47,"- Капец они лошары. Ахахха - разорвался смехом Сайн",142532,null],[149070,"2026-08-09T18:48:16",47,"- Ебать. Я в ахуе. Мне один раз в жизни не повезло. Вчера, когда меня поймали и нацепили маску. Кто же знал, что за углом их ещё двое? Но то, что происходило сегодня, это верх искусства. Пацаны. Со мной не пропадете, зуб даю - щелкнул по зубу",142532,null],[149088,"2026-08-09T18:54:17",47,"- Я предлагаю где-то здесь остановиться и передохнуть. Я если что в лесу не жил, я городской, надеюсь не оставите голодным? \n Ну и познакомимся заодно нормально. Я Сайн молчаливый... Когда кликуху поймал я голос простудил, молчал, а потом уже от обратного пошло. Ну подрабатывал взломом, иногда по мелочи продавал краденное... - помрачнел, но ничего не сказал запнувшись - ну и так по мелочи. Хотел было последним делом всё и завершить, к портнихе нанялся помощником, клей ей варил, другие смеси... Да за последнее дело меня и одели - рассказал Сайн",142532,null],[149089,"2026-08-09T18:54:36",20,"- Да, похоже ты и правда поделился с нами своей удачей, Мистер Маска *мальчик слабо улыбается*\n\n- Простите что мало чем смог помочь, да ещё и стрелу словил, лишним грузом стал... Я кроме простой работы вроде уборки и мелкого хозяйство мало что умею...",149070,null],[149102,"2026-08-09T18:58:30",47,"- Пацан, не робей. В обиду не дадим. Только в рот - спохватившись добавил - тем кто обижает",149089,null],[149119,"2026-08-09T19:07:06",47,"@dunchev @QURTZZ",142532,null],[149120,"2026-08-09T19:07:11",47,"На короткий?",142532,null],[149121,"2026-08-09T19:07:20",47,"Общаться будете?",142532,null],[149129,"2026-08-09T19:11:59",31,"Да уже на длинный наверное надо. Общаться сомнительно, тут все сильно устали",142532,null],[149130,"2026-08-09T19:12:34",47,"/как игроки, или как персонажи?",142532,null],[149131,"2026-08-09T19:13:40",31,"Хард просил нас длинный сделать//",149130,null],[149132,"2026-08-09T19:14:02",9,"//Общайтесь, на сёдня всё если на длинный ляжете завтра с утреца награды дам и пощитаю прогресс. Так то я смотрю на ваши действия и ускоряю прогресс как если бы обучались на практике",142532,null],[149134,"2026-08-09T19:14:36",31,"лдано, устраиваемся на длинный, пиздим лениво перед сном//",142532,null],[149139,"2026-08-09T19:17:44",47,"/я о себе рассказал, мой перс расчитывает на такую же честность",142532,null],[149140,"2026-08-09T19:18:01",9,"//Социалка эт хорошо, одобряем 👍",142532,null],[149141,"2026-08-09T19:18:21",31,"- я вообще не помню как оказался в темнице. я только недавно прибыл в Аннеж, ксидел себе в таверне, тянул пиво и вот вдруг проснулся в темнице, считай что голый\n\n*смотрю на руку*\n\n- суки, кольцо родовое сняли. ОЧень херово, это мое единственное доказательство принадлежности к роду. нужно бы вернуть...",142532,null],[149143,"2026-08-09T19:19:44",17,"/ Я тут",142532,null],[149144,"2026-08-09T19:19:50",17,"/ Сек прочту",142532,null],[149176,"2026-08-09T19:27:58",17,"— Сайн, ты хоть городской, а промысел у нас схожий. Я тоже замки ковырял, не от сытой жизни. Браконьерствовал.\n\n— Ваще представьте у меня все было... Дом, ферма, жена красавица, сын и дочка. Сыну вот как нашему пацану примерно. И все пропало...\n\nЛюпен смачно смаркается и плюет в сторону\n\nЯ на охоту ходил, тащу глухаря, довольный такой... Прихожу домой. А там сидит за моим столом с моими родными, тварь неведомая, один в один на меня похожа, только уши длинные эльфские. Ну я расверепел, в драку сразу, за свое привык бороться. Так жена меня не узнала, дети в слезы от меня. А этот колдун ебучий меня одной левой сработал и выбросил за калитку родного дома. Соседи смеялись, я нихуя не понял. Походил походил пару дней. \n\nИ в лес ушел, там жил, с бандой связался и пошло блять поехало. \n\nНу что сказать, если нас не поймают, прокормить вас смогу, только нужно лук сделать и стрел настрогать.",142532,null],[149177,"2026-08-09T19:28:48",17,"— Конрад, а ты и правда благородный?\nМне всё ещё не верится чтоб аристократ тифозную крысу зубами рвал, уважаю твою решимость мужик.",149141,null],[149178,"2026-08-09T19:29:59",20,"- Значит ты сказал стражникам правду? *Мальчик на твоих руках смотрит на тебя широко раскрытыми глазами* - Ты и правда из благородных...а у тебя есть замок?",149141,null],[149180,"2026-08-09T19:31:27",17,"Люпен между делом рыл ямку поглубже под корнем на половину выкорченого из земли дерева, для того чтобы схорониться",142532,null],[149185,"2026-08-09T19:33:25",31,"- я и сам уже по чуть-чуть перестаю верить. Мой отец был бароном, тут неподплеку, в Шаттаенхаусе, там же и родовой замок стоит. Пока не поругался с каким то графом, и тот просто стер наш род с лица земли, уж не знаю, как он откупился от правосудия, но нашлись бумаги, согласно которым наш род не имел права жить в постронном нами же замке 300 с лишним лет назад. всех и повесили одним днем, сразу после того как замок взяли. я вылез кое как через потайной ход, что мне отец показывал, только одно кольцо родовое и вынес на себе. оно чуток волшебное, кровь чует и, обычно просто серебряное, но на руке родича щит зеоеным становится. Это было 6 лет тому назад, мне 15 было. Что я мог? да нихрена. Сппсибо монахам, пригрели, да научили руками и ногами махать",149177,null],[149187,"2026-08-09T19:34:22",31,"- есть замок. только как туда вернуится хозяином я не знаю",149178,null],[149189,"2026-08-09T19:35:34",20,"- Звучит как что-то из старой страшной сказки... Неужели в реальности колдуны на такое способны? Жуть, особенно то, что тебя никто не узнал. Наверное это было самое страшное...",149176,null],[149197,"2026-08-09T19:39:09",17,"— Пацан, колись, ты тоже колдун? Видел как глазки блестели у тебя, да и не похоже что ты просто маленький мальчик в большом мире. У тебя слишком крепкие нервы для тринадцати лет.",149189,null],[149224,"2026-08-09T19:46:32",20,"*Рен замолкает, опуская глаза*\n\n- Не колдун я...был бы может быть смог помочь больше. Я... *Он немного тормозит, будто пытаясь обдумать, как это объяснить*\n\n- Я замечал, что иногда могу сказать что-то...ну, не в слух. Но человек все равно услышит. Как если бы ты только подумал - и это сразу пришло бы в голову другому. *он снова поднимает голову и вы понимаете что за всю эту фразу он не открывал рта. Вообще*\n\n-...не знаю, магия ли это. Сомневаюсь...да и помимо трюка с голосом я мало что могу сделать.",149197,null],[149231,"2026-08-09T19:48:02",17,"— Ну точно колдун ахазах. Но на нашей стороне колдун нам необходим, ибо против нас их целый мир. Ладно ты только не заигрывай с дьяволом слишком сильно пацан.\n\nЛюпен принял Рема таким какой он есть",142532,null],[149235,"2026-08-09T19:48:42",20,"- А то что спокоен... *Он поджимает губы и теперь становится заметно, что они немного дрожат*\n\n- я не спокоен, мне страшно...я просто не до конца могу поверить, что я- ...я будто только вчера жил своей обычной тихой жизнью...и теперь вот это все",142532,null],[149243,"2026-08-09T19:49:43",20,"- хаха, хорошо *на лице пацана появляется небольшая, но искренняя улыбка*",149231,null],[149246,"2026-08-09T19:49:58",31,"- может и не колдун, может чародей. такие рождаются с магией, она разная может быть",142532,null],[149272,"2026-08-09T19:53:03",17,"— Интересно послушать, тебя наверное учили преподаватели и все такое, я умею картошку выращивать и лук могу сделать из орешника лучше всего получится. Да и больше нихрена наукам не обучен.",142532,null],[149319,"2026-08-09T19:58:48",31,"- меня учили охотится на лис и танцевать. не думаю что мне это сильно поможет. ну чуток фестовать, хотя я уже и забыл как держать рапиру. ну читать и писать умею, да, историю знаю более или менее, хотя бльше это история рода.",142532,null],[149335,"2026-08-09T20:01:04",9,"//Актуальный музон для путешествий",142532,null],[149343,"2026-08-09T20:01:44",20,"/боже, какая ностальгия",149328,null],[149347,"2026-08-09T20:02:55",17,"/ Да, это ОНО",142532,null],[149362,"2026-08-09T20:04:30",17,"Люпен достал две крысы которые удалось найти и изловить в темнице\n\n— Есть немного мяса, но костер разжигать все ещё опасно, особенно ночью. Будет видно издалека. Терпеть нам до завтра. Отойдем дальше, найдем водоем и там уже пожарим.",142532,null],[149408,"2026-08-09T20:13:40",47,"Повторяю. Понимаю шо не просто так, а для комфортного сна",149180,null],[149430,"2026-08-09T20:17:09",17,"/ Ну да, слово схорониться там. Ошибка была",149408,null],[149436,"2026-08-09T20:20:11",31,"Ладно, я спать, перс тоже отваливается, прислонившись к дереву/",142532,null],[149437,"2026-08-09T20:20:13",47,"- Пацаны, приятно со всеми познакомиться  с вами. Но что делать будешь дальше? Понятно, что завтра новый день, печали заберёт заря, принесёт мудрости, рассвет, но всё же. Мысль на засыпку. Куда дальше? \n В ближайших городах явно на нас ориентировки, а в лесу жить лично я не умею, а обузой быть не привыкший",142532,null],[149476,"2026-08-09T20:32:43",17,"— Можно и в лесу жить. Я научу. Не знаю честно слово. Куда и как лучше.",149437,null],[149556,"2026-08-10T00:13:47",9,"// @cirson @dunchev @QURTZZ @PaIIasCat щас я вам в ваших анкетах дам опыт и укажу скок дней вы как будто обучались. Чему обучались? Всему что в теории могли бы за 4 дня имея наставника.",142532,null],[149567,"2026-08-10T05:43:48",17,"/ Круто!",142532,null],[149666,"2026-08-10T09:58:24",47,"Hard я готов. Зовём остальных?",142532,null],[149686,"2026-08-10T10:01:33",9,"//Я буду в течении часа, ничего не мешает вам немного посоциалить пока я не прийду.",142532,null],[149688,"2026-08-10T10:02:37",47,"/описываем утро?",142532,null],[149689,"2026-08-10T10:03:26",47,"@QURTZZ @PaIIasCat",142532,null],[149690,"2026-08-10T10:03:44",9,"//Щас вам опишу тогда если длительный был",142532,null],[149691,"2026-08-10T10:03:53",47,"/что по жрачке?",149690,null],[149693,"2026-08-10T10:04:01",47,"/могу объяснить как перекусил?",142532,null],[149697,"2026-08-10T10:05:24",17,"Люпен на утро встал с жуткой болью в суставах, спать на холодной земле никогда не бывает приятно. Но всё же отдых пошел на пользу.\n\n— Жрать охото. Надо найти источник воды. Как поспали? Кошмары не снились? Мне вот снился, и, сука, один и тот же. Как я возвращаюсь домой а там дьявол мою жену... Эх.",142532,null],[149699,"2026-08-10T10:06:06",31,"- я почти некогда не помрю снов. может и к лучщему это... да, жрать хочется",142532,null],[149701,"2026-08-10T10:07:29",9,"*Ночь была холодной, а утро голодным. Вчерашних пирожков и еды вам хватило едва не потерять силы, но тело не обманешь, хочется есть чего нибудь нормального.*\n\n*У рена болело все тело где он был прошит стрелой, эти боли будут его преследовать ещё долгое время, если он не вылечит раны зельем или чудесным способом. Немного тяжело дышать.*",142532,null],[149705,"2026-08-10T10:09:48",20,"*Среди корней другого дерева в куче листьев раздается шевеление и оттуда показывает пацан*\n\n- утра... *Тихо приветствует он, вылезая к остальным, морщась от раны*\n\n*Он промолчал, но хорошо припомнил свой кошмар - раз за разом повторяющийся в голове анализ, где он был слишком самоуверен или невнимателен и оступился.*\n\n- Да, еда была бы кстати ...\n\n/Я не восстанавливаю хиты?",149701,null],[149706,"2026-08-10T10:10:03",9,"Выживающие на грани поколениями:\n— Вы получаете владение навыками Природа и Выживание.\n— Каждый раз при получении уровня ваш максимум хитов дополнительно увеличивается на 1.\n— Выберите родную местность (например, лес). В сезон этой местности при активном поиске вы автоматически находите достаточно еды, чтобы прокормить 1d4 существ. В остальное время вы как минимум обеспечиваете себя пропитанием достаточным чтобы не умереть с голоду.\n//Просто напомню что человек из глубинки может найти в сезон еды в лесу еа 1д4 человек в день. Ну и у Люпена осталось то одно истощение из-за плохихи условий сна и всё такое.",142532,null],[149707,"2026-08-10T10:11:02",9,"//Не, рес хитов можно как обычно, норм усё, если бы был дебаф я бы описал, он скорее нарративный",149705,null],[149771,"2026-08-10T10:38:21",17,"— Я пойду на поиски воды, заодно поищу орешник, мне для того чтобы сделать примитивный лук нужна еще крепкая веревка, пока не знаю где взять\n\nЛюпен осматривает свои портки на предмет шнурка",142532,null],[149774,"2026-08-10T10:39:25",9,"*Обноски не очень для такого, да и шнурок не годится на роль тетивы.*",149771,null],[149776,"2026-08-10T10:40:13",31,"- жила нужна для тетивы. думаю из наших шмоток можно сделать силки, поймаем мелкого зверя, и из его жил сдлеаем тетиву",142532,null],[149778,"2026-08-10T10:41:35",17,"— Тоже верно, давайте подготовим ловушки.\n\nПокрутив нож в руке Люпен начал срезать веточки для создания силков",142532,null],[149781,"2026-08-10T10:41:45",17,"— Надо ягод найти, чтобы зайца приманить в силок",142532,null],[149782,"2026-08-10T10:41:53",47,"Сайн проснулся довольным, не зря он повторил за Люпеном действия. Мягкая листва, 3 знамени и лежбище у дерева... Почти что на топчане поспал",142532,null],[149783,"2026-08-10T10:42:23",47,"/я уже который раз счастлив, что спиздил шмоток ткани)",142532,null],[149784,"2026-08-10T10:42:55",47,"- А я пошёл искать ягоды тогда - кивнул Сайн и пошёл искать ягоды... Или яблоки?",142532,null],[149785,"2026-08-10T10:43:03",47,"/r -d20-1  лениво это делаю",142532,null],[149788,"2026-08-10T10:43:12",47,"/r d20-1  везунчик",142532,null],[149790,"2026-08-10T10:43:19",47,"12 итоговое",142532,null],[149791,"2026-08-10T10:43:26",47,"Выживание/внимание",142532,null],[149798,"2026-08-10T10:44:32",20,"/у нас кстати ещё кусок сала есть из комнаты сторожа",142532,null],[149800,"2026-08-10T10:45:10",47,"О и сыр!",142532,null],[149801,"2026-08-10T10:45:14",47,"Я же сыр пиздил!",142532,null],[149808,"2026-08-10T10:47:07",47,"Короче реинвентаризацию пора провести и вписать, то, что не вписал",142532,null],[149809,"2026-08-10T10:47:21",47,"- А, пацаны, кто рапирой умеет пользоваться? Я могу поделиться!",142532,null],[149814,"2026-08-10T10:48:20",31,"- я учился в детстве. но сейчас уже не вспомню сразу навреное, полжизн прошло.\n\n/владения нет, я хз как ей пользоваться в таком случае//",149809,null],[149817,"2026-08-10T10:48:29",17,"— Я не обучен, буду махать как палкой, да и тяжелая она",142532,null],[149819,"2026-08-10T10:48:42",17,"/ Да просто без БМ",149814,null],[149821,"2026-08-10T10:48:43",9,"*Лёс тёмен и скуден, ты нашёл мухомор с пару грибов которые не можешь определить. *",149789,null],[149823,"2026-08-10T10:49:17",47,"/ебать. А сколько надо, чтобы просто норм ягоды найти?(",142532,null],[149824,"2026-08-10T10:49:24",47,"Собрал. Вернулся назад",142532,null],[149825,"2026-08-10T10:49:24",31,"то есть чисто с онусом ловкости? д20+4 на попаданти и л8+4 на урон? без минусов?/",149819,null],[149826,"2026-08-10T10:49:34",47,"-1/",149825,null],[149827,"2026-08-10T10:49:37",9,"//Щас это +1 к попаданию не очень, но обучиться потихоньку рапире а потом найти того кто научит приемам",142532,null],[149828,"2026-08-10T10:49:40",47,"/потому что плохая рапира",142532,null],[149829,"2026-08-10T10:49:50",47,"/+3 итоговых",142532,null],[149830,"2026-08-10T10:49:57",9,"//Ты отрываешь вторую со щита?",149828,null],[149831,"2026-08-10T10:50:02",17,"/ У тебя ловкость 3 без БМ и еще -1 качество рапиры будешь бить с +2",149825,null],[149832,"2026-08-10T10:50:09",47,"Ещё нет. Если только скажут, да дай мне/",149830,null],[149835,"2026-08-10T10:50:45",17,"/r +2 Люпен изготавливает примитивный силок",142532,null],[149837,"2026-08-10T10:50:50",31,"- могу я вязть. она врод не идаель баллансированая, но лучше чем просто кулаком бить. наверное",149831,null],[149838,"2026-08-10T10:51:02",17,"/ Ваще то нет)))",142532,null],[149841,"2026-08-10T10:51:09",17,"/ У тебя там 2 атаки а тут одна кривая))",142532,null],[149842,"2026-08-10T10:51:31",31,"бля, точно, там же две. у сюка/",149841,null],[149846,"2026-08-10T10:52:39",47,"- С тебя потом тоже подачка какая нибудь - прутом от тюрьмы пытаюсь вытянуть",142532,null],[149847,"2026-08-10T10:53:20",31,"- вообще, пусть будет. вдруг пригодится",142532,null],[149850,"2026-08-10T10:53:51",9,"//Воровские инструменты от ловкости вродь и если у тебя ловкость +3 и +1 от инструмента то сложность твоего силка 21. Но у тебе нет воровсуих, поэтому только бонус от ловкости.",149836,null],[149854,"2026-08-10T10:54:45",9,"//Воровские позволяют делать и ставить ловушку в течении часа я читал, сложность = проверке, а потом при установке вродь проверка на скрытность ловушки",142532,null],[149858,"2026-08-10T10:58:49",17,"/ Надо раздобыть воровской наборчик",142532,null],[149860,"2026-08-10T10:59:35",9,"*Собрать силок без инструментов было сложно.*\n\n//Кинь ловкость рук сл 15 чтобы получился, с инструментом бы без проверок справился. А так использую правило проверки нашего крафта.",149836,null],[149862,"2026-08-10T11:00:20",47,"Так... Вот же он?.. /",149836,null],[149863,"2026-08-10T11:00:27",47,"Бросок на изготовление/",142532,null],[149864,"2026-08-10T11:00:50",9,"//Это? Ну пусть, тогда бросок ловкости на сложность силка",149862,null],[149866,"2026-08-10T11:01:02",9,"//Типа, насколько хорошо получился",142532,null],[149867,"2026-08-10T11:01:05",17,"/r +3 Ловкость рук",149860,null],[149869,"2026-08-10T11:01:05",47,"Я могу помощь оказать? /",142532,null],[149870,"2026-08-10T11:01:14",47,"Я хочу оказать помощь",142532,null],[149872,"2026-08-10T11:01:27",47,"Подхожу, делаем вместе. Изготовлением ловушек занимался я",142532,null],[149873,"2026-08-10T11:01:27",9,"//Го",142532,null],[149874,"2026-08-10T11:01:37",47,"Пусть и не силков",142532,null],[149875,"2026-08-10T11:01:46",17,"— Сайн затяни, я подержу",142532,null],[149876,"2026-08-10T11:01:53",17,"/Кидай ты",142532,null],[149877,"2026-08-10T11:01:57",9,"//Я сам ток разбираюсь в изготовлении ловушек, тяжко это",142532,null],[149878,"2026-08-10T11:02:18",47,"/r +d20+4 ну ок. Делаю",142532,null],[149880,"2026-08-10T11:02:28",47,"/r d20+4 везун",142532,null],[149883,"2026-08-10T11:02:37",47,"Ай",142532,null],[149884,"2026-08-10T11:02:40",47,"Не спецом",142532,null],[149887,"2026-08-10T11:03:57",9,"*Отличный силок, хоть и примитивный, живность вряд ли из него выберется, главное поавильно установить.*\n\n//Сложность этого силка 18 если в него чет попадет",149881,null],[149891,"2026-08-10T11:05:54",47,"/уже -2 везунчика. Ауч!",142532,null],[149899,"2026-08-10T11:08:29",31,"невезунчик ты сегодня))//",149891,null],[149901,"2026-08-10T11:10:41",9,"*Лес глух, мимо пролетела сова, у Сайна мухомор и 2 не известных гриба, еще вы потратили час на изготовление силка.*",142532,null],[149902,"2026-08-10T11:10:52",9,"*Светает.*",142532,null],[149906,"2026-08-10T11:14:56",47,"/да нет, удачно, всё",149899,null],[149923,"2026-08-10T11:30:00",9,"//Кстати я тут и веду считайте",142532,null],[149924,"2026-08-10T11:32:17",47,"/что?",142532,null],[149925,"2026-08-10T11:33:25",31,"- надо найти хорошее место для силков. торпу, или водопой. лучше водопой, у нас воды нет",142532,null],[149936,"2026-08-10T11:35:41",17,"— Согласен, Рем, давай собирайся, тоже, вместе лучше держаться",142532,null],[149937,"2026-08-10T11:35:49",17,"/ @PaIIasCat",142532,null],[149939,"2026-08-10T11:36:14",31,"- как искать воду? я не жил в лесу, не знаю",142532,null],[149941,"2026-08-10T11:36:30",20,"*Мальчик кивает, морщась и вставая, стараясь не двигать раненым плечом*\n\n- Хорошо, я готов...",149936,null],[149942,"2026-08-10T11:36:34",31,"вроде ищут лозой, но это для колодцев?",142532,null],[149944,"2026-08-10T11:38:25",17,"— У воды всегда прохладнее и по звуку, ручьи в лесу шумят",149939,null],[149948,"2026-08-10T11:39:42",31,"/roll d20? ghbckeibdf.cm r ieve djls",149944,null],[149950,"2026-08-10T11:40:03",31,"/roll d20 прислушиваюсь не шумит ли где река",149944,null],[149952,"2026-08-10T11:40:22",17,"/r +2 Выживание по лесу помогаю искать ручей",142532,null],[149955,"2026-08-10T11:44:44",47,"- Помогите травки собрать, я тогда смогу качественный яд сварить. Так, может когда пригодится",142532,null],[149956,"2026-08-10T11:45:02",47,"/r +d20+2  надеюсь помогут. Через природу ищу",142532,null],[149958,"2026-08-10T11:45:10",47,"Видимо нашёл, что-то",142532,null],[149959,"2026-08-10T11:46:46",9,"*Еще пара неизвестных грибов. Ты находишь камыш и рогоз, а ещё немного трав что выглядят интересно.*",149957,null],[149960,"2026-08-10T11:47:18",9,"/roll 1d4 лекартственных в зм\n/roll 1d4 отруйных в зм",142532,null],[149962,"2026-08-10T11:49:23",47,"Отруйных? /",142532,null],[149963,"2026-08-10T11:49:31",9,"*Местами вам встречается то что обычно растет у водоёмов, камыши это показатель! И кажется вы потихоньку спускаетесь вниз под маленьким наклоном, впереди стелится небольшой туман становясь все плотнее (мешает видеть дальше чем на 300 футов). Стоит ли рисковать и идти туда где местность плохо проглядывается? Или не рисковать?*",142532,null],[149964,"2026-08-10T11:49:38",9,"// Ядовитых",149962,null],[149965,"2026-08-10T11:49:53",47,"/я смогу что-то из них попытаться сварить?",142532,null],[149966,"2026-08-10T11:50:11",31,"хард, что по поводу поиска реки? мы с Колей кидали на ее поиск/",142532,null],[149967,"2026-08-10T11:54:44",9,"//Я описываю что есть у вас",149966,null],[149968,"2026-08-10T11:55:01",17,"Пока ищем воду заодно Люпен присматривает дерево \"Орешник\" лучшее для создания лука, упругое и прочное, даже если дерево не просушено.",142532,null],[149969,"2026-08-10T11:55:08",17,"/r +2 Поиск орешника",142532,null],[149971,"2026-08-10T11:55:23",17,"/ Хард мне нужно докинуть вдохновение? Мне очень нужен орешник",142532,null],[149972,"2026-08-10T11:56:23",20,"/пацан помогает - действие помощь в поиске",142532,null],[149973,"2026-08-10T11:56:27",9,"//Да, но ты видишь что пока мало материалов и нужны какие нить приспособления",149965,null],[149974,"2026-08-10T11:58:10",9,"*Пока нет, местность становится болотистой. Найти орешник тут? Вряд-ли он вообще здесь вырастет.*",149970,null],[149975,"2026-08-10T11:58:27",9,"//Напомню что вы видите",149963,null],[149976,"2026-08-10T12:01:06",17,"— Камыш и рогоз растет у водоемов, но тут слишком мало воды, нужно спускаться ниже в туман. Надеюсь нечисти там нет, нет ведь?\n\nЧучуть посмеивается Люпен, отгоняя страх",149963,null],[149990,"2026-08-10T12:07:29",20,"*Рен озирается вокруг, слегка напрягаясь при упоминании нежити*\n\n/Можно примерно вспомнить расположение поста откуда мы сбежали? Как далеко от него был Веспираль и в какой стороне - туда куда мы убежали или нет\n/Вроде я всегда знаю где север, так что может это поможет",142532,null],[149991,"2026-08-10T12:09:04",9,"//Ты знаешь где север, где Веспираль ты вообще хз, но наверное на севере, то место откуда вы убежали на юге",142532,null],[149993,"2026-08-10T12:09:41",31,"мы же вроде из Аннежа все выдвигались?/",149991,null],[149995,"2026-08-10T12:13:06",9,"//Из Аннежа, да на границу и вот аванпост стоял на границе земель связанных с Веспиралью. Вы сами примерно из районов и окрестностей Аннежа и городов окрестных",142532,null],[149996,"2026-08-10T12:13:35",9,"//Иначе, почему бы существовал аванпост вообще?",142532,null],[149998,"2026-08-10T12:15:23",31,"хмм, то есть тут относительно недалеко должен быть родовой замок моего перса?) не предлагаю его посетить, но если вдруг будет нужно по сюжету то можно использовать))//",149995,null],[150131,"2026-08-10T14:50:44",47,"Ладно. Котелка нет, сварить не смогу...",142532,null],[150138,"2026-08-10T14:51:52",47,"Хм. Я чувствую себя бесполезным, потому помогаю остальным. Задача пожрать, попить и двинуться в путь куда-нибудь",142532,null],[150148,"2026-08-10T14:53:04",17,"— Сайн в тумане херня всякая водится присмотри за пацаном, он из нас самый хилый. А мы с Конрадом  скорее воду отыщем. Ну что, идём вдоль зарослей камыша и рогоза, скоро должна быть вода. Там и поставим силок, наберём с собой.",142532,null],[150154,"2026-08-10T14:55:34",47,"Обычный кивок и сажусь к пацану:\n- Честно говоря я в шоке с твоих способностей. Просто взял и наебал целый аванпост. Я честно, удивлён - толкнул в плечо пацана - а что-то ещё умеешь? - с восхищением спрашивает Сайн",142532,null],[150156,"2026-08-10T14:56:33",31,"- такие способности нужно развивать. Учителя бы найти",142532,null],[150160,"2026-08-10T14:59:05",20,"- Ну... Могу составить жалобные глазки*вздыхает Рен* - обычно срабатывает, даже на самых жадных торговцах может. Время и направление хорошо могу определить\n\n- Да вот в бою я вам мало могу помочь - только голову попробовать противнику заморочить. Или вам подсказатт",150154,null],[150161,"2026-08-10T14:59:11",47,"/по описанию телепортации туманным шагом моего персонажа \n\"Сайн крикнул какую-то белиберду и рядом с ним появилась недовольная пикси. Взглянув на картину, она картинно закатила глаза, взмахнула палочкой и Сайн окутавшись туманом, очутился в таком же выделении тумана но на 30 футов дальше! \n А пикси показала язык и фак страже. Как раз в этот момент с бойниц вылетел болт. Вовремя заметив его Пикси волшебной рукой сломала его. А после щелкнула пальцами и исчезла в снопе искр и пыльцы",142532,null],[150162,"2026-08-10T14:59:58",17,"/ Я думал ты придумаешь что то более прикольное к черте \"ЗАТРОНУТЫЙ феями\"",150161,null],[150168,"2026-08-10T15:00:32",20,"- Здорово было бы, да какой там учитель - большинство местных от колдовства за вилы хватаются. Я поэтому и вам побоялся сразу сказать...",150156,null],[150169,"2026-08-10T15:00:35",47,"- Да забей на полезность в бою, жизнь вообще не про сражения, она про то, чтобы найти место как можно лучше и обустроить его... Как можно лучше. \n А остальное это уже так. Для комфорту и счастья",150160,null],[150171,"2026-08-10T15:00:48",47,"/у меня нет этой черты...",150162,null],[150176,"2026-08-10T15:01:14",47,"/и вообще, что не нравится? Это самое уникальное описание использования туманного шага!",150162,null],[150177,"2026-08-10T15:01:26",17,"/ Всё нравится)))",142532,null],[150178,"2026-08-10T15:01:37",47,"/Ну вот и всё!)",150177,null],[150183,"2026-08-10T15:02:15",20,"- Сайн, а ты получается маг? *Спрашивает с блеском в глазах пацан* - Настоящий настоящий?",142532,null],[150188,"2026-08-10T15:04:25",47,"- Да какой из меня маг, я фею одну спас, когда она въебалась в бочку с мёдом, так она теперь мне по гроб жизни должна. \n Она уточнила, что по гроб моей жизни. Иногда попиздеть приходит, с подружками если поссорится. Правда если я её дёргать постоянно начну, мне кажется она не смотря на обещание, таки нахер меня пошлёт вместе с моими проблемами - улыбаясь ответил Сайн",142532,null],[150192,"2026-08-10T15:04:59",47,"/я надеюсь среднее количество мата вас не напрягает. Перс таким задуман",142532,null],[150196,"2026-08-10T15:06:03",47,"- А вот ты пацан, даже если не хочешь, будешь учиться. Я тебя заставлю - шутливо пригрозил он ему.",142532,null],[150198,"2026-08-10T15:06:44",31,"- а читать умеешь? Не знаю как насчет учителя, но вдруг книга какая попадется, с основами",142532,null],[150200,"2026-08-10T15:06:49",20,"- Ловлю на слове *улыбается Рен*",150196,null],[150207,"2026-08-10T15:09:36",20,"*Рен задумывается,будто взвешивая стоит признаваться или нет*\n\n- Ну вообще...когда я был слугой кое-что смог выучить - так что книгу прочитать смогу. Только это конечно был секрет - если бы хозяева узнали что я их книги трогал... *Он делает страшные глаза, прикладываю палец к губам* - Так что шшшш\n\n/калиграф+фальсификатор пытается не спалиться)",150198,null],[150238,"2026-08-10T15:16:47",47,"/рядом с ним портной, взломщик, ядовар)",142532,null],[150245,"2026-08-10T15:17:37",20,"/команда мечты, можно ИП открывать",150238,null],[150255,"2026-08-10T15:20:50",47,"Хах)",142532,null],[150260,"2026-08-10T15:21:49",20,"/вообще считаю Рену и Конраду нужно научится писать книги - будем ими барыжить",142532,null],[150262,"2026-08-10T15:21:54",47,"Я кстати думаю. У товарища наёмника не запрещено брать абилки такие как компетентность... Можно взять абилку плута скаута, абилку жреца домена знаний... И так далее...",142532,null],[150266,"2026-08-10T15:22:40",9,"//Их нет в списке вродь. Владения навыками и компетентности ток чертами доставать",142532,null],[150282,"2026-08-10T15:25:16",47,"//а есть у наёмника хоть что-то прикольное? Ауру нельзя, мультиатаку нельзя, магия слабее чем даже у мист рыцаря и подобных, и даже доп атаку приходится у других классов пиздить. Остаётся совсем мало полезных, Абилок",142532,null],[150290,"2026-08-10T15:26:48",9,"//Основных абилок классов нет считай. В том его и фокус. Возможно ауры на себя ток добавлю потом",142532,null],[150291,"2026-08-10T15:26:58",31,"Наемник, как я кго вижу - это не пришей к пизде рукав в плане остальных классов. Такой себе студент троечник)//",142532,null],[150485,"2026-08-10T16:57:52",9,"//Если ждёте меня то зря, я жду ваших действий, но мне нарится что вы общаетесь",142532,null],[150493,"2026-08-10T17:01:07",47,"/ у меня нет заявок. Жру сыр",150485,null],[150495,"2026-08-10T17:01:40",47,"Делюсь с пацаном",142532,null],[150498,"2026-08-10T17:02:51",20,"*Рен берет немного сыра. Дают надо брать.*\n\n- Спасибо",150495,null],[150501,"2026-08-10T17:03:22",17,"— Пойду вперёд. Дай водички хлебнуть... Мож в последний раз..\n\nОн слабо улыбнулся\n\n— Ненавижу туманы...",142532,null],[150505,"2026-08-10T17:05:04",47,"А я тут понял, что мы всё хп подняли. За лвл ап/",142532,null],[150506,"2026-08-10T17:05:04",47,"Тело же",142532,null],[150508,"2026-08-10T17:05:58",31,"- я с тобой, подстрахую",150501,null],[150592,"2026-08-10T17:29:26",9,"//Идешь сам или кто-то с тобой?",150501,null],[150594,"2026-08-10T17:30:27",17,"/ Со мной идёт Конрад",142532,null],[150596,"2026-08-10T17:30:45",17,"— Спасибо, прикрыть спину друг другу и правда стоит.",142532,null],[150614,"2026-08-10T17:40:02",9,"*Конрад и Люпен спускаются ниже, тут начтнается топь, ноги грузли и земля не стабильна, можно провалиться в трясину, ваших союзников уже не видно.*\n\n*Редкие камыши, плохой запах, тут точно нет хорошей воды. Но полно лягушек! Мимо вас проползла змея, живность, а живность это добыча.*\n\n*(Раз Конрад из монастыря) бывший дворянин вспоминает рецепт змеиного супа на травах что восстанавливает силы, его часто варили монахи.*\n\n*Зоркий глаз Люпена на краю видимости тумана замечает то ли берёзы то ли ивы, они растут прямо из болота, но идти к ним — рисковать провалиться в трясину.*",142532,null],[150642,"2026-08-10T17:51:55",31,"/roll d20+1 природа, пытаюсь опознать змею и понять, насколько опасно будет ее схватить и открутить ей голову, чтобы пустить на суп",150614,null],[150660,"2026-08-10T17:55:22",9,"*Это обычная болотная змея, ядовита, ток если внезапно или с чьей-то помощью, может рогач? Правда болотные змеи отдают тиной.*",150644,null],[150681,"2026-08-10T18:05:17",31,"Всяко лучше тифозной крысы/",150660,null],[150684,"2026-08-10T18:06:13",17,"— Рискнем? Я ее шугану к тебе а ты резко хватай. Сверни ей сразу шею и пасть крепко держи...",142532,null],[150688,"2026-08-10T18:06:39",31,"- давай, гони ее на меня",142532,null],[150692,"2026-08-10T18:07:34",31,"Я так понимаю, через ловкость рук ее ловим?/",142532,null],[150703,"2026-08-10T18:10:12",9,"//Ты хочешь её именно поймать или атаковать?",142532,null],[150706,"2026-08-10T18:10:41",31,"Поймать и свернуть башку/",150703,null],[150719,"2026-08-10T18:13:22",9,"//Описывайте как именно вы делаете",142532,null],[150721,"2026-08-10T18:14:08",31,"Ну я жду пока Люпен шуганет змею/",142532,null],[150722,"2026-08-10T18:14:14",9,"//Я знаю около 10 способов поймать змею безопасно, вы тоже вольны импровизировать",142532,null],[150768,"2026-08-10T18:23:07",47,"Хочу в город...",142532,null],[150769,"2026-08-10T18:23:10",47,"19 века",142532,null],[150944,"2026-08-10T19:16:44",17,"— Я шугану, а ты бей. Не пытайся ее держать она вывернуться и тяпнет тебя в руку",142532,null],[150946,"2026-08-10T19:17:19",17,"/ Ловкость рук?",142532,null],[150952,"2026-08-10T19:18:30",9,"//Го по правилу окружения, типа окружили и ударил кто-то/провёл особую атаку с преимуществом",142532,null],[150966,"2026-08-10T19:22:39",17,"/ Конрад бей",142532,null],[150972,"2026-08-10T19:23:35",31,"Я хочу пиздануть ее рапирой, мне что кидать, я запутался/",142532,null],[150975,"2026-08-10T19:24:35",9,"//Вы её окружаете, получаешь преимущество на атаку",142532,null],[150977,"2026-08-10T19:24:58",9,"//Рапира -1 напомню и к урону и к попаданию",142532,null],[150983,"2026-08-10T19:26:16",31,"/roll +d20+2",142532,null],[150986,"2026-08-10T19:26:31",31,"Попал?/",142532,null],[150988,"2026-08-10T19:26:39",17,"/ У тебя +4",142532,null],[150989,"2026-08-10T19:26:39",9,"//Мисс",142532,null],[150990,"2026-08-10T19:26:45",17,"/ 3 ловкость и 1 бм",142532,null],[150992,"2026-08-10T19:26:57",9,"//Он не владеет рапирой же",142532,null],[150993,"2026-08-10T19:27:02",31,"Так нет бонуса без владения, и с самой рапиры -1э",150990,null],[150996,"2026-08-10T19:27:07",17,"/ Так а зачем ты рапирой ОООО ладно",142532,null],[150997,"2026-08-10T19:27:20",17,"/ У тебя кулаки сильнее",142532,null],[150998,"2026-08-10T19:27:31",31,"Так руками бить ядовитую змею это тупо же/",150996,null],[150999,"2026-08-10T19:27:37",17,"/ Как хочешь) щас будем отсасывать яд))",142532,null],[151000,"2026-08-10T19:27:44",17,"/ Свернуть шею",150998,null],[151001,"2026-08-10T19:27:45",47,"Она яд на клыках выделяет только... /",142532,null],[151004,"2026-08-10T19:27:56",9,"*Змея изворачивается, она хотела убежать но вы напали!*",142532,null],[151008,"2026-08-10T19:28:05",9,"/roll 1d20+2 ответочка",142532,null],[151012,"2026-08-10T19:28:24",31,"Хера она ебашит/",142532,null],[151017,"2026-08-10T19:29:04",9,"/roll 2d4 ядом",142532,null],[151020,"2026-08-10T19:29:37",9,"//Спас тела сл 10 если пройдёшь то ток 1 ядом и 1 колющего. Иначе в сумме 4",142532,null],[151022,"2026-08-10T19:29:46",31,"/roll d20+2",142532,null],[151024,"2026-08-10T19:30:07",31,"- ах ты ебань шепелявая!",142532,null],[151025,"2026-08-10T19:30:07",9,"//1 колющий и ядом 1, ваш ход",142532,null],[151026,"2026-08-10T19:30:25",9,"*Змея укусила Конрада за ногу!*",142532,null],[151027,"2026-08-10T19:30:37",31,"/roll +d20+4 кулаком ей в башку",142532,null],[151032,"2026-08-10T19:30:53",31,"/roll d4+4",142532,null],[151034,"2026-08-10T19:30:55",9,"//Опиши как убил",142532,null],[151038,"2026-08-10T19:32:12",31,"Разозлившись на свою неудачу вложился в удар от души, уже в момент прикосновения кулака к змеиннной башке увидел в ее глаза мысль: бля, завещание то не написала....",142532,null],[151041,"2026-08-10T19:32:58",31,"- яд пригодится, Сайн вроде что ттпро него говорил",142532,null],[151044,"2026-08-10T19:33:14",47,"Напал, выхватил в ответ. Обиделся. Убил/",142532,null],[151045,"2026-08-10T19:33:21",47,"/стандартный герой)",142532,null],[151087,"2026-08-10T19:43:32",17,"— Да, я помогу ему нацедить. Тоже кое какой яд делал ранее. Хороший удар. И зачем ты с такой техникой пытался железкой ее ткнуть, хе.",151041,null],[151092,"2026-08-10T19:44:42",31,"- навыки проверил. Но либо я заржавел, либо эта рапира только как кочерга работает. Будут деньги, надо бы нормальному кузнецу показать",142532,null],[151094,"2026-08-10T19:45:18",17,"— Да, сперва выбраться из леса и не помереть от обезвоживания и голода. А ну ещё диких животных.",142532,null],[151096,"2026-08-10T19:46:01",17,"— Там берёза и Ива. Для лука сгодится. Давай подстрахуешб меня, тут топь и кочки слабо видно в тумане. Вытащи если отступлюсь",142532,null],[151097,"2026-08-10T19:46:10",17,"Люпен пошел в сторону березы и Ивы",142532,null],[151098,"2026-08-10T19:46:18",17,"/r +2 Выживание",142532,null],[151100,"2026-08-10T19:46:23",17,"/ Везёт сегодня",142532,null],[151111,"2026-08-10T19:48:00",31,"/roll d20+3 акробатика, протягиваю руку, кричу держись",142532,null],[151113,"2026-08-10T19:48:14",31,"Ебать я полено/",142532,null],[151116,"2026-08-10T19:48:41",9,"//Спас ловкости сл 12 от обоих",142532,null],[151118,"2026-08-10T19:48:59",31,"/roll d20+3",142532,null],[151120,"2026-08-10T19:49:13",31,"Полено всплыло, сучком зацепилось/",142532,null],[151121,"2026-08-10T19:49:45",17,"/r +3 Спасик",142532,null],[151126,"2026-08-10T19:50:09",17,"— Ооопля. Чуть не потонули с тобой, хехе",142532,null],[151128,"2026-08-10T19:50:28",31,"- это была крайне глупая смерть",142532,null],[151129,"2026-08-10T19:50:34",9,"//Вас тянет тина, но вы типа вовремя среагировали, можете описать как не утонули в трясине",151119,null],[151131,"2026-08-10T19:51:19",17,"Люпен зацепился за ветку и обхватил ногами Конрада\n\nОн подтянулся за кочку и оба выбрались кое как",142532,null],[151134,"2026-08-10T19:52:08",17,"— Деревья тут ломкие были по пути. Вот те два дерева хороши, нужно дойти. Не вешай нос. Кто в тине не тонул тот сапоги не терял.",142532,null],[151137,"2026-08-10T19:52:28",17,"Люпен снова идёт к Иве и Березе",142532,null],[151140,"2026-08-10T19:53:21",9,"//Можете кто-то кинуть природу с преимуществом? Помогите друг другу чёль как нить",142532,null],[151145,"2026-08-10T19:53:50",17,"/r +d20+2 Я помогу",142532,null],[151150,"2026-08-10T19:54:23",17,"— Давай вот возьмём длинную палку и ей от дна топи отталкиваться можно",142532,null],[151152,"2026-08-10T19:54:38",17,"— Если качнешься в сторону толкайся палкой",142532,null],[151153,"2026-08-10T19:54:51",9,"//С палкой без проверки",142532,null],[151154,"2026-08-10T19:55:03",17,"Так Люпен отправился далее по скользким кочкам",142532,null],[151155,"2026-08-10T19:55:05",9,"//Лишь бы длинная была)",142532,null],[151158,"2026-08-10T19:55:50",31,"Иду следом",142532,null],[151160,"2026-08-10T19:56:11",9,"*Кое как, осторожничая вы дошли к иве? Нет, это странное дерево похоже одновременно и на иву и на берёзу, скрученное и гнётся от малейшего шороха.*",142532,null],[151162,"2026-08-10T19:56:37",9,"//Люпен может кинуть историю сл 10 если пытвется вспомнить что за дерево это",142532,null],[151166,"2026-08-10T19:57:59",17,"/r -1 история",142532,null],[151173,"2026-08-10T19:59:13",9,"*Ты хрен знаешь что это за дерево.*",151167,null],[151175,"2026-08-10T19:59:34",9,"//конрад конечно тоже может, но сл 15 для него",142532,null],[151184,"2026-08-10T20:01:48",31,"/roll d20+1 напрягаю извилины и вспоминаю уроки ботаники",142532,null],[151186,"2026-08-10T20:02:01",31,"Мда, я из прогуливал/",142532,null],[151193,"2026-08-10T20:02:40",9,"*Толи береза, то ли ива, хрен знает. Но выглядит прикольно. Гнется хорошо, при этом не ломается легко.*",142532,null],[151207,"2026-08-10T20:04:36",17,"— Дава срежем ровный сук. Для лука. А лучше несколько. Если вдруг сломается один, будет замена.",142532,null],[151211,"2026-08-10T20:05:18",31,"- ровные палки всегда пригодятся",142532,null],[151223,"2026-08-10T20:07:07",9,"*Суки такие почти узлы из них можно вязать или воду выкручивать.*",151207,null],[151224,"2026-08-10T20:07:17",17,"Достав ножик Люпен попросил подсадить его повыше туда где сучки были ровнее",142532,null],[151228,"2026-08-10T20:07:42",17,"/ Уточняю я не понял какие. Очень гибкие типо?",151223,null],[151232,"2026-08-10T20:08:11",17,"Ножиком начал делать зарубки чтобы сук отделить от ствола раз два три и дальше",142532,null],[151233,"2026-08-10T20:08:41",9,"//Ага и воды в них много, если скрутить аж капает",142532,null],[151234,"2026-08-10T20:09:45",9,"*Там где срезал ветви из тех мест капает вода.*",151232,null],[151246,"2026-08-10T20:13:51",31,"Ладно, я спать пошел, если буду нужен какими то проверками, то киньте за меня, чтобы не тормозить игру/",142532,null],[151266,"2026-08-10T20:17:35",9,"//Дни такие, не парься",151246,null],[151952,"2026-08-11T00:13:07",17,"— Конрад, тут что то много сока, странно это. А что это дерево такое? Нетто берёза не то ива. Ты знаешь?",151234,null],[151953,"2026-08-11T00:13:31",17,"Продолжая делать зарубки на другом суку, чтобы получить несколько ровных палок",142532,null],[151960,"2026-08-11T02:24:55",31,"- я пытался вспомнить, не вышло. На вид эллсатичная, гнуться будет. Главное чтобы она тебе руку не откусила, когда гнуть будешь. В этом мире все возможно, и обычно это неприятные сюрпризы",142532,null],[151961,"2026-08-11T02:35:36",17,"— Да вроде не должно такого быть, хых. \n\nНастругал три ровные ветки",142532,null],[151962,"2026-08-11T02:36:24",17,"— Готово, больше не надо. Так... А воду то мы и не нашли, и место для силка подходящего тут нет в этой топи. Давай выбираться назад, я думаю.",142532,null],[151963,"2026-08-11T02:46:06",31,"Шлёпаем обратно, стараясь идти по следам, ну или по памяти, а то в лужах слудов не видно",142532,null],[151964,"2026-08-11T06:44:17",9,"*Ветви хоть и ровные, но грутся и легко становятся не ровными, слишком водянистые. Вода что капает из срезов прозрачная и не смотянистая, просто стекает.*",151961,null],[151965,"2026-08-11T06:45:40",31,"- похоже из этого дерева проще сделать фильт для воды, чем лук",142532,null],[151966,"2026-08-11T06:48:47",9,"*Кроме того дерева к которому вы дошли есть ещё и ты видишь как стайка мелких зубастых оленей на краю тумана, куда можно рассмотреть, сгрызают нижние ветви и пьют? Едят? Для них это точно полезно.*\n\n//Олени эти рил мелкие, чуть выше колена может быть, как небольшая дворняга и",151965,null],[151967,"2026-08-11T06:57:22",31,"*толкаю Люпена и шепчу*:\n\n-глянь, кто там. это наш обед и ужин, если поймаем. и кажется они там что тто нашли",142532,null],[152068,"2026-08-11T11:09:39",9,"// @QURTZZ @dunchev @cirson @PaIIasCat я тут, и думаю готов вести. Первая группа на болотах присматривается к болотам, втораче где-то на полторы мили выше за туманами, кто чем занят и все такое.",142532,null],[152069,"2026-08-11T11:10:27",17,"— Пошли посмотрим поближе, но только тихо.\n\nВзяв палки в охапку Люпен двинулся в сторону оленей",151967,null],[152086,"2026-08-11T11:17:27",9,"*Очень внимательные олени быстро вас заметили и ускакали высоко прыгая по кочкам, исчещая в тумане, чуть ли не на два метра в высоту прыгали, скалились зубами и гарчали! С их то размерами, могут и вас перепрыгивать.*",142532,null],[152090,"2026-08-11T11:18:16",17,"— Ты говоришь они что то там нашли, надо глянуть.\n\nИду к месту где стояли олени",142532,null],[152092,"2026-08-11T11:18:38",31,"- ну они что то грызли вроде",142532,null],[152098,"2026-08-11T11:19:19",9,"*Видишь надгрыженные лозы такого же дерева с корого срезал палицы, из них капает вода.*",152090,null],[152110,"2026-08-11T11:22:17",31,"- видимо, они просто так пили. скорее всего это и есть источник чистой воды тут, дерево словно фильтр работает",142532,null],[152170,"2026-08-11T11:40:13",47,"Ничем. Я не знаю чем занятся. С пацаном типо пизжу",152068,null],[152179,"2026-08-11T11:41:46",17,"— Ладно, тогда нужно набрать в фляжку этого сока водянистого, лучше чем ничего.\n\nВернувшись к дереву делаю зарубку, проковыриваю в стволе дырочку и сую туда веточку\n\nПо этой ветке будет течь сок дерева и я подставляю флягу, собираю его",142532,null],[152187,"2026-08-11T11:43:49",9,"*Это заняло около получаса по ощущениям, может больше.*\n\n//Можете короткий, скип момента или поделать чет",152179,null],[152191,"2026-08-11T11:45:32",20,"/думаю да, стараемся оставаться на том месте, чтобы товарищи нас смогли отыскать, как вернуться\n/Болтаю с сайном, интересно про фею больше узнать",152068,null],[152192,"2026-08-11T11:45:48",20,"/если есть возможность осмотреться поискать травы поблизости",142532,null],[152198,"2026-08-11T11:47:34",9,"*Рядом ного старых деревьев, на них какой-то мох, редкие травы, рогоз и камыши.*\n\n//Опиши что и как ищешь",152192,null],[152217,"2026-08-11T11:49:51",20,"/осматриваю почву где она кажется чуть темнее или растительности больше - возможно в ней полезные коренья смогу найти",152198,null],[152226,"2026-08-11T11:50:54",17,"/ палку убери и осматривай он просит от тебя это))",142532,null],[152229,"2026-08-11T11:51:36",20,"/r d20+1 проверяем палочкой почву",142532,null],[152234,"2026-08-11T11:52:53",20,"//сори если с бросками могу тупить - привыкла что за столом проверка возможна только если мастер просит её)",142532,null],[152246,"2026-08-11T11:54:30",17,"/ Мммм ядовитая змея )",142532,null],[152251,"2026-08-11T11:55:06",9,"*\"Странный корень\", крахмальный, может съедобный, ты не знаешь. Несколько больших жуков, личинок и ленивых червей с палец. Лягушка сидела под листвой, убегает.*",152234,null],[152256,"2026-08-11T11:57:02",20,"*собираю корень, возможно старшие смогут понять, можно ли это есть*\n\n*Личинок и червяка тоже собираю отдельно, пригодятся для наживок*\n/Ну или экстренного белка",152251,null],[152259,"2026-08-11T11:57:24",17,"/ Наживки хе - съедим тоже!",142532,null],[152260,"2026-08-11T11:57:59",9,"*Если поднять голову, на дереве есть кикие то красноватые древесные грибы.*",152256,null],[152264,"2026-08-11T11:58:48",20,"- Сайн, ты случайно не знаешь что это может быть? *Зовёт мальчик, указывая на грибы*",152260,null],[152267,"2026-08-11T11:59:32",20,"/может даст помощь - попробую через природу опознать",142532,null],[152269,"2026-08-11T12:02:09",9,"//Типа таких грибов)))",142532,null],[152273,"2026-08-11T12:03:32",17,"/ Нямка",142532,null],[152274,"2026-08-11T12:04:00",9,"//Всё съедите, хе хех",142532,null],[152277,"2026-08-11T12:05:16",20,"/r +d20+2 на природу, надеемся сайн помогает",142532,null],[152285,"2026-08-11T12:08:58",9,"*Это кажется \"Чага\", где-то о таком слышал, но вряд-ли знаешь. Наверное где-то используются, может Люпен знает точнее?*",152278,null],[152286,"2026-08-11T12:09:29",17,"/ Да, знаю\n\nЧунга - Чага",142532,null],[152314,"2026-08-11T12:13:13",9,"//Один я изучаю флору и интересности будто, ладно)",142532,null],[152315,"2026-08-11T12:13:46",9,"*Те самые то ли берёзы то ли ивы в болоте.*",142532,null],[152318,"2026-08-11T12:14:49",17,"/ На самом деле очень атмосферно",142532,null],[152335,"2026-08-11T12:18:28",9,"//Спасибо",152318,null],[152374,"2026-08-11T12:33:12",20,"/не слышала о таком, только что из похожих наростов прикольную посуду можно делать\n/Интересно",152285,null],[152400,"2026-08-11T12:43:02",31,"Чага это очень крепкий материал, из нее детали можно точить/",142532,null],[152436,"2026-08-11T12:53:01",20,"/значит правильно подумала - видела поделки из нее в Карелии",152400,null],[152569,"2026-08-11T13:34:26",17,"Набрав во флягу березового сока. Люпен пошел искать место где можно истановить силок.\n\n— Тарх если олени жевали ветки этого дерева может их как приманку используем? На силок. Думаю может сработать\n\nНарезал еще небольших веточек и принялся искать место, неподалёку от того где олени уже были",142532,null],[152570,"2026-08-11T13:34:33",17,"/r +2 Выживание место под ловушку",142532,null],[152579,"2026-08-11T13:41:22",17,"— Конрад, найти не могу, как у тебя? Есть хорошее место?",142532,null],[152590,"2026-08-11T13:47:41",47,"Я чувствую всё ещё себя бесполезным. Сайн лежит ждёт остальных",142532,null],[152593,"2026-08-11T13:48:05",31,"/roll d20 выживание, тоже ищу",152579,null],[152595,"2026-08-11T13:48:14",31,"- не особо, увы",142532,null],[152597,"2026-08-11T13:48:48",17,"/ Миш, может вы чето тоже сделаете? Мы же вас не ограничиваем",152590,null],[152604,"2026-08-11T13:49:25",47,"Я просто подумал, а что мой перс может делать в лесу? Варить какую нибудь фигню. А как это, сделать без котелка?",142532,null],[152606,"2026-08-11T13:49:44",47,"Поэтому на нас не смотрите, найдите уже воду, вернитесь за нами и я начну активничать",142532,null],[152607,"2026-08-11T13:49:51",17,"/ Ну ты можешь пойти и раз споткнуться о сундук зарытый",142532,null],[152608,"2026-08-11T13:49:57",17,"/ Тут как повезёт",142532,null],[152616,"2026-08-11T13:51:44",47,"- Рен, го пройдёмся, поищем чего? Скучно просто так сидеть, ждать их. Уже два часа нету. Заебали шляться",142532,null],[152679,"2026-08-11T14:14:34",20,"- Давай. Только не будем уходить слишком далеко, чтобы они смогли нас найти *соглашается пацан*\n\n- Ну и можем оставлять засечки - сами не потеряемся и нас если что отыщут",152616,null],[152682,"2026-08-11T14:15:46",47,"Кивает соглашаясь\nНу чо, мы гуляем мастер",142532,null],[152683,"2026-08-11T14:15:52",47,"/кинь д100 что-ли",142532,null],[152688,"2026-08-11T14:16:15",17,"/Приятно было поиграть с вами!)))",142532,null],[152702,"2026-08-11T14:19:21",47,"/я надеюсь мастер учтёт добровольное пожелание и выдаст послабления или поощрения",142532,null],[152712,"2026-08-11T14:21:13",9,"*В сторону куда вы уходите вскоре растительность начала становиться всё более увядшая, как граница за которой начало все увядать. Лес становится все более рыжим и под деревом вы видите кости умершего животного, одного, другого... гиблое место, стоит ли в него идти?*",142532,null],[152725,"2026-08-11T14:22:38",47,"Оооо, косточки. Хочу взять несколько и закинуть в мешок",142532,null],[152731,"2026-08-11T14:23:38",9,"//Мастер доверил вашу судьбу рандому, у меня есть штуки 3 таблиц д100 личных что подходят сюда)",152702,null],[152732,"2026-08-11T14:23:41",47,"Я придумал профессию/",142532,null],[152765,"2026-08-11T14:28:14",47,"Всё. Всё зашибись",142532,null],[152774,"2026-08-11T14:29:42",20,"- Выглядит как то, куда не стоит идти. Может повернём назад?",152712,null],[152785,"2026-08-11T14:31:05",20,"/чёт мне кажется со своими 7 хитами такие авантюры самоубийство",142532,null],[152788,"2026-08-11T14:31:10",47,"- А ещё будто здесь нас ждёт смерть, посему соглашусь и обходим - мастер возвращаемся слегка назад и идём в другую сторону",142532,null],[152805,"2026-08-11T14:32:41",20,"/я бы вообще вернулся и потратил время до прихода остальных чтобы вместе попробовать опознать растительность что мы насобирали типа грибов сайна",152788,null],[152808,"2026-08-11T14:32:56",20,"/полезнее как будто будет",142532,null],[152810,"2026-08-11T14:33:14",47,"/озвучь",152805,null],[152818,"2026-08-11T14:34:37",20,"- Мне кажется лучше вернуться к месту где ждали. Я нашел пару кореньев, да и у тебя грибы ещё в запасе. Пока они ходят можем попытаться понять, что это\n- Возможно сгодится в пищу. Ну или для яда",152788,null],[152825,"2026-08-11T14:36:10",47,"Отдаю грибы и говорю:\n- Ладно, иди, а я погуляю ещё. Скоро буду - и съебываю дальше гулять",142532,null],[152831,"2026-08-11T14:38:14",47,"Мастер, продолжаю гулять!",142532,null],[152834,"2026-08-11T14:38:24",47,"/я ебанутый. Знаю",142532,null],[152836,"2026-08-11T14:38:38",47,"Hard",142532,null],[152837,"2026-08-11T14:38:57",20,"- Не забудь про зарубки. Удачи, мистер Маска *пацан машет на прощание*\n\n*Рен возвращается на изначальную полянку отдыха, раскладывая перед собой на куске ткани все найденные ингредиенты - будет сортировать*",142532,null],[152856,"2026-08-11T14:41:48",20,"/чё у пацана есть, постараюсь вспомнить:\n- грибы от сайна\n- чага\n- непонятный корень(что-то крахмальное)\n- жучки/личинки/червяк\n- камыш и рогоз",142532,null],[152906,"2026-08-11T14:51:59",9,"*Идя дальше, в одиночку по тёмному лесу наблюдаешь одни и те же привычные виды.*\n\n//Опиши \"как именно\" ты гуляешь по лесу",152825,null],[152913,"2026-08-11T14:53:38",47,"Я тихонько передвигаюсь не стремясь шуметь, но высматриваю сьестное и что-то интересное (трупы входят в это. А так же постройки и другого рода разрушения). Делаю засечки на деревьях с одной стороны, дабы не заплутать",152906,null],[152922,"2026-08-11T14:55:24",9,"//Думаю скрытность и внимательность от тебя",142532,null],[152924,"2026-08-11T14:55:40",47,"/r d20+4",142532,null],[152925,"2026-08-11T14:55:45",47,"/roll@roll_bot",142532,null],[152929,"2026-08-11T14:55:50",47,"11 скрыт",142532,null],[152930,"2026-08-11T14:55:52",47,"/roll@roll_bot",142532,null],[152933,"2026-08-11T14:56:06",47,"12 внимательность. Везунчиков нет",142532,null],[152984,"2026-08-11T15:06:45",9,"*Ты замечаешь странное бревно? Нет, это не бревно, это большой мать его змей ползущий по тёмному лесу, для тебя кажется огромный, на чём тот отожрался? И он ещё не заметил Сайно.*\n\n//У него пасивное восприе 10 с ствоим скрытом 11 везучий ты ублюдок)))",142532,null],[153012,"2026-08-11T15:13:37",47,"/вопрос.на сколько он большой и на сколько опасным он выглядит?",142532,null],[153033,"2026-08-11T15:17:23",9,"*Большой змей втрое длиннее сайно минимум, лениво ползёт куда-то, выглядит очень опасно.*",142532,null],[153037,"2026-08-11T15:17:43",47,"От 1 до 10? /",153033,null],[153038,"2026-08-11T15:17:44",9,"//Размер \"большой\" если это важно",142532,null],[153041,"2026-08-11T15:17:53",47,"Ебать",142532,null],[153042,"2026-08-11T15:18:11",9,"//А если бы ты его не заметил)",142532,null],[153043,"2026-08-11T15:18:16",47,"Я хочу убить",142532,null],[153044,"2026-08-11T15:18:19",9,"//Или он тебя",142532,null],[153046,"2026-08-11T15:18:20",47,"Но не хочу рисковать",142532,null],[153048,"2026-08-11T15:18:43",47,"Было бы хотя бы знамение или плутовская атака...",142532,null],[153057,"2026-08-11T15:20:54",9,"//Думай, но знамение мож обыграть и получить, ты ж уже 2го",142532,null],[153066,"2026-08-11T15:22:00",47,"Лады. Запомнил место, улетел обратно в лагерь. Пора точить кости",142532,null],[153074,"2026-08-11T15:23:13",9,"// @dunchev @QURTZZ что вы там? Киньте на скрытность для установки силка)",142532,null],[153076,"2026-08-11T15:23:38",47,"/скажи как в лагерь вернусь, заявку дам",142532,null],[153079,"2026-08-11T15:23:54",17,"— Ладно, хорошего места не вижу, давай прямо там где олени жевали ветки, еще навалим этих веток и силок прикроем листвой и травой",142532,null],[153080,"2026-08-11T15:24:04",17,"/r +4 Скрытность",142532,null],[153084,"2026-08-11T15:24:40",9,"*Сам бы не нашёл если бы не знал.*",153081,null],[153146,"2026-08-11T16:19:01",20,"/могу пока попробовать опознать грибы?",142532,null],[153147,"2026-08-11T16:19:23",31,"Не спрашивай, делай/",142532,null],[153148,"2026-08-11T16:19:50",20,"/r d20+2 пробуем опознать грибы",142532,null],[153150,"2026-08-11T16:20:10",20,"/r d20+2 и корень",142532,null],[153152,"2026-08-11T16:22:07",17,"— Ну что Конрад, силок поставили пошли к остальным, сок собрали. МОжет приготовим крыс, нужно сил набраться, вечером можно проверить тут.\n\nСобрав ветки Люпен готовился возвращаться\n\n— Жилы у меня пока нет на тетиву, но зато хорошие ветки для лука есть, можно будет пока что ими заняться. Хорошо, что ты со мной пошел, тут в тумане, реально стрёмно",142532,null],[153153,"2026-08-11T16:23:26",47,"/r +d20+4 нарезка гадальных костей с помощью пацана, когда вернулся",142532,null],[153155,"2026-08-11T16:24:50",31,"Будем надеется что силок не зря поставили. Надо бы решить что делать дальше, в лесу сидеть вообще не вариант",153152,null],[153347,"2026-08-11T17:18:55",17,"Мы поставили силок и возвращаемся назад тем же путём\n\nЛюпен попил сока с дерева и предложил Конраду\n\n— Будешь пить? Вода как вода вроде. Правда впервые я сок древесный пью в таких количествах. Ну березовой пил, было. На вкус сносно",142532,null],[153353,"2026-08-11T17:19:50",31,"- не тв ситуация, чтобы привередничать, давай",142532,null],[153482,"2026-08-11T17:53:32",9,"*Вы вернулись примерно когда и Сайн вернулся обратно где условились вас ждать. Рен как раз сидел и пытался узнать что за грибы же у них есть в запасе.*",142532,null],[153493,"2026-08-11T17:54:56",9,"//Вопрос к владельцу персонажа, @PaIIasCat насколько пацан прошарен о природе?",142532,null],[153511,"2026-08-11T17:56:52",9,"*Вода сладковатая и полностью жидкая, такую можно пить. Возможно те мелкие зубастые олени как раз \"пили\" таким образом.*",153353,null],[153527,"2026-08-11T18:01:03",20,"/максимум по книгам или словам тех кто имел дело с ядами",153493,null],[153531,"2026-08-11T18:01:28",20,"/лично нет, городской же",142532,null],[153540,"2026-08-11T18:03:56",20,"/саблезубый олень)",153511,null],[153682,"2026-08-11T18:32:41",9,"//Лан, похоже на сеня всё, Алексей начал вести своё, попробую вторую пати найти. Но все равно пипец круто играется всё на деле. Мне нарится, надеюсь и вам. Хотя я бы вёл активнее, хотелось бы",142532,null],[153684,"2026-08-11T18:33:36",17,"/ Все боятся рисковано куда то ходить))",142532,null],[153685,"2026-08-11T18:33:52",47,"Дай ответы на проверки!",153682,null],[153686,"2026-08-11T18:34:31",9,"*Корень странно пахнет, очень странно, хочется попробовать.*",153151,null],[153692,"2026-08-11T18:36:04",9,"*Это маслевики или лисички, похожие иногда было можно увидеть в лавках, но точно ли это съедобно? Это точно они?*",153149,null],[153694,"2026-08-11T18:37:03",20,"/а как он кстати выглядит?",153686,null],[153695,"2026-08-11T18:37:53",9,"*Кости легко поддаются обработке, это займёт не более получаса вырезать небольшой инструмент для гадания.*",153154,null],[153701,"2026-08-11T18:40:32",9,"*Липкие и маслянные, на их шляпках прилипло много мусора, листвы и травы из лесной подстилки.*",153698,null],[153703,"2026-08-11T18:42:03",20,"/ну на маслят реально похоже, да и юбочки нет - уже 70% что не ядовит🤔",153698,null],[153707,"2026-08-11T18:44:34",9,"*Шляпки немного более вывернутые наружу, а так вроде они.*",153703,null],[153721,"2026-08-11T18:51:20",20,"*Рен встречает вернувшихся взрослых, разложив все найденное перед собой*\n\n- Вы наконец то вернулись...я попробовал собрать, что тут было поблизости - вот *он указывает на найденное - от личинок до грибов* - грибы похожи на маслят, хотя не не до конца уверен.\n\n- ещё вот есть наросты - похожи на чагу. Я о таком читал, но не особо помню, насколько она полезна. Возможно вам пригодится?\n\n- Ну и этот странный корень... *Пацан смотрит на эту самую находку, невольно сглатвая. Похоже попробовать ее почему-то действительно очень хочется...*",142532,null],[153755,"2026-08-11T19:04:35",47,"/r 2d20 знамение",142532,null],[153757,"2026-08-11T19:04:40",47,"Хуйня",142532,null],[153902,"2026-08-11T20:01:56",17,"— Смотрите, дерево особо попалось на болоте. Я нарезал веток самых ровных, буду пробовать лук делать. Но тетивы пока нет.\n\nЛюпен запыхался\n\n— И так что по воде ещё. Источника мы не нашли чистой воды, но с дерева того сок сочится как из колодца набираешь. Набрали этого сока. На вкус нормально. На вот попробуй Рем.\n\nПередает фляжку пацану \n\n— Силок мы поставили надёжно, место тоже не плохое. Мы там видели оленей мелких зубастых, они делали ветки этого дерева. Так что мы там этих веток накидал и силок укрыли листвой. Должно сработать. \n\nЛюпен садится по турецки и берет одну палку, начинает делать на ней зарубки-канавуи для крепления будущей тетевы\n\n— Топь там, конечно, опасная. Потанцтт как два пальца обоссать, но если аккуратно и палку подлиннее, то пройти можно. А Корад ещё и змею словил.\n\nОн снимает наплечную сумку и приоткрывает ее\n\n— Давайте ревизию наших запасов сделаем и разведки костер. Уже как то стало зябко. \nИ так, ревизия. У меня нож и две крысы. У кого что?\n\n\n\n— Ходить лучше по двое. Рем айда со мной за хворостом, как ревизию сделаем?",142532,null],[153960,"2026-08-11T20:26:30",17,"/ @PaIIasCat гоу пошароебимся в поисках хвороста?",142532,null],[153984,"2026-08-11T20:42:09",20,"/погнали",153960,null],[153992,"2026-08-11T20:44:07",17,"/ Давай прям сразу дерзкие заявки. Водичку пьешь сок древесный?",142532,null],[153996,"2026-08-11T20:45:27",20,"- Ну, у меня есть чистый платок, фляжка воды, всякие личинки и жучки для наживки, странный корень, чага, грибы предположительно съедобные и...все? *Перечисляет пацан*",153902,null],[153998,"2026-08-11T20:45:36",20,"/конечно",153992,null],[154005,"2026-08-11T20:46:25",17,"— Ну, слушай. А молодец. Много чего нарыл. Хвалю!",142532,null],[154006,"2026-08-11T20:46:41",17,"— Сайн у тебя больше всего скарба",142532,null],[154090,"2026-08-11T22:31:13",47,"Сайн смотрит жалостливыми глазами, будто самый нищий:\n- 4 золотых, 4 серебрянных, чутка меди. Травки, фляжка с водой. Ткани, обмотки, рапира, рапира на щите, короткий клинок, стальной прут, кости. Всё - и честные глаза. Будто честным трудом заработал и купил",142532,null],[154103,"2026-08-12T06:37:35",31,"- это конечно славно, жить в лесу и не знать что тут можно съесть, или кто может съесть тебя, но вам не кажется, что отсюда надо выбираться? Меня очень смутили саблезубые олени, это ведь травоядные животные, зачем им такое оружие? Может кто то и пострашнее тут живет? Надо к цивилизации выбираться. И я бы хотел узнать, кто нас запер и почему",142532,null],[154114,"2026-08-12T07:18:27",9,"//Запер и почему? Типа почему каждый оказался в темнице тогда?",142532,null],[154115,"2026-08-12T07:20:59",47,"Сайн лишь кивает в виде согласия вырезая из костей что-то интересное",142532,null],[154116,"2026-08-12T07:25:17",31,"ну да. я за собой вины не знаю/",154114,null],[154173,"2026-08-12T09:25:10",17,"— Хм... Нужно определить направление куда нам двигаться. В лесу легко заплутать и придётся жить тут не по своей воли, а просто по фактам. Так что готовимся ко всему.\n\nОтложив будущий лук Люпен поднялся \n\n— Так мы с пацанов за хворостом, а с вас пока найти шпажки и содрать шкуру со второй крысы и змеи\n\nПонятнул пацана за рукав слегка\n\n— Пошли пошли, становится прохладно",154103,null],[154185,"2026-08-12T09:32:16",31,"/roll d20 оглядываюсь, ищу подходящий материал для шкажек. нужны более-менее ровные тонкие палочки, желательно твердые",142532,null],[154189,"2026-08-12T09:34:12",20,"*Пацан послушно кивает, следуя за старшим*\n\n*Когда они отходят чуть дальше, он тихо говорит*\n\n- Думаю,я знаю, где точно север. Если это поможет сориентироваться...",154173,null],[154190,"2026-08-12T09:35:07",9,"*Без особого труда находишь, древесины в лесу полно.*\n\n//Для такого бросать проверку в лесу святотатство)",154185,null],[154197,"2026-08-12T09:42:29",17,"— Отлично, это уже пол дела.\n\nОтойдя подальше Люпен шепотом решил спросить \n\n— Слушай, Рем, ты вижу парень обученый, образованый, при дворе каком то был?",154189,null],[154199,"2026-08-12T09:42:45",17,"И продолжает искать хворост посматривая по сторонам в поисках опасностей леса",142532,null],[154200,"2026-08-12T09:42:49",17,"/r +2 Выживание",142532,null],[154205,"2026-08-12T09:44:15",9,"*Хвороста полно, даже немного сухого что лежал поверх дряблого, такие быстро разгоряться. Да и найти еще парочку грибов маслят тебе не составило труда.*",154201,null],[154220,"2026-08-12T10:12:35",17,"/ @PaIIasCat",142532,null],[154285,"2026-08-12T11:07:53",20,"- Можно сказать и так...прислуживал по мелочам в одном благородном доме. Матушка у меня там прачкой была, а мне разную простую работу поручали *Отвечает Рен*\n\n- ну и получился чему смог там ...наблюдая",154197,null],[154287,"2026-08-12T11:09:19",20,"- А потом в один день важных гостей кто-то отравил *он опускает голову* - ...а я подносил им вино. Разбираться никто не стал - схватили меня и сюда...",142532,null],[154310,"2026-08-12T11:20:13",17,"— Оно как. Крайним сделали и выгнали. А мать твоя, что? Тоже с тобой вылетела? Или там осталась?",142532,null],[154311,"2026-08-12T11:20:40",17,"— Ненавижу я эти интриги подковёрные, ради власти, ради пустого....",142532,null],[154315,"2026-08-12T11:21:58",20,"- Да нету ее уже давно... *Тихо отвечает пацан, как будто сдерживая всхлип*\n- почти не помню её ...",154310,null],[154316,"2026-08-12T11:22:19",9,"*Идя вглубь леса вы замечаете повешенного, он висит на дереве и его ноги едва едва касаются земли, в старом тряпье, иссохший труп, давно висит.*",142532,null],[154317,"2026-08-12T11:22:22",17,"/r +1 Проницательность",142532,null],[154319,"2026-08-12T11:22:42",17,"— Помнишь ты её, мне не заливай, всё до мельчайших деталей лица, повадок, голос. Всегда помнить будешь",142532,null],[154320,"2026-08-12T11:22:54",20,"/на Рена?",154317,null],[154323,"2026-08-12T11:23:20",20,"/r +d20+3 обман",142532,null],[154335,"2026-08-12T11:26:50",17,"— Не люблю я мёртвых трогать, но нам выбирать не приходиться, у него вещи тёплые, может в карманах что-то полезное есть. Давай снимем его, всё что можно заберем. А тело закопаем, правда без лопаты... Ну в песке сможем, что думаешь?",154316,null],[154336,"2026-08-12T11:26:51",20,"*Ты чувствуешь настоящую горечи в словах ребенка о матери, а слова что он ее не помнит звучат довольно искренне*\n\n*Но вот остальное...ты замечаешь как он чуть выпрямляется на твоих словах о власти. Почти незаметный признак тренированной осанки, будто тело выдало его в секунду задумчивости*\n*А в словах про отравление... Так не только страх и обида ребенка из-за несправедливости. Да, они есть. Но что-то ещё, что сложно уловить...*",154317,null],[154337,"2026-08-12T11:27:23",17,"/ Сам траванул",142532,null],[154338,"2026-08-12T11:27:26",17,"/ И спалился",142532,null],[154339,"2026-08-12T11:27:29",17,"/ ББывает)",142532,null],[154341,"2026-08-12T11:27:53",20,"/кто знает...",154337,null],[154344,"2026-08-12T11:28:41",20,"/r d20+1 на внимательность, осмотреть труп",154316,null],[154346,"2026-08-12T11:29:05",9,"*Труп висит, качается.*",142532,null],[154349,"2026-08-12T11:30:05",17,"— Давай палочкой тынкем, проверим, что не живой мертвец\n\nЛюпен берет палку и тыкает мертвеца легонь, что покачался",142532,null],[154350,"2026-08-12T11:30:49",9,"*Не реагирует.*",154349,null],[154351,"2026-08-12T11:30:50",20,"- А они тут водятся? *Пацан выглядит слегка напуганным*\n\n*Тоже берет палочку*",154349,null],[154353,"2026-08-12T11:31:42",17,"— Да чего только нет. Ладно я полез его отвяжу, кстате веревка добрая, сгодится",142532,null],[154355,"2026-08-12T11:31:57",17,"/r +4 Акробатика полез на дерево отвязывать",142532,null],[154359,"2026-08-12T11:32:48",20,"/интересно как действие помощь на акробатику отыграть",142532,null],[154360,"2026-08-12T11:32:56",9,"*Дерево слишком ровное чтобы залезть, по крайней мере нижняя его часть.*",154356,null],[154364,"2026-08-12T11:34:08",17,"— Руки скользят, есть что нибудь чтоб руки обмазать вокруг, посмотри тоже",142532,null],[154365,"2026-08-12T11:34:16",17,"/Ищем природный тальк",142532,null],[154368,"2026-08-12T11:34:42",20,"/помощь от пацана",154365,null],[154369,"2026-08-12T11:35:01",17,"/Давай ты",142532,null],[154371,"2026-08-12T11:35:27",20,"/r +d20+2 на природу, ищем",142532,null],[154376,"2026-08-12T11:36:44",9,"*Ничего особого нет, но есть большая ветка, почти бревно, если её поставить под углом и попробовать забраться на него, может достанете к ближайшим ветвям.*",142532,null],[154383,"2026-08-12T11:39:37",20,"- Вот, тут какая-то коряга довольно прочная. Может подойдёт?",142532,null],[154385,"2026-08-12T11:40:11",17,"— Да, попробую.",142532,null],[154387,"2026-08-12T11:40:30",17,"/ ОНО",142532,null],[154392,"2026-08-12T11:45:39",47,"Что происходит?",142532,null],[154394,"2026-08-12T11:46:09",9,"*Выше к кроне достаточно ветвистое, можно легко забраться и пролезть к узлу на который подвешен мертвец.*",142532,null],[154396,"2026-08-12T11:46:29",17,"/ Мы пошли в лес набрать хвороста, вас попросил содрать шкуру с крысы и язмеи, подготовить место под костём",142532,null],[154397,"2026-08-12T11:46:34",17,"/ Шпажки заготовить и тд",142532,null],[154398,"2026-08-12T11:46:47",31,"шпажки готовы уже)/",142532,null],[154400,"2026-08-12T11:47:15",17,"Добравшись ближе Люпен лёг на ветку где висел мертвец и начал отвязывать веревку\n\n/Проверка ловкости рук нужна?",154394,null],[154401,"2026-08-12T11:48:04",9,"*Мертвец падает вниз, вместе с верёвкой. Лежит не двигается.*",142532,null],[154402,"2026-08-12T11:48:24",20,"*Пацан на всякий случай отступает подальше*",142532,null],[154411,"2026-08-12T11:54:11",47,"Я это вижу?",154401,null],[154413,"2026-08-12T11:54:45",9,"//Спроси у них? С тобой они пошли по хворост или нет",142532,null],[154416,"2026-08-12T11:55:05",47,"/со мной ушли?",142532,null],[154417,"2026-08-12T11:55:24",9,"// @dunchev @PaIIasCat ?",154416,null],[154418,"2026-08-12T11:55:42",20,"/вроде только вдвоём",154417,null],[154420,"2026-08-12T11:56:22",9,"//Сайн выходит на месте стоянки с Конрадом",154416,null],[154422,"2026-08-12T12:02:02",9,"//Го действия, Люпен на дереве, малой внизу, трупец лежит",142532,null],[154428,"2026-08-12T12:04:09",20,"*пацан очень пристально наблюдает за трупом, держа дистанцию. Слова Люпена о живых мертвецах его встревожили*\n\n/Если дернется - предупредит",154422,null],[154429,"2026-08-12T12:04:35",17,"/ Не мы были у лагеря и потом с пацаном пошли по хворост",154416,null],[154432,"2026-08-12T12:05:16",17,"Люпен слез аккуратно с дерева и подошел к трупу\n\nНачал обшаривать его карманы, а заодно проверяя некоторые частые тайники в одежде, которые делают воры, подшиваю в подкладку или воротник",142532,null],[154434,"2026-08-12T12:06:08",9,"/roll +d20+3 хвать люпена за руку внезапно, захват",154432,null],[154437,"2026-08-12T12:07:11",9,"*Иссохшийся мертвец медленно и с трудом пытается ухватить Люпена за руку, его намеренья выдал хрип.*\n\n//От тебя атлетика или акробатика",142532,null],[154438,"2026-08-12T12:08:11",17,"/r +4 ой блять",154434,null],[154440,"2026-08-12T12:08:20",17,"Резко оторвав руку\n\n— Сука, живой!",142532,null],[154442,"2026-08-12T12:09:00",9,"*Мертвец пытается расшевелиться, но пока не может встать, жутко сипит.*",142532,null],[154444,"2026-08-12T12:09:17",47,"Я хочу найти любую крупную упавшую ветку, взять у Конрада нож и обработать деревянную чашку.",142532,null],[154445,"2026-08-12T12:09:27",47,"/r +d20+4 с помощью Конрада",142532,null],[154449,"2026-08-12T12:11:13",9,"//Ну, чашка точно будет, скорее на блюдечко похожа. Сам опиши ток)",154446,null],[154454,"2026-08-12T12:12:40",20,"/можно попробовать по нему психически вьебать запугиванием, чтоб дезориентировать?\n/Или уже в порядке инициативы?",154442,null],[154457,"2026-08-12T12:13:10",9,"//Делай чет, смотри рещультат",142532,null],[154460,"2026-08-12T12:14:13",20,"/r +d20+3 запугивание, громкий крик несколькими голосами в голове мертвяка",142532,null],[154464,"2026-08-12T12:14:51",17,"— Надо разрушить мозг КАРЛ Рем. \n\nЛюпен взял покрепче нож и выбирает угол атаки",142532,null],[154466,"2026-08-12T12:15:40",9,"*Мертвец не боится, но вмешательство кажется его дезориэнтировадо, вместо того чтобы пытаться встать он просто корчится на земле.*",154462,null],[154467,"2026-08-12T12:15:40",20,"/Рен воспринял это по своему, устроив психотеррор",142532,null],[154470,"2026-08-12T12:16:29",17,"/r 3d20+3 Ножом по лежачему в глаз. Эльф точность",142532,null],[154472,"2026-08-12T12:16:36",17,"/ 12))",142532,null],[154473,"2026-08-12T12:16:57",9,"//Ровно)",142532,null],[154474,"2026-08-12T12:17:06",17,"/r d4+3",142532,null],[154476,"2026-08-12T12:18:04",9,"*Мертвец принял удар, кажется это его встряхнуло и в момент когда кинджал его прошил рукой махнул в сторону Люпена.*",142532,null],[154477,"2026-08-12T12:18:10",9,"/roll -d20+2",142532,null],[154481,"2026-08-12T12:19:08",9,"*Попытка не увенчалась успехом, и с новыми силами он пытается встать, это ему удается когда из него вытащили кинджал.*\n\n//Ваш ход",142532,null],[154482,"2026-08-12T12:19:17",17,"/Рен ходи",142532,null],[154483,"2026-08-12T12:19:42",9,"//Просто я не вижу смысла ини в таких моментах, а вот когда рил будет чет такое...",142532,null],[154485,"2026-08-12T12:20:35",20,"/r +d20+3 Рен продолжает пытаться дезориентировать мертвеца ментальной атакой на остатки его мозгов",142532,null],[154491,"2026-08-12T12:21:07",17,"Люпен перехватил руку мертвеца и с силой выдернул нож\n\nЧтобы снова нанести удар уже в другой глаз",142532,null],[154493,"2026-08-12T12:21:17",17,"/r d4+3",142532,null],[154496,"2026-08-12T12:21:36",17,"— Не знаю что ты делаешь! Но продолжай!",142532,null],[154497,"2026-08-12T12:21:47",17,"Кричит пацану",142532,null],[154498,"2026-08-12T12:21:52",9,"//Защитаю как помеху ему\n\n*Мервеца начало шатать на ногах.*",154486,null],[154500,"2026-08-12T12:22:07",9,"//Я писал он встал, но первфй попал 13",154492,null],[154504,"2026-08-12T12:22:59",9,"/roll -d20+2 дезориэнтированный пытается все же цапнуть Люпена, на этот раз наваливается укусить",142532,null],[154507,"2026-08-12T12:23:11",17,"/ КД 13 пробил",142532,null],[154512,"2026-08-12T12:23:43",9,"/roll 1d4+2 он упал на люпена, но достаточно удачно чтобы вцепиться в него своими зубами",142532,null],[154515,"2026-08-12T12:24:34",9,"*Мотает головой, зубы мертвеца вываливаются из челюсти, мертвяк сделал на левой руке рваную рану.*",142532,null],[154516,"2026-08-12T12:24:48",17,"Как только зомби выдирает кусок плоти из плеча лбюпен отстраняется и зажимает рану\n\n— Да когда же ты уже сдохнешь!",142532,null],[154518,"2026-08-12T12:25:16",17,"/Рен",142532,null],[154523,"2026-08-12T12:26:19",20,"*Рен вздрагивает, видя что старшего ранило, но продолжает не сбивает фокус, продолжая удары по менталке*",142532,null],[154526,"2026-08-12T12:26:41",20,"/r +d20+3 по мозгам мертвяку",142532,null],[154529,"2026-08-12T12:28:16",47,"/мне нравится отыгрыш Рена, даже в бою)",142532,null],[154530,"2026-08-12T12:28:18",17,"Видя что зомби впервые не зашатало от воздействия пацана, страх проникает внутрь Люпена\n\n— Нам нужно бежать парень!",142532,null],[154531,"2026-08-12T12:28:24",47,"/контроль разума фул)",142532,null],[154532,"2026-08-12T12:28:50",20,"- Х-хорошо!",154530,null],[154533,"2026-08-12T12:29:12",17,"Еще один удар в голову мертвецу без надежды на успех, и Люпен встаёт перед пацаном, чтоб прикрыть его отход",142532,null],[154534,"2026-08-12T12:29:15",17,"/r +4",142532,null],[154536,"2026-08-12T12:29:20",17,"/r d4+3",142532,null],[154538,"2026-08-12T12:30:03",9,"*Череп треснул, мертвец ошатнулся и на мгновение показалось что сейчас упадёт, но в глазах вспыхнул красный огонёк и он устоял.*",142532,null],[154540,"2026-08-12T12:30:37",47,"7 хп ещё кажись /",142532,null],[154541,"2026-08-12T12:30:51",20,"/пу пу пу",142532,null],[154542,"2026-08-12T12:31:40",47,"Да добьете как делать нехуй",142532,null],[154543,"2026-08-12T12:32:02",9,"//Еще действия какие есть или?",142532,null],[154544,"2026-08-12T12:32:12",20,"/есть",154543,null],[154545,"2026-08-12T12:32:49",20,"*Поняв что ментальная атака больше не действенна, Рен меняет тактику. И пробует обман*",142532,null],[154547,"2026-08-12T12:33:54",47,"/я в ахуе со сборки Рена",142532,null],[154548,"2026-08-12T12:34:05",20,"/r +d20+3 в сознании мертвеца раздается звук. Прямо за спиной. Детский плач и шевеление. Жертва, намного более нежная. Уязвимая, в отличие от вооруженного мужчины перед ним",142532,null],[154550,"2026-08-12T12:34:15",47,"Переговорщик, дипломат, телепат\nЖуть/",142532,null],[154551,"2026-08-12T12:34:22",20,"/да блять, чтож такое",142532,null],[154552,"2026-08-12T12:34:32",20,"/там знамений нет ещё?",142532,null],[154553,"2026-08-12T12:34:33",47,"4 пошли. Стартовые /",142532,null],[154554,"2026-08-12T12:34:35",17,"/ Зомби уже сдох его не обманешь он чует кровь))",142532,null],[154555,"2026-08-12T12:34:41",47,"Я далеко от вас)",154552,null],[154556,"2026-08-12T12:34:52",20,"/эх(",142532,null],[154557,"2026-08-12T12:35:03",17,"/ Ты можешь отойти на 30?)",142532,null],[154558,"2026-08-12T12:35:38",20,"*Видя что и это не срабатывает пацан оставшейся скоростью отходит на 30 ф по направлению к лагерю*",142532,null],[154560,"2026-08-12T12:35:50",20,"/сколько кстати до лагеря?",142532,null],[154561,"2026-08-12T12:35:53",9,"//С языка снял",154554,null],[154563,"2026-08-12T12:36:25",9,"//Минимум футов 500 думаю скорей больше, вы ж отошли неплохо так",154560,null],[154564,"2026-08-12T12:36:48",20,"/ну будем надеяться что мертвяк медленный",142532,null],[154565,"2026-08-12T12:37:11",9,"//Люпен пытается отойти от мертвеца?",142532,null],[154566,"2026-08-12T12:37:20",9,"//Или так и стоит возле",142532,null],[154569,"2026-08-12T12:37:54",17,"Стоит пацану начать убегать люпен тут же пригибается и уходит в сторону тоже отступая\n\n/Отход на 35 отбежал за пацаном, бонуской спрятался",142532,null],[154571,"2026-08-12T12:37:59",17,"/r +4 Скрытность",142532,null],[154574,"2026-08-12T12:38:20",17,"Люпен ищет камень который можно метнуть в голову мертвецу из засады",142532,null],[154576,"2026-08-12T12:38:28",17,"/Есть импровизированное?",142532,null],[154577,"2026-08-12T12:38:51",17,"/ Щас мы его камнями закидаем Рен",142532,null],[154578,"2026-08-12T12:39:08",9,"//Эээ как вы делаете 2 лействия в ход?",142532,null],[154579,"2026-08-12T12:39:08",17,"/ Это же... Медленный мертвец... Правда...?",142532,null],[154580,"2026-08-12T12:39:20",17,"/ У меня засада за бонусное, а отход основным",154578,null],[154581,"2026-08-12T12:39:29",20,"/да норм, я может даже одну атаку выдержу - хотя не должен догнать, Рен был чуть дальше от них футов на 10",154577,null],[154582,"2026-08-12T12:39:33",17,"/Пацан не стоял впритык",142532,null],[154583,"2026-08-12T12:39:43",9,"//С этого момента мертвец ниче не делал, а вы и отошли и убежали и все такое)",154515,null],[154584,"2026-08-12T12:40:00",9,"//Это ясно",154582,null],[154585,"2026-08-12T12:40:05",17,"/Бей по мне",142532,null],[154586,"2026-08-12T12:40:10",17,"/ Его ход",142532,null],[154587,"2026-08-12T12:40:16",17,"/ Потом уже я",142532,null],[154588,"2026-08-12T12:40:16",9,"/roll 1d20+2",142532,null],[154591,"2026-08-12T12:41:11",9,"/roll 2d4+2 его холодные пальцы цепляют Люпена под рёбра в прямом всмысле прошивая плоть",142532,null],[154593,"2026-08-12T12:41:49",20,"/живём?",142532,null],[154594,"2026-08-12T12:42:00",47,"Ща + мертвец будет в армии",142532,null],[154596,"2026-08-12T12:43:05",20,"/да не, там вроде 19 хитов у Люпена",142532,null],[154597,"2026-08-12T12:43:38",9,"//У него крепкий и человек из глубинки, 6 хитов ток от этого есть на втором лвле + родные",142532,null],[154600,"2026-08-12T12:44:30",17,"/ Че то ваняет слабостью мертвец",142532,null],[154601,"2026-08-12T12:44:48",31,"тебя доест и будет сильный/",154600,null],[154602,"2026-08-12T12:45:05",17,"На отходе получив удар под рёбра Люпен спасался в кустах",142532,null],[154603,"2026-08-12T12:45:12",47,"/6+4+6... 16/",142532,null],[154604,"2026-08-12T12:45:13",17,"/ Ну и мой ход описаный выше, щас Рен",142532,null],[154605,"2026-08-12T12:45:22",47,"И +1/2 тело/",154603,null],[154606,"2026-08-12T12:45:44",17,"/ Он нанес только 5 + 5",142532,null],[154608,"2026-08-12T12:46:06",17,"/Тут вот первое попадание",154512,null],[154609,"2026-08-12T12:46:54",20,"*Рен понимает, что обман даже более гиблое дело. И выбирает насилие. Психическое*\n\n*Снова ментальная смута и отход на 30ф*",142532,null],[154610,"2026-08-12T12:47:20",20,"/r +d20+3 работай уже😡",142532,null],[154612,"2026-08-12T12:47:46",9,"*Мертвец медленно плетётся за раненым Люпеном, неуклюжими дёрганными движениями, казалось вот вот упадёт.*\n\n//15 футов скорость, ползёт считай, ещё не расшевелился, закостянел",142532,null],[154613,"2026-08-12T12:47:51",9,"//ход",142532,null],[154622,"2026-08-12T12:52:11",20,"/ну Рен получается походил",142532,null],[154623,"2026-08-12T12:52:38",20,"/22 на дизориентацию",142532,null],[154624,"2026-08-12T12:53:15",9,"//Помеха у него есть, но он не доползёт просто до цели",142532,null],[154625,"2026-08-12T12:53:21",17,"/ Ты не будешь вскрывать засаду там скрытность 17",154612,null],[154626,"2026-08-12T12:53:32",17,"/ Он чует кровь?",142532,null],[154627,"2026-08-12T12:53:50",9,"//Не скажу)",154626,null],[154628,"2026-08-12T12:54:03",17,"/ у меня будет преимущество на атаку скажи",142532,null],[154629,"2026-08-12T12:54:13",9,"//Проницательность мож кинуть свободным",142532,null],[154630,"2026-08-12T12:54:23",17,"/r +1 Проницаю",142532,null],[154632,"2026-08-12T12:54:40",9,"*Он точно знает где ты.*",154631,null],[154633,"2026-08-12T12:55:04",17,"Люпен подбирает камень и метает его в мертвяка издали, потом отходит и ведёт к лагерю",142532,null],[154634,"2026-08-12T12:55:11",17,"/r +3 Метаю камень",142532,null],[154636,"2026-08-12T12:55:13",20,"/понятно, пора переключаться с ментального террора на ментальную поддержку",142532,null],[154637,"2026-08-12T12:55:22",17,"/r d4",142532,null],[154639,"2026-08-12T12:55:38",17,"/ Ловкость я полагаю не добавляем к урону",142532,null],[154640,"2026-08-12T12:55:54",9,"*Череп почти проломило, оно едва ползёт и двигается за вами.*",142532,null],[154641,"2026-08-12T12:56:21",9,"//Метательное без фехтовального свойства ловкость использует?",154639,null],[154642,"2026-08-12T12:56:48",9,"//У импровизированного свойство метательное 20/60 есть",142532,null],[154643,"2026-08-12T12:57:31",20,"/можно ли попробовать через проверку убеждения ментально дать преимущество союзнику? Типа вдохновить/успокоить?",142532,null],[154644,"2026-08-12T12:57:54",47,"Да/",154641,null],[154647,"2026-08-12T12:59:05",47,"Просто действием можно. Да/",154643,null],[154654,"2026-08-12T13:01:22",17,"/ Чтож я отбежал, ход мертвяка видимо",142532,null],[154657,"2026-08-12T13:02:14",17,"Прицелно метнув камень Люпен зажимая раны продолжил продираться через кусты к лагерю",142532,null],[154661,"2026-08-12T13:03:17",9,"//Вродь нельзя, но хз, потом разберёмся",142532,null],[154662,"2026-08-12T13:03:54",17,"/ Действие помощь даже от фамильяра даёт преимущество на 1 атаку",142532,null],[154663,"2026-08-12T13:04:04",9,"*Вы намного быстрее чем оно, мертвец медленно ковыляет в сторону где вы исчезли, к лагерю.*",142532,null],[154664,"2026-08-12T13:04:22",9,"//Он не должен быть на 5 футов от тебя?",154662,null],[154665,"2026-08-12T13:04:32",17,"/ Ну я мог бы кидать в него камнями, но думаю давайте перейдем так\n\nмы его завлекли к лагерю, к остальным, чтобы нам помогли",142532,null],[154667,"2026-08-12T13:05:01",9,"//Го, подключейте команду",142532,null],[154668,"2026-08-12T13:05:07",20,"/там вроде на атаку он должен быть рядом с противником",154664,null],[154669,"2026-08-12T13:05:28",20,"/так что и хочу попробовать через доп проверку дистанционно это делать",142532,null],[154670,"2026-08-12T13:05:37",9,"//Это для окружения",154668,null],[154671,"2026-08-12T13:05:40",17,"/ Ну да в 5 футах, но сказано отвлекающее действие делаете, телепатией в принципе это и делается, ан усмотрение мастера кароче",142532,null],[154672,"2026-08-12T13:05:45",17,"Действие помощь:\nВ качестве альтернативы, вы можете помочь дружественному существу атаковать другое существо, находящееся в пределах 5 футов от вас. Вы совершаете финт, отвлекаете цель или каким-то другим образом делаете атаку союзника более эффективной. Если ваш союзник атакует цель до начала вашего следующего хода, первый бросок атаки совершается с преимуществом.",142532,null],[154673,"2026-08-12T13:06:49",20,"/через обман противника даже выгоднее такая помощь будет, там у меня преимущество от черты)",142532,null],[154674,"2026-08-12T13:06:49",9,"//Вот от него и отталкиваемся, мо описать даже как концентрируешься телепатической атакой чтобы создать слепое пятно в разуме зомби и тот не заметил удара)",154672,null],[154676,"2026-08-12T13:07:50",20,"/короче запугивание - для помех противнику\n/обман - для преимущества союзнику",142532,null],[154677,"2026-08-12T13:08:29",47,"Слыша шум, из лагеря выходит Сайн",142532,null],[154678,"2026-08-12T13:08:59",17,"— Зомби там! цапнул меня, сука... Добейте",142532,null],[154679,"2026-08-12T13:09:52",17,"Люпен запыхавшись прилегает спиной к дереву с обратной стороны от зомби",142532,null],[154680,"2026-08-12T13:10:22",9,"*Его фигура мелькает на краю туманас но... не приближается? Почему-то, отсюда не видно.*",154679,null],[154681,"2026-08-12T13:10:43",47,"Сайн пожимает плечами и достав рапиру, бежит к мертвецу",142532,null],[154682,"2026-08-12T13:11:08",47,"/r d20+2 молюсь богам удачи. Я же Сайн везунчик",142532,null],[154684,"2026-08-12T13:11:16",47,"/r d8+3",142532,null],[154686,"2026-08-12T13:11:24",47,"Боги услышали меня/",142532,null],[154687,"2026-08-12T13:11:42",20,"/отсыпь удачи🙏",142532,null],[154688,"2026-08-12T13:11:57",9,"*Ближе видно зомби тащил на шее длинную верёвку и та где-то зацепилась, он просто не мог пойти вперёд, его не составит труда подскочить и прибить.*\n\n//Описывай",154681,null],[154689,"2026-08-12T13:12:00",47,"У меня остальные персы страдальцы. В частности Рей/",142532,null],[154690,"2026-08-12T13:12:51",47,"Рапира мелькает в воздух и случайным образом вонзается мертвецу в глаза прошивая голову насквозь. Кажется задет центр нервных узлов. Мертвец оседает под ноги Сайну",154688,null],[154691,"2026-08-12T13:13:09",47,"/у меня была заявка сделать деревянную чашку. Результат 22. Сделал?",142532,null],[154692,"2026-08-12T13:15:54",9,"//А, да, не забываем что у Люпена первое истощение, он так и не смог нормально отдохнуть на длительном как и вы.",142532,null],[154693,"2026-08-12T13:17:27",9,"*Люпен чувствует себя уставшим, еще со вчерашнего дня после маршброска. Но раненый сейчас силы совсем подводят. Нужен хороший отдых.*\n\n//Будем щитать с этого момента раз забыл,",142532,null],[154694,"2026-08-12T13:17:38",17,"/ Да, я забыл",142532,null],[154696,"2026-08-12T13:19:22",9,"//А, да. Сложность и так писец, а если потеряете кого то из команды модете смело умножать её на 2 за каждого усобшего, берегите друг друга",142532,null],[154697,"2026-08-12T13:20:12",31,"- я думал вы не на охоту ходили, а вы тут закуску принесли\n\n*шутиочка от Конрада*",142532,null],[154698,"2026-08-12T13:21:13",20,"*Рен пока спешит к Люпену*\n\n- Нужно осмотреть раны...вдруг так какая зараза. *Он достает чистый платок и флягу воды*",142532,null],[154699,"2026-08-12T13:21:37",20,"- Да мы сами похоже этой закуской чуть не стали",154697,null],[154700,"2026-08-12T13:21:47",9,"*На мертвеце было \"50 футов верёвки\", дряхлая одёжка, \"кожаный пояс с металической бляшкой\" и \"добротные сапоги\". В внутреннем кармане амулет напоминающий пирамидку на серебрянной цепочке.*",142532,null],[154701,"2026-08-12T13:22:39",31,"- интересно, ка кон тут оказался. неужели рядом есть человеческое жилье? врядли бы самоубийца потащился через лес чтобы повесится",142532,null],[154714,"2026-08-12T13:52:40",17,"— Спасибо, парень, видел как ты ему голову морочил, может только от этого и спаслись. В следующий раз, сразу драпаем, еще я с мертвяками не связывался...\n\nПомогая пацану перевязать свои раны, Люпен уже с ног валился от усталости\n\n— Вы там это... Всё ценное то когда соберёте, ввы бы его оттащили подальше от лагеря мужики.",142532,null],[154717,"2026-08-12T13:55:29",20,"- Может ему голову отрезать... *Мрачно предлагает мальчик, убирая фляжку обратно*\n\n- Чтобы точно больше не встал",154714,null],[154718,"2026-08-12T13:56:00",17,"— Вообще да, пацан прав...\n\nМрачно подтвердил Люпен",142532,null],[154724,"2026-08-12T14:03:48",20,"- Можно осмотреть место, где его повесили, как отдохнем. Вдруг там ещё остались следы тех, кто его привел туда?",154701,null],[154726,"2026-08-12T14:06:22",17,"— Да, только... Мне надо бы отдохнуть, притащи ту ахапку которую вы бросили неподалёку, разведём огонь.",142532,null],[154740,"2026-08-12T14:10:43",20,"*Пацан кивает, принимаясь собирать хворост вблизи и тащить к центру поляну, где планируется костер*\n\n*Потом подходит к Сайну, слегка тяня его за рукав*\n\n- Можно одолжить ту ткань, которую ты прихватил? Которая знамёна?\n/🥺",154726,null],[154811,"2026-08-12T14:25:31",47,"- Эхъ. Осталось 3 куска... Давай так. Обмен. Мне нужен нож для работы. Я дам одну ткань и рапиру, а ты мне нож? И что-нибудь ещё? - торгуюсь слегка",142532,null],[154827,"2026-08-12T14:29:44",17,"— Ты чего решил торговаться? Я удивлён,\n\nЛюпен кидает ножик к ногам пацана\n\n— Отдай ему",154811,null],[154833,"2026-08-12T14:30:31",47,"- Эуч. Ну я так-то не против на честном слове и всё такое, но вы таки ещё не признали меня своим другом - слегка возмущён. Отдаёт ткань и отламывает рапиру",142532,null],[154835,"2026-08-12T14:31:13",17,"— Да кто не признал, все тут мы друзья по несчастью. Просто нас разделил побег, ты ушел наверх, мы снизу выскочили",142532,null],[154837,"2026-08-12T14:31:27",9,"//Вторая рапира тоже -1 к урону и попаданию",142532,null],[154844,"2026-08-12T14:33:40",47,"- Ну ладно. Тогда честно скажу, мне нож нужен для того, чтобы вырезать всякое. Хотя бы деревянные чашки - показал нормального для ручной работы деревянную чашку",142532,null],[154845,"2026-08-12T14:33:41",20,"*Рен не вмешивается в беседу, отдавая сайну нож и беря ткань. Возвращаясь к Люпену он пытается сделать для раненого более комфортное место для сна, чтобы была возможность восстановить силы*\n\n- как по мне мы все здесь в одной беде, но у меня и нет ничего в обмен, чтобы требовать у других...",142532,null],[154850,"2026-08-12T14:34:12",47,"- Ребят, всё, всё, виноват, не прав был - признаёт свою вину. Отдаёт ещё две ткани",142532,null],[154859,"2026-08-12T14:35:40",20,"- Ты себе тоже оставь хоть один. Чем лучше спишь тем больше сил. А вам взрослым они нужны",154850,null],[154886,"2026-08-12T14:37:12",47,"- Если что сбоку к люпену пристроюсь - махнул рукой",142532,null],[154888,"2026-08-12T14:37:37",17,"— Да никто не в обиде. Забей, вещи с мертвеца можешь забирать смело, это же ты его убил",142532,null],[154889,"2026-08-12T14:37:40",17,"— Я не смог",142532,null],[154892,"2026-08-12T14:38:25",17,"— Спасибо парень\n\nЛюпен ложится отдыхать до ужина, надеясь что ребята справятся с готовкой на костре",142532,null],[154894,"2026-08-12T14:38:40",17,"/r d6 Короткий d4 Отдых",142532,null],[154896,"2026-08-12T14:38:48",47,"- Давайте рассуждать так. Я бы без вас не выбрался. Рен отвлёк стражу, Кто-то принял на себя выстрелы (Рен и Конрад), Кто-то вскрыл решётки, каждый выполнял свою задачу. И я считаю нам необходимо поступать так и дальше. А заодно распределить сильные стороны",142532,null],[154897,"2026-08-12T14:38:49",17,"/ Почти фулл",142532,null],[154899,"2026-08-12T14:39:28",9,"//Д4 откуда?",142532,null],[154904,"2026-08-12T14:40:08",17,"/ А у меня одна кость? д6?",142532,null],[154907,"2026-08-12T14:40:16",9,"// у тебя 2д6",142532,null],[154910,"2026-08-12T14:40:27",17,"/ Я бросал на кости и прокинул ниже",142532,null],[154911,"2026-08-12T14:40:30",17,"/Чето такое было",142532,null],[154912,"2026-08-12T14:40:43",47,"- Лично я имею обалдеть какие ловкие пальчики - подозрительная ухмылка - а так же считаю себя умным. Ну это уже конечно субъективно, но всё же",142532,null],[154917,"2026-08-12T14:41:07",9,"//У тебя 2д6 костей хитов. Кинь вторую д6 но я защитаю уже минимум как 4",142532,null],[154924,"2026-08-12T14:41:58",17,"/r d6 Хорошо",142532,null],[154927,"2026-08-12T14:42:07",9,"//Лан, как было",142532,null],[154932,"2026-08-12T14:42:54",47,"/утс.утс.утс",154912,null],[154942,"2026-08-12T14:44:08",17,"Еще до того как провалиться в сон\n\n— Да, согласен с тобой, Сайн. Помогу чем смогу, даже если тушкой для битья. Я метко стреляю, поэтому и хочу быстрее лук изготовить, хорошо знаю лес, хорошо прячусь. В целом жизнь браконьера заставили, отмычками тоже умею орудовать и ловушки делать простенькие.",154912,null],[154959,"2026-08-12T14:45:54",47,"/то есть мудрость",142532,null],[154962,"2026-08-12T14:46:01",47,"/ну и ловкость",142532,null],[154964,"2026-08-12T14:46:40",17,"/ Мудрости у меня +1, ловкость и телосложение и всё)",142532,null],[154965,"2026-08-12T14:46:47",47,"Сайн подходит и обрабатывает раны водой. Не дезинфекция, но хоть что-то. /",142532,null],[154966,"2026-08-12T14:46:51",47,"У меня -1",154964,null],[154983,"2026-08-12T14:50:25",9,"*Сладковатая вода из тех деревьев оставляет лёгкую плёнку на ранах.*\n\n//Если ею",154965,null],[155021,"2026-08-12T14:53:13",47,"Чистой водой из фляги... Что у стражника была",154983,null],[155022,"2026-08-12T14:53:14",47,"Но можно и соком...",142532,null],[155039,"2026-08-12T14:54:36",9,"*Пока вы отдыхали ничего не произошло, где-то вдали ухукала сова. Пока все ещё тихо.*\n\n//Защитан короткий",142532,null],[155063,"2026-08-12T14:57:08",47,"/можно засчитать лечение +1 за промывание? Медицину кинуть? Какой сложностью?",155039,null],[155067,"2026-08-12T14:57:34",17,"— Не стоило воду тратить, но. Спасибо",142532,null],[155085,"2026-08-12T14:59:22",9,"//Вам не всегда такое дадут делать, по хардкору играем. Но, я вам дал кое что... а вы не осознали",155063,null],[155086,"2026-08-12T14:59:43",31,"Да поняточто что нам дал лечебную воду/",142532,null],[155088,"2026-08-12T14:59:59",47,"/такс. Смотря про что говоришь?",142532,null],[155094,"2026-08-12T15:01:25",9,"//Лан, просто бы почитали что сбоку написанно",152285,null],[155098,"2026-08-12T15:02:07",17,"/ Угу помогает от недугов, это у Сайна вроде или у Рена",142532,null],[155129,"2026-08-12T15:06:14",47,"Я Рену отдал",155098,null],[155423,"2026-08-12T15:56:08",20,"/я побежала к ортодонту, смогу играть ближе 19:00 только",142532,null],[155730,"2026-08-12T17:05:53",47,"Так. Ну пока происходит отдых, занимаюсь лёгкой деятельностью и вырезаю заготовки для фигурок. Я хочу сделать деревянную шкатулку, украденную костянными деталями",142532,null],[155731,"2026-08-12T17:06:08",47,"По окончанию готов двигаться уже из этого ебанного леса",142532,null],[156275,"2026-08-12T18:37:16",20,"/все, вернулась",142532,null],[156278,"2026-08-12T18:37:33",20,"/надо бы ещё силок проверить и сока набрать прозапас",142532,null],[156281,"2026-08-12T18:38:21",17,"/ Щас думаю мастер ожидает отыгрыша привала короткого, поедим и пойдем. Ток я сплю придется вам Крысу жарить и змеб",142532,null],[156286,"2026-08-12T18:39:00",20,"/змею вроде на отвар целебный хотели пустить",156281,null],[156289,"2026-08-12T18:39:39",31,"Из змеи яду надоить можно. Остальное сожрать. Кожу на бурдюк пустить/",142532,null],[156312,"2026-08-12T18:43:02",20,"/погнали тогда разводит костер и готовить?",142532,null],[156313,"2026-08-12T18:43:19",31,"Ок/",142532,null],[156321,"2026-08-12T18:44:34",31,"Пока Люпен отдыхает после боя с зомби, в лагере кипит жизнь. Конрад взялся за разделку крыс и змеи, голову улторойтотрубил и отдал Сайну для того чтобы тот извлек яд",142532,null],[156325,"2026-08-12T18:45:25",20,"*Рен с интересом мимоходом смотрит что там вырезает Сайн и спешит к Конраду, помогать разводить костер*\n\n- Мы собрали немного хвороста, хоть из-за мертвяка пришлось бросить часть *Он подносит охапку веточек к старшему*",142532,null],[156336,"2026-08-12T18:46:08",31,"- отлично. Жареное мясо точно лучше сырого",142532,null],[156340,"2026-08-12T18:46:54",9,"//Я могу щас пропасть на некоторое время, 7% а зарядиться негде",142532,null],[156344,"2026-08-12T18:49:24",20,"*Принимается копать яму для костра, складывая сначала туда маленькие веточки и сухую траву, сверху прикрывая уже более толстыми ветками*\n\n- Где-то у нас оставался ещё трут для факелов, можно будет немного использовать",142532,null],[156557,"2026-08-12T19:33:41",9,"//Тут, хз насколько, надеюсь на долго. Как всегда готов ответить на заявки или заспавнить тараска, по ситуации ^^",142532,null],[156570,"2026-08-12T19:35:08",31,"Я скоро спать уйду/",142532,null],[156576,"2026-08-12T19:35:24",47,"Потопали уже!",142532,null],[156585,"2026-08-12T19:36:04",20,"/разжигает костер, кушаем крысу и змею",156557,null],[156587,"2026-08-12T19:36:34",9,"//Лан, похоже споки.",156570,null],[156593,"2026-08-12T19:36:59",9,"//Это не от меня, а от вас зависит. Вы решаете меж собой)",156576,null],[156602,"2026-08-12T19:39:07",47,"Ну я за потопать. Я уже поел",142532,null],[157759,"2026-08-13T05:28:36",31,"- ну что, перекусили крысятинкой и надо думать что дальше будем делать. Тут сидеть не вариант, надо либо возвращаться и узнавать что от нас хотели, либо уходить в другую сторону. Я, честно говоря, вернулся бы и поискал свое кольцо, но осознаю что против целого аванпоста мне не выжить",142532,null],[157766,"2026-08-13T07:44:24",17,"Люпен проснулся от вкусного запаха жареной крысы мммм\n\n— Вижу все получилось. Замечательно.\n\nОн перекусил половиной крысы и запил соком дерева.\n\n— Пойдем проверять силок? Мне уже намного лучше.",142532,null],[157767,"2026-08-13T07:46:16",31,"- ага, пошли. Надеюс там будет вкусный саблезубый олень, а не эти крысы",142532,null],[157780,"2026-08-13T09:04:40",9,"*Там на месте засады небыло добычи, только погрыженный остаток от силка, хвостик на который он крепился. Сейчас где-то по лесу, болоту пыгает зубастый олень с силком на ноге. Зубки и клыки у них похоже не просто для виду.*",142532,null],[157788,"2026-08-13T09:11:36",47,"Ни-ху-я...",157780,null],[157789,"2026-08-13T09:11:54",47,"Ну и пох",142532,null],[157790,"2026-08-13T09:12:56",17,"— Видать крупная дичь попалась\n\nЛюпен в присядет осматривал место установки силка\n\n— Что думаете? Выслеживать пойдем по следам? Или будем выход из леса искать?",142532,null],[157791,"2026-08-13T09:13:07",17,"/r +2 Выживание осмотр следов",142532,null],[157795,"2026-08-13T09:17:51",9,"*Множество крохотных следов от копыт мелких зубастых оленей.*",157792,null],[157796,"2026-08-13T09:18:38",31,"Мне кажется, этот лес не слишком к нам приветлив. Саблезубые олени, оживающие трупы, змеи толщиной в два взрослых мужика. Пора валить отсюда",157790,null],[157798,"2026-08-13T09:18:57",17,"— Только следы оленей. \n\nЛЮпен встаёт и оглядывается на дерево из которого они набирали сок\n\n— Думаю можно пополнить флягу соком того дерева, и выбираться",142532,null],[157800,"2026-08-13T09:20:15",31,"- я с тобой захватил еще кожу той вчерашней змеи, будет бурдюком",142532,null],[157801,"2026-08-13T09:21:21",17,"/ Мааааленький бурдюк)",142532,null],[157816,"2026-08-13T09:33:43",17,"Набрав сока Люпен прихватил с собой обработаную палку для будущего лука, не зря же уже засечки сделал под тетиву и тканью обмотал оторвав часть от знамени",142532,null],[157817,"2026-08-13T09:34:12",17,"— Я готов выдвигаться, но куда нам двигаться то? В какую сторону? Пацан сказал, что знает где север, может туда?",142532,null],[157832,"2026-08-13T09:53:04",31,"Я так понял, что нас и хотели везти на север, в Веспираль. Стоит ли идти туда? Могли бы с комфортом доехать на телеге и в кандалах",142532,null],[157836,"2026-08-13T09:54:41",17,"— Добраться свободными и следовать чьей то воле, чьему то замыслу как рабы это разные вещи, мой друг",142532,null],[157843,"2026-08-13T09:56:23",31,"- ну для меня это примерно как желание отморозить уши назло маме не надев шапку",157836,null],[157845,"2026-08-13T09:57:31",47,"- Я считаю нам нужно на юг, в порты и уйти в замечательный Аль-Шарáм - предложил Сайн",142532,null],[157849,"2026-08-13T09:58:43",17,"— Мне не принципиально куда податься, но ферма моя недалеко от Веспираля. Я бы хотел вернуться туда, когда разбогатею...",142532,null],[157859,"2026-08-13T10:07:00",31,"- я читаю что на нужен город, и желательно не ближайший. Нужно оьрасти мясом и какой то финансовой стабильностью",142532,null],[157861,"2026-08-13T10:15:58",47,"- Ферма это неплохо, но я чувствую будут вопросы к 4 мужикам живущим под одной крышей",157849,null],[157870,"2026-08-13T10:27:12",17,"— У меня там жена и дети, Сайн. А еще тот самый двойник о котором я рассказывал. Думаю туда соваться не вариант",142532,null],[157871,"2026-08-13T10:27:17",17,"— Пока эта нечисть там",142532,null],[157872,"2026-08-13T10:27:54",17,"— В городе мы можем раствориться, я знаю тайный язык воровских гильдий, могу найти нам... Временную работу",157859,null],[157875,"2026-08-13T10:28:51",47,"- Я бы хотел отойти от дел своих тёмных. Тем более пацана в это втягивать не охота... Можем найти подработку у какого-нибудь торговца. Подшить что, или ещё что",142532,null],[157877,"2026-08-13T10:29:46",17,"— Так быстро не разжиться деньгами. Когда разок попробовал сытой жизни тёмными методами, сложно возвращаться к шитью или ворочанью навоза в хлеву",142532,null],[157880,"2026-08-13T10:30:31",17,"— Конрад, а у твоей семьи, хоть она и уничтожена, остались союзники? Кто то захочет помочь тебе? Или только уничтожить",142532,null],[157886,"2026-08-13T10:34:41",31,"- я не знаю, но думаю врядли. все кто был готов придти на помощь, были биты, а кто не захотел или не успел тогда, явно не станут делать этого и сейчас. разве что кто из родни матери, там у меня дядя должен быть жив, они с отцом друг друга не выносили, но все же родня. я, собственно, к нему и направлялся",157880,null],[157900,"2026-08-13T11:31:36",20,"*Пацан внимательно слушает взрослых, думая что можно ещё предложить. Его навыки довольно специфичны, не так хороши среди простого народа...но для начала нужно выбраться в город*\n\n- Мне кажется юг звучит привлекательно. Порт звучит как место с множеством возможностей...",142532,null],[157901,"2026-08-13T11:32:15",20,"- Но если всё-таки получится получить помощь у семьи Конрада - нужно попробовать сначала этот вариант",142532,null],[157967,"2026-08-13T13:33:10",17,"/ Hard тебе важно чтобы мы двинули в Веспираль или пофиг и на юге есть другой город с портом? Я бы лично в веспираль всё таких хотел",142532,null],[157968,"2026-08-13T13:34:03",17,"— Ну... Знаете порт это хорошо. Но я бы хотел не отрываться далеко от фермы, чтобы была возможность туда прийти. Поэтому я бы пошел в Веспираль. Тамошние шайки я немного знаю",142532,null],[157974,"2026-08-13T13:37:35",9,"//Знаете, го проголосуем и вы как персы как нить скоопитесь в одно место пойти? Я изначально хотел в Веспираль вас силком завести, но вы сбежали)",142532,null],[157975,"2026-08-13T13:37:53",17,"/ Голосую за Веспираль",142532,null],[157977,"2026-08-13T13:38:03",31,"Ну пиздуем тогда по сюжету, просто другим путем/",142532,null],[157979,"2026-08-13T13:38:42",9,"//Я подстроюсь есь чо",142532,null],[158117,"2026-08-13T14:21:28",47,"Ок. Веспираль/.",142532,null],[158148,"2026-08-13T14:44:39",20,"/я не против рельс, особенно если сумеем нарыть там остатки магии лорной",142532,null],[158154,"2026-08-13T14:47:45",9,"//Не, рейс нет, все что я планировал что вы попадете в Веспираль, а там оч от рандома зовисит, моего настроения и ваших действий. У меня есть заготовки, все от вас зависит что узнаете а что нет",142532,null],[158158,"2026-08-13T14:48:13",47,"/поехали уже",142532,null],[158237,"2026-08-13T17:01:33",20,"- Нам нужно вернуться к тому месте, где мы нашли повешенного. Если его там оставили, значит какое-то поселение должно быть недалеко. Можно попробовать дойти до него для начала, раздобыть снаряжение - потом уже по тракту идти дальше. *Предлагает мальчик*\n\n- Да, мы можем определить стороны света - но идти через глухой лес это самоубийство. Особенно без конкретной точки назначения",142532,null],[158247,"2026-08-13T17:07:44",17,"— Пацан дело говорит. Поддерживаю. Еще я думаю не получится найти мне тут тетиву добрую. Сайн, отдай мне ремень пожалуйста. Я сделаю пращу",142532,null],[158423,"2026-08-13T18:03:56",47,"Сайн с жалостью отдаёт ремень со своего пояса и выправляет китель наружу",158247,null],[158431,"2026-08-13T18:05:37",17,"/ Ремень и мертвеца был, я кстате без рубахи, надо бы лут прибрать к рукам)",158423,null],[158432,"2026-08-13T18:06:11",47,"/аааа",142532,null],[158433,"2026-08-13T18:06:12",17,"Люпен садится берет так же временно ножик и вырезает из ремня крепкую пращу, в свою сумку из простыни он набирает камней и готов ко всему",142532,null],[158434,"2026-08-13T18:06:19",47,"/сори, про Мертвечука не читал",142532,null],[158435,"2026-08-13T18:06:28",17,"/Там немножко лутецкого",158434,null],[158437,"2026-08-13T18:06:28",47,"/если что, напоминаю, Сайн в форме стражника",142532,null],[158443,"2026-08-13T18:07:08",47,"- Вообще без б -снимает ремень с мертвеца и отдаёт товарищу - а ты только один сможешь?",142532,null],[158450,"2026-08-13T18:07:48",17,"— Не знаю давай вместе, может две пращи сделаем",158443,null],[158451,"2026-08-13T18:08:05",17,"/r +3 Ловкость рук",142532,null],[158453,"2026-08-13T18:08:08",47,"/помогаю!",142532,null],[158455,"2026-08-13T18:08:14",17,"/ ХУЙ",142532,null],[158456,"2026-08-13T18:08:15",17,"/ АХАХХА",142532,null],[158461,"2026-08-13T18:08:57",47,"Вдохновение трать! /",142532,null],[158466,"2026-08-13T18:09:17",47,"/или мастер даст знамение сейчас юзануть?",142532,null],[158470,"2026-08-13T18:09:58",17,"/r d4 ЖЕСТКО ТРАЧУ",142532,null],[158472,"2026-08-13T18:10:04",17,"/ 12 сумма",142532,null],[158478,"2026-08-13T18:10:40",47,"/r d4  докину свою как помощник",142532,null],[158481,"2026-08-13T18:10:44",47,"14",142532,null],[158502,"2026-08-13T18:13:30",17,"/ Ну кайф вроде я щас с пращи буду убивать жеска\n\nд4+13 ) но на попадание -2",142532,null],[158507,"2026-08-13T18:14:21",20,"/кстати я глянула - короткий лук это просто оружие",158502,null],[158510,"2026-08-13T18:14:33",47,"Да/",158507,null],[158512,"2026-08-13T18:14:55",20,"/там что его можно будет потом взять. Лёгкий арбалет тоже простое",142532,null],[158516,"2026-08-13T18:15:27",17,"/ Значит ошибся",142532,null],[158596,"2026-08-13T18:30:53",9,"//Ни у кого нет инструментов ткача или кожевника из тех кто делал пращи?",142532,null],[158601,"2026-08-13T18:31:26",17,"/ Есть два ножа",142532,null],[158604,"2026-08-13T18:31:37",17,"/ Да и ремень вроде как располагает",142532,null],[158608,"2026-08-13T18:32:22",20,"/у сайна есть владение инструментами ткача вроде",158596,null],[158633,"2026-08-13T18:35:37",9,"//Тогда без проверок можете пару бедных пращ из ремня собрать, если бы не владели то сл 15. Не буду душнить за наличие инструмента, это праща",158608,null],[158661,"2026-08-13T18:39:40",9,"//Вдохновы тож не трогаю те что вы пытались тратить",142532,null],[158666,"2026-08-13T18:40:35",9,"*Общими усилиями у вас получаются две пращи, правда без нужных инструментов камушки не очень ровно или хорошо летят.*\n\n// Полученны \"праща -1\" 2 шт",142532,null],[158761,"2026-08-13T18:55:19",17,"/ Кайф с меткого стрелка с -3 ебашить",142532,null],[158766,"2026-08-13T18:56:22",9,"//Пока кд не более 12 хотя бы возможно",142532,null],[158778,"2026-08-13T18:59:26",47,"Эх",142532,null],[158779,"2026-08-13T18:59:28",47,"Тяжко",142532,null],[158780,"2026-08-13T18:59:56",20,"/интересно как праща конечно может быть не точной, учитывая насколько она простая",142532,null],[158807,"2026-08-13T19:02:38",47,"Банально кривая/",158780,null],[158809,"2026-08-13T19:02:46",47,"/центр смещён. Хуй знает",142532,null],[158814,"2026-08-13T19:03:27",20,"/короче как механическая условность ок",142532,null],[158816,"2026-08-13T19:03:35",20,"/справедливо",142532,null],[158829,"2026-08-13T19:06:27",31,"Просто у обывателей ручки из жопы, не могут нормально камни кидать/",142532,null],[158834,"2026-08-13T19:07:06",9,"//Инструменты найдёте нужные — поправите. Хотя ни у кого из вас нет инструментов кузнеца вродь, рапиры прийдётся в кузню на выравнивание",142532,null],[159032,"2026-08-13T20:01:40",47,"/так. Уточню сразу. Инструменты ткача могут заменить инструменты кожевенника, как ты сказал, а инструменты резчика по дереву, они же по кости и подобному твёрдому но гибкому материалу, верно?",158834,null],[159035,"2026-08-13T20:03:35",9,"//Только пока это логично. Набором травника сварить зелье лечения оке, но ты не можешь варить им все зелья. Пращу и ткачом, там работы то этой, вот реально кожаный доспех ткачом не сделать.",142532,null],[159043,"2026-08-13T20:08:34",47,"/а если бы я владел набором кожевника. Чтобы ты запретил мне делать из тканного?",159035,null],[159058,"2026-08-13T20:12:45",9,"//В принципе по ситуации, хз. Но сумку хранения ты бы не пошил 100% знай её рецепт",159043,null],[159060,"2026-08-13T20:13:03",47,"/пошил бы. Из кожи",142532,null],[159062,"2026-08-13T20:13:20",47,"/или нарезал, из дерева",142532,null],[159064,"2026-08-13T20:13:21",9,"//Ну да, или резчиком по дереву шкатулку",142532,null],[159065,"2026-08-13T20:13:34",47,"/я на шаг впереди)",142532,null],[159066,"2026-08-13T20:13:41",9,"//Смысл ты + - уловил надеюсь)",142532,null],[159068,"2026-08-13T20:14:15",47,"/в общем я понял нахожу редкую ткань, говорю: изготавливаю по рецепту доспех из змеиной чешуи. В виде чешуи подшиваю пластинки из такого-то материала. Хотов",142532,null],[159072,"2026-08-13T20:16:26",9,"//Зависит от того \"как\" ты это делаешь, да)))",142532,null],[159081,"2026-08-13T20:17:46",47,"Так. что мы делаем? Давайте уже топать!",142532,null],[159082,"2026-08-13T20:17:51",47,"Требую приключений!",142532,null],[159087,"2026-08-13T20:18:29",47,"И да. Мне нужен алхимический набор (травителя набор), портняжный, набор резчика по материалу и... Набор взломщика",142532,null],[159088,"2026-08-13T20:18:56",47,"/и да, Харди, напомни, там вроде за интелект ещё можно на изучать наборы инструментов?",142532,null],[159093,"2026-08-13T20:20:16",17,"— Тогда идём как пацан предложил. Сами посудите. Мужика повесили. Странно идти далеко в лес со смертником. Скорее там рядом дорога или домик лесника. А Рен знает где север. Так что потопали.",142532,null],[159097,"2026-08-13T20:20:37",17,"/ и мы идём к месту где повесили мужика и там будем дальше искать выход из леса",142532,null],[159098,"2026-08-13T20:21:04",47,"За! /",142532,null],[159099,"2026-08-13T20:21:12",47,"/я думаю Конрад тоже за",142532,null],[159153,"2026-08-13T20:39:31",9,"//Он спит уже 100%, с утра начну",142532,null],[159213,"2026-08-14T02:19:37",31,"За, пошли уже/",142532,null],[159260,"2026-08-14T07:47:51",47,"Hard",142532,null],[159264,"2026-08-14T07:50:46",17,"/ Спит еще наверно)",142532,null],[159304,"2026-08-14T10:03:25",9,"//Разберусь сейчас со всем, и го",142532,null],[159336,"2026-08-14T11:11:16",9,"*Вернувшись на место где был повешенный, вы не увидели никаких следов. Если они и были — тот висел здесь давно, все исчезло.*\n\n*Рен чувствовал примерное направление, север. Если подумать так. Северо-западнее — то болото, идти вдоль него, может что-то интересное встретить. Идти прямо на север, скорей всего леса, что в них ждет — неизвестно. На северовостоке больше шанс встретить дорогу или тракт, их под болотами редко ведут, так что чем дальше от болота тем больше шанс выйти на пути.*",142532,null],[159337,"2026-08-14T11:14:46",9,"// @cirson вопрос, ты куда бел ткани с гербалистикой стражи с трупа, опиши",142532,null],[159338,"2026-08-14T11:18:03",47,"/снял в мешок. Я же часть тканей потратил на верёвку, потом снял с трупа и их всего 3 осталось",159337,null],[159339,"2026-08-14T11:19:01",9,"//Меня волнует, есть ли у тебя что-то от них что можно классифицировать как \"их\" вещи. Как обычно поверх доспеха носится цветная ткань с гербалистикой",159338,null],[159340,"2026-08-14T11:19:44",47,"/доспех ты не озвучивал",159339,null],[159341,"2026-08-14T11:19:52",47,"/цветную ткань пустил на одеяло",142532,null],[159342,"2026-08-14T11:41:47",20,"- Ммм, следов нет...плохо *Вздыхает пацан, прежде чем обернуться к остальным*\n\n- Ну что, идём тогда на северо восток?",142532,null],[159343,"2026-08-14T11:42:07",20,"- Надо выйти на тракт",142532,null],[159345,"2026-08-14T11:44:22",47,"- Веди парень - кивает Сайн. Как же он заебался это мешок тащить...",142532,null],[159350,"2026-08-14T11:48:56",17,"— Да. На северо-восток.\n\nЛюпен крутит пращу без камня",142532,null],[159354,"2026-08-14T12:16:07",31,"- идем, и так задержались в этом лесу",142532,null],[159355,"2026-08-14T12:21:47",9,"*Вы вышли к быстротечной реке, она не широка но вас снесло бы течением если попытались бы переплыть, брода не предвидится и похоже она стекает в болото. У реки много хороших камней, вы спугнцли пару больших оленей. В небе едва просматривается где находятся солнца за чёрными, клубящимися облаками, пасмурно.*",142532,null],[159356,"2026-08-14T12:21:55",9,"//Восприятие с вас",142532,null],[159357,"2026-08-14T12:22:24",9,"*Время идет к вечеру, закат через несколько часов.*",142532,null],[159358,"2026-08-14T12:22:33",17,"/r +1 Восприятие",142532,null],[159360,"2026-08-14T12:23:17",9,"*Среди камней на берегу реки краб. Точно зеленый, речной краб.*",159359,null],[159361,"2026-08-14T12:26:53",20,"/r d20+2 восприятие",142532,null],[159363,"2026-08-14T12:26:59",17,"— Крабик",142532,null],[159364,"2026-08-14T12:27:30",47,"/r d20-1  не хочу никуда смотреть, дайте 1 крит",142532,null],[159366,"2026-08-14T12:27:40",47,"Просто тащу мешок, заебался",142532,null],[159367,"2026-08-14T12:27:45",9,"*У самой реки стоят рогачи возле плоского большого камня. Место для рыбалки? Но сейчас здесь никого нет.*",159362,null],[159368,"2026-08-14T12:27:53",20,"- Хм, если впереди болото, то можно попробовать идти против ее течения в противоположную сторону. Поселения обычно по берегам водоемов",142532,null],[159369,"2026-08-14T12:28:36",20,"- А вот так возможно рыбачили? Значит точно есть люди по близости",159367,null],[159372,"2026-08-14T12:56:00",9,"//Что делают ваши персонажи? Буду теперь вас тыкать)",142532,null],[159373,"2026-08-14T12:57:50",47,"- Давай только быстрее, я уже хочу что-то вкусное поесть - торопит Сайн",142532,null],[159374,"2026-08-14T12:59:39",20,"/пацан хочет осмотреть то место с рогачами - может там есть следы или тропинка",159372,null],[159375,"2026-08-14T13:00:01",20,"/r d20+2 на внимание",142532,null],[159378,"2026-08-14T13:00:48",9,"*Рогачи свежие, их обновляют или установили недавно? А ещё, один камень подозрительно сдвинут.*",159376,null],[159379,"2026-08-14T13:02:35",20,"*Рен палочкой двигает камень в сторону*",159378,null],[159380,"2026-08-14T13:04:47",9,"*Большой камень, кажется под ним что-ти припрятанно.*",159379,null],[159381,"2026-08-14T13:09:45",20,"/хочу заглянуть в тайник",159380,null],[159382,"2026-08-14T13:10:13",9,"*Тяжёлый чтобы просто тыкнуть палкой и сдвинуть. Но руками вполе возможно.*\n\n*Пахнет водой и мхом на каменистом береге реки.*",159379,null],[159383,"2026-08-14T13:12:49",20,"/ну сдвигаем, заглядываем...",159382,null],[159384,"2026-08-14T13:13:00",9,"*Под камнем лежал чей-то схрон для рыбалки, в вырытой под ним яме. По мелочи, \"35 футов шёлковой лески\", два \"пробковых поплавка\", семь \"стальных крючков\", четыре \"свинцовые грузила\", несколько \"приманок из ниток\". Ещё была аккуратно сложенна \"мелкоячеечная сеть на 50-ти футовой верёвке\" которую надо закидывать в водоём и вытаскивать.*",142532,null],[159385,"2026-08-14T13:14:15",20,"- Тут похоже снасти для рыбалки! *зовёт пацан взрослых. Они смогут воспользоваться ими лучше, чем он*",159384,null],[159386,"2026-08-14T13:20:44",31,"извините, я сейчас не могу писать//",142532,null],[159409,"2026-08-14T13:50:00",17,"— Лесочка, всё остальное и сеть.\n\nПовернулся к Сайну\n\n— Идём попробуем закинусь сеть и неводом пройтись вверх по течению, авось рыбы наловим.",159385,null],[159412,"2026-08-14T13:50:07",17,"/@cirson",142532,null],[159676,"2026-08-14T16:08:11",47,"С радостью скинул мешок:\n- Поехали, научишь",159409,null],[159722,"2026-08-14T17:58:44",17,"— Хорошо, нам на ту не попасть. Поэтому привязываем тяжесть к двум концам и забрысываем ихв воду. Сами берм за два других конца и идём вдоль берега. Это не так здорово, как если бы мы шли по двум сторонам ручья, но тоже не плохо.\n\nДаёт Сайну конец сети. Привязывает камни к двум нижним концам\n\n— Невод готов, а ты?",142532,null],[160910,"2026-08-15T08:51:55",17,"/ @cirson",142532,null],[161660,"2026-08-15T15:56:26",9,"//Я тоже бы продолжил, думаю)",159722,null],[161662,"2026-08-15T15:57:04",17,"/ Ну тут зависит многое от тимейтов",142532,null],[161663,"2026-08-15T15:57:14",17,"/ если я буду один срать постами, вероятно сдохну",142532,null],[161671,"2026-08-15T16:08:26",20,"*Пацан возвращает камень на место, слегка сочувствуя неудачливому рыбаку-хозяину*\n\n- Идёмте, возможно сможем отыскать поселение до темноты,если повезёт.",142532,null],[161677,"2026-08-15T16:13:25",17,"/ Ладно сделаем вид ничего не поймали",142532,null],[161678,"2026-08-15T16:13:44",17,"— Сеть можно взять с собой. Пригодиться против оживших мертвяков я думаю",142532,null],[161679,"2026-08-15T16:13:57",17,"— Снасти тоже.",142532,null],[161681,"2026-08-15T16:14:17",17,"— Пошлите дальше вверх по реке. Поищем брод или место где перейти.",142532,null],[161682,"2026-08-15T16:14:37",9,"*Во время рыбалки Конрад с Реном замечают легкий дымок за деревьями, немного в лес, вверх по реке где вы рыбачили. Это дым от кострища?*",142532,null],[161687,"2026-08-15T16:16:04",20,"*Рен смотрит на дым. Потом смотрит на товарищей. Есть у нас что-то еще подозрительное, что лучше спрятать, вроде спизженых снастей и символом стражи?*",161682,null],[161688,"2026-08-15T16:16:52",9,"//Ты думаешь или мне ответить? Не пойму",161687,null],[161690,"2026-08-15T16:17:00",17,"— Ты думаешь стражники там лагерем встали? Нас ищут?",142532,null],[161691,"2026-08-15T16:17:04",20,"/да, как персонаж осматриваю",161688,null],[161692,"2026-08-15T16:17:09",17,"— Тогда у них скорее всего есть наши зарисовки.",142532,null],[161693,"2026-08-15T16:17:23",9,"*Вроде бы ничего более.*",161691,null],[161694,"2026-08-15T16:17:25",17,"/ А я думал это телепатия",161687,null],[161696,"2026-08-15T16:17:56",20,"- Нет, но если там рыбаки или охотники, им лучше думать что мы просто бедняги, на которых напали бандиты и мертвяки. А не сбежавшие преступники",161690,null],[161699,"2026-08-15T16:18:44",20,"- Давайте все приметное спрячим заранее. И сразу договоримся о легенде",142532,null],[161701,"2026-08-15T16:18:59",17,"— Добро. Так и сделаем.",142532,null],[161703,"2026-08-15T16:19:34",17,"— Мы фермеры на ферму которых напали мертвяки и загнали глубоко в лес. Если спросят где ферма опишу свою. Чтоб правдоподобнее было.",142532,null],[161722,"2026-08-15T16:22:34",20,"- Хорошая идея, надо ещё объяснить наш вид... О - мы фермеры, но на ферму напали бандиты, обворовали, а нас хотели взять в рабство, поэтому особо ничего на нас нет... Ну а потом мы чудом сбежали и еле вышли к людям через лес. Так правдоподобнее наша внешность.\n\n*Ну и сочувствие вызовет, что тоже им на руку, легче манипулировать. Но это пацан решил не говорить в слух*",161703,null],[161737,"2026-08-15T16:24:24",17,"— Ну да. Тут ты прав. Так складнее",142532,null],[161738,"2026-08-15T16:25:04",20,"/ждём подтверждения от остальных и топаем на огонек?",142532,null],[161739,"2026-08-15T16:25:07",17,"— В любом случае плутать по лесу смысла нет. Идём на этот дым.",142532,null],[161740,"2026-08-15T16:25:16",17,"/ @QURTZZ @cirson",142532,null],[161741,"2026-08-15T16:25:22",17,"/ Хотябы от одного наверное",142532,null],[161742,"2026-08-15T16:25:26",17,"/ Леша тут вроде",142532,null],[161749,"2026-08-15T16:27:21",31,"- ну, я сейчас точно не тяну на сына барона. Думаю, это оптимальный вариант действия, идем",142532,null],[161776,"2026-08-15T16:33:58",9,"//Такс значит втроём идёте, описывайте как это делаете.",142532,null],[161786,"2026-08-15T16:40:28",20,"/сайн думаю тоже пойдет",161776,null],[161787,"2026-08-15T16:41:13",9,"//Я готов активно играть часто, но вы не можетесобраться, кого-то одного нет постоянно(",142532,null],[161790,"2026-08-15T16:41:40",9,"//Ирл и все такое, но наверное я просто много взял игроков",142532,null],[161792,"2026-08-15T16:42:51",31,"У меня по выходным к сожалению мало времени на отыгрыши, семья, дела))//",142532,null],[161801,"2026-08-15T16:45:44",20,"*Рен бросает взгляд в свое отражение в воде, ещё раз поправляя грязь и убеждаясь, что засохшие дорожки слез на испачканных щеках достаточно заметны. Потом делаем тоже самое с повязкой на раненом плече. Жертва бандитов. Испуганная, загнанная и отчаяния. Подходящая маска*\n\n*Он встаёт, направляясь за взрослыми.*\n\n- Сначала стоит проверить, точно ли это не стража или бандиты... *Тихо говорит он*",161776,null],[161803,"2026-08-15T16:46:19",17,"/ Да тут у меня так же.",161792,null],[161820,"2026-08-15T16:52:35",31,"- идея хорошая, но опасная для одиночки",161801,null],[161823,"2026-08-15T16:53:43",20,"- Поэтому лучше идти всем вместе. Скрытно. Если окажутся обычные мирные рыбаки - попробую уж их заболтать",161820,null],[161836,"2026-08-15T16:57:37",31,"- давай так, мы мирные рыбаки, идем толпой, даже скрываться не обязательно, мы же мирные",161823,null],[161857,"2026-08-15T17:02:18",20,"- Ну...не очень мы похожи на рыбаков за работой *Мальчик указывает на их внешность. Грязь, кровь, обноски*\n\n- Жертвы бандитов по-убедительнее. Да и на ночлег можно будет попроситься. Из сочувствия",161836,null],[161859,"2026-08-15T17:02:45",31,"- рыбаки, которых ограбили?",161857,null],[161864,"2026-08-15T17:04:21",17,"— Я прикинуть немым. Чтобы не завалить все.",142532,null],[161866,"2026-08-15T17:04:44",17,"— Так и скажите этот раненый - немой",142532,null],[161897,"2026-08-15T17:23:32",20,"- Тогда надо будет искать оправдание, из какой мы деревни ближайшей, а вдруг тут все друг друга знают...да и рыбачить вряд ли кто-то умеет из нас для подкрепления легенды. Давайте так - мы обычные люди, но издалека. Здесь оказались как раз таки из-за похищения бандитами, которые нас хотели в рабство в Веспираль отвезти продать. А там уж сбежали.\n\n- И врать то особо не надо - только стражу на бандитов подменить... Лучшая ложь она всегда полуправда.",161859,null],[161919,"2026-08-15T17:45:24",31,"- хорошо, принято, идём",142532,null],[161932,"2026-08-15T18:10:03",17,"— Я согласен. Пошли. Ты говорун у нас пацан. Я тебе доверяю",142532,null],[161937,"2026-08-15T18:26:48",47,"Товарищи, я к сожалению в ситуации когда времени очень мало и оно после 6 вечера. Я либо сейчас вылетаю, либо игра очень сильно тормозит(",142532,null],[161948,"2026-08-15T18:41:29",9,"//Эх, что будем делать?",142532,null],[161952,"2026-08-15T18:43:19",17,"/ Ну вот хз. У меня времени нормально в будни. Я могу прям плотно играть",142532,null],[161953,"2026-08-15T18:44:08",47,"Мне хрустно, печально, но вариантов мало",142532,null],[161957,"2026-08-15T18:50:06",9,"//Это точно? Можем пока подождать немного, если ничего не изменится можешь как персонаж уйти, или чет придумать.",161953,null],[161958,"2026-08-15T18:51:01",20,"//ели дойдем до поселения то персонаж может как раз отделится, АФК фармить пока не появится время",142532,null],[161962,"2026-08-15T18:52:08",17,"/ Вариант. Сайн может снова наняться к портнихе помогать ей шить одежду и работать как чесный человек",142532,null],[161964,"2026-08-15T18:52:34",20,"/а потом его позовет дорога приключений)",142532,null],[161966,"2026-08-15T18:52:37",47,"/только немного времени вечером. Выходные",161957,null],[161967,"2026-08-15T18:52:49",47,"/или просто придёт проблема и придётся решать",161964,null],[161968,"2026-08-15T18:52:56",9,"//Я ему до 3го ур нашкребу чтобы золота побольше получал",161962,null],[161972,"2026-08-15T18:53:59",47,"Не обязательно. /",161968,null],[162570,"2026-08-16T07:27:54",9,"*Леся тянется бесконечно, словно пространство искажается, оглянуться — прошли не так далеко, словно стояли на месте, фейское колдунство.*\n\n*Вечер сменился ночью? Нет, вон же оно солнце на небе, второе чуть дальше, хотя облака пропускают лишь иссиня тусклый свет, мрачный. Это был дым от костра — руины.*\n\n*Вы слышите голоса у палаток меж остатков стен, зданий и замков. Это место не просторно, эхо цивилизации, твердая кладка ято сохранилась до сих пор твердит: \"оно было важно\".*\n\n*Лагерь бандитов? Археологи, искатели сокровищь? Точно по первому взгляду не скажешь, людей тут достаточно.*",142532,null],[162571,"2026-08-16T07:34:08",9,"//Такс, решение в моменте, вы скрываетесь или все же выходите к ним как и планировали изначально?",142532,null],[162581,"2026-08-16T09:29:35",17,"— Рен, идём в открытую или полезем по кустам поближе?",142532,null],[162582,"2026-08-16T09:37:29",20,"- Давайте попробуем сначала скрытно посмотреть кто это...",162581,null],[162584,"2026-08-16T09:40:48",17,"Люпен кивает и шмыгает в кусты",142532,null],[162585,"2026-08-16T09:40:55",17,"/r +4 Скрытность",142532,null],[162589,"2026-08-16T09:41:46",20,"/опять проклятие двойки",142532,null],[162590,"2026-08-16T09:42:04",9,"//Это моё, оно везде распространяется, сорян",142532,null],[162592,"2026-08-16T09:44:01",9,"*Часовой вас явно приметил, и присвистнув указал рукой прямо на вас, сидя сверху на одной из стен. Вы модет быть и скрылись бы, но его не заметили.*\n\nЧасовой — Да, да, вы там. Что прячитесь? Ребята, у нас гости!",162591,null],[162596,"2026-08-16T09:45:03",17,"Люпен выходит из кустов и приветственно машет. Встаёт за спину пацану",142532,null],[162597,"2026-08-16T09:45:08",9,"*Весь лагерь побросали лопаты и раскопки, тут в целом было человек двадцать? Если не тридцать!*",142532,null],[162598,"2026-08-16T09:46:53",31,"Тоже держусь за пацаном, это наш мозговой центр))",142532,null],[162599,"2026-08-16T09:48:40",20,"*Рен вздыхает. Ну конечно все не может идти как им хочется. Потом оборачивается к людям, уже как испуганный и уставший ребенок*\n\n- П-пожалуйста, не с-стреляйте... *Он слегка выступает вперёд, показывая что абсолютно безоружен, зажимая рукой раненое плечо*\n\n/Параллельно активирую обнаружение мыслей",142532,null],[162604,"2026-08-16T09:59:19",31,"Извините, пока не могу тут быть, машина сломалась на ходу, надо чинить",142532,null],[162605,"2026-08-16T10:00:04",9,"//Чекни когда все будет збс, я сделал пост уже",162604,null],[162666,"2026-08-16T16:15:33",31,"Все не заебись, но я более или менее свободен, извините за ожидание//",162605,null],[162674,"2026-08-16T16:33:02",9,"*Из толпы людей, не очень хороших на вид людей с интересом бросает дела, посмотреть на вас, некоторые тянулись к оружию на поясах но не вынимали, в этот момент из-за их спин раздаётся выкрик командном тоне: \"чего встали! Опять от работы отлыниваете.\"*\n\n*Из за толпы вышла женщина с повязкой на глазу, перед ней уступали дорогу. Часовой шустряком спустился по верёвочной лестнице вниз и заискивая начал отчитываться:*\n\nЧасовой — Жан, тут это, залётные.\n\n*Прищурив глаз, глава этой шайки оценила вас на скорую руку, представляете ли вы опасность. Похоже она её не увидела, даже не скрывала этого.*\n\nЖанка — Это не повод отлинивать, марш батрачить! Я сама с ними разберусь. — *Нехотя все разбрелись создавая вид бурной деятельности поглядывая на новоприбывших, только рядом с Жанкой моросил какой-то стремный полурослик, он выглядел максимально неприметно, похоже был на побегушках.*\n\n*Сама Жанка подошла ближе и возвышаясь, а она была под два метра ростом (но не два), скрестила руки под грудью и спросила не выбирая слов:*\n\nЖанка — Какого х%я вы забыли в этих местах где даже орки срать не сядут?",142532,null],[162675,"2026-08-16T16:33:58",9,"*Жанна в цвете.*",142532,null],[162681,"2026-08-16T16:43:15",20,"/что-то в мыслях у нее слышно?",142532,null],[162685,"2026-08-16T16:49:49",9,"//А ты их читаешь?",162681,null],[162687,"2026-08-16T16:50:08",20,"/ага, там в заявке выше активировала",162685,null],[162701,"2026-08-16T17:01:11",9,"\"Хочу жёстко жрать, ужин еще ждать два часа, еще эти нарисовались тут, повесить их может или использовать как примарку для волков или повесить? Их кислые рожи портят мне настроение, ещё все мужики. Стоят ещё, молчат. Меня задрало это место, комары, бомжи и мы ничего полезного не откопали ещё...\"\n\n*Тысячи жалоб от разных мелочей до потерянной пудренницы вареницой пронеслись в мыслях. Личность и образ мышления Жанки настолько широк что видятся даже мыслеобразы ее знакомых, врагов и даже список имен кого бы она хотела похоронить лично.*",162681,null],[162719,"2026-08-16T17:15:27",20,"*Рен несколько секунд прислушивается, оценивая Жанку. Черные археологи? Чтож, кажется придется кардинально менять тактику - таких сложно разжалобить. Испуганное выражение его лица сменяется просто настороженным*\n\n- Ох, похоже нам повезло - это не лагерь стражи а вполне нормальные люди. *Он шмыгает носом, вытираясь рукавом, голос звучит как у типичной дворовой шпаны*\n\n- Босс, не пустите к огоньку погреться? Нас эти пидоры полдня по лесу гнали пока не остали, а потом ещё полдня мертвяки ебучие.\n\n- Вы нам местечко перекатываться, а мы вам помощь какую посильную - хоть байку как стражу наебали, хоть портки поштопаем, а то и за  лопаты лишние взяться можем.",162701,null],[162721,"2026-08-16T17:18:28",9,"// @QURTZZ @dunchev у вас есть какие-то действия или реакции",142532,null],[162723,"2026-08-16T17:19:03",17,"Люпен стоит улыбается и чучуть стонет прижимая руки к окровавленным бинтам на ранах",142532,null],[162726,"2026-08-16T17:20:35",31,"Согласно киваю, подтверждаю слова Рена. Сам думаю о том, как нас воспринимают, если за нас говорит малец. Кго ведь так могут принять за какого то богатого наследника в поиска приключений и с охраной потсьввденнйо добрым папашей",142532,null],[162747,"2026-08-16T17:43:03",20,"/чисто ситуация улыбаемся и машем, парни. А то на корм волчкам",142532,null],[162761,"2026-08-16T18:35:28",9,"Жанка — При малец вздумал п%здеть как взрослый? — *В наглую подходит и хватает тебя за ухо.*\n\n//Сопротивляешься?)",162719,null],[162762,"2026-08-16T18:37:39",17,"Люпен машет руками мол тише тише и мычит жалобно",142532,null],[162763,"2026-08-16T18:38:19",9,"//Не тебя, рена за ухо)",162762,null],[162764,"2026-08-16T18:38:45",17,"/ Да я понимаю",142532,null],[162765,"2026-08-16T18:38:51",17,"/ Я показываю какие мы безобидные",142532,null],[162766,"2026-08-16T18:39:10",9,"/roll 1d20+6 проницательность",162762,null],[162768,"2026-08-16T18:39:26",9,"//Ну, обман шоле давай",142532,null],[162769,"2026-08-16T18:40:27",9,"/roll 1d20+4 полурослик рядом с жанкой за вами тоже наблюдает",142532,null],[162771,"2026-08-16T18:42:28",20,"- Ай ай, босс! *Рен жалобно тянет, но не вырывается*\n\n- да что там как взрослый - выбора нет! Один немой, другой тормозной - вот и приходится за всех одуваться",142532,null],[162772,"2026-08-16T18:42:45",20,"/r +d20+3 обман",142532,null],[162774,"2026-08-16T18:43:03",20,"/r d4 вдохновение докину",142532,null],[162776,"2026-08-16T18:46:26",9,"Жанка — Мне самую малость плевать. — *Она улыбнулась и наклонилась.* — Будешь при мне материться, лишишься уха, пальца или языка. Уяснил мелочь?",142532,null],[162777,"2026-08-16T18:47:02",9,"Полурослик — Жан, он врёт, не похожи они на недоумков, таких половина, по нашим сразу видно. — *Немного прячется за главой, хитро сверкая глазками.*",162770,null],[162778,"2026-08-16T18:47:17",20,"- Так точно, босс. Ни слова поганого из этого рта не вылетет *пацан делает честные глаза, кивая*",162776,null],[162779,"2026-08-16T18:47:53",20,"/у меня за способность переговорщик есть возможность один раз ещё кинуть на убеждение если провалилось на следущий ход\n/Получится?",162777,null],[162780,"2026-08-16T18:50:16",20,"/там ещё мысли паралельно считываются)",142532,null],[162781,"2026-08-16T18:50:21",9,"Жанка — Для меня вы все недоумки. — *Не придала значения, и вернулась к малому.* — Раз врёте то хватить притворяться. Сейчас вам далут лопаты и будете работать, разберёмся за ужином. Кларк, ты ими займись.\n\n*Наконец отпустив ухо Рена он ушла. Остался ток полурослик, он вас побаивается с очень.*",162777,null],[162782,"2026-08-16T18:51:54",9,"Кларк (полурослик, подсос жанки) — Я, ну... — *Он немного растерялся, как всегда на него все скинули, а потом добавил неуверенно:* — Ну вы слышали, берите лопаты...\n\n*В одиночку уже не такой наглый, боится чтобы вы его не прибили.*",142532,null],[162783,"2026-08-16T18:53:08",9,"*Жанка уходила с настроением кого-то прирезать, найти мазь от комаров и съесть сочный стейк.*",142532,null],[162784,"2026-08-16T18:53:16",20,"- Эт чё, я правда умным выгляжу? Спасибо, дядь. *Слегка лыбится пацан.*\n\n- Никогда так не называли, хы\n\n/Читаем параллельно его мысли",162782,null],[162785,"2026-08-16T18:53:52",20,"- А лопаты где?",142532,null],[162786,"2026-08-16T18:58:08",9,"Кларк (полурослик, подсос жанки) — Вон, под стеной. — *Он осторожно идёт полуоборотом, готовфй смытся от вас в любой момент.*\n\n\"Набирает кого попало, Шило меня чуть не прирезал прошлый раз, эти тоже выглядят как те ещё бандюганы. Эти два здоровяка идут за малым не просто так, необычный пацан и глаза мне его не нравятся, будто в душу смотрит...\"\n\n*Кларк очень подозрителен к вам, и думает о том как вас прирезать втихую если к нему проявят агрессию, дёрганный слишком. Похоже на его судьбу выпало много невзгод, очень повезло что он ещё жив.*",162785,null],[162787,"2026-08-16T19:01:34",20,"- О, вижу *Кивает пацан и едет за лопатами, маша взрослым*\n\n*В их головах раздается голос*\n\n\"Вроде от виселице отболтался, но положение все ещё шаткое - коротышка нас подозревает, так что без подозрительных движений. Я слышу вас - не говорите, думайте. Сможем обсудит что делать так, мысленно.\"",162786,null],[162788,"2026-08-16T19:07:23",31,"*хмм, а ведь тут можно что то интересное выкопать. Главное, спрятать хорошо*",142532,null],[162789,"2026-08-16T19:08:34",20,"/чисто механически и Люпен и Конрад будут слышать не только пацана но и друг друга, он имитацией голоса их фразы друг другу повторяет",142532,null],[162790,"2026-08-16T19:08:53",31,"Ничего себе хаб//",142532,null],[162791,"2026-08-16T19:11:44",9,"*Вас поставили копать землю в большой яме под стеной. Посередине была верхушка какой-то скрижали, но её ток начали раскапывать, и рядом с вами ещё 3 человека бандитской наружности, поглядывают недобро.*\n\nМысли первого: \"Чёрт, я заебался не могу, мы тут уде вечность, где чортово сокровище, я хочу хорошо отдохнуть в Кабаньем Клыке. Еще какие-то новые лица, Жанка снова бродяг припахала.\" — *Постоянноноет у себя в голове, от этого кажется ему становится легче.*\n\nВторой: \"Чёрт, они не выглядят так словно что-то имеют. Даже поживится нечем, да и эти двое увальней выглядят сильными, не буду пока лезть\" — *Хочет ограбить вас, думает как стрясти пару золотых за \"защиту\" или типа того вместе с братками, тех самых братков кстати рядом нет.*\n\nТретий: \"Как там жёнка интересно, уже родила поди, надеюсь сынку, надо побыстрее закончить тут, хочу домой подарков притащить.\" — *Мужик обычный, работяга. Пошел на прибыльнре но не очень хорошее дело ради семьи.*\n\n//Я думаю это то что пацан узнаёт от тех кто близко если их мысли читает",142532,null],[162793,"2026-08-16T19:15:06",17,"/ Я почти освободился",142532,null],[162794,"2026-08-16T19:15:23",9,"//А Алексей скоро спать",142532,null],[162795,"2026-08-16T19:15:33",9,"//Но в целом мы сдвинулись, я доволен",142532,null],[162796,"2026-08-16T19:15:52",17,"/ Завтречка плотно сядем",142532,null],[162797,"2026-08-16T19:15:56",17,"/ Ну выходные они такие",142532,null],[162798,"2026-08-16T19:16:00",17,"/ В делах в заботах",142532,null],[162804,"2026-08-16T20:36:05",47,"У меня всё дни щас так",142532,null],[162807,"2026-08-16T21:41:52",17,"— Мужики, просветите залётного. Тут за работу чем греют? На кормёжке держат, звонкой отсыпают или с клада долю режут? А то лопату дали, а расклад не озвучили.",142532,null],[162808,"2026-08-16T21:44:16",17,"/ Воровской жаргон",142532,null],[163312,"2026-08-17T08:58:29",9,"Первак — Да не парься так, тут всн свои. — *Мужик не понял зачем ты по воровскому заговорил, тут нет тех кто уши греет.* — Жанка строгая, но платит, бывает конечно кого-то вздернут или ещё что, это участь кто ворует у своих или предателей.\n\nВторой — Шеф даже торговцев грабить не хочет, она просто \"берет с них деньги за сопровождение\". — *Последнее он сказал с ноткой презрения, у этого парня более бандитский склад ума.*\n\nТретий — У меня дочка родилась три года назад, я только прибился сюда, меня Жана выдернула из порта. Тогда она и подарки приготовила. — *Этот парень не отлынивал, ему на вид чуть за двадцать всего.* — Деньги все по чесноку делим, Шеф больше забирает, но она денег на нас не жалеет, если чего реально нужно своим не желеет.\n\n*Жанну все по своему хвалят, хотя видно что её жалует кто-то больше, кто-то меньше.*",162807,null],[163315,"2026-08-17T08:59:45",17,"/Что б покзать что залётный, но свой в каком то смысле)",142532,null],[163316,"2026-08-17T09:01:58",17,"— Добренько. Мужики, а какой тут город, аль деревня рядом? Мы с ребятами хотели бы осесть.",163312,null],[163319,"2026-08-17T09:08:33",9,"*Первый и третий переглянулись, а второй усмехнулся.*\n\nПервак — Фейское место это, тут одному потеряться пить дать. Есть тракт и корчма с чуханками местными, но люди в этих местах могут ограбить тебя аль обнести в два счета.\n\nТретий — Да, одному в окрестностях близ Веспирали лазить себе дороже. Можно осознать что в брюхе торчит нож но будет уже поздно. А все потому что у тебя было пару медях или булка. — *Он вздохнул, втыкнул допату и потянулся прежде чем взять тачку с землёй повезти наверх по доскам.* — Тем кому нечего терять — терять нечего.",163316,null],[163321,"2026-08-17T09:19:16",31,"- а тут что копаем то?",142532,null],[163323,"2026-08-17T09:23:15",9,"Первак — Шары какие-то ищем, руны со скрижали списать надо. Может надём клад ещё.\n\nВторой — Ничего ценного. — *Бандюга не хотел говорить, но в мыслях он прокрутил в голове что жанка торгует информацией и утраченными знаниями о магии.*\n\n//Последнее для Ренас и наверное его подождём, скок там обнарудение мыслей длится, скоро пройти наверное должно, пусть поспрашивает чёт пока оно есть",142532,null],[163324,"2026-08-17T09:25:27",17,"/ @PaIIasCat",142532,null],[163329,"2026-08-17T09:28:57",20,"/я тут",142532,null],[163337,"2026-08-17T09:32:51",20,"*Рен в основном прислушивается к мыслям. Кажется он сейчас более осторожен после неудачи с переговорами - не даются ему пока хорошо маргинальные роли. Наблюдает, запоминает повадки других, чтоб в будущем лучше мимикрировать*\n\n*Зацепился за мысль о информации и магии. Магия? Здесь? Нужно подумать, как к этому подобраться...*\n\n*Пока в мыслях передает старшим, пока обнаружение мыслей ещё работает*\n\n\"Какие наши дальнейшие планы?\"",142532,null],[163361,"2026-08-17T09:49:30",17,"Люпен думает чтоб пацан прочитал\n\n\"Давайте до вечера тут, пожрём за работу, а на утро свалим. Хотя может они собираются в город, с ними под защитой этйо Жанки шансов будет поболе. Видать они люди чесной судьбы, вопросов не задают особо.\"",142532,null],[163363,"2026-08-17T09:49:49",17,"\"Главное не выёбываться и тихо мирно работать не отсвечивая, хотябы сейчас\"",142532,null],[163369,"2026-08-17T09:58:43",20,"\"Хорошо.\" - мысленно соглашается пацан. - \"И да - будьте осторожней со вторым - он явно на нас поживиться планирует с своими 'братками'. Остальные вроде угрозы не представляют, если не лезть\"",142532,null],[163370,"2026-08-17T09:59:51",17,"\"С молодым можно скорешиться, он вроде парень простой, для семьи батрачит, напоминает мне меня, помладше\"",163369,null],[163371,"2026-08-17T10:01:04",17,"Люпен налегает на лопату сильнее, авось откопает сам этот шарик с глифами и Жанка выделит побольше жратвы",142532,null],[163372,"2026-08-17T10:01:08",17,"/r -1 Атлетика",142532,null],[163377,"2026-08-17T10:03:59",9,"//Да, любое, но ток не то пж ~",142532,null],[163378,"2026-08-17T10:04:40",31,"/roll d20-1 внимательность на поиски лута при копке",142532,null],[163380,"2026-08-17T10:06:27",9,"*Хорошая лопата попалась, штыковая, такой не говно разгребать, а землю ворочать. Да и силушки немного вернулись чтобы лопатой помохать.*\n\n//Ты снова забыл что у тебя истощение 1 степени, но ладно уже, щас не так важно",163373,null],[163381,"2026-08-17T10:08:02",9,"*Копая и роясь в грязи видняются остатки глиняных черепков и кости. Останки кажется человеческие, в поза будто человек просто лежал?*",163379,null],[163382,"2026-08-17T10:08:44",20,"*Рен тоже кое-как пытается копать, по боль в плече после стрелы делу особо не помогает. Надо будет за ужином намекнуть этой Жанке, что писать может - может дадут эти скрижали переписывать, а не лопатой ворочать*",142532,null],[163383,"2026-08-17T10:13:10",17,"/ Океееей",163380,null],[163384,"2026-08-17T10:13:56",9,"//Щас, я настраиваюсь *включил музон\"",142532,null],[163394,"2026-08-17T10:25:17",9,"*Пару часов от силы вы махали лопатами. Когда почти стемнело люди бросали потихоньку работу и собирались у костров. Вкусно пахло кашей и дичью. У каждого было свое место, по интересам или по групкам.*\n\n*Жанка уже сидела окруженная своими подчинёнными, на вид там были самые важные из них. Показывали шефу находки, говорили как прошел день, но сама Жанна выглядела так словно хорошо приготовленная кабанья ножка важнее всего, сейчас была занята основном ею.*\n\n*Мест у костров не предвиделось, как вас окликнули.*\n\nМолодой — Эй! Идите сюда, у нас есть местечко. — *Вас подозвал тот парень что хвалил Жанку и говорил о детях. Рядом с ним сидел только один тучный мужик в какой-то странной броне и глушил пиво.*",142532,null],[163399,"2026-08-17T10:27:06",9,"*У костров гомонили, слышались звуки гитары, первые песни. В этом была своя атмосфера, пока люди отдыхали от тяжёлого дня и ждали ужин.*",142532,null],[163443,"2026-08-17T10:55:43",17,"— Ага, идём. Что сегодня в лесу подствелили? Я так понял у вас тут разделение по ролям, копатели, охотники и защитники?",142532,null],[163451,"2026-08-17T10:59:27",20,"*Пацан следует за старшими, слушая и запоминая*",142532,null],[163456,"2026-08-17T11:02:15",9,"Молодой (Чифтер Люск) — Я бы так не сказал. — *Он взглянул на человека в толстых доспехах рядом.* — Это Дима. Меня зовут Чифтер Люск, или просто Чиф. Дим, поздоровайся с новичками.\n\n*Он протянул руку поздороваться.*\n\nМолодой (Чифтер Люск) — Некоторые зовут меня мастер Чиф в шутку. — *Усмехнулся парень.* — Жанна никого не делила, люди сами собираются по интересам.",163443,null],[163457,"2026-08-17T11:03:13",17,"— Димон не видел тебя на копке ты чем занимаешься в лагере? Охотишься?",142532,null],[163460,"2026-08-17T11:04:43",9,"Воин в больших доспехах (Димон) — Нет ничего лучше, чем спать после хорошего отдыха. — *Проворчал воин взглянув на вас, а после вернулся к созерцанию тлеющего пламени, пьёт пиво.* — Извините, я не отдыхаю.",142532,null],[163461,"2026-08-17T11:04:55",9,"//Чиф там был",163457,null],[163462,"2026-08-17T11:05:10",9,"//Вот чиф",163319,null],[163464,"2026-08-17T11:06:24",17,"/ ааа это чиф",142532,null],[163467,"2026-08-17T11:06:47",20,"- Я Рен, приятно познакомиться *Пацан сидит, оглядывается - как будто просто из детского любопытства и без особо дела*\n- Как много здесь людей...и у всех свое дело?\n\n/хочу посмотреть в какой  компашке сидит тот второй с раскопок и запомнить их на всякий случай\n/Ещё хочу оценить кто сидит с Жанкой, тоже запомнить кто здесь важный",163456,null],[163468,"2026-08-17T11:06:58",17,"/Поправил",163457,null],[163490,"2026-08-17T11:18:30",9,"Воин в больших доспехах (Димон) — Смерть животного, завершая старую милю и меч. — *Нехотя отвечает какими то непереводимыми формулировками, это не воровской жаргон.* — Мать не уменьшается.",163457,null],[163498,"2026-08-17T11:22:32",9,"Молодой (Чифтер Люск) — Основном мы копаемся в старых руинах, ищем уцелевшие подземелья, а иногда находим слкровища. — *Мастер чиф вернулся к готовке, перемешивая кашу. Сначала он сварил мясо с приправами и солью а потом засыпал жиноватый отвар с мясом крупой чтобы помастить ту и та впитала всё.* — Не раз мои знакомые уходили на пенсию после удачного дела, поэтому у костра так мало людей. Люди семейные редко держаться за опасное дело. Думаю ещё один или два удачных дела я тоже уйду к семье. Хватит чтобы прожить не спеша остаток, золото не стоит жизни.",163467,null],[163499,"2026-08-17T11:23:02",17,"— Угу... Ладно.",163490,null],[163518,"2026-08-17T11:32:58",9,"Молодой (Чифтер Люск) — Не обращай на говор Димы внимание, он сражается и иногда охотится. Если правильно его понял он жалутся но то что болят ноги и работы не становится меньше. Монстров в округе полно. — *Чиф примерно прикинул что имел ввиду его друг.* — Пацана с собой такскаете, откуда вы?",163499,null],[163520,"2026-08-17T11:33:06",17,"— А знаете тут кого нибудь из охотников? Я метко стреляю, мог бы пригодиться и завтра у нас к вечеру был бы мясной пир!",163498,null],[163530,"2026-08-17T11:40:20",9,"Молодой (Чифтер Люск) — Дим, возьмешь... — *Он хотел назвать имя но понял что Люпен еще не представился и запнулся.* — Новенького с собой?\n\nВоин в больших доспехах (Димон) — Извините за эту жизнь, я не хочу.\n\nМолодой (Чифтер Люск) — Да ты гляди. Бери говорю, а то будешь себе сам готовить.\n\nВоин в больших доспехах (Димон) — Это конец. — *Здоровяк посмотрел на Чифа и потом на Люпена оценивая, кажется нехотя согласился, его способ это сказать можно интерпретировать по разному:* — Держите свои ремесла. — *Недовольно допивает кружку пива.*",163520,null],[163533,"2026-08-17T11:41:31",17,"— Люпен меня звать.",163530,null],[163535,"2026-08-17T11:42:44",17,"— Спасибо, не пожалеешь. Дайте мне только лук и я белке в глаз... Ну ладно не буду бахвалиться, простите, завтра добыча скажет за себя сама.",142532,null],[163541,"2026-08-17T11:46:01",20,"- Спасли они меня, сначала от стрелы, потом от мертвяка. *Отвечает Рен на вопрос Чифа*\n- Пожалели. Вот и таскают теперь с собой. А каждого по разному судьба сюда привела...",163518,null],[163542,"2026-08-17T11:47:49",9,"Молодой (Чифтер Люск) — Чёрт, и угораздело же тебя. Рана всё ещё на месте? Как давно.",163541,null],[163558,"2026-08-17T12:02:16",20,"- Около суток... *Рен морщится, поправляя повязку* - Жить буду, но болит жуть",163542,null],[163559,"2026-08-17T12:04:53",9,"Молодой (Чифтер Люск) — Подожди немного, ещё не поздно. Мешайте кашу пока по прийду пожалуста. — *Он встал покинув готовку и пошел прямо к Жанке, с ней о чем то говорить.*",163558,null],[163561,"2026-08-17T12:06:28",9,"Воин в больших доспехах (Димон) — Глаза отца. — *Прокоментировал он и повесил кружку на пояс, смотрит на еду и взяв ложку перемешивает неуклюжими руками.*",142532,null],[163565,"2026-08-17T12:09:08",20,"- Давайте я помогу, хоть не с лопатой так хоть с поварешкой полезен буду\n\n*Рен берет ложку, помешивая кашу здоровой рукой. Но услышав комментарий воина внезапно замер на пару секунд.*\n\n-...\n\n*Потом снова продолжил мешать*",142532,null],[163590,"2026-08-17T12:20:43",20,"/какой-то вайб игры престолов пошёл",142532,null],[163601,"2026-08-17T12:23:19",9,"*Воин оставил готовку на тебя, и выразительно сказал непереводимую формулировку значение которой знал наверное только сам.*\n\nВоин в больших доспехах (Димон) — Акак, Дакан Пол Мукар, Сенсорри. — *Это звучало грустно, словно вспоминал прошлое и не совсем хорошее.*",163565,null],[163620,"2026-08-17T12:29:13",20,"*Пацан сочувственно кивает, продолжая мешать еду к котелке*\n\n- Ага ...\n\n*Параллельно запоминает стиль общения и формулировок этого человека, чтобы потом попытаться понять больше. Похоже слова про глаза его почему-то напрягли*",142532,null],[163631,"2026-08-17T12:33:35",9,"*Чиф вернулся с красноватым зельем в руках.*\n\nМолодой (Чифтер Люск) — Да, достал, показывай где рана, пока ещё свежая. — *Видно что он искренне доволен собой что делает что-то хорошее, не скрывая своего настроения.*",163620,null],[163646,"2026-08-17T12:37:17",20,"- Это...мне? *Рен смотрит на него широкими глазами. Похоже узнал зелье лечения. Он осторожно разматывает повязку на ране*\n\n- Спасибо большое...но ты уверен что стоит тратить что-то столь ценное на меня одного? \n\n/Можно ли кстати нарративно разделить это зелье чтобы боль снять? А то у люпина тоже рана была",163631,null],[163649,"2026-08-17T12:41:14",9,"Молодой (Чифтер Люск) — Тебе на вид пятнадцать не более, шрамы украшают только поживших мужиков за тридцать. — *Чих часть зелья перематывает новые свежие бинты поверх ран на которые полил а другую половину дает выпить тебе.* — Оно простое, не так и дорого. Тут места хорошие, трав на одно можно насобирать за день или два.",163646,null],[163651,"2026-08-17T12:43:54",20,"*Пацан слабо, но искренне улыбается ему. Кажется такая открытая бескорыстная помощь для него редкость.*\n\n- Хорошо, тогда я попробую поискать этих трав. С лопатой от меня пользы не очень много - а зелье всегда полезно. Да и Люпину тоже досталось, когда он от мертвого меня защищал. Нужно отплатить",163649,null],[163652,"2026-08-17T12:45:37",9,"Молодой (Чифтер Люск) — Хорошо, попробую завтра выпросится сходить за травами раз зелье одолжил. Посмотрим, может и правда больше толку.",163651,null],[163654,"2026-08-17T12:46:19",20,"/половина зелья же у меня? Могу Люпену отдать?",142532,null],[163656,"2026-08-17T12:47:07",9,"//Технически тебе его дали чтобы выпил остаток)",163654,null],[163658,"2026-08-17T12:47:26",20,"/ну ладно, тогда пьем)",163656,null],[163660,"2026-08-17T12:47:56",20,"- А много тут людей за травами ходят? Чтоб одному не идти и знать что искать",163652,null],[163678,"2026-08-17T12:52:50",9,"*Мастер Чиф возвращается к готовке.*\n\nМолодой (Чифтер Люск) — Чёрт, переварилась чутка, сейчас поправим немного. — *Пытается подправить дело приправами на вкус, отвечает как может.* — Да троя, я иногда хожу. Главное одному не ходить, только по отметкам а далее оставлять свои. Если видишь фею — иди обратно, не смотри больше на неё и не разговаривай, по нему не скадешь, но это фейское место. Днём оно ближе к Веспирали, а ночью где-то в другом месте.\n\n*Указывает на небо поварёшкой.*",142532,null],[163693,"2026-08-17T12:55:27",20,"*Рен смотрит на небо. Интересно, тут и правда будут другие созвездия?*",142532,null],[163703,"2026-08-17T12:59:00",9,"*Если прислушаться, ночь тихая, без единого дуновения ветра, тишина, только шум в лагере археологов. Ты давно слышал как мерцают звёзды? Лишь задержав взгляд на них, слышать сказки из прошлого, шёпот из пустоты который хочется слушать часами не закрывая глаз.*\n\n*В небе мерцают огни, горят огни, падают огни. Чего же ты медлишь!? Взгляни!*\n\n*Без глаз любопытных, никто не увидит, чудо, словно загаданное желание. Падают звёзды, падают звёзды. Высоко и далеко, хоть сколько, не дотянешься рукой. Низко и легко, освещая деревьев верхушки.*\n\n*Словно посеянные семена, упадут на землю и прорастут. Или сгорят, исчезнут, как тени, пыль. Звёзды которых никогда небыло, звёзды которые были всегда.*",142532,null],[163719,"2026-08-17T13:01:52",9,"Молодой (Чифтер Люск) — Правда красиво? Тут так каждую ночь, а с рассветом наплывают облака. — *Чиф насыпает и раздает миски с немного перваренной но все еще отлично приготовленной кашей.* — Только ночью не ходи от лагеря, те кто ходил — пропали. А так, словно сказка.",142532,null],[163736,"2026-08-17T13:05:25",9,"// @QURTZZ йоу, ты с нами кстати? У нас тут отыгрыш, социалка и разговоры по душам с хорошими ребятами)",142532,null],[163747,"2026-08-17T13:08:03",9,"Воин в больших доспехах (Димон) — Спрашивал много морские волны. — *Даже не взглянул вверх, звёздное небо не беспокоило воина, беспокоила остывающая каша.*",142532,null],[163753,"2026-08-17T13:09:27",31,"у меня ведение своего кветса на финишной прямой, сорян. тут я пока как рюкзачок молчаливый, обдумываю свою жизнь и слушаю разговоры других//",163736,null],[163754,"2026-08-17T13:09:52",9,"//Тогда не спешим пока",142532,null],[163806,"2026-08-17T13:26:58",20,"*Мальчик смотрит на небо, почти заворожённый. Как давно он не видел такого чистого неба? Или скорее как давно он вообще останавливался, чтобы взглянуть наверх?*\n\n*Он зачерпывает ложкой еду, теплая пища непривычно приятно ощущается после стольких дней около голода. Мог ли он представить всего неделю назад, что будет так рад такой простой без изысков еде? Навряд ли*\n\n*Странная всё-таки эта штука, судьба*",163719,null],[163807,"2026-08-17T13:27:07",20,"/чилим",142532,null],[164409,"2026-08-17T21:21:42",17,"Люпен присматривался у другим. Особенно его заинтересовал человек про которого Рен прочитал, что он опасен и настроен нас обнести. Люпен захотел с ним перетереть за жизнь. \n\n\"Авось получится показать, что у нас ни гроша за душой. Чтоб не приставал с дружками.\"\n\nОтведав каши Люпен встал и поблагодарил\n\n— Силы, спасибо за хлеб насущный. То не каша, а варёный эликсир жизни. Чувствую себя человеком теперь. Благодарю.\n\nЧуть поклонился, скорее кивнул. И начал искать того смурного парня с которым копали.",142532,null],[164416,"2026-08-17T21:25:55",9,"*Бандюган сидел и тянул вино у одного из крайних кострищ, рядом с ним сплошь бандитские рожи, человек пять. Не вооружённым глазом видно что скорей изгои, остальные держутся подальше от них.*",164409,null],[164417,"2026-08-17T21:32:38",17,"Люпен неспешно подошёл к крайнему костру, окинул взглядом мужиков и задержался глазами на вине.\n\n— Здорово, работяги. Не прогоните, если к огоньку задницу пристрою? А то за день лопатой так намхался, будто копальщик могил после войны.",142532,null],[164426,"2026-08-17T21:43:08",9,"Бандюган (со шрамом на носу коршун) — Свали а, хера хочешь уши греть. — *Один из них, самый вредный на вид махнул рукой.*\n\nБандюган (тот самый) — Пс, ребят, это же залётный. — *Тот же что присутствовал на раскопках повернулся к тебе и улыбнулся, пару передних зубов были из серебра.* — Бросил доходягу Чифа и пришел совета у старших просить? Садись, чего уж, подвинемся.\n\n*Среди толпы выдилялся жирный мужик, его рожа заплыла, глубоко посаженные черные глазки недобро сверкали как две звездочки. Детина ростом выше на голову любого здесь, словно мог съесть одного из свои товарищей на закуску и осталься голодным. Молча сидит, страшный.*",164417,null],[164428,"2026-08-17T21:48:22",9,"//Ну, ни пинов ничего нет, только слепки старой восточной династии Динь Динь пусть будет это лицо",142532,null],[164429,"2026-08-17T21:53:42",17,"Люпен на окрик Коршуна только криво усмехнулся, будто и не обиделся. А после приглашения сереброзубого благодарно кивнул и подсел к костру, не лезя слишком близко\n\n— Вот и славно. А то я уж подумал, тут у огня места по наследству передают.\n\nОн протянул ладони к теплу и покосился на серебряные зубы мужика\n\n— А совет старших дело полезное. Особенно когда залётный ещё не знает, кому тут можно на сапог наступить, а кому после этого новый сапог покупать придётся. Надо бы пояснить зелёному.\n\n/ это уже на воровском жаргоне частично",164426,null],[164431,"2026-08-17T21:55:05",17,"Люпен на мгновение оглядел собравшихся, задержав взгляд на здоровяке, но без наглости — скорее отмечая про себя, кто здесь чего стоит.\n\n— Мы сегодня как снег на голову свалились, сами видели. Жанка лопату сунула — и вроде уже свои работники, а кто тут кто, чего не любит и за что может в ухо дать — никто не объяснил.\n\nОн усмехнулся.\n\n— Так что хоть просветите человека. А то не хотелось бы по незнанию кому-нибудь на больную мозоль наступить.",142532,null],[164445,"2026-08-17T22:31:51",9,"Бандюган (тот самый) — Да, шеф она такая. — *Он ведет себя на удивление дружелюбно.* — Не беспокойся, как старшие мы тебе поможем.\n\n*В целом говорил только тот самый что хотел на вас поживится, остальные основном молчали, видно что не доверяют. Здоровяк молча ел не в себя.*\n\n*Местный шеф — Жанка, та еще воротила, она собирает буквально всё что может, предпочитает заучивать информацию сама на зубок и до последней буквы, а потом уничтожает оригиналы. И хотя глава ведет не очень честный образ жизни в некотором роде она благородна что именно этих бандинских рож не лчень устраивает. Баба то умная и хитрая, но в то же время без неё тут ничего бы в куче не удержалось.*\n\n*Есть пяток людей что вторые после жанки. Полурослик Кларк хоть и выглядит как мальчик на побегушках может прирезать кого-то и сказать что так и было, Жанка почему-то не наказывает его за это, хотя других бы вздёрнула. Повариха у них не только красавица и умеет головить, однажды к ней приставал кто-то та на него заклятье наслала, остался от бедного мужика ток гниль да кости, повариху лучше не злить. Ветеран есть, по кличке борода, сильный воин, может сдержать монстра как грифон или медведь без особых усилий справившись с любым из них без особых усилий, постоянно гоняет всех в зашей, сражаться учит. Двух зубрил упомянул лишь вскользь, по его мнению они не интересны.*\n\n*Между делом он назвал своё имя, Илистад, тот самый бандит на вас поживиться, кликуха его была \"язык\".*\n\nБандюган (Илистад) — ... того и гляди проблемы какие будут. Если чего надо — спроси, поможем. С тебя лишь доля, три пятых за защиту. — *Показывает на пальцах, правда от кого и как не говорит. По поведению видно что отстанет за хорошую долю, а если не согласишься — устроит проблемы.*\n\nБандюган (со шрамом на носу коршун) — Заканчивай язык, у меня уже голова болит, уже скоро на боковую, мы так и не допизделись по поводу. Отсылай зелёного давай.\n\nБандюган (Харя настолько широквя что выглядит так словно \"я тебя сожру\") — Много напиздел язык. — *Гулко и недовольно просопел.*",142532,null],[164446,"2026-08-17T22:56:10",17,"Люпен всё это время слушал внимательно, не перебивая. На словах про три пятых он только медленно почесал щетину и усмехнулся, будто услышал не угрозу, а особенно занятную  сделку\n\n— Язык, ты мужик складный, спору нет. За один вечер мне больше рассказал, чем некоторые за неделю знакомства. Такое я ценю.\n\nОн чуть подался к огню, спокойно обводя взглядом остальных.\n\n— Только вот три пятых за защиту — это ты лихо загнул. С меня сейчас три пятых возьмёшь — останутся две пятых дырявых штанов да половина окровавленного бинта. Я потому сюда и еле еле дополз раненый на хромых ногах, а не приехал на сундуке с золотом.\n\nЛюпен хмыкнул и посмотрел прямо на Илистада, уже без прежней простоватой улыбки\n\n— Но я и хороших людей забывать не привык. Подскажешь, где работа пожирнее, я ведь и замки ковырять умею и шмыгает по кустам молчком, а деле луком обзаведясь, то такую меткость покажу, челюсть отвиснет.  Если благодаря твоему слову что-то в кармане заведётся, тогда и поговорим о доле. С прибыли платить разумнее, чем с голой задницы.\n\nОн перевёл взгляд на Коршуна, потом на здоровяка и слегка кивнул, словно признавая их старшинство, но не подлизываясь.\n\n— А пока считай, что зелёный услышал старших и дурить у их костра не собирается. Если есть здесь дело, на котором человек с глазами, ушами и тихими руками может оказаться полезнее лопаты — скажите. Может, ещё окажется, что от меня вам больше толку, чем три пятых от нищеты.",142532,null],[164447,"2026-08-17T23:05:48",9,"Бандюган (Илистад) — С Жанкой то, только замки сокровищниц и ковырять. Да три пятх не от того что сейчас, от того что будет — *Вздыхает он, явно хотел бы разбойничним делом занятся, не ценит то что есть.* — Здесь каждый второй тот ещё плут, вот руками работать не каждый умеет, зубрилы помощников ищут. У охотников работёнка не пыльная, только вояк Борода гоняет, тут уж лопатой мохать можно отлынивать тихо, а мечом покоя не дадут. Да гляди ещё за Димой, он парень странный, кто знает что на уме у пришибленного...\n\nБандюган (со шрамом на носу коршун) — Язык, заибал. Завтра допиздитесь. — *Носатому это вкрай надоело и он обратился прямо к Люпену.* — Пиздуй к своим.",164446,null],[164448,"2026-08-17T23:17:26",17,"— Понял. Исчезаю.\n\nКивнул и поплелся назад к костру где сидели Рен, Чиф, Дима и Конрад\n\n\"Значит даже бандюганы боятся жанку. Писари, вояки, охотники и копальщики. Ну да. Так и думал. Вот только не нашел ниодного охотника. Дима вроде их вояк. А мне нужен хоть один охотник... Черт. На охоте то я сгожусь..\"\n\nВ последний раз по пути он решил оглядеться, в поисках кого то с луком или в шкурах или кто дичь разделовал.",142532,null],[164449,"2026-08-17T23:37:25",9,"*На виду ни одного места где точно могли быть охотники. Сидят по грубкам иногда люди с длинными луками, орк, пару полуэльфов, и, она? Он? Девица с белоснежными волосами, или парень не разобрать этих околоэльфов, острый нос, бледная кожа, длинные волосы, страшная немного, но внешность внушает уважение. Сидит фигура совсем одна у самого края, чинит броню, на воина не совсем похожа.*",164448,null],[164450,"2026-08-17T23:37:58",9,"//Знакомый образ не правда ли",142532,null],[164451,"2026-08-17T23:48:35",17,"Люпен от нечего делать к беловолосой решил подойти и поговорить. Простой он мужик, если есть нужна лук отыскать? Будет пытаться пока не выйдет.\n\nПодойдя он обходит сборку чтобы не стоять сзади.\n\nПрочищает горло\n\n— кх кх... Прости. Я залётный новичок тут. Не подскажешь где ж мне найти охотников лагерных. Хотелось бы свои навыки применить на деле. Я стрелок со стажем. А ты выглядишь как охотница... Не серчай если попутал.",142532,null],[164452,"2026-08-17T23:55:02",9,"*Острый взгляд за мгновение оценил тебя с головы до ног. Одно движение и в тебя летит кинджал.*",164451,null],[164454,"2026-08-17T23:55:37",9,"/roll +d20+4 в Люпена внезапно прилетело",142532,null],[164456,"2026-08-17T23:56:23",17,"/ Ну попал",142532,null],[164457,"2026-08-17T23:56:43",17,"/ С преимуществом ещё эх а там бы Крит единичка",142532,null],[164458,"2026-08-17T23:57:58",9,"*Кинджал попал рукоядью тебе в грудь, больно.*\n\nОхотница на монстров — Мёртв, животные не кидают кинджалы, но порвут на части оказавшись достаточно близко.\n\n// 1 дробящего тебе, будет синяк",142532,null],[164459,"2026-08-17T23:59:49",9,"*Голос был на удивление мягкий, скорее женский, но черт разберет этих фей.*\n\nОхотница на монстров — Добыча в палатке поварихи, разделывают и делят там же. Воины охотятся чтобы навыки не заржавели.",142532,null],[164460,"2026-08-18T00:01:12",17,"Люпен тут же прижимается ладони к месту попадания\n\n— Кха... Да... Но на этот случай я быстро ноги удираю, Але прячусь получше. Хороший бросок... Ладно. Спасибо. Я больше не смею беспокоить\n\n\nЛюпен поднимает кинжал и передает охотнице рукоятью в ее сторону держа за лезвие",142532,null],[164461,"2026-08-18T00:04:04",9,"*Молча забирает и возвращается к делу, поправлять ремни на странной кожаной брони. Под слоем кожий можно было заметить кучу пластин что держали форму доспеха, и несколько ужасных следов на ней.*\n\n*Сама ххотница сидела с оголенным животом, и это было неприглядное зрелище, будто рванули правый бок а потом зашили то что осталось и оно кое как зажило.*",164460,null],[164481,"2026-08-18T09:30:22",17,"После этого Люпен вернулся к своим и рассказал всё что узнал от бандюганов и от седой.",142532,null],[164484,"2026-08-18T09:41:45",20,"*Рен задумывается. Интересно какого рода помощников ищут 'зубрилы', стоит узнать подробнее.*\n\n- Чиф, а что за людей ищут два других помощника Жанки?",142532,null],[164485,"2026-08-18T09:50:38",9,"Молодой (Чифтер Люск) — Честно не знаю. — *Он немного смутился и обратился к Люпену.* — Всё что говорит Илистад и я мог расказать, да и Димон нормальный мужик кто бы что не говорил, лишь странный немного. Ты ходил искать охотников чтобы не идти с Димой?",164484,null],[164486,"2026-08-18T09:52:24",17,"Люпен рассказал так, понизив голос чтоб Димка и Чиф не слышали\n\n— Короче. Жанка тут главная, умная и держит весь лагерь в кулаке. Кларк опаснее, чем выглядит, повариху лучше вообще не злить, Борода — местный вояка и гоняет бойцов.\n\n— Сереброзубый — Илистад по кличке Язык. Хотел обложить нас защитой: три пятых с будущего заработка. Если не дать — может начать гадить.\n\n— По работе тут копальщики, вояки, охотники и какие-то зубрилы, которым нужны помощники. Жанке могут пригодиться люди, умеющие вскрывать замки.\n\n— Ещё Язык отдельно сказал присматривать за Димой: мол, странный он и неизвестно, что у него в голове. Ну это я думаю всем и так понятно.\n\n— Охотники добычу тащат к поварихе, там её разделывают и делят. Я бы попробовал либо к охотникам пристроиться, либо к этим зубрилам. Там больше шансов узнать что-нибудь полезное и заработать.",142532,null],[164487,"2026-08-18T09:52:33",17,"/Чуть ранее",142532,null],[164488,"2026-08-18T09:54:34",31,"- зубрилы это кто? Че занимаются? Эту хрень расшифровывают, что из земли выкапывается?",142532,null],[164490,"2026-08-18T10:08:09",9,"//Если вы с Чифом говорите или — пишите что к ним обращаетесь. На всякий",142532,null],[164491,"2026-08-18T10:10:32",31,"//я к Люпену обращался",142532,null],[164492,"2026-08-18T10:17:05",17,"— Ну по кликухе - да. Я не знаю даже кто к ним относится. Рем, попробуй разузнать. Если нужно помочь с чем то, скажи",164488,null],[164493,"2026-08-18T10:17:59",20,"*Пацан кивает*",164492,null],[164494,"2026-08-18T10:19:32",31,"- вообще, нам бы понять, стоит ли тут оставаться? Я за сегодня лопатой намахался до усрачки",142532,null],[164495,"2026-08-18T10:21:08",20,"- Я бы остался на некоторое время. А потом уже как в какой город вернёмся можно отделиться. *Замечает пацан* - Одним без оружия снова через лес опасно идти\n\n- Да и тебе не обязательно только лопатой махать - воины тут тоже есть, можно пойти у ним",142532,null],[164497,"2026-08-18T10:27:58",9,"Жанка — Уже думаете как свалить отсюда? Похвально. — *В вас прилетели спальники, она подошла тихо.* — Не забудьте тогда отдохнуть хорошо, завтра будете батрачить или валите отсюда.\n\n*Жанка не церемонилась, не переубеждала, просто озвучила факт. Пока вы здесь прийлётся работать, отлынивать не выйдет. Ну и держать похоже никто не собирался.*\n\nЖанка — Давайте быстро по вопросу и я пошла на боковую. С остальным разберётесь на месте, вижу вы быстро схватываете.",164495,null],[164498,"2026-08-18T10:29:25",20,"- Какая помощь нужна вашим учёным, босс? *Прямо спрашиет пацан. Если что он и понял с этой женщиной - иногда лучше экономить время*",164497,null],[164499,"2026-08-18T10:32:58",9,"Жанка — Алхимия, свитки, расшифровка старых записей, картография, копирование. — *Она вздохнула, похоже это и правда было проблемой.* — Большинство криворуки не годятся даже переписывать документы. Ещё что-то?",164498,null],[164500,"2026-08-18T10:36:26",31,"- я обучен грамоте, почерк вроде неплохой, если есть место среди ученых, то могу попробовать им помочь\n\n*мысли: поищем следы в бумагах, может пойму что тут копают*",142532,null],[164501,"2026-08-18T10:38:46",9,"*Она пришурила глаз, пытаясь понять нет ли злых намерений у тебя.*",164500,null],[164502,"2026-08-18T10:38:57",9,"/roll 1d20+6 проницательность",142532,null],[164504,"2026-08-18T10:39:16",9,"//Чет заебали жанку, она не сообрадает уже",142532,null],[164505,"2026-08-18T10:40:05",9,"Жанка — Ладно, Кларк завтра покажет куда тебе. Звать то как?",142532,null],[164506,"2026-08-18T10:40:20",31,"- Конрад",164505,null],[164507,"2026-08-18T10:41:54",9,"Жанка — Хорошо, тебя мордастого и пришлю забрать. — *Обращается к остальным.* — Ещё что-то?",142532,null],[164508,"2026-08-18T10:43:07",20,"- Тоже грамоту немного знаю, могу помочь",142532,null],[164509,"2026-08-18T10:47:40",9,"//Щас что Люпен скажет и дальше двинем",142532,null],[164515,"2026-08-18T11:23:36",17,"— Тут безопаснее чем в лесу.\n\nПотом когда подошла Жанка\n\n— Жан, я к охотникам хочу прибиться. Я охотник со стажем. Три года по лесам чалился, да из лука стрелял. Разреши поохотиться завтречка с другими охотниками",164494,null],[164519,"2026-08-18T11:24:44",9,"//Ыыы, димона и Чифа игнорят, но ладно, ваще право)))",142532,null],[164520,"2026-08-18T11:25:52",17,"Чифу он кивнул",164485,null],[164521,"2026-08-18T11:26:00",17,"/ Этот дима мля",142532,null],[164522,"2026-08-18T11:26:03",17,"/ Вы его видали",142532,null],[164523,"2026-08-18T11:26:07",17,"/ Какой из него охотник",142532,null],[164524,"2026-08-18T11:26:11",17,"/ Это палач",142532,null],[164527,"2026-08-18T11:29:01",9,"Жанка — Хорошо, если возьмет кто на охоту — модешь с ними пойти. — *Она кажется была в лучшем настроении чем при первой встрече, да с вами быстро разобралась.* — Отбой, вам завтра рано вставать.\n\n*Она развернулась и уходит, к себе, хоть и в самую большую но видно потасканную временем юрту.*",142532,null],[164528,"2026-08-18T11:29:39",17,"/Бля никто кроме Димы не возьмёт 😭",142532,null],[164529,"2026-08-18T11:30:06",9,"//Уверен?)",164528,null],[164531,"2026-08-18T11:30:34",17,"/ Завтра узнаем",142532,null],[164534,"2026-08-18T11:30:46",9,"Молодой (Чифтер Люск) — Быстро вас опрелелили. Не многие обученны грамоте. — *Видно что завидует, наверное и жалование у ученых тут побольше, и работают не руками.*",142532,null],[164535,"2026-08-18T11:30:49",17,"— Спасибо. Доброй ночи. Сладеньких приторных снов.",142532,null],[164536,"2026-08-18T11:31:49",17,"— Я вот тоже завидую, Чиф. Неуч деревенский. Ну хоть за белками завтра побегаю, а даст бог подстрелю.",164534,null],[164539,"2026-08-18T11:38:19",20,"*Пацан снова садится на прежнее место к костру рядом с Чифом.*\n\n- Надеюсь буду там полезен...*тихо тянет он* - а если жалование неплохое, то и отплатить за доброту вам всем.\n\n*Кажется у пацана слегка странное восприятие долга.*",164534,null],[164540,"2026-08-18T11:39:00",17,"Люпен благодарно кивает Жанке за спальник и укладывается у костра\n\nБыстро засыпает",142532,null],[164541,"2026-08-18T11:39:28",9,"Молодой (Чифтер Люск) — Если не хочешь с Димоном идти, спроси кого нибудь ещё. — *Чиф стелит спальник себе на досках.* — С Димоном безопаснее, он медведю череп открутит голыми руками. Паскаль, полуфей с крепкими руками, тоже принимает в пару часто, но он любит ленится, так что возьмет лишь если большая часть твоей добычи защитается ему. — *Помолчал немного и добавил:* — Есть еще бледная воительница, она странная, если настоять — возьмет. Но помогать в охоте не её стиль, можно остаться в зубах у монстра если не сможешь за ней поспевать.",164536,null],[164542,"2026-08-18T11:41:14",9,"Молодой (Чифтер Люск) — Не переживай парень. — *Он лишь усмехнулся.* — Я зелье у Жанки попросил, сказал что для тебя, дала одно без лишниз вопросов.",164539,null],[164543,"2026-08-18T11:41:17",17,"— От как оно. Дима, возьми с собой меня, я тебе пригожусь.",164541,null],[164545,"2026-08-18T11:41:55",9,"//Всё же палач?)",164543,null],[164547,"2026-08-18T11:43:31",17,"/ Да судя по драке с зомби, мне нужен танк который держит монстра на себе, чтобы я мог прятаться и шмалять из кустов с преимуществом",142532,null],[164549,"2026-08-18T11:46:50",17,"/ Такс я сплю, готов скипать ночку",142532,null],[164550,"2026-08-18T11:47:24",27,"// У вас тут Майнкрафт?",164549,null],[164551,"2026-08-18T11:47:33",31,"Тоже отваливаюсь спать/",142532,null],[164552,"2026-08-18T11:47:40",31,"Походу)/",164550,null],[164554,"2026-08-18T11:48:22",20,"*Пацан устраивается в спальник вслед за остальными*",142532,null],[164556,"2026-08-18T11:48:35",20,"/готов скипать",142532,null],[164557,"2026-08-18T11:48:58",9,"//Хех, начинается только \"третий\" день в игре.",142532,null],[164558,"2026-08-18T11:57:59",6,"//в днд это можно устроить, в классике есть крипер",164550,null],[164561,"2026-08-18T11:59:32",17,"/ Да, хардкорная песочница, персы обыватели",164550,null],[164562,"2026-08-18T12:00:08",17,"/ Крафтим из простыни + палка + моча = способ побега",142532,null],[164569,"2026-08-18T13:39:00",9,"*Ночь уходила, уходили звёзды и небо снова затянуло Димкой дымкой. Разбудил не первый луч солнца, солнечные зайчики не достигали земли, не пение птиц, а шум, лагерь начинал жить. Выкрики, всем раздавади баланду, посиделки и от у костра это развлечение на вечер.*\n\nМолодой (Чифтер Люск) — Эй, пора. Пока еду раздают надо успеть, всё что остаётся после семи отдают троллю. — *Чиф будит тех их вас кто не проснулся соазу.*\n\n*Димона нет рядом, скорей всего уже занял очередь. За вами еще не пришли, наверное рано ещё.*",142532,null],[164570,"2026-08-18T13:39:37",9,"//Надебсь вы записываете опыт и атаете персов",142532,null],[164571,"2026-08-18T13:42:34",31,"Я пишу/",164570,null],[164572,"2026-08-18T13:44:56",17,"Люпен вскочил как ошпареный и подхватив пращу и мешок с камнями побежал за Чифом к месту раздачи хавчика",164569,null],[164573,"2026-08-18T13:46:18",20,"*Пацан зевает, вылезая и аккуратно по привычке расправляя и складывая спальник. Потом опомнился, сложил чуть более неаккуратно и поспешил за старшими*",142532,null],[164574,"2026-08-18T13:49:47",31,"Конрад тоже проснулся. Спал в неудобной позе, но отдохнул хорошо, плотный ужин это лучшая подушка",142532,null],[164575,"2026-08-18T13:57:55",17,"Пока бежим на место раздачи обращаюсь к Чифу\n\n— Слушай, Чиф. У меня праща есть худая. Ты мне можешь помочь её выправить?",142532,null],[164576,"2026-08-18T13:58:09",17,"— Я тебе за это рыбацких снастей дам.",142532,null],[164697,"2026-08-18T18:25:32",9,"Молодой (Чифтер Люск) — Праща? С ней ты охотился? — *Он был немного удивлён, хотя и правда, что с тобой, пару палок торчит.* — Раз с Димой пойдёшь, я попрошу лук, короткий хотя бы, стрел немного. Только не потеряй, а то по шапке и мне и теье надают.\n\n*Небольшая очередь быстро продвигалась к нескольким котлам, пахло неплохо. С двумя головорезами, еду раздавала ведьма, вот как пить дать, черноеплатье, одерелье из костей, есть в ней какой-то шарм, та самая повариха наверное. Чиф занял место в самом конце.*\n\nМолодой (Чифтер Люск) — Дима наверное встал раньше всех, плохо спит бедняга, нужно будет его найти. — *Выглядывал своего знакомого, в очереди тот уже не стоял.*",164575,null],[164698,"2026-08-18T18:27:34",31,"Оглядываюсь в поисках своего провожатого к умникам",142532,null],[164699,"2026-08-18T18:30:07",17,"— Если мне лук доверят. Я бы хотел сделать из этих вот палок, нашел отличную древесину, мне бы тетиву добрую.",164697,null],[164700,"2026-08-18T18:30:09",9,"*Полурослика не видно пока. Очередь сдвигается в темпе, постояли от силы минуту, а уже оказались где-то в середине, хотя людей не так уж и много в лагере. За вами уже стоят работяги.*",164698,null],[164703,"2026-08-18T18:31:54",9,"Молодой (Чифтер Люск) — Плохо разбираюсь в луках, можно поглядеть? — *Ему интересно взглянуть на палки которые ты считаешь подходящими для лука.*",164699,null],[164704,"2026-08-18T18:32:44",17,"— Вот, отлично гнётся и прочность отличная\n\nПоказывает ровные сучки",164703,null],[164705,"2026-08-18T18:34:49",9,"*Сучки скрутились как змеи за ночь, местами высохли и стали твёрже.*\n\nМолодой (Чифтер Люск) — Ну, может тебе виднее, я не охотник. — *Он взял одну из них, слегка согнул, с трудом, прочность и гибкость те сохранили, а вот форму, не очень. Палку тебе вернули.*",164704,null],[164706,"2026-08-18T18:35:21",17,"— Точно тебе говорю, отличное плечо для короткого лука",142532,null],[164708,"2026-08-18T18:37:21",9,"Молодой (Чифтер Люск) — Верю верю. А вот и наша еда. — *Он не понимает чем тебе кривые палки на лук похожи, но не говорит ничего против. А так за ночь их и правда покарёжило мама не горюй.*",164706,null],[164709,"2026-08-18T18:38:54",9,"Головорез — Как пожрёте — миски вернуть. — *Недобро взглянул лысыл повар в колпаке с оплавленным лицом когда насыпал жрачку.*",142532,null],[164711,"2026-08-18T18:40:08",17,"Люпен благодарно кивает и Чифу за еду и повару",142532,null],[164712,"2026-08-18T18:40:13",31,"- хорошо, шеф",164709,null],[164716,"2026-08-18T18:43:06",9,"*Чиф далеко не уходил, сел рядом поесть, побыстрому.*\n\nМолодой (Чифтер Люск) — Надо будет поискать Диму, надеюсь он все еще в лагере, а не уже пошел охотится. Простите, не уследил. С его бессонницей нужно было догадаться что встанет пораньше.",142532,null],[164717,"2026-08-18T18:43:45",17,"— Эх, да, лучше мне поспешить, без Димы я точно в лесу сам добычей стану\n\nЛюпен ускоряется поедая завтрак",164716,null],[164718,"2026-08-18T18:45:42",9,"// @PaIIasCat @QURTZZ вы как там, баланду уплетаете?)",142532,null],[164719,"2026-08-18T18:46:07",20,"/естественно",164718,null],[164720,"2026-08-18T18:46:11",31,"Я вроде даже повару ответил на его приказ вернуть тарелку/",164718,null],[164728,"2026-08-18T18:50:28",31,"Раз провожатого нет, позволяю себе роскошь есть не спеша, смакую каждую ложку. Да, это не сырая тифозная крыса",142532,null],[164733,"2026-08-18T18:51:47",20,"*Пацан есть, поглядывая по сторонам. Смотря на какие группы кто разбивается, кто куда идёт.*",142532,null],[164737,"2026-08-18T18:54:11",9,"*Парни с луками попарно куда-то уходят в разные стороны. Большая часть разбирает инвентарь готовясь к раскопкам руин. Мимо трусцой пробежали несколько человек в шумящих бригантиназ, они старались двигать так чтобы не шуметь, на одних носочках, уже запыхавшийся, скоре всего те самые вояки.*",164733,null],[164738,"2026-08-18T18:54:47",9,"*Чиф быстро прикончил свою часть и взял у Люпена миску, быстрее чтобы за раз отнести.*\n\nМолодой (Чифтер Люск) — Люпен, мы пойдём по лагерю обойдем, Ищем Димку. За твоими друзьями должен прийти Кларк, если не забыл о них.\n\nПолурослик (кларк) — Не забыл, ждал пока вы поедите. — *Голос раздался сверху с уцелевшей стены, он похоже втихаря ждал там все это время. Ловкими акробатическими движениями спустился прямо со стены. Хмыкнул, он поел и жердал пустую посуду.* — Но вижу вы не спешите.",142532,null],[164742,"2026-08-18T18:55:33",31,"Обращаюсь к Рену:\n\n- на удивление неплохо организован лагерь и дисциплина в нём, особенно для невоенных. Дум, кто то из руководителей этого бедлама как минимум был сержантом в решудряной армии",142532,null],[164743,"2026-08-18T18:56:16",17,"— Да. Ты слева обходи, я справа если найдем его встреча здесь?",164738,null],[164744,"2026-08-18T18:56:54",31,"- кто понял жизнь, тот не спешит. Раз никто не гонит, то и торопится не сдудеут, в тт вдруг ещё куда то не туда успеешь.\n\nОтдаю чашку повару и не забываю сказать спасибо",164738,null],[164745,"2026-08-18T18:56:54",20,"*Рен припоминает про ветерана Бороду, о котором рассказывал Люпин. Скорее всего так*",164742,null],[164751,"2026-08-18T18:58:29",20,"*Следуя примеру Конрада пацан тоже относит посуду и теперь с любопытством смотрит на полурослика*",142532,null],[164757,"2026-08-18T19:00:38",9,"Молодой (Чифтер Люск) — Да, давай быстрее, надеюсь мы не поздно спозватились. — *В темпе идет искать.*",164743,null],[164763,"2026-08-18T19:03:36",17,"Люпен бегом а другую сторону побежал",164757,null],[164765,"2026-08-18T19:04:01",17,"/r +1 Внимание в поисках Димки",142532,null],[164771,"2026-08-18T19:06:54",9,"Полурослик (кларк) — Собрались уже? — *Он скучающе вертел в руках кинджал, острейший клинок переливающийся синим, наверное тот ещё и зачарован.* — Тогда двинули.\n\n*Он повел вас в пристройку за шатрами, писарям отгрохали целый дом. На столах куча заметок, какие то камни с рунами, доски надписи, графики, пару столов с перьями, куча макулатуры и оуолооккультных, на вид магических, безделушек. Даже несколько отдельных комнат, через одну, что открыта, видно что там местечко для алхимика.*\n\nПолурослик (кларк) — Так, умники как всегда не спешат. Подождите их здесь и ничего не трогайте. — *Он взглянул на единственную фигуру здесь, парня спящего прямо под одном из столов, неудобрительно цыкнул и удалился.*",164744,null],[164774,"2026-08-18T19:07:38",9,"*Парень спящий прямо в домике ученых лагеря наемников.*",142532,null],[164788,"2026-08-18T19:11:49",31,"/roll d20+1 на магию. Сгребаю остатки образования, пытаюсь понять что в этом наборе хлама может представлять ценность и для чего используется",142532,null],[164793,"2026-08-18T19:13:10",9,"*Это место напоминает творческий хаос, чего только не навешаннос пройти без труда можно лишь только у самого входа. В этом хламе можно утонуть а тропинками меж ними и куда станет нога наверное можно заблудится.*",142532,null],[164799,"2026-08-18T19:14:38",9,"*О магии тут, добрая четверть. Есть много чертежей и разработок, несколько вещей что выглядит как волшебные палочки, но подержанные или основном сломанные. Работающие магические предметы скорее в обиходе.*",164789,null],[164805,"2026-08-18T19:15:19",31,"- бытовые артефакты? Они тут башню волшебника, жившего до большого пиздеца раскапывают?",142532,null],[164807,"2026-08-18T19:15:27",9,"*Спящий парень спит в обнимку с какой-то бутылкой от которой за метр несет крепким, свежим кофе.*",164774,null],[164808,"2026-08-18T19:15:30",20,"*Пацан оглядывается с любопытством вокруг. Магию он знает не так хорошо, но эта обстановка почему-то навевает большее спокойствие, чем шумный лагерь за его приделами. Приятно снова увидет, ну...бумагу, записи и прочее*",142532,null],[164809,"2026-08-18T19:15:46",20,"/о, бутылка бесконечного кофе",164807,null],[164811,"2026-08-18T19:16:32",20,"- Ты разбираешься в магии? *Спрашивает Рен*",164805,null],[164814,"2026-08-18T19:17:13",9,"*Вам на глаза попадаются две сферы на которых спиралью расписанны руны, от вершины до вершины. Они лежат у входа и на них еще свежая земля.*",142532,null],[164815,"2026-08-18T19:17:16",31,"- общий курс проходил, не более того. Колдовать не умею, но кое какая теория в голове ксть, что вбили учителя",164811,null],[164817,"2026-08-18T19:17:57",31,"- ты бы и сам глянул, если кчть дар, то шансов что поймешь больше чему теоретика без дарв",142532,null],[164819,"2026-08-18T19:18:50",31,"- о, что то свежее и видимо еще не осмотренное местными",164814,null],[164820,"2026-08-18T19:19:09",31,"/roll d20+1 на анализ этих сфер",142532,null],[164823,"2026-08-18T19:19:54",20,"/r d20+2 Рен тоже оглядывается, но не на магию, а на историю. Интересно понять к какой эпохи принадлежать эти руины и сферы",164817,null],[164833,"2026-08-18T19:26:28",9,"*Определённые вещи явно старше нового календаря второго сотворения мира, возможно даже сделанны недавно. Вряд-ли большая часть вещей и вовсе отсюда, но этому месту не менее трёхсот лет, а то и старше, так что те каменные сферы с рунами и некоторый другой старый хлам скорей всего застал начало календаря.*",164824,null],[164854,"2026-08-18T19:37:09",31,"- ладно, хватит ковырять старый хлам бесцельно, давай разбудим этого местного обитателя",142532,null],[164856,"2026-08-18T19:37:48",31,"Подходу к спящему в обнимку с бутылкой парню и легонько трясу за плечо\n\n-. Просыпайся, новый день пришёл",142532,null],[164862,"2026-08-18T19:39:27",9,"Белобрысый ученый — Аааа, что случиловьсь... — *Он с трудом разодрал глаза и не узнал тебя.* — Кто, что.",164856,null],[164864,"2026-08-18T19:41:13",9,"*Вообще сонный и невыспанный, он искренне не мог втулить что происходит и собрать мысли в кучу. Ты видишь что всё настолько плохо что не факт что тот запомнит будил ли ты его если не разбудить его окончательно.*",142532,null],[164865,"2026-08-18T19:42:51",31,"- подъём, боец книжного фронта. Доложи обстановку!",142532,null],[164866,"2026-08-18T19:43:37",20,"*Рен любопытно выглядывает из-за плеча старшего*\n\n*Интересный у Конрада подход к коммуникации. Нужно запомнить*",142532,null],[164868,"2026-08-18T19:44:31",9,"/roll 1d20+4 интеллект, чистая проверка",142532,null],[164871,"2026-08-18T19:47:13",9,"*Парень кажется понял что происходит, и по заспанном недовольном лице было ясно что он хотел бы выспаться. Достав из рукава волшебную палочку он указал ею на Конрада, кончиком уперев в самый подбородок раз тот так близко к нему подошел. Малейшая угроза и он ею воспользуется.*\n\nБелобрысый ученый — Кто ты. И какого чёрта ты здесь шумишь...",142532,null],[164872,"2026-08-18T19:49:02",31,"- я Конрад, это Рен. Мы новенькие и нас направили сюда для работы. А кроме тебя тут нет никого. И что нас делать? Рядом лечь поспать, иди тебя веером обмахивать, чтобы мухи не садились?",142532,null],[164875,"2026-08-18T19:51:48",9,"Белобрысый ученый — Дождитесь других, я не хочу возиться с вами. — *Он чуть внимательнее на вас взглянул, привстав из своей лежанки. Его лицо было все такой же каменной презрительной маской, он смотрел на вас с высока.*\n\n//Опишите что он видит)",142532,null],[164876,"2026-08-18T19:52:29",9,"//Работа мечты, мохать веером и мух гонять 😏👌",164872,null],[164879,"2026-08-18T19:53:52",31,"Высокий жилистый парень в обносках монаха, подпоясанный веревкой из старой простыни и с кривой рапирой за этим поясом. Смотрит на белобрысого без страха, ибо нехер двоярнигу, даже в обносках, бояться какого то хера с горы, что палочкой угрожает",142532,null],[164883,"2026-08-18T19:55:20",9,"//Шучу",142532,null],[164884,"2026-08-18T19:55:38",20,"*Из-за спины монаха выглядывает худой пацан лет тринадцати в обносках. Смотрит внимательно, с явным любопытством.*",142532,null],[164885,"2026-08-18T19:56:06",31,"Гу я первым делом сам планировал ловкостью рук палочку вырвать и сломать об колено, но сдержался/",164883,null],[164888,"2026-08-18T20:00:39",9,"Белобрысый ученый — Не видел вас раньше. — *Он сидит и явно пытается собрать мысли в кучу, пьёт кофе, словно это его спасительная панацея, а потомо встаёт и отряхивается пряча руки в рукава, на мгновение задерживает взгляд на Рене, а точнее, на его глазах, обращается прямо к нему:* — Ты чародей или колдун.",142532,null],[164890,"2026-08-18T20:02:07",20,"- А в чем отличие? *Пацан прищуривается, слегка лукаво*",164888,null],[164892,"2026-08-18T20:05:56",9,"Белобрысый ученый — Колдун пользуется чужой силой. Чародей наследует свою с рождения. — *Он делает легкий пас, жест, бормочет что-то под нос и зажигает крохотную свечу на кончике пальцев.* — Магия, пределы, наследование. Разница огромная, даже если ты её не осознаёшь.\n\n*Он убирает огонёк и неспешно плывет через горы хлама к одному из столов. Делает это естественно, словно дома, хотя он тут наверное и живёт.*",164890,null],[164896,"2026-08-18T20:07:38",31,"- я не эксперт в магии, но сомневаюсь что Рен колдун, ну только если он не очень крутой актёр. Ставлю на чародея, ну или может дикого волшебника, которому надо учится",142532,null],[164902,"2026-08-18T20:08:56",20,"- Хм...думаю я просто Рен *пожимает плечами пацан. Похоже ответа у него нет. Или он скорее в нем не уверен*\n- Не замечал за собой ни наследства, ни покровителей \n\n- А ты сам? Чародей?",142532,null],[164905,"2026-08-18T20:13:09",9,"Белобрысый ученый — Я спрашивал не тебя. — *Он отмахнулся от Конрада и дошел к столу слушая что говорит Рен пока смешивал несколько жидкостей в ёмкости.* — Талант у обычных смертных строго ограничен, их предел третий круг магии на пике, ценой пота и крови, лет изучения и практики. У меня самого нет таланта, но я не колдун, тем более, чародей, не жрец и даже не имею связью с природой и таинствами как другие... В некотором роде силу достаточно компенсировать знаниями и предметами.",164896,null],[164910,"2026-08-18T20:17:58",20,"*Кажется слова о силе и знаниях зацепили Рена. Он подходит чуть ближе, остановившись на некоторой дистанции, не мешая но и наблюдая*\n\n- Сила полученная трудом и знаниями... Звучит надёжнее. Как клинок, который ты учишься держать, а не неуправляемое пламя. Ты учишься этому здесь?",164905,null],[164913,"2026-08-18T20:18:42",20,"*Про предметы он даже не спрашивает, и так их видет повсюду*",142532,null],[164927,"2026-08-18T20:51:57",9,"Белобрысый ученый — Не правда, без таланта легко упереться в потолок. — *Он нашел порошок, добавил в воду, та вскипела и запузырилась.* — Талант всегда важен и его не сдвинуть знаниями, а способов расширить свои физические возможности... они чаще приводят к нежелательным последствиям. Как бы небыло прискорбно, самые сильные волшебники, те кто добывает силу знаниями, растут из чародеев которые ещё не привыкли использовать магию интуитивно.",142532,null],[164942,"2026-08-18T21:12:21",20,"- Вот оно что. *Рен задумывается. Похоже в магии все так же, как и в обычной жизни. Как же там говорил дед...20 процентов таланта и 80 усилий? Плохо, что если именно этой искры ему и не достает...*\n- Интересно как понять есть этот талант или нет... \n\n*Нужно обязательно здесь задержаться, слишком много у него вопросов без ответов. Он встряхивает головой, возвращаясь к главной теме.*\n\n- Ну, даже будь мы обладателями этой магической искры, прислали нас двоих сюда увы не за этим. Какая помощь тут будет нужна от нас?\n\n*Потом вспоминает ещё что-то. Они представились, а вот сам парень нет*\n\n- Ох, и как к тебе обращаться?",164927,null],[164943,"2026-08-18T21:26:35",9,"Белобрысый ученый (Лазарь) — Лазарь, называй так. Настоящее имя имеет вес и силу. — *Он поворачивается к тебе с склянкой содержимое в ней напоминает пузырящуюся воду.* — Твои глаза, они необычные. Такие особенности часто появляются у тех кто имеет наследие, хочу проверить. Имея талант ты не будешь работать писарем. — *Он протягивает тебе склянку.* — Мало способов узнать о таланте до того как он проявится, но есть грубый, можно сказать варварский способ заставить его пробудиться. Это зелье не имеет долгоиграющих последствий, но, будет очень плохо, но если у тебя есть наследие, первые его признаки появятся вскоре после того как прийдёшь в себя, есть шанс умереть в процессе, небольшой. Если конечно тебе не симпатизирует больше роль мальчика на побегушках что будет таскать документы.\n\n*Шанс и риск, подробно обьяснив что тебе предлагает, Лазарь поставил Рена перед выбором.*",164942,null],[164944,"2026-08-18T21:32:15",20,"*Рен берет склянку, молча смотря на нее, разрываясь между холодным расчетом и,ну...страхом ребенка которым как бы он не хотел но все ещё остаётся*\n\n-...и насколько велик этот шанс? *Спрашивает он, взвешивая риск*\n\n/вот это выбор конечно 🫪",164943,null],[164945,"2026-08-18T21:33:47",20,"/будем надеяться так какой-то лорный трип, а не просто спасброски от смерти",142532,null],[164946,"2026-08-18T21:33:53",9,"Белобрысый ученый (Лазарь) — Одна из дюжины мышей умирает.",164944,null],[164949,"2026-08-18T21:40:59",20,"*Посидев несколько минут молча, Рен всё-таки выдыхает, собираясь с силами*\n\n*Шаг этот довольно рискованный, но если есть шанс выяснить, есть ли у него магия... Это может стоить того.*\n\n- Это испытание для тела или ума? \n\n/Пытается понять, как лучше себя подготовить к этому",142532,null],[164950,"2026-08-18T21:45:06",9,"Белобрысый ученый (Лазарь) — Для тела — точно. Для ума? Может, у меня небыло у кого спросить что он видел. Рецепт из нескольких надёжных источников, мне не дают экспериментировать на людях, так что на твой страх и риск, Рен. — *Лазарь внимательно смотрит за твоим поведением, странно спокойный, ощущение что ему плевать если ты умрёшь.*",142532,null],[164955,"2026-08-18T21:47:04",20,"/r d20+2 на проницательность, почему бы и нет",142532,null],[164958,"2026-08-18T21:48:47",9,"//Ты хочешь что-то конкретное высмотреть или то не лжёт ли он? Тли на самом деле ли ему плевать?)",164956,null],[164962,"2026-08-18T21:49:38",20,"/да, насчёт ситуации с зельем - насколько вообще все это правдиво",164958,null],[164965,"2026-08-18T21:49:58",20,"/и не утаивает ли он что-то",142532,null],[164971,"2026-08-18T21:50:49",20,"/то что ему плевать я чёт вообще не сомневаюсь)",142532,null],[164972,"2026-08-18T21:50:54",9,"*Всё что он говорит логично, последовательно и похоже на правду. При этом кажется ему не совсем плевать.*",142532,null],[164975,"2026-08-18T21:51:18",20,"/окак",164972,null],[164978,"2026-08-18T21:52:13",20,"/ну ладно, погнали)\n/Это конечно будет самая глупая смерть персонажа если что-то пойдет не так. Все ради лора",142532,null],[164979,"2026-08-18T21:52:34",9,"// Лора?)",142532,null],[164981,"2026-08-18T21:53:36",20,"/ну может хоте немного узнаю что за фигня с этими глазами 👀",164979,null],[164982,"2026-08-18T21:54:05",9,"//Технически, я бы конрада подождал, может он запретит тебе пить всякую гадость)))",142532,null],[164983,"2026-08-18T21:54:36",20,"/ну ладно, тогда ждём до завтра",164982,null],[165142,"2026-08-19T02:50:22",31,"- секунду. При всем уважении, пить не пойми что не пойми из чьих рук это не самая хорошая идея, Рен. Лазарь, ты вроде по мышей говорил? Ечть у тебя парочка может, чтобы им по капкльке дать, чтобы проверить, сдохнут они или нет, или можктк еще что то с ними случится?",142532,null],[165143,"2026-08-19T07:32:49",9,"Белобрысый ученый (Лазарь) — Давно ищу ученика. Надеяться на удачу тратя месяцы или годы в обучение того кто не сможет зажечь свечи? — *Маг больше не стал ждать ни ответов ни возражений. Он просто закрыл пузырящееся прозрачное зелье пробкой и оставил на столе, на самом видном месте.* — Вы вряд-ли поможете в моих изысканиях. Вижу археологи принесли несколько новых предметов, но они в грязи, эти лентяи их даже не помыли, вынесите их наружу и очистите от грязи, остальные думаю прийдут к этому времени.\n\n*Лазарь показал вам на несколько шарообразных намней у входа исписанных рунами, которые недавно принесли, вместе с парой небольших скрижалей. Он взял книгу с потёртой обложкой и занял кресло у своего стола, решил заняться чтением.*",165142,null],[165144,"2026-08-19T07:34:01",31,"Обломали Рена с учёбой/",142532,null],[165145,"2026-08-19T07:37:30",9,"//Ну, может да а может и нет. Как всегда очевидные вещи не слишком очевидны, эх(",165144,null],[165146,"2026-08-19T09:08:43",9,"*Димки нет, ни за углом, ни за стеной, ни с кажется вояками? А ещё на тебя подозрительно смотрят остальные, все же многие не видели Люпена раньше, если и знают то только то что прибыл вчера.*\n\nОхотница на монстров — Почему здесь рыщешь. — *Из-за угла выходит та сама онотница что метнула в тебя кинджал, подсекла и ловко вынырнула перед Люпеном. Она по доброму улыбнулась, наклонила голову, волосы и косы мягко качнулись перед ней, словно не собиралась говорить следующие слова.* — С предателей и шпионов снимаю кожу. — *Она подошла ближе, вторгаясь в личное пространство и провела обратной стороной слегка когтистого пальца по щеке Люпена, так близко к шее.* — Медленно, начиная с пят... говори что здесь вынюхиваешь...",164763,null],[165147,"2026-08-19T09:09:02",9,"/roll 1d20 запугивание Люпена",165146,null],[165149,"2026-08-19T09:12:05",9,"// Остальных тоже жду, постараюсь паралельно",142532,null],[165150,"2026-08-19T09:13:06",17,"Люпен побледнел\n\n— Я... Ищу Диму, он обещал взять меня на охоту.",165146,null],[165151,"2026-08-19T09:13:28",17,"женщина пугала его до усрачки",142532,null],[165152,"2026-08-19T09:15:39",20,"/да думаю лучше отдать спотлайты пока одному, чтоб не путаться. Люпин заслужил",165149,null],[165153,"2026-08-19T09:17:52",17,"/Мне работать надо)))",142532,null],[165154,"2026-08-19T09:17:56",17,"/Играйте",142532,null],[165155,"2026-08-19T09:18:41",9,"Охотница на монстров — Да? — *Она убрала палец от шеи и немного отошла от тебя. Чувство опасности и угрозы исчезло, но не внимательный взгляд острых глаз.* — Он ушёл некоторое время назад в лес, сразу как поел. Прийдётся тебе работать руками, \"охотник\". — *Последнее слово она выделила, словно полностью сомневалась в твоих способностях вести выслеживание, взять монстра измором, выследить... звучало как насмешка.*",165150,null],[165156,"2026-08-19T09:19:19",17,"— Придётся. Могу ли я взять лук и немного стрел?",165155,null],[165157,"2026-08-19T09:19:51",17,"Люпен поднялся с земли почесывая пятую точку, куда больно упал после подсечки",142532,null],[165158,"2026-08-19T09:26:24",9,"*Брови слегка взлетели вверх, она сочла это за наглость...*\n\nОхотница на монстров — Настоящий охотник сам находит себе лук и следит за ним. — *Видна насмешка в её глазах, кажется её мнение о собеседнике упало ещё сильнее.* — Просишь, видишь у меня есть запасной кибить?",165156,null],[165159,"2026-08-19T09:28:31",9,"*Наглядно стала у стены, словно открывая снаряжение на себе к обзору. За спиной было лишь единственное, длинные древко без натянутой тетивы, угадывались плечи длинного лука.*",165158,null],[165160,"2026-08-19T09:33:39",17,"— И то верно. Что ж, пока не заслужил. Пойду быстрее за Димой с тем что есть, куда он уходил утром?",165158,null],[165167,"2026-08-19T09:40:28",9,"*Она показывает в сторону леса, почти не глядя.*\n\nОхотница на монстров — Туда. — *С усмешкой добавила:* — Удачи, \"охотник\".",165160,null],[165168,"2026-08-19T09:43:48",17,"Кивнул и Люпен побежал. На ходу он закинул в пращу камень, чтобы быть готовым к встрече, хоть с медведем, хоть с чертом лысым",142532,null],[165169,"2026-08-19T09:44:36",9,"//Лишь бы не с женщиной)",165168,null],[165170,"2026-08-19T09:45:03",17,"/ Ой эта ведьмачка слишком высокомерная))",142532,null],[165171,"2026-08-19T09:49:06",9,"//Внимательность, сл 12",165170,null],[165172,"2026-08-19T09:55:38",17,"/r +1 Внимание пошло жесткое",142532,null],[165174,"2026-08-19T09:56:21",17,"\"Кричать в лесу нельзя, Дима не одобрит, всю дич распугаю. Надо найти егос леды, он такой здоровый и тяжелый, будто медведь\"",142532,null],[165175,"2026-08-19T09:56:29",17,"/r +2 Выживание еще на поиск следов",142532,null],[165177,"2026-08-19T10:17:19",9,"*Ты видишь зарубки на деревьях, так охотники и сборщики с разведчиками показывают кто куда ходит, где разведанно, куда не ходить что не делать. Следов много, есть натоптанные тропы, по каким шёл Дима не разобрать. Перед тобой по тропе идут пару сборщиков с пустыми мешками и корзинами, на поясах пращи, у каждого за спиной копья и шест, направляются поглубже, на окраинах вряд-ли что-то остальсь.*",165173,null],[165178,"2026-08-19T10:20:17",17,"Нырнув в лес Люпен вспомнил о мертвеце, который его суть было не сожрал и нервно сглотнул\n\n\"Места тут гиблые, нужно быстрее искать здоровяка. Интересно он в детсве упал на голову или почему такой говор странный, нихрена не понятно\"",142532,null],[165179,"2026-08-19T10:20:52",17,"— Здарова. Ищу Диму, здоровый такой вояка. Видали его?",165177,null],[165281,"2026-08-19T14:34:32",9,"*Двое переглянулись, наверное не могли тебя припомнить.*\n\n— Диму не видели. Чей ты?\n\n— Звать то как. Не видел раньше\n\n*Эта парочка наёмников выглядили совсем не примечательно, хотя нет, они словно на одно лицо, близнецы? Даже договаривали друг за другом. Только снаряжение немного разное.*",165179,null],[165282,"2026-08-19T14:35:25",17,"— Люпен я, новенький охотник.\n\nМахает рукой \"Ай некогда мне\"\n\n— Ладно побегу, некогда мне лясы точить, извиняйте.",165281,null],[165283,"2026-08-19T14:35:39",17,"Побежал туда где меньше утоптано",142532,null],[165284,"2026-08-19T14:35:51",17,"/r +2 Ищу большие глубокие следы сапог Дмитрия",142532,null],[165287,"2026-08-19T14:39:08",9,"*Двоя переглянулись провожая тебя взглядом, больше ничего не сказали.*",142532,null],[165288,"2026-08-19T14:40:32",9,"*Ты нашёл нечто что напоминало большие следы в траве, после длинного получасового забега по окрестностям, здесь даже метки охотников — редкость, и ведёт оно в низину, вглубь леса.*",165285,null],[165296,"2026-08-19T15:29:08",9,"// @QURTZZ @PaIIasCat у вас тоже нет времени играть как и у Николая? Если вас смущает что мы в 1 теме, могу разделить. Для меня эт просто норма, раньше 4 игры вел в одной теме, было)",142532,null],[165298,"2026-08-19T15:31:35",31,"Я вполне доступен на ближайшие 2-3 часа/",142532,null],[165299,"2026-08-19T15:34:48",20,"/я тоже",142532,null],[165300,"2026-08-19T15:35:16",9,"//.",165143,null],[165301,"2026-08-19T15:36:17",20,"- Можешь вытащить их? *Обращается пацан к Конраду* - Я пока поищу чем их можно протереть",142532,null],[165302,"2026-08-19T15:37:19",31,"- конечно\n\nВытаскиваю каменюги на улицу",165301,null],[165303,"2026-08-19T15:37:33",31,"Кстати, зелье все еще на столе и ты можешь его бахнуть/",165301,null],[165304,"2026-08-19T15:37:55",20,"/а ты думаешь зачем он тебя на улицу выманивает",165303,null],[165305,"2026-08-19T15:38:14",31,"//к-коварство",165304,null],[165307,"2026-08-19T15:39:50",20,"*Рен ждёт несколько секунд, пока Конрад скрывается со сферой на улице*\n\n*Потом быстро подходит к столу, беря колбу и откупоривая ее. В бездну сомнения и страх*\n\n*И делает глоток*",165302,null],[165308,"2026-08-19T15:40:48",31,"Так и помер дед Максим/",142532,null],[165309,"2026-08-19T15:41:19",20,"/ну надеюсь вы вдвоем если что затащите)",142532,null],[165315,"2026-08-19T15:51:18",9,"//Чисто ради интереса, го шесть проверок телосложения подряд 😏👌",165307,null],[165316,"2026-08-19T15:51:57",31,"Кабзда котенку, гадить не будет больше//",142532,null],[165317,"2026-08-19T15:52:17",20,"/r d20",142532,null],[165324,"2026-08-19T15:53:03",20,"/это программа сдохни или умри",142532,null],[165325,"2026-08-19T15:57:34",9,"*Руки и ноги не держат, тебе становится все хуже. И когда уже хотел упасть чьи то руки тебя поддержали и не дали упасть. Кровь будто кипела, голова раскалывалась и хотелось просто закрыть глаза и помереть.*\n\nБелобрысый ученый (Лазарь) — Постарайся заснуть, так будет легче. — *Это именно он подхватил Рена и хоть был слаб подтащил к своей лежанке и оставил там. Это был ужас, перед глазами все плыло, но вскоре стало полегче, резкий запах успокаивающих трав. Лазарь оставил благовония рядом, похоже, они немного приглушали боль.*",142532,null],[165326,"2026-08-19T15:58:29",9,"*Прошло несколько минут, а от Рена ни слуху ни духу снаружи.*\n\n// @QURTZZ",142532,null],[165327,"2026-08-19T15:58:47",9,"// Запиши Рену 4 уровня истощения @PaIIasCat две проверки он прошёл и не помер)",142532,null],[165328,"2026-08-19T15:59:10",31,"Я захожу в какой момент, когда он упал, когда его тащат или когда уже отдыхает?/",142532,null],[165329,"2026-08-19T16:00:44",9,"*Когда зашёл видишь как Лазарь ставит благовония возле своей лежанки, в ней лежит скрученный в поще эмбриона Рен, бесь бледный, вены под кодей пульсируют и обильно потеет. На столе пустая колба.*",165328,null],[165330,"2026-08-19T16:01:14",31,"- эй, какого хрена, ты что с пацаном сделал?!",142532,null],[165331,"2026-08-19T16:04:38",9,"*Он бросил на тебя взгляд и вернулся к установке благовоний.*\n\nБелобрысый ученый (Лазарь) — Рен сам подошёл и выпил зелье, как думаешь зачем он отослал тебя? — *Лазарь видел насквозь мелкие манипуляции.* — Он выживет скорей всего, худшее позади. Смышлёный парень, надеюсь я был прав и у него есть талант.",165330,null],[165332,"2026-08-19T16:08:17",31,"- что значит скорее всего? Для чего ты ему дал это выпить?",142532,null],[165333,"2026-08-19T16:12:27",9,"*Кажется, умираешь, звуки голосов превращаются в писк в голове, а ты сам будто пленник тела, сознание не способно пересилить ощущения, звуки угасают. Остатки чувств тоже. Остаётся только думать, вот и всё, ты не чувствуешь своего дыхания. Со временем приходят новые ощущения. Окружающий мир переливается калейдоскопом цветов, оттенков, неясных пятен и расплывчатых образов. Больше нет ничего – наверное, так и должно быть. Может быть загробный мир выглядит вот так? Ощущаешь себя шариком с дюжиной щупалец – будто осьминог. Был бы хоть за что ухватиться, но здесь пустота. Щупальца шевелятся сами по себе, без цели. Предстоит долгий путь. Без чувств, без желаний, без забот и интересов. Кажется, тебя несёт неведомое течение – лёгкое, почти неощутимое движение вперёд. В неизвестность. Может, всего мгновение прошло? А может, вечность. Какой сейчас год, месяц, час? Спросить некого. Ты видишь? Или не видишь? Чем вообще смотреть, если нечем ощущать? Куда тебя тянет? Где ты? Что там, впереди? Здесь же – бесконечная пустота, полное отсутствие органов чувств. Вот она, настоящая свобода. Когда не нужно ничего. Только одно желание не умирает. Снова стать пленником смертного тела.*\n \nОн стал свободен. Больше его нет. Всё тлен.\n \nРаб голода, сна, просторов, пригодных для жизни.\n \nЛишь одно желание…\n \nСнова попасться в тот сладкий плен.\n\n— Что из этого ощутил ты потеряв связь с реальностью?",165307,null],[165334,"2026-08-19T16:16:10",9,"Белобрысый ученый (Лазарь) — Не давал — предложил. Он был вправе отказатся. — *Ученый садится в своё кресло и пьёт свой кофе.* — Немного правда утаил, но эксперименты на себе не считаются. Мне зелье ничего не дало кроме ужаса и боли, как и ожидалось — отсутствие таланта. По словам того кто за мной приглядывал я выглядил хуже чем этот паренёк при этом.",165332,null],[165335,"2026-08-19T16:19:11",31,"- то есть эта дрянь как то должна раскрыть его потенциал? Мы можем ему как то помочь?",142532,null],[165336,"2026-08-19T16:25:40",20,"/🎉",142532,null],[165340,"2026-08-19T16:39:02",9,"Белобрысый ученый (Лазарь) — Я поставил благовония, они приглушают ощущения, больше ничем помочь не могу, может сделаю даже хуже. Не надышись ими сам, скоро догорят. — *Он открыл книгу, пахло ладаном и сладкими травами слегка морочащими голову, но дым почти весь ушёл под потолок, лишь возле Рена стелился немного.* — И да, эта дрянь раскорет его потенциал, если он есть.",165335,null],[165341,"2026-08-19T16:44:10",31,"Кошусь с недоверием, но ладно, все таки волшебник верттяго знает больше меня. Выношу и вторую сферу на улицу, сажусь около них передохнуть. Интересно, когда придут остальные умники?",142532,null],[165346,"2026-08-19T16:59:19",20,"*Сознание Рена(или же здесь даже этой маски больше нет?) плывет, когда нечто затягивает его в странную, спокойную вечность. Все, что он знал, к чему стремился будто стирается перед пустотой, манящей его...свобода...*\n\n*Свобода?*\n\n*Золотые глаза(а есть ли здесь глаза?) прищуриваются, когда какая-то одна искра в почти ускользнувшем сознании непокорно возгорается. Он желал много - безопасности, силы, мести. Но абсолютная свободы? Он знал, что ее нет, не в том привычном плане существования. Не в плоти и крови.*\n\n*Искра разгаралась все сильнее, когда частица сознания начало тянуть назад. Скрытое, странное желание питало его - сила, желание  построить собственные правила, заперев других с собой в клетке, созданный по его идеалу. Власть, сила, контроль.... Эти смутные понятия повторялись друг за другом казалось бы бесконечность, пока снова не стали обретать для сознания смысл. Смысл, которого эта пустота его почти лишила.*\n\n*Не, ему не нужна такая свобода. Ему нужен... Трон.*\n\n*И с этой новой целью золотая искра с новой силой потянула назад*\n\n/Психодел на психодел как говорится",165333,null],[165347,"2026-08-19T17:05:45",9,"??? — Ты часто врал другим? О многом ли желеешь? — *Внутренний голос, будто слышен из ниоткуда и везде. Он твой или чужой? Здесь не разобрать.*",165346,null],[165348,"2026-08-19T17:08:27",20,"- Ложь лишь один из видов оружия. Тысячи режут мечом, тысячи разят огнем и стрелами. Мне нечего стыдится своего выбора клинка. Лишь того, что это клинок иногда не идеален",165347,null],[165349,"2026-08-19T17:13:19",9,"??? — Ложь, она ходит по рукам и веры ей нет, однажды это оружие окажется у тебя в спине если продолжишь им пользоваться. — *На границе сознания возникает взгляд, колкий, золотой, словно твой, на мгновение, но это не твои глаза, зрачки на мгновение сузились в вертикальные щели прежде чем исчезли. А потом слова, на этот раз тихо, словно шепот, тайна на ухо.* — Правда, это самый острый клинок который кто когда либо держал в руках. Он обоюдо острый, самый опасный, если не знать секрет... он не заставляет тебя все говорить как есть... каждый в праве молчать и хранить свои тайны, даже тот кто всегда говорит... правду...",142532,null],[165351,"2026-08-19T17:14:48",9,"//Те самые глаза из тьмы появившийся намгновение...",165350,null],[165352,"2026-08-19T17:14:53",31,"Кошак что смотрит прямо в душу//",142532,null],[165353,"2026-08-19T17:16:10",20,"- Правда... Хорошо. Значит я оберну в оружие и ее. Ещё более идеальное",165349,null],[165354,"2026-08-19T17:16:43",20,"//как будто со всей кошкой говорю",165351,null],[165355,"2026-08-19T17:18:00",9,"*После совета ты больше ничего не услышал, а чувства мало помалу начали возвращаться.*\n\n//Щас я Конрада буду мучать, когда начнешь приходить в себя в реальности — скажу",165353,null],[165361,"2026-08-19T17:20:52",20,"/готовлюсь чилить денёк два с таким истощением)",165355,null],[165362,"2026-08-19T17:21:48",9,"//Если бы все 6 проверок тела сл 15 провалил то был бы трупец 😏👌",142532,null],[165363,"2026-08-19T17:22:48",20,"/ну мы знали на что шли👀",165362,null],[165388,"2026-08-19T18:19:59",9,"*Сидеть пришлось добрых десять минут прежде чем ты заметил двух молодых людей, лет не больше семнадцати, скорее 15-16, идущих к пристройке ученых лагеря, точно к ней. Молодой перенёк напоминающий ботаника и девушка, оба боевитые и по пути дурачились. Девушка крепко ухватилась за его запястья и хотела потрепать его за длинные волосы, явно уложенные и расчесанные, у самой же заплетены обычные косы слегка растрёпанные словно та бросила их расчесывать на пол пути, до приемлимого состояния.*\n\nДевушка — Сон, ну ты даёшь! Перед кем красуешься? Иди сюда. — *Танет руки, пытается ухватить его.*\n\nПарень (Сон) — Отстань! Не трогай прическу, кыш падла такая. — *Он уже запыхавшийся кое как вырвался и бежит от неё прямо в двери, девушка же не собиралась сдаваться, она быстро его догнала дернув за рубаху у самой двери, от не упал лишь потому что схватился за дверь.*\n\nДевушка — Поймала!\n\n*Звуки возмущения и причитаний под звонкий девичьий смех, парень даже руками махать начал отбиваясь, весь покрасневший  от возмущения. Но девушка не только сильней и быстрей, схватила его за руки и держа перед собой тьмокнула в щёку, от чего ввела его в полный ступор.*\n\nДевушка — Растрёпанные волосы мне больше нравятся. — *И пока парень пытался сообразить что происходит нырнула под рукой исчезнув в проходе.*\n\n*Что сказать, молодые устроили сцену не обращая внимания на Конрада. Парень попытался отдышаться и успокоился и просто со злости громко закрыл дверь за ней, после чего кажется горячка прошла, он стал вытирать щёку и пытаться по ощущениям рук поправить волосы, но получалось откровенно плохо.*\n\nПарень (Сон) — Вот же проблемная, как работать в таких условиях... покоя не дает...",165341,null],[165389,"2026-08-19T18:21:24",9,"*Если задуматься, в лагере небыло никого их возраста почти, а если моложе — тем более. Только может Рен.*",142532,null],[165390,"2026-08-19T18:22:38",31,"Ну и нехоен детям в лесу тусить в мутных компаниях//",165389,null],[165391,"2026-08-19T18:23:43",31,"- и не говори, работать невозможно. У меня правда, менее симпатичные помехи. Привет, я Конрад, меня отправили к вам на помощь",165388,null],[165392,"2026-08-19T18:29:59",9,"*Парень только заметил тебя, причёску поправил на самом деле плохо, но забыв о ней вспомнил о манерах.*\n\nПарень (Сон) — Простите, я вас не заметил, меня отвлекли. — *Он учтиво сделал поклон, словно аристократ. Что возможно обьясняет почему столь \"близкое\" внимание от девушки его бесило.* — Сондж Тин-Паунд, для друзей и знакомых в неофициальной обстановке просто \"Сон\". Ученик господина Лазаря.\n\n*Парень представился, даже если присмотреться, хотя на нём простые рубаха, ботинки, штаны, они были вычищены и накрохмалены.*",165391,null],[165395,"2026-08-19T18:36:50",31,"- да, с Лазарем я уже познакомился. Колоритный тип. А кто еще тут работает? Ну собственно, чем вы занимаетесь конкретно?",142532,null],[165403,"2026-08-19T18:49:11",9,"Парень, ученик Лазаря (Сон) —  Лика, вы её видели, обучена грамоте и чертежам. Я помогаю господину Лазарю и учусь у него, это оплачивается моей семьёй поэтому почти не прикасаюсь к работе, только когда учитель загружен. — *Он выровнялся и стоял уверенно обьясняя что к чему.* — Старый алхимик Одисей, почти ничего не слышит, но зелья варит исправно. Большая Грета, мать Лики, разбирается в механизмах, леди с золотыми руками. Помощников мы редко просим, только когда много физической работы. Единственное, нет рабочей силы для переписи и классификации заметок, старшие не хотят этим занимаиься, в лагере есть грамотные, но никто не может должным образом оформить и рассортировать документы. Вы достаточно обученны грамоте для этой работы?",165395,null],[165406,"2026-08-19T18:52:18",9,"//Пардон, это парень говорил, я сначала написал сам Лазарь 😅",142532,null],[165407,"2026-08-19T18:53:16",31,"- грамоту я знаю, писать и читать обучен. Только в магии профан",142532,null],[165408,"2026-08-19T18:58:48",9,"Парень, ученик Лазаря (Сон) — Магию знать не обязательно. Просто скопировать и классифицировать записи по тематике. — *Он подумал немного, присмотрелся к тебе.* — Мне самому приходится этим заниматься, для закрепления тем — отличная практика, но уже по первым строкам иногда могу предугадать содержимое нескольких следующих абзацов. Поэтому можете просить у меня помощи, буду только рад подсобить если в будущем рабочая нагрузка уменьшится.",165407,null],[165409,"2026-08-19T18:59:49",31,"- хорошо. Пойдём посмотрим что там по рабочим задачам. Да и ты познакомишься с еще одним новичком. Если он очнулся",142532,null],[165416,"2026-08-19T19:19:19",9,"*Сон кивнул и положил руку на ручку, вздохнул собираясь с мыслями ведь там был не только учитель а и его головная боль... открыл дверь и вошёл.*\n\nБелобрысый ученый (Лазарь) — Доброе утро Сон. — *Маг всё ещё сидел в кресле и читал.*\n\nПарень, ученик Лазаря (Сон) — Доброе утро учитель. — *Поздоровавшись с учителем, он шагнул внутрь в поисках еще одного человека о котором упомянул Конрад и заметил Лику что уже сидела возле Рена и гладила того по волосам сменяя тряпку с холодной водой. Благовония уже догорели, незнакомец лежал на месте учителя.* — А это?\n\nБелобрысый ученый (Лазарь) — Мой новый ученик, Рен. В нём есть внешние проявления чародейских черт, он выпил элексир пробуждения. — *Маг наученный практикой, словно читая лекцию объяснил ситуацию, как ему казалось — исчерпывающе, чтобы не задавали лишних вопросов.*\n\nДевушка из писарей (Лика) — Смотри, ему совсем плохо. Бедняга, надо будет одолжить с кухни чего нибудь вкусного. — *Видно что жалеет Рена.*\n\n*Сон был немного ошарашен что Лазарь так быстро принял кого-то в ученики, даже не нашел что сказать, просто постояв мгновение пошёл к столам с кучей документов весь в своих мыслях пока не найдя что спросить.*\n\nБелобрысый ученый (Лазарь) — Конрад, вы не занесли камни. Ведро воды и щетки можете попросить на складе, он у высокой стены, южнее отсюда. Не перепутаете, близ него раскопан фонтан. — *Он давал указания и при этом перевернул страницу.* — Как почистите древности и приведете себя в порядок тоже, обсохните, можете вернутся и приступить к своей непосредственной работе.",165409,null],[165423,"2026-08-19T19:26:27",31,"Отправляюсь в путь за щётками и водой, быстро добегаю и прошу у местного завхоза орудияэто труда, после чего возвращаюсь и начинаю драить камни. \n\n//Если что то нужно обыграть в этом процессе, скажи",142532,null],[165429,"2026-08-19T19:29:11",31,"Рубит меня , сорян, ухожу спать//",142532,null],[165434,"2026-08-19T19:31:50",9,"*Тебя за делом находит Чиф, он кажется устал и забегался, за ним плелся недовольный здоровяк.*\n\nМолодой (Чифтер Люск) — Ты не видел Люпена? Везде его ищу, мы искали Диму, я его нашел а Люпен пропал куда-то, в лагере его нет, стоял ждал и не дождался.\n\nВоин в больших доспехах (Димон) — Я должен хоронить. — *Пробурчал здоровяк под нос, недобро поглядывая на Чифа.* — Оставайся так далеко.\n\nМолодой (Чифтер Люск) — Да, знаюч извини. Ты должен быть уже на озотеч а в итоге ждешь тут, прости. Отдам своё пиво сегодня вечером. — *Молодой парень знал как и чем подкупить здоровяка чтобы тот не злился.*",165423,null],[165503,"2026-08-19T20:10:49",9,"// @dunchev кажется Алексей уснул, могу с тобой продолжить. Пиши когда и если свободен",165288,null],[165508,"2026-08-19T20:13:01",17,"Люпен отправляется по этим следам в низину\n\n\"Точно пошел сюда. Такие тяжёлые следы только у него.\"\n\nОзираясь по сторонам мурашки на коже сигнализировали страх. \n\nТогда Люпен решил идти тихо и сбоку от тропы по кустам, на всякий случай.",165288,null],[165510,"2026-08-19T20:13:25",17,"/r +4 Скрытность",142532,null],[165518,"2026-08-19T20:18:53",9,"*Следы уходят в болото и исчезают в нём. Водоём не выглядит глубоким, это скорее лужа а не топь, и стоячая вода в ней на удивление достаточно прозрачна чтобы виднелось отражение ветвей и фигур, твердое дно. Окружение кажется гиблым, деревья словно кто разделил их на до и после, возле воды достаточно зелено как и в остальном лесу, а в нем уже коряги. На дне видны нечеткие следы животных, но рядом ни одной животины и тихо.*",165508,null],[165530,"2026-08-19T20:22:23",17,"\"Димы нету... Наверное я ошибся... Блять... Столько времени просрал. Надо бы хоть какую нибудь белку, жабу или кролика подбить. Ато засмеют\"\n\nЛюпен сосредоточился на поиске дичи, а не на поиске Димы\n\nВ болото он не пошел вернувшись в сухой лес",142532,null],[165533,"2026-08-19T20:22:38",17,"/r +2 Сосредоточенный поиск следов добычи",142532,null],[165545,"2026-08-19T20:26:57",9,"*После часа поисков по незнакомых местах на глаза попались рытвины, точно лежка кабана под густым кустарником. Не понятно есть там кто или нет, но один раз было слышно тоненькое хрюканье, словно там есть поросенок, но так же как и раздался один \"хрю\" так и сейчас тихо.*\n\n//Что ты делаешь?",165534,null],[165547,"2026-08-19T20:28:52",17,"\"Поросенок может и есть, а где его мамочка...?\"\n\nЛюпен затаился неподалеку в кустиках у густого кустарника приготовил пращу и стал ждать",142532,null],[165548,"2026-08-19T20:29:02",17,"/ Скрытность кинуть? Хочу засаду на кабана",142532,null],[165551,"2026-08-19T20:39:55",17,"/r +4 Скрытность",142532,null],[165570,"2026-08-19T21:10:27",17,"/ Докину вдохновение вдруг кабан не шипко внимательный пассивно",142532,null],[165571,"2026-08-19T21:10:35",17,"/r d4 Ну ка!",142532,null],[165573,"2026-08-19T21:10:46",17,"/ ну вот 11",142532,null],[165611,"2026-08-19T22:34:09",9,"*Несколько поросят бегают под кустами. Два, три, удалось насчитать трёх поросят. Взрослого кабана не видно, наверное отдыхает глубже в этом кустарнике.*\n\n*Трое поросят весело хрюкают и валяются в грязи рытвин что сделали сородичи покрупнее.*",142532,null],[165688,"2026-08-20T08:49:09",17,"Люпен примерно в 60 футах от кабанчиков \n\n\"Охота начинается\"\n\nОн раскручивает пращу и выпускает камень по мелкому поросёнку из засады",142532,null],[165689,"2026-08-20T08:49:36",17,"/r 3d20-2 C метким стрелком",142532,null],[165691,"2026-08-20T08:49:50",17,"/ 17 - попал?",142532,null],[165692,"2026-08-20T08:50:03",17,"/r d4+12 Дробящего урона",142532,null],[165694,"2026-08-20T08:50:30",9,"//Ну, значит пора...",142532,null],[165695,"2026-08-20T08:50:32",17,"/r +4 Скрытность бонусным",142532,null],[165697,"2026-08-20T08:51:01",17,"/ невидимка",142532,null],[165698,"2026-08-20T08:55:59",17,"Прищурившись из своей засады взгляд охотника остро сфокусировался на добыче. В такие моменты играла частичка эльфийской крови в теле парня, о которой он не подозревал. Звуки леса затихли, солнце не слепило глаза, только он и жертва на приличном расстаянии.\n\nОн выдохнул и поднявшись в полный рост раскрутил пращу, дёрнул рукой и швырнул камень в цель.\n\nЛюпен видел что попал и сразу же обратно скрылся и замер в кустах\n\nСердце бешено колотилось, даже если он принесёт в лагерь этого поросёнка уже хоть что-то. Но где детишки там и родители.\n\nОн пытался успокоить дыхание",142532,null],[165699,"2026-08-20T08:59:37",9,"*Мгновение и тишина которую прорезал острый свинной визг, из кустов несколько кабанов разбегаются в разные стороны леса. Кабаниха выходит и тыкается носом в мертвое порося, её глаза наливаются кровью, но из места лёжки вышла не только она.*\n\n*Помимо пары молодых кабанов из кустарника вылез грёбаный вепрь, машина для убийства в полтора раза больше своих сородичей которая могла бы сожрать обычного человека и не подавится, оно хрюкноло, но это было тяжёлое хрю, от которого слегка могло стать не по себе.*\n\n*Они резко выскочили и встали на ноги готовые ринутся прямо на обидчика сразу как поймут где он.*",142532,null],[165700,"2026-08-20T09:00:38",9,"/roll 1d20 Внимание Свинины\n/roll 1d20-1 Внимание Тушонки\n/roll 1d20-1 Внимание Жаркого",142532,null],[165702,"2026-08-20T09:01:49",9,"*Люпен отлично спрятался, глубоко посаженные глазки на свинных мордах ищут не достаточно хорошо чтобы увидеть.*",165701,null],[165703,"2026-08-20T09:17:44",17,"\"А вот и папочка и мамочка...\"",142532,null],[165704,"2026-08-20T09:17:52",17,"/r Храбрость Люпена",142532,null],[165706,"2026-08-20T09:20:30",17,"Поджилки затряслись от одного вида этого огромного вепря\n\nЛюпен решил подождать немного, вдруг они разойдутся и будет шанс стащить поросёнка\n\n\"Лезть на вепря самоубийство, да тут еще и кабаниха...\"\n\n\"Или.. она могут меня тут вычислить...\"\n\nЗамешкался не надолго он думал как лучше подступить, решил немного выждать, может расклад станет получше",142532,null],[165707,"2026-08-20T09:20:34",17,"/Засада моя 17",142532,null],[165708,"2026-08-20T09:21:00",31,"Прощай Люпен, мы запомним тебя молодым//",142532,null],[165709,"2026-08-20T09:21:34",17,"/ Я щас их всех добуду на мясо!)))))",142532,null],[165710,"2026-08-20T09:22:39",31,"Ладно, я тогда пока не реагирую на слова о том что Люпен потерялся/",142532,null],[165711,"2026-08-20T09:23:03",17,"/ Два трупика на поляне лучше чем один)",142532,null],[165712,"2026-08-20T09:23:49",9,"//Так скади им хоть че нить)",165710,null],[165713,"2026-08-20T09:25:16",31,"- так он же вроде побежал в лес, за Димкой. Вроде кто-то ему сказал что тот уже ушёл\n\n//я хз, не помню, видел ли то охотница наебала Люпена, но пусть будет что видел/",165434,null],[165718,"2026-08-20T09:34:43",17,"/r Храбрость Люпена снова",142532,null],[165720,"2026-08-20T09:35:09",17,"Руки тряслить так что голову из кустов боялся поднять",142532,null],[165721,"2026-08-20T09:35:22",17,"/ Хард кинь внимание кабанов, может найдут ))",142532,null],[165722,"2026-08-20T09:35:33",17,"/ Храбрости добавят)",142532,null],[165773,"2026-08-20T10:00:09",9,"//Тебе никто ниче не говорил, но ладно)",165713,null],[165775,"2026-08-20T10:00:50",9,"/roll 1d20 Внимание Свинины\n/roll 1d20-1 Внимание Тушонки\n/roll 1d20-1 Внимание Жаркого\n/roll 1d20-1 Внимание Кабанихи",142532,null],[165778,"2026-08-20T10:01:33",9,"//Ну, щас буду описывать получается *ищет музыку в наушники для настроения*",142532,null],[165782,"2026-08-20T10:05:23",17,"/ ТУШОНКАААА НЕЕЕЕТ",142532,null],[165783,"2026-08-20T10:06:01",17,"/ Кто из них вепрь? Я так понимаю Кабаниха 2 молодых кабанчика как тот что я грохнул и вепрь",142532,null],[165785,"2026-08-20T10:10:18",9,"//Неа, мелочь убежала в кусты, 2 взрослых кабана, кабаница и вепрь. У вепря мудрость повыше. Щас соберусь и булет веселье",165783,null],[165788,"2026-08-20T10:15:37",31,"Я так понимаю, имена Кабанов это олицетворение того что они хотят сделать из Люпена?/",142532,null],[165789,"2026-08-20T10:16:01",17,"/ Ага, кабаниху сделать и...",142532,null],[165790,"2026-08-20T10:16:21",9,"//Да, я только что понял что у них скорость 40 ^^",142532,null],[165791,"2026-08-20T10:16:32",17,"/ Я в 60 сижу",142532,null],[165792,"2026-08-20T10:16:59",17,"/ Вообще я могу с пращи пулякать со 120 футов без помех)",142532,null],[165793,"2026-08-20T10:17:32",9,"//Я настраиваюсь на бой",142532,null],[165802,"2026-08-20T10:25:41",9,"*Лес, тут много кустарника в сизой дымке некротических облаков закрывающих солнца. Много старых, вековых деревьев. Тушонка что-то заметила и резко с разгона двинулась в сторону Люпена. Остальные среагировали опосля, как отработанная тактика или инсктинт, куда первый туда и они!*\n\n//Тушонка теперь на 40 футов от Люпена, остальные по 50, думаю этого достаточно чтобы среагировать, а теперь кажется иня)",142532,null],[165805,"2026-08-20T10:27:58",9,"/roll 1d20 иня Свинины (вепрь)\n/roll 1d20 иня Тушонки\n/roll 1d20 иня Жаркого\n/roll 1d20 иня Кабанихи",142532,null],[165807,"2026-08-20T10:31:35",17,"/r +3 Ини",142532,null],[165811,"2026-08-20T10:33:47",31,"/мы отомстим за тебя. Или нет//",142532,null],[165822,"2026-08-20T10:37:12",9,"Иня:\n\nСвинина (вепрь) — 19\n??? — 14\nКабаниха — 11\nЖаркое — 6\nЛюпен — 4\nТушенка — 3",142532,null],[165824,"2026-08-20T10:38:36",9,"//Бля, Люпену все равно повезло, его ток тушонка знает где точно он, а оно ходит последним)",142532,null],[165825,"2026-08-20T10:40:47",9,"//Ладно, его всё еще могут протаранить думаю",142532,null],[165826,"2026-08-20T10:41:38",9,"/roll 3d3 везение, наткнетля ли кто, первый это вепрь",142532,null],[165828,"2026-08-20T10:43:21",9,"/roll -d20+5 вепрь в слепую по Люпену\n/roll -d20+3 жаркое тож не видит его",142532,null],[165830,"2026-08-20T10:44:15",17,"/Погоди а как они добежали?",142532,null],[165831,"2026-08-20T10:44:35",17,"/Рыком просто",142532,null],[165832,"2026-08-20T10:44:40",9,"//Рывок и просто на ходу в твою сторону)",165830,null],[165833,"2026-08-20T10:44:52",17,"/ окей",142532,null],[165834,"2026-08-20T10:45:10",17,"/ Попал Жаркое",142532,null],[165835,"2026-08-20T10:45:18",9,"//Они не видят тебя, просте бежат в твою сторону, я вот кидал столкнутся ли с тобой)",165827,null],[165837,"2026-08-20T10:49:23",9,"*Вепрь был сильнее и быстрее, Жаркое бежало прямо на Люпена, но его сбил товарищ покрупнее, и они просто пробежали мимо. Кабаниха бежит с налитыми кровью глазами, совсем мимо мордой вырывая кусты, кадется она в ярости, это было её порося которого нещадачливый охотник так зверски прикончил.*\n\n// 30 Тушенка точно знает где ты, 15 Вепрь, 20 кабаниха, 10 жаркое от тебя футов",165829,null],[165838,"2026-08-20T10:50:11",9,"//Знает где ты ток Тушонка, если бы не крит провал у Вепря, жаркое бы попало в тебя)",142532,null],[165856,"2026-08-20T10:58:48",17,"/ Если я начну бежать кто сможет дать по мне провоцировнную?",142532,null],[165857,"2026-08-20T10:59:22",9,"//Смотри, ща",165856,null],[165858,"2026-08-20T10:59:47",9,"*Рисует карту*",142532,null],[165859,"2026-08-20T11:00:13",17,"/Да не карта не нужна, просто скажи если никого нет рядом я с рывком побегу прятаться, если есть то с отходом",142532,null],[165863,"2026-08-20T11:05:25",9,"//Основа готова, щас сохраню и потом буду показывать где чё. Кричневые круги это деревья, зеленое — кустарники, есть несколько коряг и веток и достаточно крупных камней голубоватым",142532,null],[165866,"2026-08-20T11:08:45",9,"//Чёрный вепрь, красные кабанф, тушонка дальше всего, синий ты. Карта немного хуйня но я её начеркал в тг вот щас на клеточках. А если тебя не видят они могут провоцированную вообще?",142532,null],[165869,"2026-08-20T11:16:21",9,"Молодой (Чифтер Люск) — Не знаю. — *Молодой смущенно (не в романтическом смысле) почесал затылок.* — Мы договорились встретиться как пройдем по лагерю, его на месте не оказалось. Он не выглядит как те кто мог бы просто решить и сделать иначе не предупредив.",165713,null],[165876,"2026-08-20T11:33:56",31,"А не слишком ли опасно одному идти в лес? Он ведь может попасть в беду, без прикрытия то",165869,null],[165878,"2026-08-20T11:34:33",17,"/Нет не могут.",165866,null],[165879,"2026-08-20T11:35:05",17,"Люпен удирает по кустам от кабанов\n\n/Карта не нужна тут будут каждый ход забеги на 70 футов и прятки",142532,null],[165882,"2026-08-20T11:35:26",17,"/r +4 Скрытность засады бонусным, чтобы скрыться от всех.",142532,null],[165884,"2026-08-20T11:35:36",17,"/ Засада работает так:",142532,null],[165885,"2026-08-20T11:37:22",17,"/ представим меня все видят. Я убегаю куда то где нет обзора врагов, например за деревья и кусты. Кидаю кубик. Значение это сложность моей засады. \n\nЗасада автоматически не срабатывает если у существа значение пассивной внимательности выше чем моё значение засады, тогда ЭТО существо меня видит и знает где я.\n\nЕсли это были бы люди, очевидно он бы крикнул \"ОН ТАМ!\" но это кабаны, так что остальные не знают где я. Я для них не невидимый, они буквально теряют меня и не понимают куда делся, могут пойти в другую сторону искать. и тд",142532,null],[165886,"2026-08-20T11:39:06",9,"//Я более менее так и прелставлял)",142532,null],[165888,"2026-08-20T11:39:44",9,"//Как давно Люпен мылся?)))",142532,null],[165889,"2026-08-20T11:40:01",17,"// Ну с момента камеры не мылся",142532,null],[165890,"2026-08-20T11:40:10",17,"/ Помеха на скрытность?)",142532,null],[165891,"2026-08-20T11:40:20",17,"/ Или преимущество на внимание?)",142532,null],[165892,"2026-08-20T11:41:35",9,"Молодой (Чифтер Люск) — Охотники по двоя ходят в этих местах и то иногда пропадают. Плохо если один пошёл, с Паскалем его не видел.",165876,null],[165893,"2026-08-20T11:43:26",9,"*Кабаны не нашли тебя, слегка успокоившись и разбредясь начинают искать, но не хитрая Тушёнка. Он тебя видел и поэтому пытается вынюхать по запаху где был Люпен последний раз, тот еще и не мылся давно.*",142532,null],[165894,"2026-08-20T11:44:07",9,"/roll +d20-1 тушёнка ищет Люпена по запаху",142532,null],[165896,"2026-08-20T11:44:32",9,"*Тушёнка не нашёл охотника.*",142532,null],[165897,"2026-08-20T11:44:47",17,"/r 3d20-2 Из кустов по тушенке летит камень",142532,null],[165899,"2026-08-20T11:44:54",17,"/ 17",142532,null],[165900,"2026-08-20T11:45:06",17,"/r d4+12",142532,null],[165902,"2026-08-20T11:45:07",9,"//Я пока не походил другими)",142532,null],[165903,"2026-08-20T11:45:15",17,"/ Ну потом полетит)))",142532,null],[165904,"2026-08-20T11:45:30",17,"/ Билд работает!",142532,null],[165905,"2026-08-20T11:45:58",9,"/roll 1d20 Вепрь \n/roll 1d20-1 второй кабан\n/roll -d20-1 кабаница не соображает, она готова порвать не то что всех а все что видет",142532,null],[165907,"2026-08-20T11:46:43",9,"//Ну и как мне с этим работать скажите на милость? Пох на средние значения, крит успех и крит провал в одном флаконе.",165906,null],[165908,"2026-08-20T11:48:37",17,"/ ахахах вот кабаны",142532,null],[165909,"2026-08-20T11:48:43",17,"/ во дают",142532,null],[165910,"2026-08-20T11:48:58",9,"*Зоркий глаз Вепря с легкостью бы выследил Люпена, если бы его сородич не стоял четко меж ним и Люпеном когда тот смотрел в его сторону.*",165906,null],[165911,"2026-08-20T11:49:39",9,"//Твой ход, описывай как убил тушенку и делай дела",142532,null],[165929,"2026-08-20T12:33:17",17,"Люпен видел, что кабаны растерялись, никто его не заметил, это придало ему уверенности, он посчитал, что сможет. Сможет завалить всех в одиночку.\n\nГлупая наивная идея, но пока что он был ей поглащен\n\nКогда он снова раскрутил пращу и выпустил камень он с хрустом врезался в глаз кабана и застрял там, животное как мешок с карточшкой рухнуло на землю\n\nЛюпен обратно нырнул в кусты\n\nЕхидная хищная улыбка на его лице выдала некие садисткие наклонности этого человека. Мир жесток и ожестоячает людей. Мало кто может сопротивляться этому, лишь отсрочить неизбежное. Люпен почувствовал азарт охоты и не сдерживался более",142532,null],[165930,"2026-08-20T12:33:34",17,"/r +4 А ВОТ СКРЫТНОСТЬ ЗАСАДЫ?!",142532,null],[165932,"2026-08-20T12:33:41",17,"/ Пупупу",142532,null],[165933,"2026-08-20T12:34:07",17,"Он понял что нашумел поэтому тут же побежал прочь от кабанов ломая сучья\n\n/Отошел на свои родные 35",142532,null],[165934,"2026-08-20T12:34:14",17,"/Конец хода",142532,null],[166141,"2026-08-20T15:55:23",9,"*Кабан мешающий обзору отошёл и Люпена тут же заметил Вепрь, он хрокнул, угрожающе пошевелил пятачком, ногой несколько раз загреб землю, как в тех самых Вестернах. Ракурс со стороны охотника, после кабана, идеальное растояние для разбега, время застыло, между вами пробежал барсук, став на лапки, посмотрел, влево, вправо, и решил смотаться и не стоять между двух огней. Другие кабаны хоть и искали, как свинина ломонулась к Люпену заметили не сразу. Рывок, бег, мгновение, ты осознаёшь что свинная рожа прямо перед твоим лицом, её зловонное дыхание, он ел не только трюфели, периодически и тех кто их собирал. Кабан с кабанихой бегут следом за ним.*\n\n//Ход бля, с разгона к тебе вепрь в притык и другие два кабана на 20 и 30 футов от тебя",142532,null],[166142,"2026-08-20T16:21:06",17,"\"БЛЯТЬ БЛЯТЬ БЛЯЯЯЯТЬ\"\n\nЛюпен кинув в рыло кабану гость земли пустился наутёк в кусты и нырнул за несколько стволов деревьев в кусты",142532,null],[166143,"2026-08-20T16:21:11",17,"/Отход действие\n\n засада бонусное",142532,null],[166144,"2026-08-20T16:21:17",17,"/r +4 Прятки от смерти",142532,null],[166147,"2026-08-20T16:21:38",17,"/Я в 35 футах",142532,null],[166148,"2026-08-20T16:21:59",31,"Заманивай их в лагерь/",142532,null],[166149,"2026-08-20T16:22:15",17,"/ Да я бегу в сторону лагеря",142532,null],[166150,"2026-08-20T16:22:41",20,"/мы все обязательно выживем...",142532,null],[166151,"2026-08-20T16:23:22",31,"//ну я то да, сижу себе, камни отмываю, пока один в наркотрипе, а второй от свиней бегает/",166150,null],[166152,"2026-08-20T16:23:39",9,"//Там вдохновы 1д4 есть)",142532,null],[166153,"2026-08-20T16:23:59",9,"//У Люпена всего 2 остались)",142532,null],[166154,"2026-08-20T16:24:15",17,"/r d4 ВДОХНОВА",142532,null],[166156,"2026-08-20T16:24:19",17,"/ СУДА",142532,null],[166169,"2026-08-20T16:40:09",9,"*Вепрь вовремя матыляет головой и тут же примечает куда именно пытается скрыться Люпен, бежит к нему, разгона хватает чтобы догнать и протаранить поддев большими иклами.*",142532,null],[166174,"2026-08-20T16:41:29",9,"/roll 1d20+5 попадание выходит",142532,null],[166177,"2026-08-20T16:43:13",9,"*Морда вепря застряет в кусте, Жаркое и кабаниха подспевают к Люпену зажав по бокам.*\n\n//На сколько понял у Вепря промах, а те двое добежали на рывке, твой ход.",166175,null],[166191,"2026-08-20T17:47:16",17,"/ Мой КД 13",142532,null],[166192,"2026-08-20T17:47:39",17,"/ Я буду продолжать делать отход от всех и прятаться, так я бегу по 35 в ход к лагерю, пока кабаны меня не съели",142532,null],[166197,"2026-08-20T17:48:44",31,"Вопрос в том, далеко ли бежать? И кто добежит первым, ты до лагеря, или рак кубов от свинюх?/",166192,null],[166198,"2026-08-20T17:48:46",17,"Люпен отскакивает, когда кабаны зажимают его по бокам\n\n\"ЭТО ЧТО КАБАНЫ ГЕНИИ!? НАДО ЕБЖАТЬ В ЛАГЕРЬ!\"\n\nАдреналин бьёт в голову, тело как наэктризованое выполняет одну базовую функцию - спасаться",142532,null],[166199,"2026-08-20T17:49:03",17,"/r +4 Прыгнул в кусты и кубарем покатился прячусь",142532,null],[166204,"2026-08-20T17:49:29",17,"/Атакуй всеми кабанами, у них 40 я в 35",142532,null],[166205,"2026-08-20T17:49:34",31,"Хард не тот смайл на реакцию выдал надо поискать смайлы с пятачками/",142532,null],[166206,"2026-08-20T17:50:06",17,"/ Бля, я уже поверил что щас кубы будут лететь и я всех кабанов с говённой пращи -1 расстреляю",142532,null],[166207,"2026-08-20T17:50:16",9,"//У николая ещё есть вдохнова последняя)",142532,null],[166208,"2026-08-20T17:50:20",17,"/ Но в итоге меня насадят на кабаньи клыки)",142532,null],[166209,"2026-08-20T17:50:35",17,"/r d4 А че солить вдруг хоть",142532,null],[166211,"2026-08-20T17:50:47",17,"/r d4 А че солить вдруг хоть",142532,null],[166213,"2026-08-20T17:50:53",17,"/ 10",142532,null],[166214,"2026-08-20T17:50:57",17,"/ МОЯ СКРЫТНОСТЬ!",142532,null],[166216,"2026-08-20T17:51:35",31,"🐽 нашёл////",142532,null],[166219,"2026-08-20T17:52:08",9,"*У кабанов удалось выпрыснуть из под носа, но вепрь тебя не потерял из виду и гонясь по кустам за Люпеном таранит мордой.*",142532,null],[166220,"2026-08-20T17:52:32",9,"/roll 1d20+5",142532,null],[166223,"2026-08-20T17:52:46",31,"Как же прёт/",142532,null],[166224,"2026-08-20T17:53:24",9,"*Свиньи бежат вместе с вожаком и они рядом, хотя их крохотные глазки не улавливают Люпена, но усиленно ищут.*",142532,null],[166225,"2026-08-20T17:53:52",9,"/roll 1d20-1 Жаркое\n/roll 1d20-1 Свинья",142532,null],[166228,"2026-08-20T17:54:20",9,"*Они не отстают от бедного охотника ни на шаг.*\n\n//Ход Люпена",142532,null],[166236,"2026-08-20T17:55:26",9,"//Это моё проклятье, там по калькулятору ему писец в первом ходу должен быть, рекомендован один противник 1/4 а тут их три и вепрь 2 опасности))",166223,null],[166238,"2026-08-20T17:56:09",9,"//Ща, ща",142532,null],[166246,"2026-08-20T17:59:23",20,"/мне теперь очень интересно как ты вообще рассчитывешь сложность тип всегда смертельно + ещё немного?",166236,null],[166247,"2026-08-20T17:59:33",17,"Схватившись за бивни кабана Люпен уперся в них руками и прокатился на вожаке добрые десять метров\n\nОт страха он плюнул ему в морду и попал на удачу в глаз, спрыгнул с бивней и снова побежал в густые заросли.\n\nСтая уже догнала его и единственный шанс был прятаться и бежать\n\nбежать и прятаться",142532,null],[166248,"2026-08-20T17:59:55",17,"/ АГА НЕМНОГО СМЕРТЕЛЬНО х10",142532,null],[166249,"2026-08-20T18:00:08",17,"/r +4 Я НЕВИДИМКА КАБАНЫ МЕНЯ НЕТ",142532,null],[166252,"2026-08-20T18:00:33",17,"/ Отход и засада прячусь в 35 футах от них",142532,null],[166263,"2026-08-20T18:03:43",9,"/roll 1d20 вепрь \n/roll 1d20-1 жаркое\n/roll 1d20-1 Свинья",142532,null],[166268,"2026-08-20T18:04:20",17,"/ Я БУДУ СТРЕЛЯТЬ!",142532,null],[166275,"2026-08-20T18:05:38",9,"*Разьярённые кабаны бегают и ворочают все подряд кусты в поисках Люпена. Местность уже превращается в поле из рытвин, поднявшихся листьев, свиньи злятся, у Вепря наливаются красным глаза.*",142532,null],[166278,"2026-08-20T18:06:13",9,"//Ход Люпена)",142532,null],[166280,"2026-08-20T18:06:39",31,"Лузеры пятачковые//",166264,null],[166281,"2026-08-20T18:07:07",17,"Хитрый лист смог оторваться, люпен отболз еще дальше и уже собирался оставить кабанов впокое....\n\nНооо....\n\n\"Нет, я вам сейчас твари, покажу!\"\n\nОн раскрутил пращу смотря на Жаркое и метнул камень из засады",142532,null],[166282,"2026-08-20T18:07:15",17,"/r 3d20-2 Пошла родимая!",142532,null],[166285,"2026-08-20T18:07:26",17,"/ 12 это промах? по Жаркое",142532,null],[166289,"2026-08-20T18:08:46",20,"/у обычных кабанчиков вроде 11 кд",142532,null],[166291,"2026-08-20T18:09:06",17,"/ Ну это кабаны демоны))) Ладно если пробил вот урон",142532,null],[166292,"2026-08-20T18:09:14",17,"/r d4+12 Дробящего",142532,null],[166296,"2026-08-20T18:09:28",17,"/ Это лишняя)",142532,null],[166297,"2026-08-20T18:09:37",2,"// извините, я листал каналы и случайно нажал",142532,null],[166304,"2026-08-20T18:10:44",20,"/добро пожаловать в ад",166297,null],[166308,"2026-08-20T18:11:03",9,"//Описывай как убил, и что делаешь дальше)",142532,null],[166311,"2026-08-20T18:12:16",17,"Камень дробит череп кабану, угол попадания по счастливой случайности вышел идеально разрушительный\n\nЛюпен аж хихикнул\n\nОн кажется забыл что играет со смертью\n\nСнова попытался спрятаться от кабанов",142532,null],[166312,"2026-08-20T18:12:24",17,"/r +4 Скрытность новой засады",142532,null],[166315,"2026-08-20T18:13:07",31,"Первое правило в казино: выиграл - уходи//",142532,null],[166331,"2026-08-20T18:15:39",9,"*Кабаниха и Вепрь, разьяренные точно поняли откуда прилетел камень, бегут толкаясь к Люпену со всех ног, из ноздрей летит пена и пар, тяжёлое хрокающее дыхание. Если его поймают то к хренам затопчат в землю.*\n\n//Рывок, считай они впритык",142532,null],[166332,"2026-08-20T18:15:54",17,"/ А до лагеря далеко?",142532,null],[166333,"2026-08-20T18:16:07",9,"//Несколько миль)",142532,null],[166334,"2026-08-20T18:16:14",17,"/ Ясно)))",142532,null],[166340,"2026-08-20T18:17:30",17,"Кабаны настигли горе охотника и уже заносили свои бивни чтобы насодить его \n\nВ этот момент Люпен уже не знал что делать, вытащил палку Вялой березы из сумки и ткнул кабану в ноздрю, отползая от них, он свалился по наклонному оврагу вниз, где вскачив на ноги метнулся в сторону",142532,null],[166341,"2026-08-20T18:17:33",17,"/Отход и засада",142532,null],[166342,"2026-08-20T18:17:39",17,"/r +4 Засаживаюсь",142532,null],[166346,"2026-08-20T18:18:41",9,"/roll 1d20\n/roll 1d20-1 поиск",142532,null],[166349,"2026-08-20T18:20:10",9,"*Мать уже двоих поросят не собиралась тебя упускать, гонится что есть мочи, вепрь тоже выгадал примерное направление.*\n\n//Кабаниха впритых, и вепрь за 10 футов от тебя, твой ход",142532,null],[166351,"2026-08-20T18:21:11",17,"Нащупав на земле густую тину из какой то лужи на дне оврага Люпен кинул в лицо кабанихе и внось поспешил ретироваться",142532,null],[166352,"2026-08-20T18:21:20",17,"/Отход продолжается и снова засада",142532,null],[166353,"2026-08-20T18:21:23",17,"/r +4",142532,null],[166355,"2026-08-20T18:21:34",17,"/ Конрад ыт меня не хочешь пойти искать?",142532,null],[166356,"2026-08-20T18:21:43",17,"/ Я уже думаю начать кричать \"ПОМОГИТЕ!\"",142532,null],[166359,"2026-08-20T18:22:31",27,"// Не бойся. Прибежит стая лютоволков и быстро тебя загрызёт, решив любые твои кабаньи проблемы.",166356,null],[166361,"2026-08-20T18:22:59",17,"/ У меня отход + засада и еще удача которая хранит",142532,null],[166362,"2026-08-20T18:23:06",17,"/ Но возможно пора уже умирать",142532,null],[166363,"2026-08-20T18:23:15",9,"/roll 1d20\n/roll 1d20-1 поиск",142532,null],[166365,"2026-08-20T18:23:24",17,"/ АХАХАХХА ЛОВИ КАБАНЧИК",142532,null],[166366,"2026-08-20T18:23:30",20,"/терпи, господь с тобой ещё не закончил",166362,null],[166367,"2026-08-20T18:24:37",9,"*Кабаны бушуют так сильно что Люпен мог бы поклясться что мельком видел барсука который залез на сосну и держится за голову с мыслью \"что нахер тут происходит\".*",142532,null],[166368,"2026-08-20T18:24:41",9,"//Люпен",142532,null],[166369,"2026-08-20T18:24:45",17,"Охотник заметил что кабаны снова его упустили извиду он двинулся от них подальше подкидывая камень в пращу\n\n\"Если выгорит и я не сдохну, бля... Да обо мне весь лагерь будет судачить! Легенда в одиночку добыл недельный мясной запас!\"\n\nПрицелившись в голову кабанихе он метнул камень что осталось сил",142532,null],[166370,"2026-08-20T18:24:54",17,"/r 3d20-2 Летит",142532,null],[166372,"2026-08-20T18:25:03",31,"Конрад икнул, словно его кто то вспомнил",166355,null],[166373,"2026-08-20T18:25:04",17,"/ 13 На попадание",142532,null],[166374,"2026-08-20T18:25:19",17,"/r d4+12 ПОШЛА",142532,null],[166376,"2026-08-20T18:25:30",17,"/r +4 ПРЯЧУСЬ!",142532,null],[166379,"2026-08-20T18:26:06",17,"/ Кабаны догнали Люпена",166378,null],[166380,"2026-08-20T18:26:21",9,"*Камень ударил кабаниху по голове, но она не слегла за удар, ей было откровенно плевать на ранения.*",142532,null],[166381,"2026-08-20T18:26:34",9,"/roll 1d20\n/roll 1d20-1 поиск",142532,null],[166383,"2026-08-20T18:26:51",17,"/ Бля эти опасные)) У кабанихи еще варварская ярость)",142532,null],[166385,"2026-08-20T18:28:07",9,"*Вепрь бегая как угорелый наткнулся ровнона люпена поцеловав его в лоб мокрым пятачком. Непонимание было лишь мгновением, следующим делом он тебя сожрёт.*\n\n//Твой ход, вепрь впритык, Кабаниза 20 футов",142532,null],[166390,"2026-08-20T18:28:25",9,"//Ты её порося убил, конечно)",166383,null],[166391,"2026-08-20T18:28:44",31,"Мать года/",166390,null],[166392,"2026-08-20T18:28:53",17,"/r +4 Я прячусь отходя, щас может быть конец, но я верю🙏",142532,null],[166395,"2026-08-20T18:29:03",17,"/ НЕПЛОХО",142532,null],[166396,"2026-08-20T18:29:22",9,"/roll 1d20\n/roll 1d20-1 поиск",142532,null],[166399,"2026-08-20T18:29:49",17,"/ БЕЙ КАБАН",142532,null],[166400,"2026-08-20T18:29:53",17,"/ ТЫ ЗАСЛУЖИЛ",142532,null],[166401,"2026-08-20T18:30:31",9,"*Вепрь не собирался тебя упускать и с разбегу бежит ровно за Люпеном, и взмахивает мордой насадить на бивни!*",142532,null],[166402,"2026-08-20T18:30:36",9,"/roll 1d20+5",142532,null],[166406,"2026-08-20T18:31:44",9,"/roll 2d6+3 рубящий\n/roll 2d6 дробящий с разбега",142532,null],[166412,"2026-08-20T18:34:53",9,"*Люпена подкидывает вверх тяжелым ударом, бивень кажется пробил бок, в спине что-то хруснуло.*",142532,null],[166413,"2026-08-20T18:35:09",9,"//Спас силы сл 13 чтобы не оказаться лежачим на земле",142532,null],[166414,"2026-08-20T18:35:57",17,"/r -1 Пошла сила! Я кстате живв?",142532,null],[166416,"2026-08-20T18:36:12",9,"//21 урон)",166414,null],[166417,"2026-08-20T18:36:18",20,"/1 хит походу)",166414,null],[166418,"2026-08-20T18:38:10",17,"/ да 1 хит ебать. Ладно я возьму паузу на подумать. Как раз еду. Пока на этом месте замер. Может Конрад и Рем чето сделают))) поиграйте ))",142532,null],[166421,"2026-08-20T18:39:17",31,"/может Ресу там виденье было что надо спасать Люпена? В его наркотрипе/",142532,null],[166422,"2026-08-20T18:39:20",20,"/я чилю в трипе)",166418,null],[166423,"2026-08-20T18:39:29",9,"*Ты заваливаешься на землю и лежишь, и слышишь шипение? Откуда в поле зрения дым, может тебе превиделось.*",166415,null],[166424,"2026-08-20T18:39:51",9,"/roll 1d20+4 ещё иня",142532,null],[166426,"2026-08-20T18:40:02",17,"/ Ну да, змея еше",142532,null],[166427,"2026-08-20T18:40:07",17,"/ Подколодная!",142532,null],[166428,"2026-08-20T18:40:35",31,"Юань ти спешит на помощь/",142532,null],[166432,"2026-08-20T18:41:31",9,"*Ты в дыму сейчас и кажется дымится и шипит шарик размером с кулак что упал рядом, щиплет глаза.*\n\n//Преимущество на скрыт в дыму",142532,null],[166433,"2026-08-20T18:43:56",9,"// Не спойлерю)",142532,null],[166434,"2026-08-20T18:44:23",17,"/ Мастер уточняю. Я уже не вижу кабана и он не видит меня? Если не видишь не можешь дать провоцирку",142532,null],[166436,"2026-08-20T18:46:24",20,"/ты отлетел на 10ф",166434,null],[166437,"2026-08-20T18:46:32",17,"/r +3 Люпен отползает и кидает рыбацкую сеть из сумки в сторону где был кабан",142532,null],[166440,"2026-08-20T18:46:59",17,"/r +d20+4 Прячемся в дыму",142532,null],[166443,"2026-08-20T18:47:38",9,"// Еще есть последняя вдохнова вродь",142532,null],[166445,"2026-08-20T18:47:48",17,"/ нет",142532,null],[166446,"2026-08-20T18:48:04",17,"/ Ну а чё у него выше 11 пассива?",142532,null],[166447,"2026-08-20T18:48:20",9,"//Когда успел? Но ладно",142532,null],[166448,"2026-08-20T18:48:35",9,"/roll -d20 вепрь ищет, глаза щиплет",142532,null],[166450,"2026-08-20T18:48:39",17,"/ да тут вот кабанов гонял",142532,null],[166452,"2026-08-20T18:49:39",9,"*Кое как ты скрылся и видишь как на вепря сверху падает та самая охотница, она держит в руках по кинджалу.*",142532,null],[166453,"2026-08-20T18:49:55",9,"/roll 1d20+5 первый\n/roll 1d20 второй",142532,null],[166456,"2026-08-20T18:50:21",17,"/ Ааа критт проваааааллл",142532,null],[166457,"2026-08-20T18:50:24",17,"/ ахахаххахахах",142532,null],[166458,"2026-08-20T18:50:31",17,"/ а выпендрежу то было",142532,null],[166459,"2026-08-20T18:50:45",17,"/ )))",142532,null],[166461,"2026-08-20T18:51:04",9,"// А, забыл, засада же)))",142532,null],[166464,"2026-08-20T18:51:31",17,"/ Жеееесть)))",142532,null],[166465,"2026-08-20T18:51:47",9,"/roll 2d4+4\n/roll 1d4 не помню добавляется ли ловкость при сражении двумя",142532,null],[166468,"2026-08-20T18:52:28",31,"Если чкотв ечть на сражение двумя оружиями то да, добавляется/",166465,null],[166472,"2026-08-20T18:54:43",9,"*Два кинджала втыкаются ровно кабану в спину и охотница ловко отпрыгивает в сторону отбегая достаточно далеко от вепря чтобы тот не догнал её сразу учитывая сторону побега и по отношению к кабанихе, которая решила догонять все что движется.*\n\n//Упала с ветки из засады и отбежала на 45 футов, кабаниха погналась за охотницей",142532,null],[166473,"2026-08-20T18:54:50",9,"//Ход Люпена",142532,null],[166484,"2026-08-20T19:13:13",17,"Люпен харкнул кровью на землю\n\nЗакрыл рот и нос рукой и выбежал из дыма куда глаза глядят\n\nБежал теряя кровь дальше и дальше\n\nСпоткнулся, рукой опёрся дерево. На белой коре березы осталась кровавый отпечаток пятерни\n\nОн бежал дальше, чтобы выжить и в конце без сил свалился в заросли ежевики",142532,null],[166485,"2026-08-20T19:13:20",17,"/ Рывок основным и бонусным засада",142532,null],[166486,"2026-08-20T19:13:32",17,"/r +4 Ну вот",142532,null],[166488,"2026-08-20T19:14:44",9,"*Кабан и Кабаниха пытаются догнать охотницу, но та отбывается от них и всегда чуточку быстрее чем те успевают её задеть.*",142532,null],[166489,"2026-08-20T19:15:07",9,"/roll 1d20+5 вепрь\n/roll 1d20 кабаниха",142532,null],[166491,"2026-08-20T19:15:38",9,"/roll 1d4+4 вепрю порезала табло над глазом",142532,null],[166493,"2026-08-20T19:17:53",9,"*Охотница ловко управляется с кинджалами, ее удары точны и целенаправленны сбивающие врагов с толку, те за ней не поспевают.*\n\n// Подвижный и правило сражение двумя = неловить провоцирки уже от двух противников",142532,null],[166494,"2026-08-20T19:18:08",9,"//Люпен, что делаешь",142532,null],[166495,"2026-08-20T19:18:46",17,"/ Я могу кидать камень на 120 футов вижу кабаниху?",142532,null],[166496,"2026-08-20T19:18:51",17,"/ Ну по механике, я отыграю нарративно",142532,null],[166498,"2026-08-20T19:31:42",9,"//Давай, можешь. Охотница агрит кабанов на себя",166495,null],[166505,"2026-08-20T19:48:47",17,"Люпен приходит в себя, это помутнение рассудка прошло так же быстро как и началось\n\nОн вылазит из зарослей ежевики и видит, как между деревьями мелькает белобрысая башка охотницы. А за ней несутся кабаны.\n\nЛюпен вкладывает камень в пращу и раскручивает ее. Делая глубокий вдох он метает камень на упреждение по кабанихе",142532,null],[166506,"2026-08-20T19:48:47",17,"/r 3d20",142532,null],[166508,"2026-08-20T19:49:05",17,"/r 2d4+12 Опа крииииииит",142532,null],[166510,"2026-08-20T19:50:02",9,"//8 урона, на 1 больше чем кабан модет выдержать абилкой и ранее урон был, убил и описывай что делаешь)",166509,null],[166511,"2026-08-20T19:53:46",17,"Крученая подача, камень по дуге пролетает между деревьев и сучков.\n\nОхотница оборачивается в момент когда камень вонзается на огромной скорости в глазницу Кабанихи. От удара она на полной скорости валится на пок и скользит пока не кроется в дерево.\n\nПаралельно между деревьев мелькает раненый оборванец с худой пращой",142532,null],[166512,"2026-08-20T19:53:59",17,"Люпен бежит паралельно скрываясь в зарослях и заряжая новый камень",142532,null],[166513,"2026-08-20T19:54:14",17,"/ На расстоянии держусь двигаюсь паралельно с охотницей и прячусь бонуской",142532,null],[166514,"2026-08-20T19:54:20",17,"/r +4 Засада",142532,null],[166519,"2026-08-20T19:55:49",9,"*Вепрь всё ещё пытается угнаться за охотницей, Люпен стал второстепенной целью.*",142532,null],[166520,"2026-08-20T19:56:09",9,"/roll 1d20+5 \n/roll 1d20 пл вепрю кинджалы",142532,null],[166522,"2026-08-20T19:57:56",9,"*Клинки безуспешно били толстую шкуру, но это было не страшно, ведь хряк не мог поспевать за охотницей которая ловко уверачивалась, даже если мог догнать вкладываясь в бег, оказываясь рядом, момента для удара небыло.*",142532,null],[166523,"2026-08-20T19:58:06",9,"//Люпен",142532,null],[166526,"2026-08-20T20:00:04",17,"Позиция была неудачная оттуда не было видно вепря. \n\nЛюпен принял решение подойти ближе и запрыгнуть на поваленное дерево \n\n/ Засаду сделать не смогу. Прошлый ход. Делаю сперва засаду. И потом атаку чтобы получить преимущество держусь дальше 40 футов от вепря",142532,null],[166528,"2026-08-20T20:00:09",17,"/r +4 Засада",142532,null],[166530,"2026-08-20T20:00:29",17,"/ У меня нет гифки на это",142532,null],[166532,"2026-08-20T20:00:37",17,"/ Упал со ствола на сук и сдох",142532,null],[166533,"2026-08-20T20:00:48",17,"/ Жааааль",142532,null],[166537,"2026-08-20T20:02:24",9,"*Нога застряла в поваленном дереве, оно оказалось пустотелым и протрухшим.*\n\n//Чтобы выбраться из захвата трухлявого дерева проверка силы сл 12",142532,null],[166539,"2026-08-20T20:02:49",9,"/roll 1d20+5 \n/roll 1d20 пл вепрю кинджалы в ход охотницы",142532,null],[166541,"2026-08-20T20:03:32",9,"// Четыре последние броска и на всех 6, что за нах",142532,null],[166543,"2026-08-20T20:04:52",9,"/roll 1d20 мудрость вепря, зверь всё де с опытом",142532,null],[166547,"2026-08-20T20:07:53",9,"*Догонялки продолжались слишком долго, зверь сбавил ход. Ярость поутихла. Выхохнув через нос, палка вялыя бярёзы вылетела из ноздри.*\n\nОхотница на монстров — Что, устал? Я только начала! — *Она с разбегу бьёт по кабану и снова отбегает не давая тому собраться с мыслями.*\n\n//Ускорение и налетчик",142532,null],[166548,"2026-08-20T20:08:15",9,"/roll 1d20+5 бонусным от черты",142532,null],[166550,"2026-08-20T20:08:46",9,"/roll 1d5+4+5 с разбега доп урон и отбегает достаточно далеко",142532,null],[166552,"2026-08-20T20:10:04",9,"*Клинок с набранной инерцией прошил череп животного и остался в нём, Вепрь был все ещё жив. Злой, но уже не настроенный на сражение.*",142532,null],[166553,"2026-08-20T20:10:48",9,"//Люпен, твой ход)",142532,null],[166624,"2026-08-20T21:28:33",17,"/r -1 Тааак я тут спас силы",142532,null],[166629,"2026-08-20T21:30:19",17,"Выбравшись их трухлявого ствола Люпен пал на колени у сосны.\n\nНа нее удобно было залезть и он забрался повыше. Оттуда закрутил наконец пращу и метнул камень в вепря",142532,null],[166630,"2026-08-20T21:30:27",17,"/ Тоже сперва засада. Потом уже атака",142532,null],[166633,"2026-08-20T21:30:41",17,"/r +4 Ну щас то невозможно обосраться?!",142532,null],[166635,"2026-08-20T21:30:56",17,"/r 3d20-2 Ну вроде норм",142532,null],[166637,"2026-08-20T21:31:06",17,"/ 13 по нему на попадание",142532,null],[166638,"2026-08-20T21:31:21",17,"/r d4+12 Неее я в таком диком кайфе от билда",142532,null],[166647,"2026-08-20T21:32:49",9,"// Ну, четко, описывай)",142532,null],[166657,"2026-08-20T21:38:49",17,"Камень не был выпущен с огромной силой, как из пушки. Это не супер заклинание разрушительной мощи. Но Люпен, сукин он сын, просто как то случайно каждый бросок попадал в уязвимые места. А как известно случайности не случайны. \n\nПо неведомой причине камень снова угодил в критическую точку зверю, острый снаряд скалистой породы под идеальным углом влетел в ухо грозному вепрю и так и застрял у него в черепе раздробив мозг грозного зверя. \n\n\nЛюпен сделал максимально удивлённое лицо. Хмыкнул \n\n— Повезло. \n\nСкорчился от боли накатившей новой волной \n\nНачал кряхтя спускаться и брести к охотнице зажимая рукой раны от бивней вепря.\n\nДойдя он лишь сказал ей\n\n— Спасибо, что спасла. Чуть не помер.\n\nИ упал перед ней на колени, а потом и на бок просто на землюшку матушку",142532,null],[166706,"2026-08-20T21:49:16",9,"*Остроухая достала из сумки лезье, кажется оно лечащее, но тянучее, с комочками и кислое. Немного грубо открыв тебе рот силком заставила выпить. Конечно варево было не сахар, она сама его варит.*\n\nОхотница на монстров — Я хотела тебя оценить, а не убить. — *Сказала она пока поила горькачом от которого хотелось сдохнуть.*\n\n//Обычное зелте лечения 2д4+2",166657,null],[166720,"2026-08-20T21:51:43",17,"/r 2d4+2 Я снова живой!",142532,null],[166722,"2026-08-20T21:51:51",17,"/ 8 хитов",142532,null],[166724,"2026-08-20T21:52:23",17,"— Кха уха уха. Это дварфийская жженка? Жгет, хах",142532,null],[166738,"2026-08-20T21:57:43",9,"Охотница на монстров — Жить будешь. — *Она не церемонилась и оставив Люпена лежать на земле пошла резать горла кабанам подвешивая их на верёвках, чтобы кровь стекла, Вепря в одиночку не смогла полноценно подвесить, его морда осталась упирающейся в землю. Снимает кожу пока теплая и это легко, со слоем подкожного сала чтобы не пересохла сильнее необходимого до обработки. Окрестность обсыпала травами, и суетилась слишком сильно делая периодические пробежки в разные стророны, не заявится ли кто сюда.*",142532,null],[166740,"2026-08-20T21:59:28",17,"— Там еще... Сколько же. Пока бежал прибил двух молодых, самку ты видела, вепрь вот тут и дальше всех лежит поросеночек. Надо бы всех собрать.\n\nСмотрит что она решила им головы резать прямо в лесу.\n\n— Слушай, может мы их обвяжем и отволочем в лагерь? Повар там сам распотрошит.",142532,null],[166744,"2026-08-20T22:06:07",9,"Охотница на монстров — Ты хочешь всё это тащить сам на себе? — *Она кажется возмутилась.* — Из тебя никудышний охотник. Кожа должна быть снята сразу или задубеет, мясу положенно стечь кровью пока та ещё текучая и тёплая, иначе останется окровавленным и испортится текстура со вкусом, хранить и есть такое совсем не приятно. Повар пошлет тебя нахер за такое, разве ты не знаешь и этого?\n\n*Она метнула к твоим ногам кинджал.*\n\nОхотница на монстров — Раз есть силы говорить, найдутся и помочь пока свежак.",166740,null],[166747,"2026-08-20T22:11:54",17,"— Да, вижу мне многому можно у тебя научится. Прости, что такой неумеха. Я обычно охотился на мелкую дичь и продавал ее как есть. \n\nЛюпен взял кинжал и пошел помогать свеживать тушу вепря",166744,null],[166749,"2026-08-20T22:12:03",17,"/ Помощь ей? Или мне кидать выживание?",142532,null],[166778,"2026-08-20T22:28:58",9,"Охотница на монстров — Для того кто охотился всю жизнь за зайцами — неплохо. — *Она сделала надрезы и шкура вепря сползала как по маслу до самой головы а потом срезала голову вепря и завернула её в свою кожу, а Вепря оставила лежать на земле.* — Он слишком стар и воняет, не годится, только трофей. Он твой. — *Отдала трофей, голову вепря с иклами завёрнутые в собственную кожу с копытцами.*",166747,null],[166792,"2026-08-20T22:33:08",9,"Охотница на монстров — А теперь помоги снять шкуру с других. Головы просто срезаем полностью и выкидываем, еще надо приготовить дымник и подвесить над ним. Скажу работягам пусть заберут добычу. — *Охотница перестала испытывать Люпена оценив на что тот способен.* — Тебе нужен лук, хороший. Надо держаться как можно дальше от добычи, не бойся от неё убегать и прятаться. Если же добыча прячется от тебя, слишком близко или быстрее при этом с лёгкостью может тебя прикончить — беги.",142532,null],[166804,"2026-08-20T22:37:38",17,"Пока они шли к туше кабанихи\n\n— Слова твои... Правдивы полностью, я сегодня отведал клыков вепря под ребрами. Думал богу душу отдам.\n\nОн принимает трофеи и складывает в свою нищую сумку. \n\n— Да, добрый лук, то что мне надо. Кстате, ты сказала сучья вялой берьёзы не подойдут для лука, а какую древесину посоветуешь?\n\nЛюпен опустился около туши Кабанихи и начал пытаться делать надрезы повторяя точь в точь за разрезами охотницы",166792,null],[166806,"2026-08-20T22:37:46",17,"/r +2 Ну не обосрись!",142532,null],[166822,"2026-08-20T22:40:30",9,"Охотница на монстров — Думаю тебе нужна практика... на одну пушнину у тебя будет меньше, продолжай. — *Она кажется смирилась что ты профан, даже закатила глаза но ничего не сказала. Она взяла твои руки своими руками и начала направлять.* — Вот так, и тут.\n\n//Помощь",166807,null],[166827,"2026-08-20T22:42:35",9,"Охотница на монстров — Видишь, уже лучше. Теперь сам.",142532,null],[166844,"2026-08-20T22:47:25",17,"В помощью и по наставлению ментора, молодой охотник делает надрезы по туше до самой головы и шкура слазит хорошо.\n\nТеперь голова была отрезана и выброшена, как охотница учила.\n\nЛюпен пробует сам",142532,null],[166845,"2026-08-20T22:47:32",17,"/r +2 Выживалити",142532,null],[166878,"2026-08-20T22:56:17",9,"*Видя что ты уже справляешься она сняла кожу с третьей туши самостоятельно и занялась сборкой листвы и прочего для дымника. Выбирала влажные трухляки с валежником да мхом, и тем что не имеет резкого запаха, листья траву, чтобы разжечь её под подвешенными тушами, и срезала окорки с задними ногами кабанихи полностью. Один окорок себе а второй Люпену, попутно поведав что добыча из женской особи вкуснее.*\n\nОхотница на монстров — Это убережёт добычу от животных и насекомых пока её не заберут. — *Полив водой из фляги она подожгла кострище и проследила чтобы оно дымело. Нужен лишь дым, не костер, не для готоки.*",166847,null],[166888,"2026-08-20T23:28:37",9,"Охотница на монстров — Старайся не убиыать молодых животных. Они — будущая добыча.",142532,null],[166891,"2026-08-20T23:32:18",17,"— Я запомню твою науку. Молодого я от того, что крупных не заметил прибил. Щас понимаю, что поспешил.\n\nЛюпен выдернул камень из глаза Кабанихи. \n\n\"Счастливый камешек будет\"\n\nПоложил его себе в сумку. \n\n— Ты давно с Жанной? Научилась охотится тут по необходимости выживать или где то напрямую ещё обучают этому ремеслу?",166878,null],[166906,"2026-08-20T23:47:23",9,"Охотница на монстров — С наемниками проще всего. Каждый получает то что вложил, честно и по заслугам. — *Она едва заметно задумалась прежде чем ответила.* — Я ведьмец, чародеи, дети с испорченной кровью усиленные зельями. Алхимия жестокая наука. Магический талант предка не всегда проявляется у детей, тело же можно заставить проявить физическую мощь насильно. — *Она усмехнулась, словно не придавала этому много значения.* — Называя это селекцией, я сама перерезала глотку парочке так называемых учёных. Со мной лишь ужасный облик, почти бесконечная выносливость и разум быстрее тела, постоянное угнетающее ощущение, словно плывёшь в воде что мешает свободно двигаться а люди говорят медленно и их приходится ждать.\n\n*Не смотря на слова, кажется она гордится своей особенностью.*",166891,null],[166908,"2026-08-20T23:50:42",9,"Охотница на монстров — Всему что умею научила жизнь.",142532,null],[166910,"2026-08-20T23:54:27",17,"— Да ну.. брось ты. Прям уж такой и ужасный облик у тебя. Нормальный облик. Симпатичный даже. \n\nЛюпен набрал ворох листвы для задымления около тела кабана пониже \n\n— Вот в чем я с тобой с радостью соглашусь, что жизнь лучший учитель. Иногда так с размаху даст тебе по яйцам, что выжить захочешь, научишься. \n\n— Я мечтаю поквитаться с одним чудищем, он в меня семью отнял, жену, дочку и сына. Занял мое место сволочь. Внешность сделал гад, ровно мою. Только уши поострее. Ее знаешь что за гадина?",166906,null],[166914,"2026-08-20T23:58:28",9,"Охотница на монстров — Неа, я охочусь только на монстров которых можно перехитрить или взять на измор. — *Даже думать не стала, ответила сразу и дала совет:* — Самый страшный враг — разумный. Особенно тот кто умнее тебя.",166910,null],[166918,"2026-08-21T00:02:30",17,"— Да он не только умнее похоже, а ещё и сильнее в два раза. Отметелил меня перед всей деревней. Живого места не оставил. Вот теперь мечтаю когда нибудь поквитаться... Ладно если не знаешь, ничего страшного. Доберусь до него позже.\n\n— Ну кажестя со всех шкуру спустили, трофеи забрали. Костры запалили для сборщиков. Что дальше?",142532,null],[166919,"2026-08-21T00:10:05",9,"*Она взглянула на небо, было немного за полдень.*\n\nОхотница на монстров — Иди отдыхай, зелье поможет, но без хорошего сна не оправиться. Я скажу что ты постарался. — *Она улыбнулась.* — Добро пожаловать в наёмники — \"охотник\". — *Последнее слово она произнесла с насмешкой соберая свои вещи.* — Никогда не ходи по этим лесам один. Если тебе будет нужен хороший лук — найдёшь меня завтра.\n\n*Прихватив свои пожмтки она направляется по тропам в лагерьс её шаг всё равно немного быстрый чтобы не вызвать лёгкой задышки у попутчика если тот решит идти рядом.*",166918,null],[166921,"2026-08-21T00:15:22",17,"Люпен улыбнулся \n\n\"Ох будет у меня лук, я такоооое покажу\"\n\nПоплелся за седой, зажимая уже частично затянутую от зелья рану. Старался не отставать. Он был собой сегодня очень доволен, хоть и ходил по лезвию смерти несколько раз.\n\nЕсли задуматься сколько раз вепрь по счастливой случайности не смог насадитье го на клыки? Раз? Два? На третий все таки смог, но по всем признакам, Люпен сегодня должен был умереть. Похоже богиня удачи присматривает за ним и не дала этому случится.\n\n\"Надеюсь ты от души посмеялась, пока я носился по кустам… богиня удачи?\"",166919,null],[166922,"2026-08-21T00:19:26",9,"*Герои возвращаются в лагерь, а пока...*\n\n//Продолжение следует)",166921,null],[166923,"2026-08-21T00:20:04",9,"//Такс, завтра, тоесть сегодня, надо нашу парочку расчехнить. Надеюсь Конрад будет поактивнее",142532,null],[166927,"2026-08-21T03:07:04",31,"Я тоже надеюсь. Но вообще грех было влезать в такой эпик, только нерв игры ломать. Ну и ждал когда уже охотница появится/) вообще, очень сочная охота вышла, как зрителю зашло прямо//",142532,null],[166933,"2026-08-21T07:44:26",9,"//Знал что следит?)",166927,null],[166935,"2026-08-21T08:25:13",31,"Откуда мне знать? Я просто предположил такой ход, что ты не захочешь убивать иоитка просто так и явно пустишь кого то ему на подмогу, либо ее, что вероятно, либо Димку, который пойдет спасать//",166933,null],[166936,"2026-08-21T08:26:58",9,"//Димку ты сам не повёл, а охотница хоть была на подстраховке, она откровенно слабая и не дамажная, могла не зарешать. Но ладно, это я уже в обсуждении квестов говорил)",166935,null],[166939,"2026-08-21T08:42:56",9,"*Молодой мастер Чиф поняв что Конрад не особо переживает за товарища, слегка покачал головой.*\n\nМолодой (Чифтер Люск) — Ладно. Надесь с ним ничего не случилось.\n\nВоин в больших доспехах (Димон) — Наука и кирпичи. Используйте руки, руки и руки. — *Здоровяка кажется показабавито \"как именно\" Конрад работает писарем, а может хотел дать совет? Так и не разберёшь.* — Вылейте воду в воду и сделайте воду.\n\n*Вода плохо брала вековую грязь, но с помощью щёток и куска мыла удалось более менее смести всю грязь с шаров.*\n\nМолодой (Чифтер Люск) — Пошли Дим, сегодня я с тобой на охоту пойду. Разделывать туши всяко умею лучше тебя. — *Немного подкалывал его Чиф.*\n\n*Димон не обижался, просто кивнул Конраду, кажется поиски Люпена на этом закончились.*\n\nВоин в больших доспехах (Димон) — Брюки. Штаны используются для брюк. — *Парировал здоровяк Чиф признаться не нашёл что ему ответить.*\n\n// @QURTZZ ну, это уже к тебе",142532,null],[166960,"2026-08-21T09:28:43",31,"*мысль*\n\n- да уж, интересно что бы нашел в голове Димки знающий доктор?",142532,null],[166961,"2026-08-21T09:29:38",31,"Тащу шары обратно в здание\n\n- принимайте работу. Но я вроде как сюда приходил не совсем для этого, щёткой работать можно и будучи безграмотным",142532,null],[167013,"2026-08-21T12:18:27",9,"Белобрысый ученый (Лазарь) — Я не вижу чтобы вы обмылись и обсохли. — *Маг вместе с Соном Тин-Паундом сейчас возились с малой алхимией и пробирками, нв столе было пробирка с ртутью, кусок овечьей шерсти и засохшие какашки летучих мышей да медная проволока.* — Помниться я просил вас привести себя в порядок тоже. Поработать вы всегда успеете, но в таком виде переписывать бумаги не лучшая идея.",165416,null],[167014,"2026-08-21T12:20:18",31,"- глянь на мои руки. Пока я чистил камни, то и по рукам прошелся не раз, они чисты",167013,null],[167019,"2026-08-21T12:23:24",9,"*Ученый вздохнул и оставил дела подошёл к Конраду ближе пряча руки в мантии. Рядом с ним Сон извиняющейся улыбнулся Конраду, похоже учитель был со своими заморочками.*\n\nБелобрысый ученый (Лазарь) — Прошу, коснитесь своей рубахи господин Конрад.",167014,null],[167021,"2026-08-21T12:24:23",31,"Выполняю",167019,null],[167049,"2026-08-21T12:41:38",31,"Провёл руками по одежде, вытерев из таким образом от остатков воды.\n\n- ну, и?",142532,null],[167101,"2026-08-21T13:00:30",9,"Белобрысый ученый (Лазарь) — Теперь руки нельзя назвать чистыми. Возвращайся когда сделаешь то что я попросил, или не возвращайся вовсе. — *Лащарь не злился, в просто говорил что думает намекая что запачкать руки легче чем кажется и он просто не пустит пачкать документы.* — То что вы обученны грамоте это прекрасно, но необходимо быть хоть сколько то опрятным чтобы работать с важной документацией. Увы, я не смогу предложить вам эту работу если вы не будете соответствовать. Держать себя в должном виде будет столь же важной задачей для вас как и классификация с сортировкой бумаг если вы стремитесь занять здесь своё место.\n\n*Похоже проблема была не только в безграмотности большей части наёмников и археологов когда Жанка вас закинула сюда. Мало кто захочет работать со строгим и душным магом. В этот момент в комнату зашла та молодая девушка из писарей.*\n\nДевушка из писарей (Лика) — Дедушка Одисей не проснулся? Может стоит его разбудить. — *Девушка взглянула на дверь в комнату алхимика, там ничего не поменялось. Сама она пришла с чайником из которого отлично пахло чаем.*\n\nБелобрысый ученый (Лазарь) — Не стоит. Пока он отдыхает это место достаточно тихое и спокойное. — *Лишь отмахнулся от переживаний девушки и взглянул на Рена.* — Уже мирно спит, думаю скоро пора его будить, как заварится чай.",142532,null],[167129,"2026-08-21T13:07:00",31,"- я тебя понял. Скоро вернусь\n\nМысль: на кой хер я это терплю?\n\nВыхожу из здания, опркидываю на себя пару вёдер воды, отскребываюсь от грязи, возвращаюсь\n\n- теперь я достаточно чист для этой обители знаний? Или мне нужно в кислоте искупаться, чтобы и кожи не осталось, которую можно запачкать?",142532,null],[167137,"2026-08-21T13:20:49",9,"Белобрысый ученый (Лазарь) — Подожди снаружи и обсохни. Я попрошу Сона подготовить твоё рабочее место. — *Учёный дердал на столе несколько книг, сверяясь с ними по очереди и так же исчерпавыюще давал указание.*\n\n*Рен к этому времени уже слышал окружающие голоса. Просыпался ли он? Спал ли вообще? Лежал в полудрёме? Может все сразу? Да.*\n\n*Сон подошёл к Конраду, положил руку на поечо, словно \"старший\" и тихо сказал:*\n\nПарень, ученик Лазаря (Сон) — Учитель сегодня в хорошем расположении духа, не сильно обращай внимания, он всегда так. — *Сон извиняющеся улыбнулся.* — Извини за учителя, он всегда так.",167129,null],[167142,"2026-08-21T13:22:18",31,"- а, это еще хорошее, значит...\n\nВыхожу обсохнуть. \n\n//на улице хотя бы солнце светит? Или все заволокло туманом духоты?//",142532,null],[167166,"2026-08-21T13:32:29",9,"*Солнца за некротическими облаками дают все то же мрачное сизое освещение с лёгкой синевой. Все щаволокло туманом духоты.*",142532,null],[167169,"2026-08-21T13:34:05",9,"*У тебе подходит знакомый полурослик, тот что на побегушках у Жанки, и спрашивает горда хмыкнув:*\n\nПолурослик (кларк) — Как сработался с \"коллегами\"? — *Видит что ты обсыхаешь все еще в влажной одежде.* — Лазарь снова не пускает никого за документы, ясно ясно.",167142,null],[167173,"2026-08-21T13:35:05",31,"- ага, обтекаю весь день. Чую, не сработаемся мы с этим Лазарем. Рано или поздно я его ударю, а он мне поджарит задницу. Надо поискать себе другое место",167169,null],[167271,"2026-08-21T14:29:15",9,"Полурослик (кларк) — А где мелкий. Ну, пацан? — *Не найдя Рена глазами спросил полурослик.* — Лазарь его принял к себе? Или того, прибил уже. — *Показывает жест мол писец котёнку, но не серьёзно, ухмыляется.*",167173,null],[167293,"2026-08-21T14:33:40",9,"// @PaIIasCat можешь уже очнуться и играть 👌",167137,null],[167321,"2026-08-21T14:47:39",31,"- он пацана напоил каким то зельем, ипа это ему поможет развиваться, если не убьет к херам. Мутный он, Лазарь этот",167271,null],[167360,"2026-08-21T14:58:00",9,"Полурослик (кларк) — Совсем за пацана не переживаешь? А то что говоришь как есть хорошо. — *Полурослик почесал подбородок и спросил.* — Может нахер Лазаря, я смотрю ты крепкий малый. Морды бить умеешь?",167321,null],[167368,"2026-08-21T15:01:28",31,"- переживаю, но я ему не папа и не мама, у него своя голова есть и свои тайны и стремления. Он сам решил эту дрянь выпить, пусть теперь сам переживает последствия. А что до мордобития... Ну, вообще да, умею, правда, больше руками а не оружием",167360,null],[167397,"2026-08-21T15:09:09",9,"Полурослик (кларк) — И то правда. — *Кларк думал что пацан родной или знакомый, но раз нет и не спросит более.* — Руками ещё лучше, дело такое, вояки постоянно спарингуются под вечер. Я и мои друзья любим организовать ставки с небольшими наградами участникам, чтобы честно сражались. Новое лицо на ринге все будут рады увидеть.\n\n*Кларк хитро предложил тебе поучавствовать в незатейливом деле, бои. Подпольными их конечно не назовешь, не то место, но все же.*\n\nПолурослик (кларк) — Заработать можно побольше чем возясь с писаниной. А маг пусть сам ебётся с чернильницой.",167368,null],[167398,"2026-08-21T15:09:46",20,"*Пацан тем временем слабо шевелится, сдерживая слабый стон остаточной боли и пытаясь найти силы открыть глаза, чтобы проверить, точно ли он жив. Сил особо не было, по один глаз полуоткрыть получилось*\n\n*В голове все было слегка туманно и следы видения, корое он видел ещё смутно окружали его, мешая реальность со сном*\n\n*На секунду ему показалось что он все ещё видет те глаза, пристально смотрящие на него...но вот моргнул - и видение растаяло, когда перед глазами проступили размытые очертании палатки магов.*",167137,null],[167406,"2026-08-21T15:14:53",9,"Белобрысый ученый (Лазарь) — Приходишь в себя? Травяной чай готов, Лика, помоги парню. — *Маг скурпулезно что-то записывал в свиток.*\n\nДевушка из писарей (Лика) — Вот, чай. Привет, я Лика. — *Девушка помогла рену подняться и подала горячий травяной напиток на блюдце, с мёдоми лепёшкой которая немного уже остыла.* — Как себя чувствуешь, уже получше?",167398,null],[167408,"2026-08-21T15:15:40",20,"/а как я себя кстати чувствую? Помимо степеней истощения есть что-то?",167406,null],[167412,"2026-08-21T15:16:27",9,"//Слабость во всем теле из за истощения, немного жар в груди может быть или что-то такое",167408,null],[167419,"2026-08-21T15:20:47",20,"- Р-рен... *Голос вышел почти шепотом, когда пацан благодарно кивнул, беря чай и делая глоток* - спасибо, Лика \n\n*Он продолжал делать небольшие размеренные глотки, стараясь вернуть разум 'на землю', сосредоточившись на ощущениях тела. Слабость, жар... Хорошо, значит он все ещё жив - думал он, кусая лепешку.*\n\n*Когда Рен более менее пришел в себя после пары минут он всё-таки задал вопрос, который волновал его больше всего теперь когда он очнулся*\n\n-...сработало?",167406,null],[167426,"2026-08-21T15:23:18",31,"- интересная мысль, думаю, попробовать стоит",167397,null],[167443,"2026-08-21T15:28:54",9,"Белобрысый ученый (Лазарь) — Можем проверить, Сон, Рен, идите сюда. — *Лазарь достал из шкафчика иглу большую по которой пробегала жёлтая вспышка элекричества, словно молния.*\n\nПарень, ученик Лазаря (Сон) — Да, сейчас... — *Это кажется был Сон, он подошел ближе, но его слегка передернуло когда на игле вспыхнул очередной всплеск элекричества. Он знал что-то и не очень хотел повторять.*",167419,null],[167455,"2026-08-21T15:34:25",20,"*Рен кое как встаёт, подходя ближе и смотря на иглу с отстранённым любопытством*\n\n- Это будет просто больно или как с зельем? *Уточняет он спокойно, возможно даже слишком. Может ещё не до конца в себе, кто знает*",167443,null],[167456,"2026-08-21T15:34:55",9,"//Стыренные концепт арты, оригинал и что вышло 😏👌",142532,null],[167458,"2026-08-21T15:36:05",20,"/какой-то фул собираем - сначала испытание травами, теперь электрошок",142532,null],[167474,"2026-08-21T15:46:04",9,"*Лазарь сам поднес свой палец и его укусила вспышка едва едва.*\n\nБелобрысый ученый (Лазарь) —  Как комар укусит. — *Он резко направил эту иглу на Сона и парень резко отпрыгнул на метр.*\n\nПарень, ученик Лазаря (Сон) — Учитель, вы бы хоть прелупредили! Больно. — *Он потел руку, следов небыло, ноего ударило сильнее чем Лазаря.*\n\nБелобрысый ученый (Лазарь) — Знаешь что маги в зоне антимагии плохо снбя чувствуют? Чем силтнее их магическая сила, тем хуже ведь она становится их частью. — *Он наклоняет иглу на деревянной ручке в сторону Рена.* — Сейчас на тебя действует зелье пробуджения, может горят нервные окончания или огонь внутри, если он есть — это движение магической силы, и сейчас она кипит, но вскоре успокоится. Попробуй закрепить это ощущение и прочувствовать как можно сильнее. — *Он сделал паузу, давая осознать его слова, а после добавил.* — Эта игла неизвестного происхождения реагирует на живые потоки магии один из которых и есть внутренний резерв. Мой слишком скуден чтобы эта вещь полноценно отреагировала, у Сона же талант, лишь не достает опыта. Сейчас, когда магия кипит можешь попытаться коснутся этого предмета, таким образом на глаз мы сможем определить твой резерв.\n\n*Предлагает коснуться иглы по которой бегают золотистые молнии.*",167455,null],[167475,"2026-08-21T15:50:15",20,"*Рен кивает, протягивая палец к игле. Он внутреннее готовит себя - не к боли. К разочарованию*\n\n*Если отклика не будет это будет больнее, чем укол иглы, стрела или даже зелье*\n\n*Лишь бы с работало...ему будет достаточно и небольшой искры, которую можно будет отточить*",167474,null],[167486,"2026-08-21T16:08:33",9,"*В ответ по руке проходится обжигающая искра, не такая сильная чтобы отскочить как Сон, можно вытерпеть, но сильнее чем у учителя.*\n\n//Реакция?",167475,null],[167487,"2026-08-21T16:09:53",20,"*Рен слегка задерживает руку, что лучше понять свои ощущения.*",167486,null],[167492,"2026-08-21T16:18:24",9,"*Обжигает нервные окончания, те горят сильнее в месте соприкосновения. Тот же самый непонятный жар что чувствовался внутри после того как очнулмя, только там где пробежалась молния. Видя что реакция есть, Лазарь вскоре убрал иглу.*\n\nБелобрысый ученый (Лазарь) — Неплохо, даже отлично. Основы лучше чем у меня. — *Он спрятал иглу обратно в шкаф.* — Когда мне попала эта вещь в руки только начал изучать магию, отклика почти небыло, лишь лёгкая дрожь на кончиках пальцев. Внутренний резерв можно расширить.\n\n*Сон стоял рядом и слушал, он улыбался. Может чужому успеху, а может что случайный парень не окащался лучше чем он? Так сразу и не разберёшь. Лика пока тоже не вмешивалась.*\n\nБелобрысый ученый (Лазарь) — Остался лишь один момент. — *Он повернулся у Рену и посмотрел тому прямо в глаза задавая вопрос.* — Ты хочешь стать моим вторым учеником и постигать тайным магии. Уверен ты сможешь стать отличным чародеем и без посторонней помощи, но по моему личному мнению знания намного сильнее, приобретённые стараниями и трудом, дадут намногобольше пользы с твоими данными.",167487,null],[167493,"2026-08-21T16:22:53",20,"- Я хочу стать учеником *Кивает Рен, успокоенный тем, что отклик все же есть.*\n\n*Он говорил это уверенно. Возможно чародеи и сильны, но их магия видилась мальчику слишком стихийной и хаотичной. И он не хотел полагаться только на природный талант и удачу. Как никак в этой жизни он ценил больше всего две вещи - контроль и порядок, в том числе и над самим собой*",167492,null],[167494,"2026-08-21T16:23:54",9,"Полурослик (кларк) — Тогда иди шли нахрен колдуна. Вечером приходи вон к той разваленной башне, будет развлеяение. — *Он улыбнулся и сощурил глаза.* — Если хорошо себя покажешь пристрою тебя так чтобы работы поменьше и платили как писарю в свободное время.",167426,null],[167495,"2026-08-21T16:24:29",31,"Я за руль на 3-4 часа, отпишу как доеду//",167494,null],[167497,"2026-08-21T16:31:42",9,"Парень, ученик Лазаря (Сон) — Поздравляю. — *Парень подошел и пожал тебе руку.* — Учитель, мне искать шляпу?\n\nБелобрысый ученый (Лазарь) — Пособия по заговорам и настройке на магические предметы в том числе. — *Поправил он ученика.*\n\nПарень, ученик Лазаря (Сон) — Да, конечно. Надо попросить еще новый стол и убрать один из углов.\n\nДевушка из писарей (Лика) — Так, всё. Пусть ест и отдыхает! — *Она подошла и пихнула Рену лепешку, уже остывшую.* — Щас на кухню сбегаю, новых принесу.\n\nБелобрысый ученый (Лазарь) — Не докучайте ему. — *Остудил он немного их пыл.* — Зелье крепко его вымотало, пусть отдыхает и не занимается ничем выматывающим пару дней. — *Он посмотрел на Рена.* — Это я говорю тебе, сосредоточься на ощущениях и закрепи их. До послезавтра свободен делать что хочешь.",167493,null],[167499,"2026-08-21T16:40:29",20,"*Рен кивает, держа в руках лепешку и провожая шумную парочку в лице Сона и Лики взглядом. Какие беззаботные...Он слегка улыбнулся*\n\n- Хорошо, я понял. Где здесь можно привести себя в порядок? *Он оглядывает свои запачканный обноски. Теперь когда появилась возможность хоть немного навести чистоту в спокойной обстановке он очень не хотел ее упускать.*",167497,null],[167502,"2026-08-21T17:00:58",9,"*Ты смотришь на свои обноски, они идеально чисты как и ты сам, ни единого пятнышка. Фокусы какие-то.*\n\nБелобрысый ученый (Лазарь) — Новая одежда тебе пригодится. — *Он достает тёмно зеленую мантию, как у себя и его ученика — Сона. На ней и кошель в котором ровно 10 золотых, 10 серебрянных и 10 медях.* — Это на расходы. Помогая мне и учась здесь будешь получать по 10 золотых в день (считай работаешь волшебником на простое). Помимо учёбы у тебя здесь будут и другие обязанности. Когда прийдёшь в себя можешь пойти у складам купить необходимое. Книги и чернила у нас...\n\nБУМ!!!\n\n*Звук вспышки справа, дым из комнаты алхимика, оттуда вывалился дед, он был ростом не больше Рена и кашлял. От взрыва немногозвинело в ушах. Лазарь сделал жест рукой и дверь за алхимиком закрылась.*\n\nБелобрысый ученый (Лазарь) — Одиссей, ты закаптишь все книги. — *Дед его не слышал, вообще не среагировал. Лазарь вздохнул и покрутил медную запонку на рукаве (серьга сообщения) бормоча что-то себе под нос.*\n\nСтарый алхимик (Одисей) — Аааа, колдун ебучий, хватит мне лезть в мозги, я тебя слышу! — *В Лазаря что-то полетело, но перед магом возник щит и книга просто отскочила от него. Дед был немного не в себе.*\n\nБелобрысый ученый (Лазарь) — Думал он спит. Оказывается всю ночь что-то варил у себя. — *Наклоняется к Рену.* — Одиссей плохо слышит, сейчас из-за неудачи он скорей всего в бешенстве. Не тревожь старика пока не успокоится.\n\nСтарый алхимик (Одисей) — Нет! Да! Как оно могло, я почти сделал его, почти, камень мой камушек... — *Дед ударил слабыми руками по двери своего кабинета несколько раз, а потом сполз на пол, сидит и плачет.*",167499,null],[167503,"2026-08-21T17:07:33",20,"*Рен держит в руках одежду, переводя взгляд со своего нового учителя на плачущего алхимики (решая его пока не трогать, хоть и очень любопытно над чем тот работал - а то вдруг попадет под горячую руку). Мда, похоже даже в стремящемся к системности мире магии всегда найдется место хаосу. Нужно учится с этим жить. Эта мысль снова вызывает у него слегка кривую улыбку*\n\n*Он кивает Лазарю и отправляется переодеваться*\n\n/Я так понимаю маскировку цвета у него с волос фокусами счистили?",167502,null],[167507,"2026-08-21T17:09:53",9,"//Выходит что так)",167503,null],[167511,"2026-08-21T17:19:40",9,"*Лика принесла еще еды, солонину со свежими лепешками, яблоко и лук. Сон потихоньку начал разбирать завал в одном из углов.*\n\n*Алхимик заснул возле двери в свой кабинет и засопел, похоже и правда всю ночь не спал и уторо до обеда. Сон подмостил тому подушку а Лика укрыла.*\n\n*Лазарь же сидя на кресле пил кофе задумчиво глядя куда то вперед, пока перо словно живое само писало по страницам что у него на уме.*\n\n//Сейчас ты волен делать что захочешь, тебе посоветовали сходить на склад закупиться если что надо когда будут силы. А так взаемодействуй с персонажами, болтай и тд. Дали по 10 золота, серебра и меди.",167503,null],[167512,"2026-08-21T17:20:24",9,"//И тёмно щеленую мантию дали)",167511,null],[167513,"2026-08-21T17:20:32",20,"/а Лазарь похоже ордена Писарей",142532,null],[167514,"2026-08-21T17:22:18",9,"*Уже было за полдень когда вы воротились в лагерь. Охотница ворвалась на склад и командным тоном указала где ожидает добыча и что надо ее забрать пока не стемнело. Ночью из лагеря выходить было опасно.*\n\n//Есть заявки?",166921,null],[167515,"2026-08-21T17:22:41",9,"//Или у него есть то писчее перо с настройкой 😏👌",167513,null],[167559,"2026-08-21T18:11:27",9,"//Жду корочеваших заявок, или чутка перерыв если их нет, ток Конрада на бои сводить выходит.",142532,null],[167631,"2026-08-21T19:11:31",20,"*Рен находит уединённое место, стягивая с себя лохмотья и переодеваясь в чистую новую мантию.*\n\n\"Какая всё-таки полезная вещь эта магия...\" - думает он, разглядывая свою кожу на которой нет и следа преждей грязи. - \"... как не бывало\"\n\n*И тут его нагоняет осознание, прошибая холодным потом. Рука метнулась к волосам. Ни следа грязи, ни следа золы, которую он втирал. Чистый цвет, который он так старательно прятал. Первая мысль - быстрее спрятать, снова скрыть. Но потом он замирает, опуская руку, когда ему приходит осознание*\n\n*Он больше не там, где это хоть что-то значило. Сейчас это просто цвет. Просто ещё одна черта, которую все просто пропустят или спишут на чародейской происхождение, как глаза. Нет смысла это прятать.*\n\n\"Забавно. Все это время я пытался скрыть их... А выдавали всегда не они, а глаза\" - он криво усмехается\n\n\"Правда, это самый острый клинок который кто когда либо держал в руках.\" - снова звучат в голове слова того голоса из ведения.\n\n*Рен поправляет рукав мантии, выпрямляясь. Уже не скрывая ни золотистого отблеска, ни алых прядей. Потому что он наконец-то начал усваивать свой самый важный урок - правда всегда будет совершенней лжи. И в этот раз его маска будет соткана именно из нее.*\n\n*Закончив с этим, юный ученик мага развернулся, возвращаясь в палатку - на встречу своей новой роли*",167511,null],[167632,"2026-08-21T19:12:58",20,"/все, пацан отправляется помогать Солу разгребать место\n/А я пошла обновлю его арт в новой мантии",142532,null],[167633,"2026-08-21T19:13:28",9,"//На заметку, магам домину деревянную пристроили, это остальные в палатках и юртах)",142532,null],[167634,"2026-08-21T19:16:23",20,"/кайф)",167633,null],[167635,"2026-08-21T19:17:12",20,"/все, теперь его точно из этого места добровольно не вытащить",142532,null],[167650,"2026-08-21T20:33:53",31,"Возвращаюсь в домик умников, обращаюсь к Лазарю:\n\n- думаю, моё появление тут было ошибкой. Пожалуй, пойду я дальше по своим делам. О, Рен, рад что ты очнулся, надеюсь больше не увижу тебя в таком состоянии",167494,null],[167651,"2026-08-21T20:34:50",31,"Выхожу и ищу ту самую разваленую башню.\n\n//время к вечеру уже?//",142532,null],[167656,"2026-08-21T20:52:54",20,"*Пацан машет ему рукой с улыбкой. Выглядит все ещё бледноватым, но довольным*\n\n*Он надеется что конрад тоже найдет себе дело по душе*",167650,null],[167680,"2026-08-21T21:12:00",9,"*Время к вечеру, правда ещё относительно светло. Ты подходишь к месту немного огражденном хлипким забором на скорую руку, импровизированный ринт. Вокруг бочки, импровтщированные столы, только несколько увальней сейчас тут, народ лишь начинает собираться. На самом же ринге два мужика голые по пояс обмазанные маслом пытаются взять друг друга в захват и повалить на пол, но так как они в масле, простой силой дело не обходится, лишь толчки, выверенное движение, и ловкость. Их рубахи сейчас на заборе.*",167651,null],[167686,"2026-08-21T21:15:09",9,"//Турецкий вид спорта, маслянная борьба 😏👌",142532,null],[167727,"2026-08-21T21:52:40",17,"/ Тааакс щас буду читать все",142532,null],[167728,"2026-08-21T21:52:55",17,"/ Чё тут пацан уже на короткой ноге с верхушкой?",142532,null],[167729,"2026-08-21T21:53:46",20,"/пока не, но жилищные условия апнулись",167728,null],[167735,"2026-08-21T21:58:35",17,"— Если ты не против, я бы помог тебе ещё. Есть какое нибудь дело? И кстате как тебя звать. Я Люпен.",167514,null],[167804,"2026-08-22T14:33:53",31,"Мысли:\n- о, ну тут то наверное я окажусь в своей стихии. \n\nОглядываюсь, где тут регистратор или кто то еще, кто организует бои",167680,null],[167871,"2026-08-22T18:57:13",9,"Охотница на монстров (Имельда или Шельма) — Тебе нужно моё настоящее имя, или прозвище? — *Она наклонила голову и улыбнулась слегка более чем надо осрыми зубами.* — Имельда. Прозвище правда немного интереснее — Шельма. Как после такого прозвища не кошмарить людей?",167735,null],[167872,"2026-08-22T18:57:37",9,"*Никого не видно, только странный кот, невероятно странный кот...*",167804,null],[167875,"2026-08-22T19:00:17",9,"*Страшный как тысяча чертей рыжий кот сидит и курит трубку, чистит рыбку, внимательно наблюдает за боем.*",142532,null],[167879,"2026-08-22T19:03:25",47,"/чем занимается мой товарищ?",142532,null],[167882,"2026-08-22T19:05:42",9,"//С рыбалки времени день прошло игрового, но произошло писец как много)",167879,null],[167898,"2026-08-22T19:28:52",9,"*В хижине волшебников царил хаос, надо было освободить целый угол! Сон не мог там пройти и поэтому волшебной рукой перекладывал книги, безделушки и записи с одной кучи на другую. Некоторые вещи были слишком тяжелы для заклинания, пришлось передвигать их в ручную.*\n\n*Лазарь, словно забыл о Рене, погрузился в книги.*\n\n*Лика убедившись что парень хорошо поел и более менее нормаль себя чувствует уже сидела за рабочим местом точно работая с чертежами.*\n\n*Одиссей спал под дверью где его оставилт, дед выглядел немного покинутым, но на деле его поведение уже воспринимали как должное.*\n\nПарень, ученик Лазаря (Сон) — Нашёл. — *Сон волшебной рукой подтягивает к себе старую шляпу.* — Сколько воспоминаний, с её помощью я наложил своё первое заклинание.\n\n//Он держит в своих руках обычный магический предмет \"шляпу волшебства\"",167729,null],[167904,"2026-08-22T19:32:14",17,"— А что звучит отлично. Шельма. Тебе подходит. Что ж, тебе нужна моя помощь в чем то, точнее я бы пошел занялся полезным делом ты только направь. Ну и... Лук свой собственный заиметь хотелось бы.",167871,null],[167907,"2026-08-22T19:35:39",9,"Охотница на монстров (Имельда или Шельма) — А у тебя есть материал? Охотник должен сделать свой лук сам. — *Казалось она имела какие-то свои заморочки по этому поводу.*",167904,null],[167919,"2026-08-22T19:46:58",17,"— У меня есть упругая ветвь вялой берьёзы. Трофеи с кабана и рыбацкие снасти. Это все.",142532,null],[167925,"2026-08-22T19:49:16",9,"Охотница на монстров (Имельда или Шельма) — Рыбацкие снасти не у берега взял? Борода любит ловить рыбу у реки, советую вернуть. — *Она подошла ближе, ветви её явно заинтересовали.* — Покажи веточки, та ли это берёза что я думаю или ты перепутал.",167919,null],[167927,"2026-08-22T19:49:51",31,"- привет. Что то мне подсказывает, ты не просто так тут сидишь и куришь",167875,null],[167930,"2026-08-22T19:52:53",9,"Страшный как тысяча чертей рыжий кот (???) — А ты рожа новая, что здесь забыл? Лентяйничаешь поди. — *Кот не церемонился, он постучал трубкой о дерево вытряхнув старый табак и начал новый насыпать. Рыбку конечно отложил.*",167927,null],[167931,"2026-08-22T19:53:35",17,"— Ну да та. Ещё в ноздре у вепря побывала эта ветка. Считай в бою заколена.\n\nЛюпен вытащил полность ветку и передал Шельме\n\n— А снасти я Бороде верну. Он где тут расположился? Бородатый видимо, судя по прозвищу?",167925,null],[167934,"2026-08-22T19:54:57",31,"- ну вроде того. Хотя я бы скорее сказал более изысканно: ищу себя. Я Конрад, в ты кто?",167930,null],[167967,"2026-08-22T20:05:21",9,"Охотница на монстров (Имельда или Шельма) — Просто положи где взял, не говори никому. — *Она смотрит ветку, а потом вздыхает, словно потеря...* — Иссохла, это уже мусор.",167931,null],[167971,"2026-08-22T20:05:44",20,"- Ого, а что она позволяет делать? Быстрее учить заклинания? *С интересом спрашивает Рен, помогая Сону разбирать завал и методично сортируя не слишком тяжёлые вещи.*",167898,null],[167986,"2026-08-22T20:12:56",9,"Страшный как тысяча чертей рыжий кот (Рыжик страшила) — Я Рыжик по прозвищу страшила. — *Кот улыбнулся, так страшно что побежали мурашки по спине, этого кота вряд ли кто гладит.* — Слежу за борьбой для Бороды, чтобы реально сражались а не отлынивали, и оцениваю результаты вечернего мордобоя, честно ли морды били. — *Кот обратил внимание на тех двоих что боролись облитые маслом.* — А ну блядь не обниматься как бабы, активнее. Вы не на свиданке!\n\n*С мужиков уже и так в три пота встало, они вялые пытаются в борьбу, но вымотались, ни один другого уде не схватит нормальнг и не повалит.*\n\nСтрашный как тысяча чертей рыжий кот (Рыжик страшила) — Бездари. — *Кот сплюнул на пол густую слюну, от того места поднялась дымка как от кислоты.*",167934,null],[167999,"2026-08-22T20:15:22",31,"- а мне можно поучаствовать? А то вроде учился драться, а не применяю совсем знания, так и заржаветь недолго",167986,null],[168010,"2026-08-22T20:17:30",9,"Парень, ученик Лазаря (Сон) — Надо прочувствовать шляпу, почувствовать как по ней течет магия. После, при должном старании с её помощью можно попытаться воспроизвести одно из простейших заклинаний. — *Парень кажется кое что вспомнил и стал более официальным сделав лёгкий поклон.* — Простите, не представился как следует. Сон Тин-Паунд, в неофициальной обстановке просто Сон.",167971,null],[168041,"2026-08-22T20:26:54",9,"*Оценивающе на тебя глянул, кажется Рыжику понравилось то что он увидел.*\n\nСтрашный как тысяча чертей рыжий кот (Рыжик страшила) — От чего же, можно. Сегодня вечером у нас будет классический бой на кулаках и Темноградская \"народная драка на стульях\". — *Кот взял рыбку и продолжил её чистить.* — Все мы любим новые лица на арене. Думаю могу дать тебе небольшой приз.\n\n*Кот кажется что-то задумал, ухмылялся он жуткл и хитро.*\n\nСтрашный как тысяча чертей рыжий кот (Рыжик страшила) — Ты новичок, тебя никто не знает. Так что если победишь во всех раундах дам тебе кое что из своих закромов. — *Кот будто специально тянул резину, чистил луску да дымел.* — Обмотки одного монаха от которых отскакивают мечи. Я люблю честные бои, что скажешь? Устроишь этому коту шоу.",167999,null],[168042,"2026-08-22T20:28:14",31,"- еще поди и ставки принимаешь? На меня как новичка небось коэффициент будет немалый...",168041,null],[168049,"2026-08-22T20:30:48",9,"Страшный как тысяча чертей рыжий кот (Рыжик страшила) — Да, да. Смышлёный, мне такие нравятся. — *Кот оказался доволен что Конрад сразу понял к чему всё это.* — Но презент тоже того стоит, ты не разочаруешься.",168042,null],[168053,"2026-08-22T20:31:30",31,"- жаль мне самому поставить нечего. Ну да ладно, я готов, хоть сейчас на ринг",168049,null],[168057,"2026-08-22T20:32:18",31,"- какие правила то хоть?",142532,null],[168073,"2026-08-22T20:37:44",9,"Страшный как тысяча чертей рыжий кот (Рыжик страшила) — Никакого оружия и доспехов, бой на чистых кулаках, кто первый упадет без сознания или сдасться — проиграл. — *Кот постучал трубкой по дереву, он дочистил рыбку.* — Народная драка на стульях сложнее, нужно думать и подбирать момент. Дерутся только га специально сделанными для этого стульях, проигрывает тот у кого сломался стул, бить друг друга нельзя. В Темнограде такие драки в тавернах постоянное разлечение, разрешить спор, а проигравший ещё останется пировать стоя или сидя на полу. Отличная традиция и народ в тех краях хороший.",168057,null],[168076,"2026-08-22T20:40:22",31,"- ну я пожалуй кулаки почешу, а стульями драться это конечно интересно, но пока для меня слишком экзотично. Но посмотрим, может тоже поучаствую",168073,null],[168081,"2026-08-22T20:52:00",9,"*Кот смеялся слегка прокашлявшись шерстью, казалось что он сейчас подавится и сдохнет, но пронесло. Кот начал смаковать сырую рыбку.*\n\nСтрашный как тысяча чертей рыжий кот (Рыжик страшила) — Мммммрррр, я и не предлагал тебе драку на стульях. Лишь разговор на кулакаааххх. — *Кот настолько доволен был рыбкой что начал тянуть слова.* — Только надо подождааать пока стемнееет.\n\n*Люди и правда только начинали собираться. За сизой дымкой облаков солнца лишь клонились к закату.*",168076,null],[168083,"2026-08-22T20:52:28",9,"//Го завтра с Конрадом, я знаю что у тебя уже писец поздно)",142532,null],[168084,"2026-08-22T20:52:45",31,"//ок, ушёл спать",142532,null],[168117,"2026-08-22T21:21:31",20,"*Рен машинально повторил лёгкий официальный поклон.*\n\n- Рен, титула не имею. Рад нашему знакомству, юный лорд Тин-Паунд.\n\n*Так же легко вновь переключился на прежнее непринужденное любопытство*\n\n- Получается чтобы почувствовать магический предмет нужно на нем сосредоточится и настроиться? Вроде медитации?",168010,null],[168122,"2026-08-22T21:32:19",9,"Парень, ученик Лазаря (Сон) — Не дворянин, не совсем. Из рода проклятых дворян большой Веспирали, но из родовой ветви дворецких. — *Сон слегка смутился когда его назвали Лордом.* — Каждый представитель моей семьи ищет себе лорда которому он должен служить, мы не имеем чина ни при каком дворе, лишь фамилию и кодекс. Есть чёткие критерии и принципы... — *Сон внезапно понял что начал говорить о семье, постарался исправится.* — Прости. Да, на шляпу надо настроиться, это чем-то напоминает медитацию и является неплохой практикой, думаю для начала тебе пригодится эта книга.\n\n*Сон завёл руку за спину а второй подал книгу что отложил. Пособие о принципах использования магических предметов.*\n\nПарень, ученик Лазаря (Сон) — Прошу.",168117,null],[168138,"2026-08-22T21:47:29",20,"*Рен удивлённо приподнимает бровь. Обычаи Веспирали казались ему такими отличными от того, что он видел в Аннеже*\n\n- Ох, вот оно что. Какие интересные традиции у тебя на родине. Звучит почти как рыцарство в немного другой форме... *Кажется тема явно заинтересовала пацана, но он пока тактично решил оставить это на потом, когда лучше познакомиться с Соном.*\n\n- Спасибо *Он взял книгу, положив ее на уже очищенный участок*\n\n*После этого он снова приступил к помощи в уборе, чтобы взяться за изучение книги и шляпы уже в обстановке полного порядка. Перфекционизм, что с него взять*",168122,null],[168155,"2026-08-22T21:56:19",9,"Парень, ученик Лазаря (Сон) — Извини, я не могу дать тебе работать. Ты слабо на ногах стоишь. — *Сон улыбнулся, он ценил что ты хочешь помочь, но не мог эксплатировать в такомсостоянии.* — Лучше попробуй настроиться на шляпу пока чувствуешь течение магии, это не требоет больших физических услий. Возможно даже важнее, на сколько знаю эти ощущения навеянны зельем и вскоре снова притупятся.",168138,null],[168162,"2026-08-22T22:01:41",20,"- Хорошо... \n\n*Рен вздохнул, понимая что свою манию порядка ему пока не удастся утолить. Он оглянулся выискивая пригодный уголок где можно было устроится.*\n\n*Найдя такой он сел и прикрыл глаза, стараясь сосредоточится на шляпе в руке. После пары минут надел ее - может так дело пойдет быстрее?*\n\n/Часок сижу чилю и настраиваюсь",168155,null],[168521,"2026-08-23T11:02:14",31,"Как будешь готов, маякни//",168083,null],[168555,"2026-08-23T11:51:11",47,"Так, вопрос, что произошло с моим персонажем и нужно ли моё, хотя бы малое участие?",142532,null],[168620,"2026-08-23T12:16:43",9,"//Я не знаю, целый день пропущен, события слишком плотно идут. Все очень зависело от поступков, поведения и решений пати.",168555,null],[168635,"2026-08-23T12:29:01",31,"Пропал в лесах видать/",168555,null],[168649,"2026-08-23T12:33:50",47,"Я предлагаю так. Мой персонаж пропал по той причине, что свалился в воду и его унесло течением. Сейчас он к вам грязный подойдёт, норм?",142532,null],[168749,"2026-08-23T13:05:12",9,"//. @dunchev",167967,null],[168762,"2026-08-23T13:09:19",17,"— Хм.. а ты знаешь где в лесу растут ещё? Я готов на новую вылазку ради нового лука.",167967,null],[168770,"2026-08-23T13:12:24",9,"*За дверью все темнее, вечереет? Наверное.*\n\n*Шляпа покалывала на кончиках пальцев, так пока что-то не сплелось, связь занимающая часть твоего внимания. Волшебный предмет словно стал частью того огня что горит внутри, его присутствие, текстура предмета смутно ощущалась, как она сгибается в руках, уже немного теплая, не холодная шелка и ткань как раньше, словно ожил.*\n\n//Настройка удалась, по книжке надеюсь делал)",168162,null],[168809,"2026-08-23T13:23:00",9,"*Огни! Костры и факела. Рыжик распорядился, Конраду принесли пожрать прямо сюда, свежий кабаний стейк прожаренный в масле, говорят новый охотник постарался.*\n\n*Всё больше людей сходилось к рингу, сборщики кидали на пол немного подсохших трав на землю, соломы. В толпе можно было заметить того самого полуростика, он помахал рукой и подошёл ближе.*\n\nПолурослик (кларк) — Будь ты рыжий чорт. Уже нового чемниона лелеешь? — *Слегка язвительно он обратился к коту.*\n\nСтрашный как тысяча чертей рыжий кот (Рыжик страшила) —  Иди отсюда, не порть мне настроение Кларк. Надеюсь сегодня увидеть хороший бой. — *Кот явно был с небольшим человечком слегка не в ладах.*\n\nПолурослик (кларк) — Это я и направил его к тебе хорошеее настроение поднять. К писарям да ученым его пристроить хотели. — *Подошел и в наглую облокотился рядом на забор.*\n\nСтрашный как тысяча чертей рыжий кот (Рыжик страшила) — Писарем? Эти руки хороши не только для пера, такой талант чуть не зарыли. — *Кот немного удивился, и указал трубкой на руки Конрада, а после обратился к нему:* — Но я еще посморю как ты себя покажешь. Скоро, совсем скоро.",168076,null],[168820,"2026-08-23T13:25:18",31,"- угу\n\nОтвечаю с набитым кабанятиной ртом",168809,null],[168830,"2026-08-23T13:29:39",9,"*Она покачала головой.*\n\nОхотница на монстров (Имельда или Шельма) — Не знаю где взять ещё Вялыя Бяръозы. Знаешь. — *Она начала гнуть ветку, та была очень гибкой.* — Из этого редкого дерева плетут луки, без никакой магии, они сами по себе хороши. — *Она согнула ветку чуть сильнее и та треснула.* — Но эти уже не годятся. — *Имельда посмотрела ровно в глаза Люпену.* — Где ты взял ветви болотистой берёзы. Это очень далеко отсюда?",168762,null],[168842,"2026-08-23T13:34:37",17,"— Примерно сутки пути. У болота.",168830,null],[168855,"2026-08-23T13:37:41",9,"*Она обошла тебя и взялась за твои плечи, начав их массировать, немного грубо и крепче чем нужно.*\n\nОхотница на монстров (Имельда или Шельма) — Ты же покажешь дорогой подруге где такие растут... — *Она заигрывала, настаивала показать или угрожала было не понятно. Ясно только то что хочет ветви Вялой Берёзы.*",168842,null],[168875,"2026-08-23T13:43:19",17,"— Ну я не дурак Шельма. Вижу что тебе сильно нужно найти это дерево. Мне оно тоже нужно. Так что я брыкаться не буду. Готовь снаряжение и можем выходить. Раны мои уже почти и не ощущаются. Так что, можем хоть сейчас отправляться. \n\nЛюпен боялся шевельнутся, он понимал что Шельма скорее требует показать ей место и готова свернуть ему шею если будет отказываться",168855,null],[168877,"2026-08-23T13:43:54",17,"— Правда ночь придется в лесу провести.",142532,null],[169365,"2026-08-23T18:57:53",17,"/ Hard отыграем поход к вялым березам на болота? Или долго это. Могу просто дать направление Шельме. Обычный лук может дадут?",142532,null],[169366,"2026-08-23T18:58:21",9,"//Я настроен отыгрывать)",142532,null],[169367,"2026-08-23T18:58:31",9,"//Это не просто дерево",142532,null],[169372,"2026-08-23T19:00:20",31,"Здорово конечно что настроен. Я правда весь день жду и походу не дождусь, спать пойду//",169366,null],[169373,"2026-08-23T19:00:44",9,"//Прости, не так уж много времени сегодня было",169372,null],[169383,"2026-08-23T19:13:42",9,"*Заводила, на вид полный головорез, загорелая кожа, вставные зубы, серьги. Он встал на круглый стол и затрубил в рожок, это был сигнал.*\n\nВедущий головорез — Кто готов начать?! — *Дождавшись немного хоть и вялого отклика, он взял горсть песка и пламени, бормоча тайные слова бросил его на арену и та вспыхнула зеленым и багровый пламенем что взментнолось вверх и застыло звездной дымкой, люди не часто видели такое, это не огонь, волшебство, грубое, зрелищное, хоть и бесполезное.* — Кто хочет сеья попробовать в ролм нового чемпиона!? Храбрецы, марш на арену, хватит сиськи мять.\n\nПолурослик (кларк) — Ты смори, не буду отвлекать. — *Он кивнул Конраду и исчез в толпе.* — Удачи.\n\nСтрашный как тысяча чертей рыжий кот (Рыжик страшила) — Хех, как всегда. — *Прокоментировал кот видя как молодые илут на арену по одному, махают кулаками и пытаются удержаться. Детский лепет, не далеко им до кулачников, но некоторые дрались вполне себе. Рядом с ареной стоял стол, где сидело несуолько крупных парней.* — Вон, это чемпионы. Лоск, Фауст (тёзка одного эладрина) и Гримли. Когда из молодых определится кандидат выйди на арену, кажется ты с ним справишься. После победы вызови на поединок Фауста (ловкач) или Лоска (кажется как здоровяк. Гримли как чемпион слишком гордый чтобы сразу выходить против новичка, если у тебя есть особые приёмы то лучше прибереги для него, по нему не скажешь но он быстро адаптируется...\n\n*Кот раздавал советы пока молодёжи на арене становилось все меньше, кто-то уходил после пары ударов, кто-то пока его сильно не побили и он не упал. Правда всё было вполне чинно, их после лечили от побоев да наливали вино, сидели в ряд у стены наблюдая как идёт бой.*",168820,null],[169386,"2026-08-23T19:15:52",9,"*Она вздознула и отпустила плечи.*\n\nОхотница на монстров (Имельда или Шельма) — Далеко. Надо взять алхимию с собой... — *Слегка расстроилась а после взглянула на Люпена.* — Завтра чуть свет пойдёшь со мной, я все подготовлю, а пока.",168877,null],[169387,"2026-08-23T19:18:08",31,"Оглядываю чемпионов. Серьёзные ребята конечно. Но прежде надо глянуть на тех, кто будет до них, нельзя допускать недооценку противника",169383,null],[169389,"2026-08-23T19:19:20",9,"*Охотница взяла Люпена за руку и потащила к месту, арена где вздымалось магическое марево, только начиналось всё. Прямо к костру где уже сидели мастер Чиф и Димка, они уже жарили на вертеле парочку зайцев.*\n\nМолодой (Чифтер Люск) — О, Люпен! Ты где пиопадал, мы тебя весь день искали.\n\nВоин в больших доспехах (Димон) — Ты теряешь свою жизнь. — *Димон взглянул на жалкий вид Люпена которого неплохо потрепало и покачал головой.* — Очистите меч огня. — *Он показал на костёр, явно приглашал.*",169386,null],[169391,"2026-08-23T19:19:41",17,"— Договорились, Шельма. Там были саблезубые олени и может быть кто ещё опаснее. В лагере есть короткий лук который я могу одолжить на время, пока не сделаю свой?",169386,null],[169392,"2026-08-23T19:20:52",17,"— Попал в передрягу. Я пошел искать тебя\n\nКивает на Димку \n\n— Но нашел вместо этого ледку кабанов и кое как ноги унес, Шельма меня спасла.",169389,null],[169394,"2026-08-23T19:21:46",9,"Парень, ученик Лазаря (Сон) — Ты как хорошо себя чувствуешь? Я хочу сегодня сходить посмотреть бои. Не хочешь со мной? — *Сон внезапно подошел с предложением.* — У нас там отдельный стол и меню. Учитель не ходит смотреть, нам достанется самое лучшее.",168162,null],[169401,"2026-08-23T19:25:33",9,"Охотница на монстров (Имельда или Шельма) — Оставляю его на вас мальчишки, не потеряйте. — *Она быстрым шагом по делам удалилась.*\n\nМолодой (Чифтер Люск) — Да да, присмотрим. — *Когда реа ушла он присвистнул.* — Это когда ты успел нашу Шельму заинтересовать. Она говорят своему бывшему отрезала кое что потому что на лево ходил. Поосторожнее с женщинами.\n\nВоин в больших доспехах (Димон) — Что можно сделать с этой бумагой. Я хочу плавать. Я не сдаюсь.",169392,null],[169406,"2026-08-23T19:28:36",9,"*Наарене осталось трое молодых людей, Рыжик кивнул заводиле и тот остановил бой. Все трое уже немного помятые разошлись по углам, каждому дали трав, зелья, приложили холодное к лицу.*\n\nВедущий головорез — Вот наши будущие чемпионы, можеткто-то из них займет место у стола почёта. Но подождите, почему их три!? — *Он указал прямо на Конрада что стоял у арены.* — У нас сегодня тёмная лошадка. Новичок с которым никто не знаком, выходи на сцену, ты, да да ты!",169387,null],[169409,"2026-08-23T19:30:04",9,"Страшный как тысяча чертей рыжий кот (Рыжик страшила) — Твой выход. Не разочаруй этого кота. — *Кошак улыбнулся так что этой улыбкой можно было пугать бандюганов на ночь перед сном. Детей таким пугать не стояло, они бы просто срались и не спали.*",169387,null],[169416,"2026-08-23T19:32:26",31,"Выхожу на арену, поднимаю руки и приветствую толпу, затем подхожу к соперникам",169406,null],[169419,"2026-08-23T19:36:19",9,"*К тебе не очень приветливо ставятся зрители, чужак. Сможешь ли ты завоевать их любовь?*\n\nУчастнк третий, мужик со шрамом — Свали в свой угол выскочка. — *Он сплюнул прямо перед тобой, никакого уважения. Один из углов правда был никем занят, похоже твоё место.*\n\nВедущий головорез — Вы смотрите, новичок сам выбрал себе соперника, но вы столкнётесь в последнем рауде, а сейчас представься. Как нам тебя называть!? — *Ведущий явно хотел добавить интереса твоей личности.",169416,null],[169424,"2026-08-23T19:39:39",9,"Молодой (Чифтер Люск) — Эй, смотри. Это не твой знакомый там, на арене. — *Хоть и стояли поодаль но отсюда можно было рассмотреть назревающий бой.*\n\nВоин в больших доспехах (Димон) — Вы знаете возможность? Закончите пустыню своей жизни. — *Здоровяк лишь махнул на арену.*\n\nМолодой (Чифтер Люск) — Кстати, Димка наш настоящий чемпион. Раньше он один сидел за столом почета. Но людям смотреть на это было не интересно и его попросили уйти. Дуется до сих пор. — *Чиф хихикнул и спросил Люпена.* — Как охота хоть прошла?",169392,null],[169425,"2026-08-23T19:39:58",31,"Смотрю на плюющегося мужика как на вошь грязную, лицом выражая пркзриткльнцю брезгливость и не цдостоив его ответа отхожу в свой угол. Услышая вопрос, коротко отвечаю\n\n- меня зовут Конрад. Большего вам пока знать не нужно",142532,null],[169432,"2026-08-23T19:45:13",9,"Ведущий головорез — Таинственный, немногословный, это он! А сейчас, первфй раунд. — *Вышел тот же бандит что сплюнул под ноги Конралу и схлестнулся с неким парнем. По стилю боя можно было понять, он ловит удары на себя и бьёт в ответ, словив пару ударов противникапросто вывел его в нокаут, а у самого лишь немного помято лицо, он сел в угол и взглянул на конрада \"ты сдедующий.*\n\nВедущий головорез — А сейчас, молодой Бунгаль который уже третий раз пытается схлестнутся за право силеть с чемпионами и наш новенький. Кооооннннрррраааддддд!!!!",142532,null],[169436,"2026-08-23T19:46:42",9,"*Молодой парень выходит сражаться, его немного качает, он подвипивши.*\n\nМолодой Бунгаль — Ты чей смотри. Давай, хади сюда. — *Немного шатаясь он пригласил подойти ближе, руки поднялись повыше, самоучка.*",142532,null],[169438,"2026-08-23T19:49:17",31,"Выхожу против Бунгаля, принимаю стойку готовности, из которой смогу как нападать, так и защищаться",142532,null],[169439,"2026-08-23T19:49:21",31,"Инициатива?/",142532,null],[169441,"2026-08-23T19:49:45",9,"/roll -d20+1 пусть иня, он пьяный вот и помеха",142532,null],[169443,"2026-08-23T19:50:10",31,"/roll d20+3",142532,null],[169445,"2026-08-23T19:50:11",17,"/ Чуть позже подключусь. Дела ещё есть",142532,null],[169446,"2026-08-23T19:50:27",9,"//Го Конрад",142532,null],[169448,"2026-08-23T19:50:43",31,"/roll d20+4 первый удар\n/roll d20+4 второй удар",142532,null],[169450,"2026-08-23T19:50:54",9,"*Бунгаль кажется приготовился ударить как ты подойдешь.*",142532,null],[169451,"2026-08-23T19:51:05",9,"/roll 1d20+3 ответочка",142532,null],[169453,"2026-08-23T19:51:19",31,"Попал/",142532,null],[169454,"2026-08-23T19:51:24",31,"А я попал?/",142532,null],[169456,"2026-08-23T19:51:38",9,"//4 урона тебе безоружным",142532,null],[169457,"2026-08-23T19:52:10",9,"*Тяжёлый кулак, хоть и пьяного парня полетел в плечо.*\n\nМолодой бунгаль — На!",142532,null],[169458,"2026-08-23T19:52:37",9,"//Урон кидай)",142532,null],[169459,"2026-08-23T19:52:50",31,"/roll d4+3 первый удар, кулаком в челюсть\n/roll d4+3 второй удар, коленом в грудь",142532,null],[169461,"2026-08-23T19:52:59",31,"10 урона/",142532,null],[169464,"2026-08-23T19:54:42",9,"*Получив пару таких мощных ударов он чуть не свалился, едва стоит наногах. Вроде бы выдержал, но сплюнул кровь.*\n\nМолодой Бунгаль — Нэ, ты сильный. — *Он опустил руки, выглядел так словно щас свалится.* — Сдаюсь, помоги.",142532,null],[169465,"2026-08-23T19:55:19",31,"Подхватываю парня, чтобы не упал, помогаю дойти до его угла. Мы же не враги, просто спарринг",169464,null],[169466,"2026-08-23T19:55:25",9,"*Просит помочь дойти ему к сидению. Хоть и выпивши он понял что не сдюжит.*",142532,null],[169467,"2026-08-23T19:56:09",9,"Молодой Бунгаль — Пасиб, выпьем обязательно. Пакажешь как удар дяржишь. Мне нравится.",169465,null],[169470,"2026-08-23T19:57:12",31,"- замётано",169467,null],[169472,"2026-08-23T19:58:04",31,"Вновь выхожу на арену, и взглядом нахожу противника",142532,null],[169473,"2026-08-23T19:58:16",9,"Ведущий головорез — Даже одного раунда не продержался Бунгаль, у нашего новичка неплохо поставлен удар, согласитесь!? — *Никто ничего не понял а на арене стоял тот самый бандюган что не проявил уважения.* — Мы так обычно не делаем и даем передышку, но кое кому уде не терпится с тобой схлестнутся. Что скажешь, Конрад, ты согласен не ждать?",142532,null],[169474,"2026-08-23T19:58:54",31,"- готов, я не устал",169473,null],[169475,"2026-08-23T20:01:32",9,"Ведущий головорез — Тогда, пртготовьтесь. Гарет проьив нашего новичка. — *Он видя что меж вамт напряжеги выпрыгнул на сцену лично и установив меж вами растояние, растолкав немного руками начал отсчет.* — Сейчас начнем бой, три, два, один!\n\n*Он ловко выскользнул и нырнул подальше успев взмахнуть рукой меж вами.*",169474,null],[169476,"2026-08-23T20:01:46",9,"/roll 1d20-1 иня Гарета",142532,null],[169479,"2026-08-23T20:02:02",31,"/roll d20+3 моя инициатива",142532,null],[169482,"2026-08-23T20:02:30",9,"*Он делает рывок и машет тяжелым кулаком в твою сторону.*",142532,null],[169484,"2026-08-23T20:02:37",9,"/roll 1d20+6",142532,null],[169486,"2026-08-23T20:03:00",9,"//Кд какое у тебя кстати?",142532,null],[169490,"2026-08-23T20:04:38",31,"16/ я бы хотел использовать прием готовность реакцией",142532,null],[169491,"2026-08-23T20:05:08",31,"Как это механически должно выглядеть?/",142532,null],[169493,"2026-08-23T20:05:27",9,"//Ты бьешь сразу как онв досягаемость входит, тоесть перед ним",142532,null],[169494,"2026-08-23T20:05:31",31,"Бросать на атаку и если пройдёт, то к урону добивать кость д8?/",142532,null],[169495,"2026-08-23T20:05:45",31,"/roll d20+4",142532,null],[169497,"2026-08-23T20:05:56",31,"Видимо, мимо/",142532,null],[169498,"2026-08-23T20:06:01",9,"// попал, кд 9 у него, ловкость -1",142532,null],[169500,"2026-08-23T20:06:10",31,"Ок/",142532,null],[169501,"2026-08-23T20:06:34",31,"/roll d4+3+d8",142532,null],[169503,"2026-08-23T20:06:47",31,"Правильно?/",142532,null],[169505,"2026-08-23T20:07:04",9,"/roll 1d4+4 его удар, твой его не свалил",142532,null],[169511,"2026-08-23T20:07:56",9,"*Противник крепко выдержал удар и дал ответочку. Он слегка пошатнулся от неожиданного выпада по сеье, но стоит.*\n\n//Твой ход",142532,null],[169512,"2026-08-23T20:08:06",31,"/roll d20+4 первый удар\n/roll d20+4 второй удар",142532,null],[169516,"2026-08-23T20:09:00",31,"/roll d4+3 первый удар, пинаю его в колено\n/roll d4+3 после попадания в колено кулаком бью в ухо, чтобы оглушить и дезориентировать",142532,null],[169518,"2026-08-23T20:09:05",9,"Ведущий головорез — Удары сыпятся градом. Новичок ояень шустрый! Он кск молния или щмея в прыжке, осыпает градом!",142532,null],[169519,"2026-08-23T20:09:08",31,"12 урона/",142532,null],[169522,"2026-08-23T20:10:02",9,"*Противник ещё стоит, защищая лицо в стойке, почти не щащищая тело и находи время чтобы попытаться выписать ответочку.*",142532,null],[169523,"2026-08-23T20:10:21",9,"/roll 1d20+6 тяжелый удар уже от него в его ход",142532,null],[169526,"2026-08-23T20:10:28",31,"Увернулся",142532,null],[169528,"2026-08-23T20:10:47",9,"*Подбитый и не точный промахивается едва едва не попав.*",142532,null],[169529,"2026-08-23T20:10:55",31,"/roll d20+4 первый удар\n/roll d20+4 второй удар",142532,null],[169533,"2026-08-23T20:12:08",9,"Ведущий головорез — Какой точный выпад, но сегодня гарету не благоволит удача. Против него вышел наш новенький, кск и говорил парень окащался темной лошадкой. Кажется он имеет шанс занять место у столя победителей! Давно такого у нас небыло.",142532,null],[169534,"2026-08-23T20:12:25",31,"/roll d4+3 перехожу в ближний бой, уворачиваюсь от тяжелого удара и бью ч размаху в печень\n\n/roll d4+3 после того как удар в печень проходит и его выгибает дугой от боли, бью в солнечное сплетение, сбивая дыхание",142532,null],[169536,"2026-08-23T20:12:31",31,"11 урона/",142532,null],[169538,"2026-08-23T20:12:36",9,"//Хватило, описывай как ты его вырубаешь",142532,null],[169540,"2026-08-23T20:13:32",31,"Удар в солнечное сплетение оказался финальным, у Гарктв перехватило дыхание и он грузно упал на землю, словно мешок с квртошкой",142532,null],[169553,"2026-08-23T20:19:44",9,"Ведущий головорез — Даааа! Вот наш победитель! Сегодня он бросит вызов чемпионам, посленебольшой пепедышки. Делайте ставки господа, займет ли он место у стола. — *Ведущий подошел и поднял твою руку уже полноценно представляя толпе.* — Он выберет себепротивника после перерыва, ждите, нас ждет зрелище! — *Он уводмт тебя в свой угол, на арену выходят мужики в масле что в свете факелов борются и пытаются схватить друг друга и повалить. Надо время народу пообсуждать, попринимать ставки.*\n\nСтрашный как тысяча чертей рыжий кот (Рыжик страшила) — Мне в какой то момент показалось что ты продуешь Гарету. Как себя чуыствуешь. — *В углу уже ждали пару молодых парней с зельем лечения, бинтами и прочим, он сейчас собираются подлатають Конрада.*\n\n//Востанови фулл хп и может посоциаль. Или иди спать если поздно оч",169540,null],[169555,"2026-08-23T20:21:48",9,"//Иди спать, дела в ирл чутка как раз ~",142532,null],[169557,"2026-08-23T20:23:14",31,"Ок, ушёл спать))//",142532,null],[169679,"2026-08-23T21:51:36",20,"/блин, весь день драила окна и пропустила эпик(\n/Короче если ещё не поздно хочу подоспеть на бой посмотреть с Соном. Может медленно шли - у меня как раз скорость в жесть снижена\n\n*Рен удивлённо приподнимает бровь*\n\n- Тут и таким развлекаются? Хорошо, пошли - может я и своих там среди зрителей повидаю",169394,null],[169684,"2026-08-23T21:54:20",9,"Парень, ученик Лазаря (Сон) — Пошли, отдых необходим не только для тела, а и для разума. — *Он взял свою шляпу и напялил на голову, вспомнил что-то.* — Кстати, как у тебя продвигается со шляпой? Удалось нащупать ощущение связи?",142532,null],[169687,"2026-08-23T21:56:56",20,"- Чувствую тепло и... что-то вроде связи, наверно *Кивает Рен, бережно разглаживая края своей шляпы* - как будто теперь это не просто шляпа, а что-то мое, особенное. Это со всеми волшебными предметами так?",169684,null],[169691,"2026-08-23T22:03:46",9,"Парень, ученик Лазаря (Сон) — Некоторые работают сами по себе, а другие с ними надо установить связь. — *Он подумал мгновение и предложил.* — Помнишь то чувство что было при соприкосновении с той игрой? Вспышка и укол электричества. Эта шляпа помогает воспроизводить простейшие заклинания, попробуй сделать вспышку похожую на ту, представь как из рук вылетают молнии, скажи сдова что сильнее ысего ассоциируются с ней и жест.\n\n*Он делает жест руками, как Палпатин когда бил своими молниями.*",169687,null],[169692,"2026-08-23T22:07:33",20,"- Молния, да? Хм... *Пацан сосредотачивается, пытаясь снова представить жёлтые всполохи той игры. Как бы это выглядело, будь у него возможность управлять этим...*",169691,null],[169693,"2026-08-23T22:07:56",20,"/r d20+2 на магию чтоб кастануть заговор",142532,null],[169695,"2026-08-23T22:12:34",20,"/лассо молнии \n\n- Рази! *Он выхватывает первое пришедшее на ум слово и направляет руку на какой-то небольшой камешек, валяющийся в стороне на полу*\n\n*В руках формируется золотистый разряд как тот у иглы, но больше похожий на плеть или лассо. Чисто инстинктивно Рен перехватывает его делает направленный щелчок в сторону камешка, оплетая и рывком притягивая к себе в ладонь*\n\n- Хах... получилось? *Он рассматривает камешек в руке, когда электрические разряды рассеиваются*",142532,null],[169696,"2026-08-23T22:12:45",9,"//Там сложность 10, башь электрошок",169694,null],[169697,"2026-08-23T22:13:08",9,"//Нихуя, лассо 😂👍",142532,null],[169698,"2026-08-23T22:13:29",20,"/электрошок как то слишком банально показалось 👀",169697,null],[169786,"2026-08-24T05:51:25",31,"- ну, он и правда крепкий мужик. Даже интересно насколько сильны чемпионы, если это был только претендент. Я так понимаю, мне один бой остался?",169553,null],[171307,"2026-08-24T21:41:17",9,"*Сон оступился и чцть не упал.*\n\nПарень, ученик Лазаря (Сон) — Ох, как. — *Он был слегка ошарашен и тут же взял себя в руки.* — Так сразу? У меня три дня заняло чтобы... учитель. — *Сон взглянул мимо плеча Рена.*\n\nБелобрысый ученый (Лазарь) — Неплохо, но я рекомендовал не напрягаться. Ты хорошо себя чувствуешь? — *Словно из ниоткуда Лазарь появился возле Рена, хотя мгновение сидел на своём кресле читая книгу. Он кадется беспокоился? По его бесстрасному лицу не понять.*",169695,null],[171359,"2026-08-24T21:48:47",20,"- А? *Кажется Рен был слишком поглощён ощущением магии на кончиках пальцев, чтобы быстро сообразить. Он слегка тряхнул головой, возвращая внимание на магов*\n\n- Все ещё чувствую слабость конечно. Но как вы и говорили - пока зелье потенциала ещё действует не хотел терять возможность. Вдруг когда востановлюсь было бы уже тяжелее начать?\n\n*Он смотрит на свою руку, в которой зажат камешек*\n\n- Хотя по ощущением сегодня точно не смогу ничего такого повторить...жаль.",171307,null],[171439,"2026-08-24T22:00:37",9,"Белобрысый ученый (Лазарь) — Раз ты не намерен отдыхать тогда завтра займёмся основами защитных искусств. — *Он подошел и снял магическую шляпу у Рена.* — Её заберешь завтра. Сон, надёшь справочник о заговорах, пусть Рен испробует каждый и выберет те что посчитает нужными, после заучит их формулу и способ воспроизведения на зубок, пока они не начнут получаться и без шляпы. — *Раздав указания Лазарь махнул рукой, жест частично пюнапоминающий особый, как при заклинании, скорей всего привычка.* — На сегодня свободны.\n\nПарень, ученик Лазаря (Сон) — Да учитель. — *Сон слегка поклонился и взял Рена за руку чтобы поддержать в пути.* — Пошли.",171359,null],[171504,"2026-08-24T22:10:03",20,"*Рен проводил шляпу слегка тоскливым взглядом - видать первая магическая настройка и правда странным образом западает в душу. Но возражать не стал.*\n\n- Понял, учитель *он кивнул на прощание , следуя за Соном*\n\n*Интересно как обустроились в лагере его спутники...Он мог только надеется, что каждый нашел дело себе по душе и решит задержаться здесь. Как никак он не хотел так скоро разлучаться с людьми, с которыми прошел столько испытаний(пусть и всего за два дня)*\n\n- Сон, у тебя же получается уже есть набор этих самых заговоров, которые ты заучил, так? *Спрашивает он, когда они делали лёгкую передышку на пути к арене - долго идти пока все ещё было не так просто.*\n- Как ты их выбирал?",171439,null],[171564,"2026-08-24T22:16:32",9,"Парень, ученик Лазаря (Сон) — У меня всего три. Например фокусы, они слишком хороши и универсальны чтобы не выучить, поджечь или потушить свечу, крошечные иллюзии и ветер, все в одном! — *Он показал иллюзию летающей бабочки, жестом потушил горящий факел на стене, и потом достал из-за уха Рена монетку.* — Сожми монету в руке.",171504,null],[171595,"2026-08-24T22:19:49",20,"*Рен берет монетку и сжимает ее в кулаке, с интересом смотря что из этого выйдет*",171564,null],[171597,"2026-08-24T22:20:19",20,"/цыганские фокусы пошли",142532,null],[171642,"2026-08-24T22:26:30",9,"*В какой то момент та пересталась чувствоваться в ладони.*\n\nПарень, ученик Лазаря (Сон) — Она исчезла, это временная безделушка. — *Он улыбнулся, наблюдая за реакцией Рена.* — Заговоров множество. Но два других я выбрал боевые, учитель настоял. Это электрошок чтобы ошарашить противника вблизи на мгновение и огненная стрела. Огонь неплохо поджигает и далеко летит. Учитель очень любит базовые заклинания, он расстроился когда я не выучил более полезные малые иллюзии вместо фокусов, несколько недель игнорировал и старался не общаться. Маг в уме может держать лишь несколько заговоров, так что выбирать нужно с умом. — *Сон заговорил тише.* — На самом деле учитель очень обидчив, властен и на удивление добр при этом. Только я тебе этого не говорил, это секрет.",171595,null],[171674,"2026-08-24T22:32:00",20,"*Рен разжимает ладон, на секунду на лице мелькает неподдельное удивление, которое сменяется искренней улыбкой*\n\n- Хах, и правда всего иллюзия! И ты так все время можешь делать? *Он уже чувствует что выбор заговоров будет очень непростым и долгим делом. Но вместе с тем и крайне увлекательным - как и любая магия в глазах мальчика*\n\n- Фокусы и правда выглядят очень полезными...\n\n*Он приподнимает бровь на словах Сона о характере учителя*\n\n- Вот как? И почему у меня такое чувство будто он знает о чем мы говорим...",171642,null],[171746,"2026-08-24T22:38:53",20,"/я уже представляю лицо Лазаря когда второй ученик подряд выберет фокусы вместо иллюзии",142532,null],[171818,"2026-08-24T22:46:17",9,"//Ну, мне как игроку нарятся разные вещи, лассо молний то же, и всё такое. Но да, бесим учителя 😏👌",171746,null],[171826,"2026-08-24T22:47:59",20,"//когда играла в долине ледяного ветра в нетерильском некрополе наткнулись на книгу что-то вроде \"101 способ применения малой иллюзии\". Учителю нужно такой же аналог в этом мире написать для нормисов с фокусами",171818,null],[171847,"2026-08-24T22:51:17",9,"//Вообще круто написать книгу о заговорах, реально книгу с вариантами применений)",171826,null],[171919,"2026-08-24T22:59:16",9,"Парень, ученик Лазаря (Сон) — Не переживай, так. Да и мы почти пришли. — *Шум, огни и на сцене уже кто-то сражался, когда Сон провел тебя за спинами людей. Выкрики чтобы Гарет показал выскочке, люди явно делали ставки на проверенного человека.*\n\n*Столик на уцелевшей части стены куда открывался хороший вид. Правда пришлось пройтись немного пройтись, тут было еще несколько таких мест и столов, там сидел знакомый полурослик Кларк с каким-то мужиком, слишком далеко чтобы услышать о чем шушукались.*\n\nПарень, ученик Лазаря (Сон) — Располагайся, сейчас я быстро распоряжусь чтобы нам накрыли на стол. — *Он взгянул на сцену, где Конрад дрался с каким-то головорезом, удар, уворот, удар, нокаут. Выкрики и аплодисменты, Конрад вырубил противника.* — А это там не твой друг?",171674,null],[171980,"2026-08-24T23:06:58",20,"*Рен переводит взгляд на сцену, видя знакомую фигуру*\n\n- И правда. *Он наблюдает за блестящей победой товарища* \n- Вот уж кто действительно нашел свое место *он присоединяется к аплодисментам, взглядом ищу Люпена и Чифа с Димоном*",171919,null],[171986,"2026-08-24T23:08:06",9,"//Люпена уже проверка восприятия, сл 14",171980,null],[171987,"2026-08-24T23:08:10",20,"/какая в целом дистанция вокруг на арене? Что примерно попадает в 60ф?",142532,null],[171993,"2026-08-24T23:09:00",9,"//Не знаю что отвечать, не совсем понимаю что именно спрашиваешь ~",171987,null],[171995,"2026-08-24T23:09:32",20,"/r -d20+2 ищем знакомые лица",171986,null],[171999,"2026-08-24T23:10:03",20,"/кто примерно попадает в область обнаружения мыслей",171993,null],[172000,"2026-08-24T23:10:31",9,"//Скок футов там вокруг тебя?",171999,null],[172001,"2026-08-24T23:11:21",20,"/30",172000,null],[172003,"2026-08-24T23:12:39",20,"/хочу просто немного подслушать собрать инфу для товарищей - может кто теперь замышляет что-то против или просто что-то интересное попадется",142532,null],[172350,"2026-08-25T13:20:20",9,"*Несколько людей внизу, Сон пошел пока уведомит чтобы им принесли еду. Кларк на мгновение взглянул на тебя, смотрел мгновение и обсуждал тихо указывая на сцену, но он далеко, только его собеседник сидит спиной к тебе , ближе и попадает под заклинание.*",171999,null],[172364,"2026-08-25T13:25:55",9,"Страшный как тысяча чертей рыжий кот (Рыжик страшила) — Фауст или Лоск, а после может Гримли согласится выйти против тебя, уговор был что после сражения с одним из чемпионов ты вызовешь на бой Гримли, тогда он не сможет отказаться. — *Кот закурил трубку, сделал паузу.* — Надо внимательнее слушать этого кота. Конечно ты можешь отказаться, но уговоренной награды тебе не видать. — *Кот когтем встряхнул трубку.* — Как и своей репутации. Советую подумать о том, есть ли у тебя вообще выбор. Хе хе кхе кхк кх... кхм. Отдыхай и готовься к бою, \"чемпион\".",169786,null],[172366,"2026-08-25T13:26:37",9,"//Напомню о вдохновах, их можно докидывать как и к броскам на атаку, проверки так и к урону, по одному за раз)",145244,null],[172419,"2026-08-25T13:50:31",31,"- ладно, думаю я готов выйти простив следующего. Выбираю громилу, это Лоск вроде?\n\n//Я так понимаю, короткий отдых и лечение меня восстановили?//",172364,null],[172469,"2026-08-25T15:06:17",9,"// @PaIIasCat",172350,null],[172472,"2026-08-25T15:07:14",9,"// @dunchev",169424,null],[172474,"2026-08-25T15:08:17",9,"//Короче, пока Конрад отдыхает, вы видите его на арене, сидите на своих местах и все такое. У вас есть окошко для своих дел перед раудом с кем-то из чемпионов.",142532,null],[172481,"2026-08-25T15:34:26",20,"/хочу обнаружением мыслей пройтись по тем до кого дотягиваюсь",172469,null],[172797,"2026-08-25T18:33:04",9,"*Снизу трое о чем то горюют. Кто то вспоминает почившую маму, это чувствуешь отчетливо. Они кадется подвыпивши, сидят под стеной, грустят о своём каждый.*\n\n*Тот человек что сидит спиной к тебе сейчас заботится о выгоде, тренировках и власти, очень властный человек.*",172481,null],[172813,"2026-08-25T18:36:24",9,"Парень, ученик Лазаря (Сон) — Я распорядился, нам принесут отличную отбивную. — *Сон вернулся и сел с улыбкой рядом, но мысли, хоть и поверхностные были его тяжелы.*\n\n*Он боялся глаз Рена, кажется старался в них не смотреть, словно его разум каждый раз вздрагивал когда ты сморел на него. Внешне Сон старался не показывать это. Тревоги, мысли о родных и какие-то невнятные обрывки о проклятии роились в его мыслях.*",172481,null],[172877,"2026-08-25T18:51:59",20,"*Пацан вздыхает, похоже мало что путного из мыслей окружающих удастся вытянуть. Поэтому сосредотачивается на властном человеке, сидящем к ним спиной. Наверное это и есть тот самый ветеран из приближенных Жанки, который тренирует воинов. Тут может и что-то интересное проскочить... Особенно когда начнется бой Конрада.*\n\n*Параллельно обращается к Сону*\n\n- А чем ты ещё занимаешься в лагере? Ну, помимо учебы и помощи учителю. Есть тут какие-то события кроме арены по вечерам? *Рен спрашивает беззаботно, стараясь разговорить и отвлечь от мыслей.*\n\n\"Почему он боится моих глаз?\" - крутится в голове мальчика. Конечно, они и раньше были слегка странно цвета, но почему-то последние пару дней люди слишком часто фокусируются на них - раньше такого не было. Это начинает его настораживать - может те самые внешние проявления из-за зелья? Нужно найти зеркало...*\n\n/Рен не в курсе какого они сейчас цвета стали, думает что все ещё блекло серые с желтизной\n/В остальном ждём бой",172813,null],[172884,"2026-08-25T18:55:10",9,"//Тоесть ты хочешь вытянуть больше мыслей с здоровяка и концентрируешься на нём?)",142532,null],[172887,"2026-08-25T18:56:20",20,"/не углубленное чтение, чтоб не спалится)\n/Просто его мысли чисто слушаю, без отвлечения на всяких грустных работяг",172884,null],[172904,"2026-08-25T19:01:16",9,"Парень, ученик Лазаря (Сон) — Помогаю учителю с делами и исследованиями древностей. Делаем волшебные палочки, и... — *Он взглянулна твои глаза и его передернуло. Сидит молчит пару мгновений пока его не перебивает звук тарелок, уставшая повариха принесла вам поесть, отбивные, овощи, фрукты, салат все самое лучшее. От Сона на мгновение повеяло решимостью и он заговорил начиная есть будто невзначай.* — Ты же... из проклятого дворянства?\n\n*В это время большой парень повернулся к арене, ему нравилось то что он там видел. А ещё чувство наживы, когда предстоит хорошая сделка совсем скоро или появятся лишние деньги.*",172877,null],[173038,"2026-08-25T19:29:00",17,"— Да, мой товарищ. \n\nЛюпен посмотрел на бой\n\n— Он справится.",169424,null],[173044,"2026-08-25T19:31:56",17,"— Охота пошла не по плану, я набрёл на ледку кабанов и за мной погналась Кабаниха и вепрь. Кое как откидывался камнями из пращи и прятался. А потом меня насадили на кабаньи клыки.\n\nПоказывает перевязанный живот\n\n— Шельма спасла. Представь, я только что был отброшен вепрем на землю, шансов спастись нет. И тут дымовая шашка, слепит вепря, я в кусты нырнул. А Шельма начала их колоть. Ну... Я чуть оклемался и тоже помог. Я не хвастаюсь, но пару камней удачно залетели прямо в жбан.",142532,null],[173045,"2026-08-25T19:32:20",20,"/я вообще в курсе что такое это проклятие дворянство? Что-то из Веспирали?",172904,null],[173047,"2026-08-25T19:33:02",9,"//Да, вряд-ли знаешь, но можешь кинуть на историюс сл 20 минимальная инфа, крит 20 чуть побольше может",173045,null],[173054,"2026-08-25T19:35:01",20,"/r -d20+2 история, чем черт не шутит",173047,null],[173061,"2026-08-25T19:39:50",20,"- Проклятое дворянство? *Рен недоуменно хмурится. Такое понятие ему явно не знакомо*\n\n- Нет, никогда о таком не слышал, точно не в Анежже. Это кто-то с твоей родины? *Спрашивает он, приступая пока к мясу и фруктам, аккуратно разрезая на кусочки (наконец-то нормальная еда!)*",172904,null],[173062,"2026-08-25T19:39:55",9,"*Никаких мыслей, едва ли упоминания в книгах.*",173055,null],[173070,"2026-08-25T19:43:33",9,"Молодой (Чифтер Люск) — Черт тебя потрепало как. Неужели ведьма тебя эта реально спасла. — *Видно что немного побледнел, под впечатлением.*\n\nВоин в больших доспехах (Димон) — Легко и кровь, нет ничего плохого. — *Вот Диме было все равно.*\n\nМолодой (Чифтер Люск) — Сейчас, я найду чет из целебных трав, полегче будет. А ещё, хорошо поешь сегодня. — *Он рассмеялся и похлопал по плечу.* — Главное жив, остальное прибудет.",173044,null],[173074,"2026-08-25T19:48:55",17,"— Общий улов будет.. дай ка вспомню. Поросенок, два кабанчика, Кабаниха и вепрь. \n\nЛюпен достал трофеи с вепря\n\n— Вот у меня трофеи есть, Шельма отдала. Ты не знаешь куда их в дело можно пустить?",173070,null],[173075,"2026-08-25T19:51:25",9,"*Парень вздохнул и наклонился чуть ближе.*\n\nПарень, ученик Лазаря (Сон) — Когда ты был в шляпе твои глаза горели золотом, как и сейчас. Ты колдуешь? — *Он тихо спросил но ответа не стал ждать.* — Я один из проклятых дворян, наш талант это проклятие. Золотые глаза, пока в поколении от одного человека более одного наследника оба безумеют пока не останется в живых лишь один из них, их глаза все сильнее горят золотом а магия становится хаотичной, искаженной и непредсказуемой. — *Он выдержал паузу, тяжёлая тема убрала улыбку с его лица.* — Поэтому я единственный ребенок своего отца, в моих глазах нет того блеска. Твои же глаза горят так словно два угля во тьме, ты... скажи честно... Рен, ты все ещё в себе?",173061,null],[173077,"2026-08-25T19:53:13",9,"Молодой (Чифтер Люск) — Черт, крупный. — *Он был впечатлён.* — Могу на выделку завтра отдать, такая толстая кожа. Из пушнины получится отличный доспех, или плащ.",173074,null],[173078,"2026-08-25T19:54:29",9,"*Его кулак сжался слегка согнув вилку которой он ел. Страх непредсказумости, хаоса.*",173075,null],[173079,"2026-08-25T19:56:23",17,"— Хм... Может получится плащ чтоб прятаться лучше. Бери.\n\nВсе отдал Чифу\n\n— Чиф, знаешь ещё рыбака Бороду? Я случайно прихватил его снасти из схрона. Хочу вернуть",173077,null],[173081,"2026-08-25T19:59:58",9,"Молодой (Чифтер Люск) — Борода? Не тот ли самый борода? Чёрт, он убьет если узнает, борода сам поплавки и снасти делает, гордится ими. Надо вернуть. — *Чиф осморелся неслышал ли кто его, благо шум и разговоры не выдали его.* — Лучше вернуть поскорее, переполоха пока небыло, значит на рыбалку он не ходил с пропажи. Что-то придумаю чтобы занять Бороду на утро, а ты утром пораньше верни где было.",173079,null],[173082,"2026-08-25T20:00:58",9,"*Достаточно темно и в небе развеваются облака, медленно, в этом месте... снова... видны звезды, яркие как никогда, кометы.*",163707,null],[173106,"2026-08-25T20:11:37",17,"— Да, завтра с утра с Шедьмлц сговорились пойти в лес. И точно будем проходить близ того места. Верну. А сейчас... Поесть и спать. Спасибо Чиф. \n\nЛюпен берет чеплашку и накладывает из общего котелка себе\n\n— Как у тебя и у Димы день прошёл расскажи",173081,null],[173109,"2026-08-25T20:18:53",20,"/пипец тут лордроп пошел",173075,null],[173110,"2026-08-25T20:21:48",9,"Воин в больших доспехах (Димон) — Положение позиции. Иди, иди. Так далеко. — *Димка явно был не в настроении.*\n\nМолодой (Чифтер Люск) — Тебя почти до обеда искали, да. Мне пришлось с димкой идти, но за пол дня мы ничего не выследили. — *Он насыпал себе поесть и Диме.* — Ты чего один в лес то пошел? Сказал бы хоть.",173106,null],[173111,"2026-08-25T20:25:10",20,"*Рен на добрых пол минуты просто...замирает. Не зная что сказать*\n\n*Проклятое дворянство? Безумие? Золотые глаза?*\n\n*Вилка сжимается в его руке. Какова вероятность что это не совпадение, какова вероятность-*\n\nНо что если Сон прав? Что если эта часть крови, от которой он всегда отмахивался действительно отравлена ядом проклятия?\n\n\"Не. Нет нет нет...Этого не может быть. Не может!\" \n\nТолько не разум. Только не контроль, которым он так гордился всю жизнь. Только не та власть над своей силой и самим собой, которую он так лелеял в неимении большего...",173075,null],[173112,"2026-08-25T20:28:49",17,"— Ну мне показалось я следы четкие нашел, явно Димкины. Но ошибся и заплутал",173110,null],[173113,"2026-08-25T20:29:46",9,"*Ты чувствуешь что он слегка паникует а потом начинает успокаиваться.*\n\nПарень, ученик Лазаря (Сон) — Ты слишком спокоен для сумашедшего. Прости, я наверное ошибся в суждении, это слишком близко связанно с моей семьёй. — *Кажется он пытается себя успокоить найдя какие-то доводы в голове, что ты вряд-ли с этим связан. Молча ест, звук столовых приборов о тарелку, где то на заднем плане выкрики \"давай, он почти упал, еще чуть чуть!\".*",173111,null],[173114,"2026-08-25T20:33:01",9,"Молодой (Чифтер Люск) — Ну выжил, это самое главное. Да еще с каким трофеем! — *Мастер чиф был все еще под впечатлением и достал боченок.* — Смотри чегоч свежее, сегодня привезли. Надо это отметить. — *Потом он умерил пыл и улыбнулся слегка ищвиняющейся.* — Хотя, за тобой с утра прийдет Шельмас не стоит напиваться, но пару кружек мы раздавим.\n\n*Дима уже сидел с протянутой кружкой.*",173112,null],[173115,"2026-08-25T20:33:25",20,"- Да. Ты прав *голос Рена звучит нарочито нейтрально, когда он тоже возвращается к еде.* - Наверное просто побочный эффект того зелья. Вот и все\n\n*Нож разрезает мясо на тарелке. Контролируемо. С выверенной точностью. Даже когда в мыслях хаос*",173113,null],[173116,"2026-08-25T20:35:40",17,"— Это очень соблазнительно. Но Шельма мне завтра шею свернёт если утром буду с похмелья. Так что...\n\n\nЛюпен смотрит на боченок, слюна подступает к глотке, он проглатывает ее и делает глубокий выдох\n\n— Только одну кружечку",173114,null],[173117,"2026-08-25T20:38:21",9,"*Реакция рена и слова о зелье добавило немного смятения в поверхностные мысли Сона, но он ничего не сказал.*\n\nВояка сидящий недалеко (наверное борода) — Сейчас начнут, думаешь новичок справится? — *Эти его слова были слышны.*\n\nПолурослик (кларк) — Со счетов его явно не списывал бы, выглядит так словно осилит раунд и... — *Его перебил.*\n\nВояка сидящий недалеко (наверное борода) — Да, Гримли засиделся на лаврах славы, хитрец. Неплохой способ ты придумал. — *На его слова Кларк лицюшь хмыкну и похоже поумерил пыл бороды, они снова начали общаться тише.*",173115,null],[173118,"2026-08-25T20:43:19",9,"Молодой (Чифтер Люск) — Да, лучше одну. И ты главное, заедай. — *Он из кармана достает немного ржавый пробку краник и просто вкручивает его в специальное место в бочко, наливая всем по кружке.* — Ну, будем! За знакомство и товарищество!\n\nВоин в больших доспехах (Димон) — Я не сдаюсь. — *Тоже поддержал тост.*\n\n*После нечкольких глотков, густого пенного солода почти в идеальной кондиции, что перебродило лишь чуть чуть но это не ощущалось особо, мастер Чиф решился тихо спросить.*\n\nМолодой (Чифтер Люск) — Как тебе Шельма? Её все бояться, глаз положил или она сама тебя за собой таскает, может ты ей приглянулся? — *Спрашивает тихо, секретничает. Видно что интересно молодому что все так сложилось.*",173116,null],[173119,"2026-08-25T20:51:54",17,"— Ну... Знаешь. Чесно сказать не в моем вкусе. Понимаешь у меня жена есть. Да и в целом девушки нравятся слабые, утонченные, нежные. Такие которых хочется оберегать и хранить от опасностей. А Шельма, ну она просто оторвёт тебе член если ты косо посмотрел. Так что... Нет. Это точно не моего поля ягодка.",173118,null],[173120,"2026-08-25T20:53:07",9,"Молодой (Чифтер Люск) — И то правда. — *Задумчиво пьет пиво, кажется он наприлумывал себе лишнего.*",173119,null],[173121,"2026-08-25T20:53:54",9,"//Думаю, может Рен еще скажет чего в своей сцене по желанию, а так пора к Конраду уже, скоро битва с чемпионом)",142532,null],[173122,"2026-08-25T20:55:50",20,"/да ты на него столь лора дропнул что он там в афиге сидит)\n/Я тоже, так что наверное можно к Конраду переходить",173121,null],[173123,"2026-08-25T20:56:12",9,"//Ток Алексей спит, щавтра уже",142532,null],[173151,"2026-08-26T06:01:14",31,"Конрад восстановил пошатнувшееся здоровье и готов к бою. Выходит на арену и говорит ведущему:\n\n- я бы хотел вызвать на бой Лоска, если он не против конечно. \n\nСмотрит на Лоска и говорит:\n\n- ты же не против, правда, Лоск?",142532,null],[174630,"2026-08-27T13:08:05",9,"*Мужики в масле закончили свой раунд, это был бой на истощение, в песок и солому упал первый кто выдохся, что стало победой для другого.*\n\nВедущий головорез — Дааа, наш претендент уже отдохнул и готов. Он выбрал своего чемпиона!\n\n*Лоск усмехается, он снимает рубаху и перепрыгивает через ветхую ограду, идёт играя мышцами. Опытный борец и воин, он обходит по кругу демонстрируя свои мышцы и силу. Если с ним сражаться то надо выложится по полной, иначе точно можно проиграть.*\n\nВедущий головорез — Делайте ставки господа! Сможет ли тёмная лошадка занять место чемпиона, или нет!\n\n*Людям давали время определится, подумать, решить. Толпа поддерживает Лоска, но некоторые за Конрада всем сердцем, краем уха слышно что соотношение собралось 1 к 10.*\n\nЛоск — Ты проиграешь. — *Он небрежно улыбается после обхода хрустит шеей и пальцами. Конрада он не принимает всерьёз как противника. Ждет пока люди закончат делать ставки и ведущий обьявит начало, так почему не перекинутся парой фраз?*",142532,null],[174631,"2026-08-27T13:13:13",31,"- проиграть можно войну, или борьбу за жизнь. А у нас тут просто бой на потеху публике, так что не драматизируй, а покажи шоу, не разочаруй публику",142532,null],[174632,"2026-08-27T13:18:48",9,"*Он хмыкнул и слегка кинул взгляд на абсолютного из трех чемпинов, на Гримли, больше ничего не сказал.*\n\nВедущий головорез — Дааа! Ещё мгновение и будет бой, я чувствую нам ьудет на что посмотреть. Возьмет ли Лоск проворного и быстрого Конрада в захват или нет! — *Он нагревал толпу и вскоре уже стоял перед вами.* — Вы готовы начать?!\n\nЛоск — Да, только если наш новичок не передумал. — *Он улыбнулся, явно уступатт свое место не собирался в обозримом будущем, даже не допускал этого.*",174631,null],[174634,"2026-08-27T13:20:01",31,"- это я тебя вызвал, и это у тебя был вариант не выходит. Приступим",142532,null],[174635,"2026-08-27T13:20:30",31,"/roll d20+3 инициатива",142532,null],[174643,"2026-08-27T13:29:14",9,"/roll 1d20+1 ну и кд одинадцать как понятно",142532,null],[174645,"2026-08-27T13:31:35",9,"*Лоск встал в стойку, нагнулся готовый совершить рывок и всем весом ринулся на Конрада как только ведущий отдал старт, чуть не сняся по пути самого ведучего.*\n\n//Он входит в твою досягаемость, есть какие-то действия вне хода перед тем как ударит?",142532,null],[174659,"2026-08-27T13:49:52",31,"/roll d20+4 Применяю прием готовность",174645,null],[174665,"2026-08-27T13:51:21",31,"/roll d4+3+d8 встречаю его ударом колена в голову, ловлю на противоходе и использую силу инерции его же тела против него",142532,null],[174667,"2026-08-27T13:51:28",31,"9 урона",142532,null],[174669,"2026-08-27T13:51:39",31,"Мой ход?/",142532,null],[174670,"2026-08-27T13:52:00",9,"//Ты реакцию использовал, еще его ход)",142532,null],[174672,"2026-08-27T13:52:11",31,"А, ок/",142532,null],[174673,"2026-08-27T13:52:14",31,"Ебашь/",142532,null],[174675,"2026-08-27T13:55:15",9,"/roll 1d20+6 удар",142532,null],[174678,"2026-08-27T13:55:38",9,"/roll 1d8+4 урон",142532,null],[174680,"2026-08-27T13:56:14",9,"/roll 1d20+8 захват бонусным спас атлетики или акробатики чтобы не оказать в захвате",142532,null],[174684,"2026-08-27T13:59:07",31,"А не дохера урона от голых кулаков? Это что за демон тут в противниках, у него железные кулаки?/",174678,null],[174685,"2026-08-27T13:59:37",31,"/roll d20+3 акробатика, пытаюсь вывернуться из захвата",174682,null],[174690,"2026-08-27T14:01:49",9,"*Тебя крепко обнимают под плечи после тяжелейшего удара, не двинутся.*\n\nЛоск — Поймал.\n\n//Твой ход, ты в захвате, там просто скорость 0 и у него тот боевой стиль на кулаки и он драчун поэтому если попал то схватил бонусным)",174686,null],[174693,"2026-08-27T14:04:07",31,"//не, меня интересует именно почему у него кость урона аж д8. У меня д4, да и вообще, чтобы так голой рукой бить это нужно быть монахом уровня так 10.",142532,null],[174694,"2026-08-27T14:05:03",31,"/roll d4+3 удар головой в нос\n/roll d4+3 коленом в бедро пытаюсь отсушить ногу",142532,null],[174696,"2026-08-27T14:05:11",31,"Все мимо, добивай/",142532,null],[174697,"2026-08-27T14:05:35",9,"//Это урон, а попадание где, почему там д4???",174695,null],[174699,"2026-08-27T14:06:29",9,"//Урон от боевого стиля воина, того что через силу, там если он не использует оружие кость урона кулаками от силы ищ д6 становится д8)",174696,null],[174702,"2026-08-27T14:07:14",31,"Затупил, сорян/",174697,null],[174703,"2026-08-27T14:08:07",31,"/roll d20+4 удар головой в нос\n/roll d20+4 колоеном в бедро, пытаюсь отсушить ногу",142532,null],[174705,"2026-08-27T14:08:25",31,"/roll d4+3 удар головой в нос проходит",142532,null],[174707,"2026-08-27T14:08:29",9,"//Первая попала ток",142532,null],[174708,"2026-08-27T14:09:04",9,"*Он слегка окилывает голову, пытается тебя обронить на пол и скрутить.*",142532,null],[174710,"2026-08-27T14:09:28",9,"/roll 1d20+8 атлетика против твоей атлетики или акробатики черта борец",142532,null],[174715,"2026-08-27T14:09:52",31,"/roll d20+3 акробатика, пытаюсь вывернуться",142532,null],[174717,"2026-08-27T14:10:47",9,"*Он берёт в захват, твои руки в неудобном положении чтобы к нему достать.*\n\n//Теперь ты ещё и опутан, атаки по нему с помезой, ход",142532,null],[174718,"2026-08-27T14:12:13",9,"Ведущий головорез — Да! Лоск взял Конрада в свой знаменитый захват! У него нет шансов против чемпиона, из него не выбраться.\n\n//А ещё все попытки выбраться теперь с помехой)",142532,null],[174719,"2026-08-27T14:13:53",9,"//У тебя есть вдохновы, их можно докидывать к чему угодно, урон, броски попадания и тд, по одному к однойму броску, напомню)",145244,null],[174720,"2026-08-27T14:16:33",9,"Парень, ученик Лазаря (Сон) — ... это там не Конрад? Тот что хотел стать писарем но после передумал. — *Юный волшебник отвлёкся от тяжелых дум на шум со сцены.*",173122,null],[174721,"2026-08-27T14:18:27",9,"Молодой (Чифтер Люск) — Черт, Конрад не вытаскивает. Я на него постабял семь золотых, немного но если бы выиграл было бы уже семдесят.\n\nВоин в больших доспехах (Димон) — Два денег. — *Димон не деьает ставки, он в эти азартные игры не играет.*",173119,null],[174724,"2026-08-27T14:19:17",31,"Бить то будешь?/",174717,null],[174727,"2026-08-27T14:19:50",20,"- Ага, это он *Кивает Рен, смотря за боем. Кажется этот бой идёт не так удачно, но шансы все ещё есть. Наверное*\n\n- Ну, надеюсь он хотя бы получает удовольствие...",174720,null],[174728,"2026-08-27T14:19:53",9,"//Действие потратих он свое чтобы тебя скрутить, твой ход все попытки выбраться и удары с помехой",174724,null],[174729,"2026-08-27T14:20:53",17,"— Бывает не везёт. Но он смотрелся не хуже второго это точно. Конрад не обучен грязному бою, он воспитан как то слишком хорошо. А вот второй то, по моему другого поля ягодка.",174721,null],[174736,"2026-08-27T14:23:35",31,"/могу одну атаку потратить на попытку вывернуться, а вторую уже на атаку? Или обе на то чтобы вывернуться?/",174728,null],[174737,"2026-08-27T14:23:43",9,"Молодой (Чифтер Люск) — Выбери он Фауста, это был бы равный бой. Тот быстр так же, или чуть быстрее чем наш друг, но у него нет техники. — *Мастер Чиф лишь покачал головой.* — Но и с Лоском дело идет, Гримли легко его побеждает, просто не попадаясь в захваты.",174729,null],[174739,"2026-08-27T14:24:49",9,"//Действие чтобы вывернутся и то с помехой, атаки по нему с помехой но кд всего 11 и у тебя 4д4 есть к урону или попаданиям, броскам своим персом, думай)",174736,null],[174741,"2026-08-27T14:25:58",31,"/roll -d20+4 попытка ударить головой еще раз\n/roll -d20+4 ну и коленом куда попаду",142532,null],[174743,"2026-08-27T14:26:21",9,"Парень, ученик Лазаря (Сон) — Люблю смотреть на бои. Но если бы мне предложили участие? Отказался бы.",174727,null],[174745,"2026-08-27T14:26:54",31,"/roll d4+3+d4 использую одно из вдохновений для усиления урона от удара головой и надесб что он захлебнётся кровью",142532,null],[174747,"2026-08-27T14:28:16",9,"Лоск — Что ты вертишся. — *Он шмаркнул кровью тебе на шею, второй удар уже прошелся ему в нос, он явно злится.*",142532,null],[174748,"2026-08-27T14:28:34",9,"/roll +d20+6 тяж удар",142532,null],[174750,"2026-08-27T14:28:44",9,"/roll 1d8+4 урон",142532,null],[174753,"2026-08-27T14:29:11",9,"*Он заламывает руку, очень, очень больно, лицом в пол.*",142532,null],[174754,"2026-08-27T14:29:20",9,"//Жив там?",142532,null],[174755,"2026-08-27T14:29:49",31,"1 хп",142532,null],[174756,"2026-08-27T14:30:12",9,"//Твой ход, на бонусное у него нет ничего, у тебя ещё 3д4 вдохновений)",142532,null],[174761,"2026-08-27T14:31:16",9,"Ведущий головорез — Кажется наш победитель почти определился! Конрад хорошо шел но отработанная техника захватов... — *Разгорячает толпу.*",142532,null],[174762,"2026-08-27T14:31:43",31,"/roll -d20+4+d4\n/roll -d20+4+d4\nПытаюсь бить локтем той руки что не заломлена, использую на каждую атаку потулсьи вдохновения",142532,null],[174764,"2026-08-27T14:32:03",31,"Не вдохновился/",142532,null],[174765,"2026-08-27T14:32:27",9,"/roll +d20+6 ну, с богом",142532,null],[174768,"2026-08-27T14:36:12",9,"*Конрада вырубают, слышится брейк и Лоска убирают со сцены. Тот немного постоял у края арены прежде чем вернулся на своё место. Конрада отнесли и положили там где сидит кот, он пришел в сознание лишь когда его обрабатывали и поили отваром, на сцене сейчас бились Фауст и Гримли, абсолбтный чемпион был медленнее, но удары по нему словно не шли, будучи на волосок от больнинства кулаков летящих в него.*",142532,null],[174769,"2026-08-27T14:36:50",31,"- рыжик, насколько все было херово?",142532,null],[174777,"2026-08-27T14:38:57",9,"Страшный как тысяча чертей рыжий кот (Рыжик страшила) — Ты был близко. Немного не хватило. Народ вдохновился. Лишь бы повезло чуть сильнее. — *Он пустил пару дымных колец и ответил на вопрос Конрада.* — Лоск сильнее тебя физически, мастерски использует захваты, но не более. Ешё одного хорошего удара в нос он бы не выдержал.",174764,null],[174784,"2026-08-27T14:43:56",31,"- я надеялся что с тяжелым противником смогу справится за счет скорости. Не вышло",142532,null],[174789,"2026-08-27T14:53:24",20,"*Рен с лёгким сожалением смотрит, как вырубленного Конрада уносят с ринга. Ну может в следующий раз повезет больше, уже с опытом*\n\n- А что тебе так в них нравится? Возможность понаблюдать за тактикой разных бойцов?\n\n/Или просто накаченные мужики в масле?🧐",174743,null],[174889,"2026-08-27T16:21:51",9,"Парень, ученик Лазаря (Сон) — Тут кормят сытнее если ходить не часто. А так. — *Он стал немного серьёзнее.* — Противники бывают разные. Немного знать о них не помешает, заклинатель держит расстояние, на нём найболее эффективен. А ещё, если ты знаешь что к тебе не добегут но могут достать стрелой лучше сесть на пол, плести заклинание, встать, использовать и присесть обратно. — *Сон немного усмехнулся.* — Если это волшебные стрелы, можно лежать за укрытием и не вставать, главное чтобы к тебе не подобрались.",174789,null],[174890,"2026-08-27T16:22:52",9,"*Ты наблюдаешь как собеседник Кларка чем то воодушелённый уходит. Кларк допив своё пиво тоже исчезает.*",174789,null],[174891,"2026-08-27T16:24:26",9,"Страшный как тысяча чертей рыжий кот (Рыжик страшила) — Скорость это хорошо, всегда бывают не удачные дни. — *Кот был немного разочарован, и тут из толпы вышел к вам бородатый мужик, он окинул Конрада что лежал на лаве, отходил.*",174784,null],[174892,"2026-08-27T16:25:20",31,"Окликнул?/",174891,null],[174893,"2026-08-27T16:25:56",9,"//Пока ток окинул, щас окликнет)",174892,null],[174894,"2026-08-27T16:26:03",9,"*Борода, но щас без доспехов.*",142532,null],[174895,"2026-08-27T16:33:08",9,"Борода (???) — Чей это Рыжий ты его на Лоска послал, с Фаустом бы посподручнее было, они же равны, техника та же. — *Обратился он к коту.*\n\nСтрашный как тысяча чертей рыжий кот (Рыжик страшила) — Он сам выбрал. — *Кот не вилял, но и в то же время, советов кому именно бросить вызов тоже не давал. Ухмыльнулся страшной улыбкой, да, не говорил всей правды остаыив вояку додумывать и хмурить брови.*\n\nБорода (???) — Ладно, что уже есть. — *Он отмахнулся от Рыжика и обратился к Конраду.* — Вижу, хороший ты боец, но не хватает техники, силы в ударах. Надо для дела, пойдешь к моим? Молодых учить времени нет, у тебя и удар поставлен и сам опыта наберёшься.",174892,null],[174896,"2026-08-27T16:34:06",31,"- а что за дело? Так то да, опыт мне явно нужен",174895,null],[174901,"2026-08-27T16:49:49",9,"Борода (???) — Учителем говорю пойдёшь. А то старшие уж больно занятые все, не хотят с молодежью возится. — *Борода ладонью чуть не сбил кота.* — А ты отдай ему что обещал, от меня будет, аванс.\n\n*Рыжик потер плечо прищемлившись на лапы от удара.*\n\nСтрашный как тысяча чертей рыжий кот (Рыжик страшила) — Лааадно, пусть берёт. — *Он нехотя отдает обмотки которые напоминают скорее тончайшую кольчугу порванную местами.*",174896,null],[174904,"2026-08-27T16:54:06",9,"\"Обмотки защиты\" (как наручи защиты)\n\nЧудесный предмет, редкий но сейчас \"необычный\" потому что потаскан (требуется настройка)\n\nПока вы носите эти обмотки, вы получаете бонус +1 к КД, если не носите доспех и не используете щит.\n\nЕсли починить обмотки они будут работать как \"Наручи защиты\". Для починки необходим мастер владеющий нужным рецептом и 1500 зм на починку только работой и материалами для этого.",142532,null],[174907,"2026-08-27T16:55:11",9,"//Я хотел дать наручи защиты, но они оказались редкими (думал они необычные), поэтому вот так извернутся пришлось.",174904,null],[174915,"2026-08-27T17:05:11",31,"- хмм, в учителя пойти? Ну вообще это интересно, я согласен. Меня учили монахи, так что будет теперь кому передать знания",174901,null],[174919,"2026-08-27T17:09:58",9,"Борода (???) — Во, наш человек. — *Он похлопал и Конрада по плечу, слишком по братски.*",174915,null],[174920,"2026-08-27T17:11:19",9,"*Взяв у Рыжика обмотки тыкнул их Конраду.*\n\nБорода (???) — Держи. И я надеюсь в слелующий раз ты их размоташь. Через месяцок, другой, мы тебя подтянем, поднатаскаем.",174904,null],[174921,"2026-08-27T17:13:49",9,"Страшный как тысяча чертей рыжий кот (Рыжик страшила) — Так ты и транжиришь всё, мне нечим людей приманивать уже. — *Ворчал кот высыпав пепел табачный.*\n\nБорода (???) — Деньгами мани, деньгами. А то всяким хламом разбрасываешься. За деньги купить можно что нужно, а это непонятный мусор. — *Борода явно не жаловал всякую хрень непонятную.*",142532,null],[174924,"2026-08-27T17:16:37",31,"Беру обмотки, осматриваю, вижу что толк какой то будет от них и наматываю на руки\n\n- спасибо, Борода. И тебе, Рыжик, тоже спасибо",142532,null],[174928,"2026-08-27T17:17:51",9,"Борода (???) — Выздаравливай давай, завтра с утра жду где жрачку раздают. — *Он махнул рукой и уходит по делам своим.*",174924,null],[174934,"2026-08-27T17:19:57",9,"Страшный как тысяча чертей рыжий кот (Рыжик страшила) — Плохо благодарить, не заметил, испольщуют тебя все. И я, и борода и Кларк для дел своих тёмных. — *Он ворчал и сел на лавку где лежал Конрад.* — Кто не знает спит крепче. С другой стороны, тоже плюсы.\n\n*Рыжик был не в настроении, откровенничать начал кот, о грешках чужих.*",174924,null],[174935,"2026-08-27T17:21:12",31,"-:а с чего ты взял, что и я вас не использую для своих дел?  \n\nПодмигиваю коту",174934,null],[174936,"2026-08-27T17:21:17",9,"Молодой (Чифтер Люск) — Эх, не сдюжил. — *Папень не долго оплакивал сыои 7 золотых.* — Пошли чёль заберем его к костру.",174729,null],[174937,"2026-08-27T17:21:43",9,"Страшный как тысяча чертей рыжий кот (Рыжик страшила) — Хех. — *Кот лишь хмыкнул и молчит.*",174935,null],[174948,"2026-08-27T17:40:39",20,"- Понятно, значит оценить на всякий случай на будущее *кивает Рен, кажется ответ ему показался очень...полезным.*\n- Интересно будет понаблюдать за этим в следующий раз с такой точки зрения\n\n*Он снова оглядывает толпу*\n- Интересно где там сейчас мои товарищи - найти бы их, поболтать немного перед сном. А то столько произошло за день...будто целая неделя прошла.",174889,null],[174954,"2026-08-27T17:43:26",9,"Парень, ученик Лазаря (Сон) — Доешь отбивную, или не будешь? — *Он указал на тарелку Рена.* — Можем пройтись, поискать твлих друзей, у костра где-то сидят наверное.",174948,null],[174962,"2026-08-27T17:53:08",20,"- Давай\n\n*Рен быстренько доедает то немногое что осталось от отбивной, аккуратно складывая тарелку и столовые приборы*\n- Посуду надо куда-то относить?",174954,null],[174971,"2026-08-27T17:54:50",9,"Парень, ученик Лазаря (Сон) — Да, но не нам. — *Он усмехнулся и позвал рукой за собой.* — Привыкай. Пошли поищем твоих друзей.\n\n*Идёт.*",174962,null],[174984,"2026-08-27T17:57:48",20,"/фига у магов тут вип сервис\n\n*Рен следует за ним, хоть и слегка медленно из-за физического состояния*",174971,null],[176207,"2026-08-28T11:07:47",31,"У нас тут уже поздний вечер вроде? Не пора на долгий отдых?/",142532,null],[176212,"2026-08-28T11:10:44",31,"Линии дня для всех троих явно же закончены/",142532,null],[176215,"2026-08-28T11:13:01",9,"//Рен пошел вас искать, Мастер чиф хочет Конрада к костру короче сходка у нас а потом снова все по своим делам. Жду когда будут все",142532,null],[176216,"2026-08-28T11:21:10",17,"Завидя Рена Люпен встаёт и машет ему",142532,null],[176221,"2026-08-28T11:43:48",31,"Конрад отходит от Рыжика, сам не зная куда идет, обдумывает предложение Бороды и то, чему ему предстоит учить новичков",142532,null],[176225,"2026-08-28T12:15:58",20,"*Рен завидев знакомые лица машет в ответ, спеша вместе с соном к костру*",176216,null],[176538,"2026-08-28T16:49:32",9,"Молодой (Чифтер Люск) — Ей! Конрад. Иди к нам. — *Ты слышишь как тебя подзывают к костру, среди шума толпы лагеря наемников.*",176221,null],[176539,"2026-08-28T16:51:04",31,"Оборачиваюсь на крик\n\n- о, привет. Иду\n\nПодхожу к костру, приветствую всех и присаживаюсь рядом",176538,null],[176607,"2026-08-28T17:55:50",9,"Молодой (Чифтер Люск) — Как, ничего тебе не сломали? Жив. — *Мастер Чиф насыпает тебе вкусной свинины из котелка.*",176539,null],[176608,"2026-08-28T17:56:59",31,"- только чуток гордости поломалось, а кости целы. Вроде",176607,null],[176609,"2026-08-28T17:57:32",9,"//Паллас нет на этот раз, эх",142532,null],[176610,"2026-08-28T17:57:48",17,"/ @PaIIasCat",142532,null],[176611,"2026-08-28T17:58:04",17,"/ Да вон она сидит, работает, щас маякну))",176609,null],[176613,"2026-08-28T17:59:21",9,"//Го, там дальше я вас каждого соло еще поведу немного и будет. Хочц закончить и устроить перерыв, не думать некоторое время. А то затянулось чуть чуть дольше чем планировал. Слона по кусочкам едят",142532,null],[176622,"2026-08-28T18:10:48",20,"/оп, я тут",142532,null],[176625,"2026-08-28T18:22:43",9,"*Когда вы подошли к костру Чиф тоде помахал в ответ.*\n\nМолодой (Чифтер Люск) — О, к нам уважаемый маги пришли, быстро ты занял место повыше. — *Он показал большой палец.* — Так держать малец.\n\nПарень, ученик Лазаря (Сон) — Да Рен везунчик. Мне стоило больших трудов найти учителя, хорошие волшебники перевелись. — *Сон потрепал Рена по волосам.* — Не переживайте, я за ним присмотрю, учитель местами бывает строг и перебарщивает. Правда, никогда не заставляет делать то что предлагает, скорее предлагает выбор от которого невозможно отказаться.\n\nВоин в больших доспехах (Димон) — Истинный цвет. Выбирите все что вы хотите. — *Здоровяк кажется ценил свободу выбора, кск и хорошее пиво которое давил вместе с едой.*",176225,null],[176653,"2026-08-28T18:49:14",20,"- Хах, да сегодня явно удача была на моей стороне *Рен улыбается, присаживаясь ко всем* \n- И с временем, и с местом и с людьми. \n\n- Истинные цвета мне и правда больше по душе *Отвечает он Димону, поправляя выбившуюся от потрепывания по голове алую прядь*\n\n- А вы как, обустроились? Хотя Конрада я на арене видел, в своей стихии похоже.",176625,null],[176660,"2026-08-28T18:50:29",9,"//Как вы могли заметить, Димон ведет вполне осмысленные беседы, накидываю вдохнову 1д4)))",176653,null],[176693,"2026-08-28T19:07:11",31,"- ну, я получил люлей и работу. Завтра пойду тренировать новичков рукопашке, Борода предложил место. И то хлеб",176653,null],[176694,"2026-08-28T19:08:44",9,"Молодой (Чифтер Люск) — Хорош, борода не обидит. Оно того стоит. — *Чиф и тебе пива налил, а после Рена спросил, был не уверен.* — Будешь пивчански? Или тебе рано ещё.",176693,null],[176696,"2026-08-28T19:15:42",31,"Хлебаю пиво. Кисляк, но не самый худший.\n\n- ну Рен теперь крутой маг, сам поди может наколдовать выпивки, если захочет",142532,null],[176707,"2026-08-28T19:25:40",20,"- И рано, и думаю мое тело сейчас может не выдержать *извиняющееся разводит руками пацан* - не хотелось бы упасть прям тут от одной кружки \n\n- А до того чтобы самому наколдовать мне ещё далеко - хотя было бы неплохо...",176694,null],[176713,"2026-08-28T19:32:16",9,"Парень, ученик Лазаря (Сон) — Не скажи. Сегодня Рен сплёл первый заговор. Но пиво рановато пить, да. — *Сон обратился к Чифу.* — А мне налей немного, только немного. — *Показал жестом примерно сколько в кружке быть должно, всего на несколько глотков.*\n\nМолодой (Чифтер Люск) — Да не вопрок, держи. — *Подает молодому магу кружку.*\n\n*Сон остородно пьет пиво, как маг он не гордый, довольно скромный, не то что его учитель.*",176707,null],[176714,"2026-08-28T19:32:36",9,"// @dunchev а ты, есть какие-то заявки?",142532,null],[177092,"2026-08-29T11:55:07",9,"// @PaIIasCat @QURTZZ @dunchev если вам не интересно или нечего сказать и тд — могу скипнуть",142532,null],[177097,"2026-08-29T11:57:52",17,"/ Да есть и интересно. Проблема в том что я щас заливаю отмостку, мешу цемент. Вот и все",142532,null],[177101,"2026-08-29T11:59:34",20,"/ждем когда все будут, мне интересно тоже поболтать",177092,null],[177113,"2026-08-29T12:20:22",31,"//я тоже занят пока//",142532,null],[177132,"2026-08-29T13:08:43",31,"//вообще, я не против скипа, если нет чего то реально двигающего сюжет. Не люблю я просто так трещать, вытягивая из себя речи//",142532,null],[177372,"2026-08-29T16:52:09",20,"/там, мы по социалке же сейчас чисто рассказ Люпена ждём?",142532,null],[177373,"2026-08-29T16:52:31",9,"//Я жду что вы друг другу хотите сказать и все такое",142532,null],[177395,"2026-08-29T17:47:09",17,"— Я поохотится, с переменным успехом. Шельма беловолосая спасла. А так ну вот завтра условился с ней снова пойти в лес, такие новости.",176653,null],[177396,"2026-08-29T17:49:39",17,"— Красивый плащик, ученикам магам такие выдают?",142532,null],[177400,"2026-08-29T17:53:27",20,"- Да, ещё и шляпу дали волшебную. *Рен разглаживает невидимую складку на мантии, явно довольный обновкоц* \n- Правда ее учитель перед походом сюда забрал - может чтобы я сегодня не колдовал больше, после зелья того...\n\n- А завтра ты тоже на охоту уходишь?",177396,null],[177405,"2026-08-29T18:03:36",31,"- волшебная шляпа, говоришь? Кроликов из нее можно вытаскивать? Облегчили бы охоту\n\nКонрад угарает чутка",142532,null],[177420,"2026-08-29T18:34:09",17,"— На охоту за сучьями въялой беръозы. Мы такую на болоте находили. Но ветки оказывается нужно сразу сгибать, пока сок внутри.\nА мои уже высохли и пришли в негодность.\n\nШельма согласилась сходить со мной, чтоб не помер по дороге. \n\n\nЛюпен отпил из кружки кисляка\n\n— Вепрь одним ударом суть на тот свет не отправил. Рем ты какую магию умеешь теперь делать? От вепря сможешь отбиться?",177400,null],[177421,"2026-08-29T18:35:43",17,"— Эх Конрад, жалко не держал последнего. Видел как тебе пару раз не повезло. \n\nЗатем Люпен вспомнил\n\n\"Кстате, борода там который, надо бы его снасти завтра его снасти вернуть\"",177405,null],[177431,"2026-08-29T18:44:54",20,"- Надо проверить - может и может *отвечает Рен крайне серьезно, не понятно шутка или нет*",177405,null],[177442,"2026-08-29T18:46:33",20,"- Пока не уверен, один на один точно не смогу - пока буду заговор пытаться наложить меня точно сожрут\n\n- Надо ещё научится их творить самому, не только со шляпой - там может и смогу что-то атакующее применять. Хотя фокусы пока звучат как самое нужное в быту...",177420,null],[177448,"2026-08-29T18:51:48",9,"Парень, ученик Лазаря (Сон) — Ммм, не понимаю ваше пиво. — *Он отдал кружку обратно.*\n\nМолодой (Чифтер Люск) — Хех. Молодой ещё, иногда без хорошего пива не обойтись после насыщенного дня. — *Протирает кружку.*\n\nВоин в больших доспехах (Димон) — Акак Дакан Пол Мукар Сенсорри. — *Бормочет здеровяк себе под нос.*\n\nМолодой (Чифтер Люск) — Дим, не налегай на пиво так сильно, заедай. На пустой желудок в голову сильно бьёт. — *Вроде отчитывал но с улыбкой, здоровяк лиш устало посмотрел на него и продолжил пить.*",142532,null],[177450,"2026-08-29T18:58:25",20,"- Если здесь есть пиво, значит что его здесь варят? Или есть кто-то, кто занимается поставками из ближайших поселений?",177448,null],[177453,"2026-08-29T19:00:16",9,"Молодой (Чифтер Люск) — Привозят, то с корчмы придорожной, то из союза.",177450,null],[177457,"2026-08-29T19:00:47",31,"- города недалеко получается? А казалось бы медвежий угол",142532,null],[177462,"2026-08-29T19:03:10",9,"Парень, ученик Лазаря (Сон) — Поставки неплохо налаженны. Шеф знает свое дело. — *Хорошо отозвался о Жанке и уже ответил Конраду.* — Смотря что называть городом. Большие поселения такими не назвать, а сама Веспираль, это скорее замаскированный некрополь, не город.\n\nМолодой (Чифтер Люск) — Не говори, жуткое место. — *Согласился мастер Чиф.*",142532,null],[182429,"2026-08-31T17:47:49",9,"*Поболтав с вами, Сон распрощалмя и ушёл с Реном в пристройку волшебников. Учитель не спал, Рену пока дали подушек и одеяло, похоже он будет спать сегодня у своего пустого мтола, или под ним как Лазарь под своим.*\n\nСон — Прости, пока так. Нам как писарям положенны свои небольшие палатки.",177450,null],[182442,"2026-08-31T17:49:19",9,"*С Люпеном да Конрадом Чиф и Димка додавили бочёнок, кто то пил больше, кто меньше. Да спать разложились.*",142532,null],[182446,"2026-08-31T17:50:02",9,"*Только звёзднре небо, такое красивое над головой.*",163707,null],[182452,"2026-08-31T17:51:04",9,"//Я решил скипнуть уже долгий раз заявок нет, с каждым отыграем по очереди ваши арки потихоньку.",142532,null],[182493,"2026-08-31T18:24:22",9,"// @PaIIasCat -2 уровня истощения, теперь у тебя всего два, дали лекарство, Рен спал крепко\n\n*Утро встречало тебя тем что было уже обедом. Лика сидела за своим письменным столом, усиленно переписывала документы. Лазарь на кресле пил кофе из своей фляги. Сон отсутствовал в домике у писарей да магов, похоже по делам.*\n\n*На твоём столе лежали письменные принадледности, по сравнению с отальными теперь личный угол Рена казался пуст. Небольшая стопка учебников по магии, пустые книги для заметок, листы, чернила, стул, все что надо для работы. Вчерашняя шляпа... а ещё волшебная палочка?*\n\n// Запиши себе: Набор каллиграфа, 3 пустые книги, Пустая книга заклинаний, Запасная зелёная мантия.\nИз особого: \"Волшебная палочка снарядов\" (необычный предмет) и \"Шляпа волшебства\" (обычный предмет)",142532,null],[182497,"2026-08-31T18:27:37",9,"// @QURTZZ рес все кости хитов и утро.\n\n*Когда ты проснулся, тебя растолкал Чиф.*\n\nМолодой (Чифтер Люск) — Просыпайся! Пора есть. — *Он собирался идти ща утреним завраком. Готовили то за вас, смысл жаловаться? Люпена уже нигде небыло.*",142532,null],[182503,"2026-08-31T18:29:26",9,"// @dunchev рес все кости хитов и хиты\n\n*Сон был не долгим, Люпен очнулся ни свет ни зоря от удушья, нос и рот был закрыт, дышать почти невозможно.*",142532,null],[182540,"2026-08-31T18:44:38",31,"-ммм, еда это славно",182497,null],[182579,"2026-08-31T19:05:43",9,"*Сегодня всем подавали рагу с хлебом.*\n\nМолодой (Чифтер Люск) — О, это не борода к нам идёт? — *Заметил он вояку что точно держал направление к вам.*\n\nБорода — Утро. Готов к трудовому дню, помятые кости уже не болят? — *Ровно, четко, по делу. Борода точно знал что говорит, зачем и что делает.*",182540,null],[182611,"2026-08-31T19:17:45",31,"- я довольно крепкий, сам удивляюсь что хороший сон лечит все, может даже перелом срастется, хрен знает",142532,null],[182652,"2026-08-31T19:32:21",9,"Борода — Хорош, доедай и пошли.\n\nМолодой (Чифтер Люск) — Удачи. — *Пожелал мастер Чиф.*\n\n*Лагерь, дела в нем шли своим чередом, сегодня Конрад полноценно станкт его частью, затесавшись своим среди наёмников.*",182611,null],[182679,"2026-08-31T19:45:30",31,"Быстро проглатываю завтра и спешу за бородой",182652,null],[183760,"2026-09-01T09:10:01",17,"/Время пришло",142532,null],[183761,"2026-09-01T09:10:46",17,"Люпен выпучил глаза продираясь с просони. Инстинктивно он схватился за руки котоыре его душили\n\n— МФМФММФМ ММФМФММИ",182503,null],[183822,"2026-09-01T10:36:36",20,"*В палатке магов Рен, пожелав всем присутствующим доброго утра, приступил к изучению своего стола. Первым делом переложив некоторые вещи в своем порядке.*\n\n*После этого он взялся за палочку и книги - наверное где-то в них может быть описание этого магического предмета и как им пользоваться. Ну а заодно посмотреть в целом что за учебные пособия у него есть*",182493,null],[183944,"2026-09-01T13:15:59",9,"*Тебя ждали молодые люди, они сидели на брёвнах да занимались своими делами. Парни лет 17-20 что недавно подались в наемники, там же сидел вчерашний претендент, и молодой Бунгаль среди них, кунял подпитый и слегка помятый.*\n\nБорода — Слушать! — *Он громогласно рявкнул на молодых из за спины, некоторые подскочили от его громогласного командирского голоса.* — Вы совсем зеленые перцы. Не хочу с вами возится, нашёл вам учителя. — *Он похлопал Конрада по плечу.* — С этого дня они твои, гоняй их как посчитаешь нужным, главное результат. Если не будут слушатся... — *Он улыбнулся, хотя это было больше похоже на угрозу.* — Заберу к себе особо ретивых и способных.",182679,null],[183945,"2026-09-01T13:17:37",9,"Охотница на монстров (Имельда или Шельма) — Умер. — *Она прошептала Люпену на ухо и перестала душить. Кинула в него поклажу и стала рядом опершись на стену, жлала.* — Собирайся, я жду.\n\n// Получен: \"Набор путешественника\"",183761,null],[183995,"2026-09-01T13:28:51",9,"*Основы магии и её плетения, подробная информанция о магических зонах и аномалиях, почему так. Учебники по математике, небольшой бестиарий предметов с описанием мвгических эффектов что им принадлежать и по мелочи.*\n\n*Есть книга с подробным описанием базовых заклинаний (сможешь изучить их не тратя материалы когда получишь использование заклинаний). Среди них: Щит, Доспехи мага, Волшебная стрела, Обнаружение магии и призыв фамильяра (остальные прости, ток на квестах уже тратя всё нормально).* \n\nБелобрысый ученый (Лазарь) — Ты проснулся. — *Он слегка хлопнул  книгой закрыв её и отложил её все ещё сидя на своем кресле, пил кофе.* — Сегодня я покажу тебе основы защитных искуств на практике. Книги не выносить, они мои. Шляпа и прочие принадлежности используй как хочешь. На столе у тебя есть волшебная палочка, будем учиться её использовать, но для начала. — *Он показал пальцем на остывший завтрак.* — Сначала завтрак.\n\nДевушка из писарей (Лика) — Доброе утро. — *Она тоже заметила Рена, и помахала мило улыбнувшись, вернулась к переписыванию. Судя по стопке, у девушки было прилично работы.*",183822,null],[184355,"2026-09-01T16:37:02",20,"\"Доброе утро\" - Рен ещё раз желает им доброе утро и отправляется завтракать. Интересно, есть ли магия способная погеть еду? Надо будет глянуть в книге...*\n\n*Завтракая, он задаёт интересующий его вопрос*\n\n- Лика, а над чем ты работаешь?",183995,null],[184377,"2026-09-01T16:43:47",9,"Девушка из писарей (Лика) — Это мамины чертежи. Хочешь посмотреть? — *Немного отвлёгкись она поправила волосы и слегка отсунулась на стуле, будто приглашая подойти и взглянуть.*",184355,null],[184408,"2026-09-01T16:47:21",20,"- Твоя мама изобретатель? (Насколько помню Рен был в отлючке когда Конраду рассказывали кто тут ещё есть)\n\n*Он тщательно вытирает руки после еды и подходит ближе, рассматривая чертежи. Интересно...*",184377,null],[184424,"2026-09-01T16:50:43",17,"Люпен откашливается и поднимается, трёт горло. \n\n— Вот тебе и доброе утро. Что прикажешь выставлять ночного дозорного?\n\nСобирается натягивая портки и рубаху с мертвеца. Берёт поклажу которую кинула ему Шельма и раскладывает удобнее. Сумку из простыни он оставляет. Теперь есть надёжный рюкзак\n\n— Я готов",183945,null],[184431,"2026-09-01T16:54:33",9,"*Основном отдельные элементы одного объекта, но есть и рисунок целиком с подписью:*\n\n\"Армилярная сфера, плохой звездочет из меня, но интересно будет такую собрать\"\n\nДевушка из писарей (Лика) — Ма любит всякие вещи, но чаще на ногах и собирает что-то. — *Она зыркнула на Лазаря тайком.* — Сюда приходит только по делам, ей слишком душно сидеть тут в заперти.",184408,null],[184434,"2026-09-01T16:55:28",9,"//Чертежи и зарисовка самой Армилярной сферы",142532,null],[184459,"2026-09-01T17:00:11",9,"Охотница на монстров (Имельда или Шельма) — Настоящий охотник всегда готов. — *Она поправила поклажу у себя на плече и бесшемными шагами направляется через лагерь к реке. Сонный часовой увидев её даже не стал обращать на вас внимания, или даже не стал интересоваться, потому что увидел Шельму.*\n\n//Скоро у Люпена наверно будет ПТСР от \"ты мёртв 1000 и 1 способом\" 😏👌",184424,null],[184464,"2026-09-01T17:00:40",31,"- ну привет, бойцы. я не знаю вашего уровня подготовки, и даже уровня выносливости. так что сеголдня начнем тренировку с забега на милю, а потом поделтесь на пары и посмотрю, какой у вас уровнь. Все ясно, или есть вопросы?",183944,null],[184473,"2026-09-01T17:03:23",17,"С завистью посмотрел на лук часового и крепче сжал свою худую пращу, набрал камней в боковой карман рюкзака\n\n— Есть какие нибудь правила путешествия с тобой? Или совет?",184459,null],[184474,"2026-09-01T17:03:53",31,"/два правила: не ссать и желтый снег не есть/",184473,null],[184475,"2026-09-01T17:04:46",20,"- Амилярная сфера...*Рен рассматривает рисунок с живым интересом. Что-то похоже он как будто бы помнил, но называлось оно немного по-другому*\n- Похоже на астролябию. Это тоже для определения положения светил?\n\n- Интересно как оно будет работать в этом месте, учитывая его странное перемещение и как сильно меняется звёздное небо ночью",184431,null],[184503,"2026-09-01T17:16:44",9,"Борода — Так держать. Я пошёл. — *Кажется мужик оушел довольным, он явно скинул свои проблемы на Конрада.*\n\n*Парни не то чтобы хотели отвечать, когда борода ушёл, кто усмехнулся, кто расслабился. Они яно собирались лентяйничать, только часть вела себя серьёзно.*\n\n— С чего бы это нам.\n\n— Ты сам не силтно старше нас, тебя вчера Лоск в песок уложил.\n\n*Уважения никакого, хотя добрая часть молчали, некоторые этого лишь не сказали вслух.*\n\nМолодой Бунгаль — Ах чартяка. Это жа ты, шустрыя рука змея. — *Ему плевать было что где когда, на него даже неодобрительно глянуло те двоя, он это заметил.* — Чо распизделись. Он теперь наш папка. — *Он встал более менее справляясь с похмельем, готовый к трудовому дню.* — Ящо рямня на вас вазьмёт хе хе, он сильнея.\n\n*Молодой Бунгаль встал готовый исполнять указания, хотя половину мимо ушей пропустил, но это был пример другим, большая часть просто пошла делать, а там и остальные. Тем двоим было нечего больше добавить когда за их спиной небыло толпы и молодые задрав носы все же снизошли до того чтобы побегать и позаниматься с остальными.*",184464,null],[184511,"2026-09-01T17:22:41",31,"Подхожу к болтливому пиздюку и даю затрещину:\n\n- я что то не видел чтобы ты вчера на арене феерил. Я, если что, хот ябы дошел до боя с Лоском, сможешь до него дойти, тогда и вякай. Уяснил? А с чего мен янужно слушать? тут две причины, первая - так сказал Борода. Можешь ему предъявить, что такой мастер как ты считает меня недостоным себя тренировать. Пойдешь или яйки сжались и ноги не идут? и вторая причина, почему ты мен ядолжен слушать - ты сам сюда пришел, ты даже не солдат, а наемник, то етсь пришел добровольно. и если тебя сюда определили, то ты либо слушаешь и учишься, либо пиздуешь обратно в свою деревню. Еще вопоосы?",142532,null],[184515,"2026-09-01T17:23:57",9,"*Пока вы шли к реке, она немного подумала и ответила на вопрос:*\n\n— Не хочу с тобой няньчится. Большой мальчик, должен сам справится. — *Она повернулась и усмехнулась, будто самое естественное.* — Если будет то с чем я не справлюсь, помощи не жди. Выживи.\n\n*Еще немного и вы дошли к рекес знакомые места.*\n\nОхотница на монстров (Имельда или Шельма) — Оставь снасти Бороды где те лежали и веди. — *Она не представляла кула дальше, зоря слегка сделала мир светлее.* — Покажешь где растут бяръозы.",184473,null],[184527,"2026-09-01T17:26:32",17,"— Да я не прошу нянчится. Скорее надо наверное какую то тактику выработать. Я вот всегда прячусь сперва, а потом бью изподтишка. Только так и выживаю.\n\nЛюпен говоря это уже шел к схрону под камнем. Он выложил все снасти ранее тут взятые.\n\n— Готово. Так... Мы шли оттуда, туда и отправимся\n\nЛюпен повёл Шельму за собой в сторону болота",184515,null],[184542,"2026-09-01T17:30:01",9,"Девушка из писарей (Лика) — Да, но точнее. У мамы есть сфера направления. — *Она показывает в центр где есть стекляная сфера с чем-то вроде компаса внутри.* — Ее устанавливаем тут, а вот. — *Показывает на отметки, градусы и другие измерителтные значения на деталях чертёжных.* — Они точно поменяют положение в зависимости куда девается это место. Можно будет наблюдать сам процесс перемещения, где мы и что с нами, даже время в том месте. — *Она улыбалась и расказывала с самоотдачей. Лика гордилась своей мамой и хвасталась её идеями.* — Можно проще, уйти ночью. Но никто не возвращался обратно.",184475,null],[184551,"2026-09-01T17:34:05",9,"— Да... — *Нехотя прошипел он, второй пошел за ним тренироваться.*\n\n*Были те кто старался, те кто отлынивал. Особо отличился Бунгаль, он делал через не могу, падал, все еще не восстановившись после вчерашней попойкис его разок вырвало завтраком, но на шатающизся ногах делал, упертый малый и не жаловался.*\n\nПолурослик (кларк) — Маешься. Борода на тебя зелень скинул. — *Пока Конрад наблюдал к нему почти подкрался подсобный Жанки.* — Как тебе, нравится дело.",184511,null],[184573,"2026-09-01T17:38:06",31,"- привет. да пока еще не понял. Но кто то же должен их тренировать.\n\nОглядываю своих полудохлых подопечных.\n\n- перерыв, 15 минут. затем разбиваемся на пары и отрабатываем связку из удара и контрудра с подсечкой. \n\nПодзываю Бунгаля и показываю пример.\n\n- после отработки перейдем к спарингам. Повоторим вчерашний турнир, но чуток попроще, до трех чистых ударов, за чистое использование разученой контратаки будет дополнительный балл. Приступаем",184551,null],[184576,"2026-09-01T17:38:15",9,"Охотница на монстров (Имельда или Шельма) — Просто избегаем опасности, мы здесь не за этим. — *Похоже те самые ветви были ей нужны.*",184527,null],[184577,"2026-09-01T17:39:01",17,"— По пути если заметим дичь охотиться будем?\n\nЛюпен присел как ему показалось у следа",184576,null],[184578,"2026-09-01T17:39:08",17,"/r +2 Выживание",142532,null],[184583,"2026-09-01T17:40:58",9,"Бунгаль — Да, я.\n\nПолурослик (кларк) — Нет, пусть отдыхают. Нам нужно с тобой перетереть. Отойдём? — *У кларка подмышкой было несколько свёрнутых листгв, лыбился он так будто задумал что-то недоброе.*",184573,null],[184585,"2026-09-01T17:41:40",31,"- Бунгаль, присмотри за тренировкой.\n\nКларку:\n\n- ну пойдем",142532,null],[184588,"2026-09-01T17:43:24",20,"- Значит сфера всегда показывает на север, так? *Рен задумывается, сопоставляя это со своим внутренним компасом. Небо было очень уж чистым, без следа пепла...это не просто перемещение куска земли на пару миль - тут явно что-то большее. Пересечение миров? А может само небо было лишь иллюзией, как то сияние на севере, о котором ему доводилось читать только в книжках? Интересно, такое вообще возможно?* \n\n- Вам уже удалось выяснить, в каком месте мы отказываемся ночью? В лагере говорили, что это фейское место - значит это из-за их влияния? Или все дело в какой-нибудь остаточной магии руин?\n\n*Когда он говорил о руинах его глаза буквально горели  любопытством. Явно хочется узнать о них больше*\n\n/кстати, а Рен чувствовал разницу в расположении севера днём и ночью? И момент перехода?",184542,null],[184592,"2026-09-01T17:44:32",9,"Охотница на монстров (Имельда или Шельма) — Если так хочешь поохотиться, мы поищем добычу после. — *Она остановила Люпена от его попыток найти что либо. Не смотря на это, кажется её позабавила ситуация.* — Когда сделаешь себе новый лук.",184579,null],[184598,"2026-09-01T17:45:58",9,"//Север был на севере, может и были отличия но минимальные, если бы так просто они бы по сфере направления вычислили а не собирали чёрти что)",184588,null],[184599,"2026-09-01T17:46:14",17,"— Понял, ну тогда просто пошли скорее к тому дереву. Тут еще где то Чага росла на коре деревьев, надо бы её прихватить, Рен сказал она лечебная.",184592,null],[184600,"2026-09-01T17:46:29",17,"/r +1 Поиски вниманием чаги на деревьях",142532,null],[184604,"2026-09-01T17:46:49",31,"Как ты в лесу выживал с такими бросками?))/",142532,null],[184605,"2026-09-01T17:46:50",9,"*На деревьях только ветки.*",184601,null],[184610,"2026-09-01T17:48:07",17,"/Так же как ты на арене))",184604,null],[184622,"2026-09-01T17:50:18",9,"*Кларк отошёл слегка от толпы, место слегка укромное но где вы стоите видно большой части лагеря и протянул листовки. На них розыск, Конрада, Люпена, всех вас.*\n\nПолурослик (кларк) — Я немного поспрашивал о вас, и мне пришли некоторые вести. — *Он не собирался обьяснять как и что, просто сказал:* — Расказывай как было. Если соврешь потом узнаю.",184585,null],[184627,"2026-09-01T17:51:37",31,"- да чт о сказать. Очнулись в темнице и спонтанно решили свалить. Каким то чудом это вышло, ушли лесом, потом на вас натолнкулись. все",142532,null],[184637,"2026-09-01T17:57:30",9,"Девушка из писарей (Лика) — Прости прости. Я не знаю. — *Она замахала руками и расммеялась. Её позабавило такое колличество вопросов, но то как настаивал Рен на ответах, его напор, немного смутил, обычно это она сама ко всем пристает.* — Не знаю я. А место фейским называют потому что тут много карликов, и они часто мешают. — *Она отсунула шухлядку и достала оттуда синий колпак чуть более 30 сантиметров, он торчар и был ровным таким конусом.* — Да и все странности этого места, как не назвать его фейским?",184588,null],[184647,"2026-09-01T18:02:24",9,"Охотница на монстров (Имельда или Шельма) — Из чаги получается хороший чай. Если её высушить, истолочь и сварить. — *Она расказывала несмылёному Люпену для чего этот гриб.* — Есть небольшие целебные свойства, да.\n\n//Если механически из-за чая чаги выпитого на коротком отдыхе востанавливаешь 1 хит. Может еще какие вопросы к Имельде пока идёте?",184599,null],[184659,"2026-09-01T18:06:01",9,"*Полурослик указал на суммы, по 500 золотых за большие лбы и 120 за пацана.*\n\nПолурослик (кларк) — Такие суммы за обычных воров не дают. Или вы важные шишки или... убийцы. — *Как много можно узнать просто по листовке о розыске.* — Это точно не всё.",184627,null],[184665,"2026-09-01T18:07:46",31,"- лично я никого не убивал, за других не скажу, мы познакомились в темнице. Больше скажу, я вообще за собой не знаю никаких преступлений, как оказался в камере просто не знаю",142532,null],[184667,"2026-09-01T18:08:44",9,"Полурослик (кларк) — За что ты оказался в темнице?",184665,null],[184670,"2026-09-01T18:10:48",31,"- не имею понятия. Последнее что я помню до того как проснулся в темнице - я зашел в таверну чтобы перекусить и переночевать. Я шёл из монастыря у своему единственному родичу. Сделал заказ, и злоп, очнулся в темнице, и так понимаю, нас планировали отправить в Веспираль",184667,null],[184683,"2026-09-01T18:15:13",17,"Люпен задумался что ещё спросить у охотницы со стажем он вспомнил как на первый взгляд крепкий и замаскированный силок сорвал и уловолок саблезубый олень\n\n— Шельма я тут силок давеча ставил. Ну вроде крепкий, шнурок там был надёжный. Замаскировал хорошо. Но на оленя мало оказалось. Есть какие нибудь хитрости. Чтоб ловушку наверняка ставить, а не на авось.",184647,null],[184689,"2026-09-01T18:17:01",9,"Полурослик (кларк) — Не хочешь говорить, ладно. — *Он не собирался долго распрашивать и перешел к делу.* — Я могу это дело замять, наёмники все разные люди с разными проблемами. Убьёшь для меня одного человека. — *Последнее он произнёс тихо, а после добавил:* — С твоим дружком Люпсеном возится Шельма. Пацан мал да к маг его под крыло забрал. Остался только ты, борода за тебя не вступится.\n\n//Вот такие вот пироги 😁",142532,null],[184694,"2026-09-01T18:20:04",9,"Охотница на монстров (Имельда или Шельма) — На оленя и силка хватит. Как он выбрался то? — *Она слегка удивилась, но вспомнив все моменты от поиска дичи до разделывания добычи (все крит еденицы) отмахнулась.* — Нужно делать силки, чтобы хорошо затягивались. Из плохого не только олень, лягушка сбежит.",184683,null],[184701,"2026-09-01T18:23:56",31,"- я разве на киллера похож? Тут вокруг толпа головорезов, выбирай любого. А мне такое не интересно, и на шантаж я вестись не буду, очень сомневаюсь что ту все вокруг ангелы с крыльями и сильно обрадуются появлению в лагере каких либо охотников за головами или законников",184689,null],[184702,"2026-09-01T18:25:33",9,"Полурослик (кларк) — Ты уверен что хочешь отказаться от моего щедрого предложения? — *Он слегка насмешливо улыбается.*",184701,null],[184703,"2026-09-01T18:26:09",31,"- да, уверен",142532,null],[184708,"2026-09-01T18:29:18",9,"*На мгновение, показалось что в глазах Кларка вспыхнул золотистый огонёк, словно чары или зкклинание пролились следующие слова из его уст:*\n\nПолурослик (кларк) — Ты сам выбрал свою судьбу... — *Мгновение и марево прошло, словно слов этих небыло вовсе.* — Ладно, я тебя услышал, если что — пиняй на себя.\n\n*Кларк уходит махнув листовками в след, оставив Конрада одного.*",184703,null],[184712,"2026-09-01T18:32:53",31,"С нехорошим предчувствием возвращаюсь к своим подопечным, наблюдаю за их тренировкой",184708,null],[184717,"2026-09-01T18:35:22",9,"//Выбор был слелан, мне сейчас нужен рен, в щависимости от его действий вглянуть пересечётесь ли вы и подумать крепко. Ну люпена вести, он на этот день из лагеря выпал точно",184712,null],[184733,"2026-09-01T18:44:06",20,"*Рен извиняющиеся улыбнулся, поняв что завалил бедную девушку вопросами.*\n\n- Все в порядке, прости что так много всего и сразу навалил. Просто все вокруг так сильно отличается от того, что я знал всю жизнь... Вот невольно и желание узнать новое пробуждается.\n\n- Хотя не могу обещать что не замучаю вас всех вопросами в будущем *полушутя говорит он на прощание.*\n\n*Он оставляет Лику заниматься переписыванием чертежей, а сам возвращается, убирает посуду после завтрака и после идёт к Лазарю. Наверное уже пришло время первого занятия*",184637,null],[184737,"2026-09-01T18:52:07",9,"Белобрысый ученый (Лазарь) — Ты уже щакончил свои дела? Тогда пошли, возьми с собой волшебную палочку.\n\n*Он взял несколько стеклянных колб и пошел наружу.*",184733,null],[184738,"2026-09-01T18:52:49",20,"*Рен взял с собой палочку, надел шляпу и последовал за учителем*",184737,null],[184786,"2026-09-01T19:19:08",9,"*Маг снаружи поставил несколько колб. У стены, а сам отошел. Вы были еще у пристройки магов, жизнь в лагере шла своим чредом. Кто-то иногда поглядывал на Лазаря мимоходом, походе тот редко выходил и показывался.*\n\nБелобрысый ученый (Лазарь) — Это волшебная палочка сделанная чтобы воспроизводить простейшее, но при этом не менее полезное атакующе заклинание. Его легко может остановить простейший барьер, но сейчас не об этом. — *Он достал из рукава свою палочку и взмахнул ею, сказав несколько таинственных слов, четко, чтобы Рен их услышал и запомнил, почти по слогам не спеша.*\n\n*Возле самих колб появились крохотные розововатые или больше фиолетовые вспышки и погасши превратились лучи или стрелы которые точно попали в колбы резким прошивающим движением и разбили их.*\n\nБелобрысый ученый (Лазарь) — Это магическая стрела, сотканая из барьера. Не смотри что они выглядели странно, годы практики ушли на то чтобы те появлялись прямо возле противника, обычно это несколько стрел которые ты направляешь точно куда тебе нужно. Заклинание простейшее и не требует концентрации, почти мгновенное. — *Он взмахнул палочкой еще раз во второй раз стрелы образовались уже вокруг него, синеватые пояти прозрачные и кажется улетели куда-то вверх.* — Как мог заметить, их преимущество в том что барьер остается невидим или почти что позволяет играючи попадать в противника, имея всего немного сноровки — в нескольких. Сначала могут быть ошибки и промахи, но с опытом ты сможешь с легкостью направлять их просто своей волей не задумываясь об этом. — *Он сделал шаг в сторону, будто давая рену проявить себя и при этом легче следить за учеником.* — Теперь возьми свою палочку и повтори с точностью за мной каждое действие и слово. Постарайся почувствовать отклик и направить своей волей снаряды куда положенно. Последнее — когда у тебя получится воспроизвести заклинание, сейчас лишь воспроизведи эффект и направь его в небо. Это все еще базовая практика, любой сможет при должном старании.\n\n//Магия сл 18, попыток неограниченно. Кинул куб, описал результат коротко, кинул следующий пока не получится скастовать стрелы",184738,null],[184799,"2026-09-01T19:22:58",9,"//Ебучая слодная магия, кастовать стены текста мать её и это только базовая магическая стрела её в зад, колесись она в аду чертова магия, какой же кайф это описывать, перфекто о май сир СПОЙЛЕР МАТЮКИ",184786,null],[184808,"2026-09-01T19:25:23",20,"*Рен в умен повторяет каждое слово, которое произнес учитель, примерно стараясь понять связь между ними и волшебной палочкой в уме. Потом сосредотачивается на этой связи и пытается направить ее импульсом воли, чтобы активировать магию*\n\n/Пошли попытки",184786,null],[184811,"2026-09-01T19:25:58",20,"/r d20+2 магия✨",142532,null],[184816,"2026-09-01T19:26:44",20,"*первый раз ничего не происходит, палочка просто направлена в небо. Ни искры*",184812,null],[184821,"2026-09-01T19:27:53",20,"*Второй раз тоже. Рен слегка хмурится. Возможно стоит попытаться повторить только слова, но представить их не как вспышки у учителя, а как стрелы?*",142532,null],[184826,"2026-09-01T19:29:05",20,"*Мальчик чувствует лёгкую ответную дрожь в магическом предмете. Близко. Но пока не достаточно. Ещё раз*",142532,null],[184834,"2026-09-01T19:30:44",20,"*Внезапно три яркие золотые искры вырываются из палочки, устремляясь в воздух, оставляя за собой стрелообразный след*",184827,null],[184835,"2026-09-01T19:30:48",9,"//Описывай свою первую магическую стрелу)",184827,null],[184838,"2026-09-01T19:31:20",9,"Белобрысый ученый (Лазарь) — Отлично, теперь еще раз.\n\n//Можешь без проверки",184834,null],[184859,"2026-09-01T19:38:15",20,"*Рен кивает, примерно поняв принцип. Оставить заученные слова, найти связь с предметом, подобрать свое воплощение для магии*\n\n*В этот раз уже освоив базовые заученные шаги, он начинает экспериментировать с последним - вопрощением.*\n\n*Хм, можно попробовать заострить наконечники, чтобы они больше были похожи на стрелы? Или попытаться уменьшить оставляемый ими след - в реальном бою он может выдать его положение...*\n\n*Из палочки вновь вырывается вспышка, уже в виде заострённые золотых четырехконечных звёзд. Небольшой след все ещё остался, похоже потребуется больше практики*",184838,null],[184860,"2026-09-01T19:41:24",9,"Белобрысый ученый (Лазарь) — Снова, по целям. — *Он указывает на колбы что расставил заранее.*",184859,null],[184864,"2026-09-01T19:42:24",20,"/проверки нужны?",184860,null],[184871,"2026-09-01T19:43:25",20,"/и надо ли кстати считать заряды 🤔",142532,null],[184873,"2026-09-01T19:44:31",9,"//Пока 5 зарядов истраченно, проверки не нужны, откуп на отыгрыш",142532,null],[184885,"2026-09-01T19:58:55",20,"*Рен направляет палочку на колбы, примерно прикидывая расстояние между ними. У него всего пара осталась зарядов, в целей больше. Но если постараться...*\n\n*Он выпускает одну искру, нацеливая ее в сосуд посередине так, чтобы попытаться осколками разбить соседние*\n\n*Две остальные искры следуют за первой и бьют по той же логики в следующие более отдаленные колбы, стараясь также зацепить осколочно соседние сосуды\"",184860,null],[184888,"2026-09-01T20:03:40",20,"/а стоп, почитала описание предмета - один заряд это по сути три стрелы, а не одна за один заряд \n/Сейчас описание немного подправлю",142532,null],[184975,"2026-09-01T20:29:09",9,"//Да по 3 их",142532,null],[185032,"2026-09-01T21:10:09",9,"//Меня сбили прибывшие кубы с игры, втянутьсь чуть позже)",142532,null],[185095,"2026-09-02T01:36:58",9,"Белобрысый ученый (Лазарь) — Теперь в него. — *Маг обошёл Рена, и положив руку на плечо слегка ращыернул его указав в сторону Сона что шел неся какие-то книги к хижине. Он не шутил и говорил атаковать другого ученика на полном серьёзе. Чтобы Сон успел среагировать — Лазарь его окликнул слегка повысив голос чтобы его услышали.* — Сон.\n\n*Сон сбавляет шаг поворачивая голову, среагировав на своё имя.*",184885,null],[185116,"2026-09-02T08:38:16",9,"// @dunchev нет никаких ещё заявок по пути?",184694,null],[185118,"2026-09-02T08:42:02",17,"— Не знаю, я видел саблезубых оленей они не выглядели ну... Намного больше или резвее обычных оленей. Но силка не хватило. Может тут хищник покрупнее?",184694,null],[185119,"2026-09-02T08:44:34",9,"Охотница на монстров (Имельда или Шельма) — Зубастые олени? — *Она поняла о чем речь и почему силок не выдержал.* — Он просто перегрыз твой силок. А хищник покрупнее есть везде, если ты его не видишь, о нём не знаешь — он есть. Смотри в остро, охотник.",185118,null],[185120,"2026-09-02T08:46:53",17,"— Ладно, да ты права, нужно будет подумать о силках из железных троссиков, так будет надежнее",142532,null],[185121,"2026-09-02T08:48:04",9,"//Я не зря описыаал их как зубастых хоть и мелких. Рил ток понял?",185120,null],[185122,"2026-09-02T08:48:34",17,"/ ДА уже неважно сейчас было и было",185121,null],[185123,"2026-09-02T08:49:17",17,"/ У всякого оленя есть зубы чтобы перетирать траву и листья, а саблезубые клыки по сути рудимент, если эти олени не хищники, саблезубые клыки только мешают",142532,null],[185125,"2026-09-02T08:49:31",9,"//Я для себя. Сам по невнимательности пропускаю описания мимо глаз",142532,null],[185128,"2026-09-02T08:49:57",9,"//Саблезубые олени есть в реальном мире при этом, я ими вдохновлялся)",185123,null],[185129,"2026-09-02T09:18:31",9,"Ветер шатает ветви тёмного леса.\nПо мертвым землям ты ходить привыкнешь.\nМеста где земли не коснётся луч солнца.\nОтравленная вода часто в колодцах.\nТак повезло найти богатое будущее.\nМногим не светит даже оно, многим оно даже не светит.\nВетер шатает ветви темного леса.\nСудьба человека мало кого колышет.\nЖизнь стоит так много, жизнь стоит так мало.\nНе теряй её, береги и лелей.\nСдаваться не смей, падать не смей.\n\n*Ведя, направляя по темной чаще. Люпен уже видит ту низину, все так кау прошлый раз, редкий туман, чем дальше не видно.*\n\n*Имельде не нравится ограниченный обзор, она бы сюда не полезла. Нотименно в таком опасном для неё месте и росли бяръозы.*\n\nОхотница на монстров (Имельда или Шельма) — Будешь шуметь, я сама тебя прирежу. — *Она ОЧЕНЬ напряженна, может это угроза, а может она боится, а может что-то знает, одними губами прелупреждает.*\n\n//Дальше 300 футов плохо видно из за тумана, штраф за 300 футов к проверке восприятия -5 ну а на 500+ вообще ничего не видно.",185120,null],[185150,"2026-09-02T09:40:02",9,"Охотница на монстров (Имельда или Шельма) — Показывай где. — *Шепчет она.*\n\n*К местам тем самым ещё примерно под мили, ноги уже несли в низину.*",185129,null],[185153,"2026-09-02T09:41:41",17,"Люпен шепчет\n\n— Да, техонечко идём, тут топкая земля, нужна ветка, чтоб прощупывать",185129,null],[185154,"2026-09-02T09:41:51",17,"/r +1 В поисках ветвки",142532,null],[185156,"2026-09-02T09:42:44",9,"*Что что, а ветви в лесу было найти легко.*\n\n//Щас опишу, найду ток",185155,null],[185164,"2026-09-02T09:46:50",9,"*По своим же следам, словно шаг в шаг, Люпен находит те же несколько Вялыэ Бяръозы, даже срезы что он оставил прошлый раз на месте, на болоте очень тихо, никого кроме вас, квакает и скрекочет ярко зелёный лягушонок.*\n\nОхотница на монстров (Имельда или Шельма) — Постой,смотри в оба, я выберу. — *Она идёт, но срезает не самые ровные ветви, а самые длинные, будто знает что-то.*",185155,null],[185169,"2026-09-02T09:53:49",9,"//Восприятие го, может чёт интересное увидишь)",142532,null],[185170,"2026-09-02T09:54:19",17,"/r +1 Восприятие",142532,null],[185172,"2026-09-02T09:56:05",9,"*В воде справа от тебя что-то есть, человеческая фигура?*",185171,null],[185176,"2026-09-02T09:56:43",17,"— Шельма, в воде человек!",142532,null],[185177,"2026-09-02T09:57:00",17,"— Стойма стоит!",142532,null],[185181,"2026-09-02T10:04:21",9,"Охотница на монстров (Имельда или Шельма) — Тшшшш! Не кричи. — *Она посмотрела на тебя так словно хотела убить. Бросила дело на пол пути и острожно идёт смотреть.*\n\n*Там, в воде, у самого верха словно лежит человек, как живой но не живой, словно только что утонул в трясине и застыл. На нем белый, без единой помарочки плащ, в руке золотой серп и кажется еще кольцо на пальце.*\n\nОхотница на монстров (Имельда или Шельма) — ... — *Она долго смотрела, подумав немного, не стала лезть.* — Делай что хочешь, но поглядывай за ним. И если еще раз закричишь, будешь рядышклм плавать, ясно?\n\n*Имельда добрых минут десять осматриыалась, не пришло ли на звук что-то после чего вернулась к своему делу.*\n\n//Что делает Люпен?",142532,null],[185184,"2026-09-02T10:16:21",17,"Люпен позарился на снаряжения этого мертвеца, он большой палкой начинает его подтаскивать ближе.\n\nПомня урон к повешеным мертвецом он приготовил веревку чтобы связать мертвецу руки и ноги как достанет",142532,null],[185186,"2026-09-02T10:18:00",9,"*Мертвец никак не реагирует, достать его было трудно, но как нить ты зацепил его за край штанины и вытащил из топи.*",142532,null],[185187,"2026-09-02T10:20:23",9,"*Это на вид мужик лет немного за сорок, сгустой, опрятной и ухоженнойбородой в которую вплетены деревянные кольца и прищепки. Он выглядит очень опрятно.*",142532,null],[185189,"2026-09-02T10:26:18",17,"Держась подальше от головы и рук Люпен вяжет ноги морским узлом",142532,null],[185206,"2026-09-02T11:10:21",9,"*Труп никак не реагирует. На ощупь он окоченевший и холодный, будто умер давным давно и тело застыло в таком положении.*",185189,null],[185214,"2026-09-02T11:23:48",17,"\"Чертовщина какая то\"\n\nСвязав ноги люпен обрезал веревку и связал еще и руки за спиной.\n\nпотом начал шарить по карманам мертвеца",142532,null],[185216,"2026-09-02T11:24:24",9,"//Атлетика сл 12 чтобы руки согнуть, они словно задеревнели",185214,null],[185228,"2026-09-02T11:27:46",17,"/r -1 Атлетично",142532,null],[185231,"2026-09-02T11:28:23",17,"\"Черт окоченевший какойто, ну ладно, вроде мертвый\"\n\nВоспользовавшись тем что не может загнуть руки люпен решает сперва стянуть белый плащ",142532,null],[185245,"2026-09-02T11:33:25",9,"*Плащ ломкий сильно, рверся и рассыпается в руках, под ним простая одёжка.*",185231,null],[185247,"2026-09-02T11:35:24",17,"\"А чего ж он такой нетронутый на вид, эх чертовщина\"\n\nПолез по карманам",142532,null],[185248,"2026-09-02T11:35:28",9,"*Серп крепко сжат в похолодевшей руке. На второй руке потертое медное кольцо с рунами, посеребрёное. На поясе кажется принадлежности травника, кошель.*",142532,null],[185249,"2026-09-02T11:35:48",9,"//Опиши что забираешь из этого, одежда и другие вещи не годится, истлели будто",142532,null],[185250,"2026-09-02T11:36:38",17,"Люпен забирает, все эти предметы, и кладёт в свой рюкзак",142532,null],[185253,"2026-09-02T11:38:47",9,"//Полученно:\n— \"Золотой ритуальный серп\" произведение искуства стоимостью 35 золотых.\n— Набор травника\n— В кошеле 4 золотых и 6 серебрянников\n— \"Кольцо с друидичесуими рунами\" ???",142532,null],[185254,"2026-09-02T11:41:23",9,"*Когда Люпен забрал эти вещи в рюкзак, он обнаружил что у мертвеца открылись глаза, они были закрытыми. Он начал усыхать, расчыпаться на глазах, словно гнил изнутри, в болото и вязь, секунды иянулись словнг минуты, так это выглядело жутко, плоть словно превращалась в ил, почерневшую воду, утекала в болото, оставался лишь почерневший скелет в запачканных остатках одежды.*",142532,null],[185259,"2026-09-02T11:43:26",17,"\"Жуть, наверное что то из его вещей, которые я забрал сохраняло его тело, проклятые побрякушки, куда я залез...\"",142532,null],[185260,"2026-09-02T11:44:12",17,"— Эм... Об этом мертвеце можно больше не беспокоится. Ну как? Для меня ветка под добрый лук осталась?",142532,null],[185267,"2026-09-02T11:56:12",9,"*Он подошла и взглянула уже когда мертвец разложился.*\n\nОхотница на монстров (Имельда или Шельма) — Храбрец или дурак. Его давно забрало болото, может он пролежал в нём несколько сотен лет. — *На ветку она лишь ухмыльнулась и перед собой выставила вязь из дюжины кривущих длинных ветвей что гнулись под собственным весом и текли. Улыбается.* — Это Вялыя Бяръоза, из неё луки не делают. Из неё луки варят, плетут и каптят.",185259,null],[185274,"2026-09-02T12:09:03",17,"— О как. Можешь показать как? \n\n\nЛюпен поднялся и протянул руки чтобы предложить тащить охапку самому\n\n— Мы назад? Или тут еще есть дела? Место жуткое",185267,null],[185275,"2026-09-02T12:12:04",9,"Охотница на монстров (Имельда или Шельма) — Свалим с болота в лес, мне не нравится это место, туман не дает осмотреться, и для костра нет ветвей. — *Она очень нервничает, постоянно оглядывается, привыкла всегда быть в движении и понимать свое окружение.*",185274,null],[185277,"2026-09-02T12:19:08",17,"— Согласен.\n\nВзвалив на спину ветви двинулся назад по своим следам к лесу из тумана\n\nОзираясь по сторонам в поисках возможных опасностей",142532,null],[185278,"2026-09-02T12:19:12",17,"/r +1 Смотрим",142532,null],[185302,"2026-09-02T12:32:12",9,"*Вы вышли из болот, сдедя за друг другом, по кочкак, к счастью опасности так и не встретив. Прилично отойдя от болот, где лес хоть немного пореже и можно осмотреться. Имельда достала котелок и щабрав палки у люпена стала их во всю длинну заправлять сгибая в котелок. Благо свежая бяръоза гнулась как верёвка.*\n\nОхотница на монстров (Имельда или Шельма) — Найди веток и разожги костёр.\n\n//Не над проверок, чисто отыгрыш",142532,null],[185385,"2026-09-02T14:55:41",20,"*Рен, слегка удивлённо приподнимает бровь, по потом принимает новое задание. Кажется время демонстрации того самого простого заклинания, которое может остановить стрелы?*\n\n*Он поднимает палочку, направляя ее на Сона - кажется с фактом применения магии против живых людей у него вообще сомнений нет.*\n\n*Но пока не активирует заклинание, жестом давая понять что ждёт, когда Сон будет готов отразить атаку*",185095,null],[185513,"2026-09-02T15:39:10",9,"*Сон чутка напрягся увидев что на него направленна палочка, а потом слегка нахмурился.*\n\nПарень, ученик Лазаря (Сон) — Учитель, я думал вы перестали использовать на мне тренировку внезапных волшебных стрел... — *Он кажется понял что происходит.*\n\nБелобрысый ученый (Лазарь) — Щит лучшее из защитных заклинаний, всегда должно быть подготовленным, быстрее показать как оно раьотает на практике. — *Он отпустил плечо Рена и не направлял больше, просто стоял со своим строическим лицом.* — Тогда ты продолжишь его урок, оставь книги на моём столе.\n\n*Поняв что урок пошел не по плану, Лазарь просто перестал его вести. Пока Сон пришёл упомянул лишь о нескольких основах.*\n\n*Он поднял свою руку и запястье как и все его тело словно покрылось вспышкой, плёнкой что стала невидима.*\n\nБелобрысый ученый (Лазарь) — Доспехи мага, работают долго и верно. — *Он взял нож и провел по ладони, раны небыло, тот словно прошёлся на милиметр от кожи не коснувшись её.* — Никто не скажет есть ли на тебе защита, лишь те кто видит магию. Применив усилие ранить мага все еще можно, но сложнее. В комбинации с простейшим барьером (щит) он лучшее решение для волшебника. Да, еще несколько магических стрел и палочка может сломатбся, так что с практикой пусть Сон одолжит тебе свою.\n\n*Лазарь больше ничего не сказал ушел обратно как Сон вышел с несколькими учебникам. Ученик провожал глазами учителя ко6да тот скрылся в хижине магов, лишь после сказал:*\n\nПарень, ученик Лазаря (Сон) — Учитель любит устраивать практические занятия... если он узнает что ты выучил щит начнет метать в тебя магические стрелы в самые неожиданные моменты. — *Он посмотрел на Рена и извиняющейся улыбнулся, извиняясь за Лазаря что уде ушёл:* — Прости, он всегда такой. Меня совсем не жалел.",185385,null],[185564,"2026-09-02T15:48:43",20,"*Рен слегка криво улыбается, вспоминая как его 'учили' в детстве. Пара внезапных магических стрел и лёгкие капризы учителя на самом деле не казались ему таким уж безжалостным подходом к обучению. Скорее наоборот*\n\n- Все в порядке. Уж лучше выучить защищаться так, чем на горьком опыте когда тебя действительно захотят убить, не правда ли?",185513,null],[185584,"2026-09-02T15:54:23",9,"Парень, ученик Лазаря (Сон) — Да, в этом есть своя правда. Может учитель нас бережот. Уитель слегка помешан на защитной магии. — *Согласившись Сон узнал что показывал и успел расказать учитель. После одолжил свою палочку чтобы наглядно показать как работает щит. А потом уже более лениво болтал о теории, хотя и была воды, не так чётко и по делу как учитель.*\n\n//По сути, заявки если есть",185564,null],[185586,"2026-09-02T15:57:43",20,"*Рен какое-то время потренировался ещё с волшебными стрелами, прежде чем снова решил поинтересоваться более теоретической частью*\n\n- Ты говорил что во время обучения попробовал множество заговоров, прежде чем сделать выбор. Как ты пробовал применять малую иллюзию? Какие у нее основные недостатки?\n\n/Есть у меня одна мысль насчёт нее...",185584,null],[185602,"2026-09-02T16:04:42",9,"Парень, ученик Лазаря (Сон) — Она имитирует звук или обьект, но совсем недвижима. Её могут распознать если почуют неладное или попытаются коснуться. — *Он вспомнил слова учителя.* — Глаавное, делать все так чтобы никто не усомнился в том что обьект или звук настоящий. У меня была та же шляпа что и у тебя чтобы попробовать все загоры. Но фокусы, как ты уже знаешь, мне понравились сильнее. — *Слегка улыбается вспоминая как учитель дулся.*",185586,null],[185623,"2026-09-02T16:13:52",20,"- Хм, совсем никак не получится ее перемещать или имитировать движение? *Рен слегка расстраивается, понимая что не получится хорошо имитировать живых существ.*\n\n*Хотя если поэкспериментировать...может получится найти возможность обмануть зрение даже без движения*\n\n*Он прикрывает глаза, решив кое-что испытать*",185602,null],[185624,"2026-09-02T16:14:08",20,"/r d20+2 малая иллюзия",142532,null],[185627,"2026-09-02T16:14:48",20,"/r +d20+3 обман на трюк со звуком телепатией",142532,null],[185635,"2026-09-02T16:17:05",20,"*Сон слышит за спиной какое-то шебуршение. Обернувшись...*\n\n*Котенок, маленький черный котенок лежит свернувшись клубочком. И очень громко мурчит*\n\n/Иллюзия без движения + обман с подражанием звука на то, что звук идёт от объекта",142532,null],[185649,"2026-09-02T16:18:27",9,"*Сон не видел этого кота, протянул руку и та прошла сквозь.*\n\nПарень, ученик Лазаря (Сон) — ... как ты сымитировал звук и изображение, одновременно?",142532,null],[185669,"2026-09-02T16:22:48",20,"*Рен улыбается, тоже рассматривая иллюзию котенка. Похоже очень доволен что трюк с совмещением видения и звука удался*\n\n- Оно и не издает звука, это был я сам. *Объясняет он.*\n\n- Как сейчас *Сон снова слышит в голове мурчание. Но на этот раз вполне различимо, что слышит он его именно в мыслях, а не от котенка*\n\n- это безобидный фокус, который я освоил - всегда хотел уметь дополнять его ещё и визуально",185649,null],[185685,"2026-09-02T16:28:11",20,"/блин, я только сейчас подумала что при должном извертывании можно через перспективу имитировать объекты на отделении. Тоже обман на то чтобы ракурс правильно подобрать",142532,null],[185687,"2026-09-02T16:28:54",20,"/надо начинать делать заметки в этой кампании - 101 способ наебать врага",142532,null],[185764,"2026-09-02T16:57:05",9,"Парень, ученик Лазаря (Сон) — Мне прийдется постараться чтобы не отставать от тебя. — *Он рассмеялся и напрягся, видно было как это стоило ему усилий, несколько минут он старался пока Рен у себя в мыслях не услышал отклик, лёгкий шипящий звук в голове, а глаза Сона едва заметно сверкнули золотистыми искорками. Поняв сто получилось Сон выдохнул и присел на крыльцо с отдышкой и слегка покраснев.* — Телепатия. Кровное наследство. Не настолько сильная, не умею ей пользоваться. — *Так немного посидев, подумал и показал большой палец с улыбкой.* — Очень хорошая идея сочитать это так. Может мне стояло больше уделять внимание таким вещам.",185669,null],[185774,"2026-09-02T17:15:58",20,"*Глаза Рена распахиваются от удивления, которое быстро переходит в что-то между взвешенной настороженностью(опять слова о кровном наследии и золотой цвет. Связь с проклятьем?) и...радостью?*\n\n- Ты... тоже можешь это делать? *Он садится на крыльцо рядом.*\n- Это здорово! Я никогда не думал что встречу человека, который владеет таким...или хотя бы понимает что это такое. Я и сам пока до конца не понимаю\n\n*Он задумчиво смотрит на Сона*\n- Не хочешь тренироваться вместе? У меня пока может и лучше получается, но ты знаешь об этом намного больше - совместим теорию и практику *с лёгкой улыбкой предлагает он*",185764,null],[185778,"2026-09-02T17:18:11",9,"Парень, ученик Лазаря (Сон) — Боюсь практики у тебя побольше будет. — *Он смущённо потер затылок.* — Я узнал что это телепатия только здесь, по книгам учителя, отец всегда умел разговаривать в уме не открывая уст. Как видишь это мне стояло всех усилий.",185774,null],[185779,"2026-09-02T17:21:21",20,"- Хм... странно, я не очень помню, как научился это делать *Рен задумчиво хмурится*\n- наверное это просто вышло само собой?\n\n- Думаю чем чаще мы стараемся это делать тем меньше усилий на это будет уходить. Как учится ходить",185778,null],[185782,"2026-09-02T17:25:07",9,"Парень, ученик Лазаря (Сон) — Может потому что мой отец слегка обезумел. Он еще разговаривает с картинами, наверное. — *Сон слегка замялся, не очень хотел говорить о семье.* — Думаю мы достаточно потренировались, я хотел узнать о заклинаниях второго круга, рано но интересно. Попробуешь почитать литературу без меня? Конечно помогу если будет что не понятно, всегда только рад помочь.",185779,null],[185783,"2026-09-02T17:30:00",20,"*Рен кивает, соглашаясь. Пока идёт читать книги, которые у него сейчас есть на столе*\n\n*Для начала азы - достаточно будет один раз пролистать чтобы запомнить. Потом нужно поискать что-то о той самой телепатии, про которую говорил Сон. Она была его надёжным орудием все это время, возможно есть способ пользоваться ей эффективней или развить ещё больше...*\n\n*Между делом бросает взгляд на картину(ну или чертеж, если нет картин)*\n\n-... *Прищуривается* - Я не буду разговаривать с тобой, отстань\n\n*Снова утыкается в книги*",185782,null],[185787,"2026-09-02T17:35:30",9,"//Ладно, ещё какие заявки есть?",185783,null],[185790,"2026-09-02T17:37:08",20,"//да наверное пока нет, учимся \n//Хотелось бы конечно найти инфу об иллюзиях и телепатии - может их можно как навык развивать типа золотых рук или писательства",185787,null],[185798,"2026-09-02T17:43:56",9,"// @dunchev остался ток ты, если они не придумают себе приключений на пятую точку)))",142532,null],[185803,"2026-09-02T17:44:59",9,"//Щас буду писать очень большое сообщение, наверное, эх",142532,null],[185810,"2026-09-02T17:46:07",17,"/ Ды я домой щас поеду",142532,null],[185811,"2026-09-02T17:46:20",17,"/ Хочу продолжить, но попозже, опишу пока Иллугу и погнал",142532,null],[185843,"2026-09-02T18:08:33",9,"*Пока Люпен набрал дров по её указанию. Имельда достала алхимические смеси что одолжила еще вчера и залила в котелок. Ветви бяръозы в ней разварились на волокна, известь и кислота, еще что-то. Достав плотные перчатки, она кинула такие же Люпену и у каждого был стальной гребень. Следующим шагом было потушить отвар каким-то белым порошком, тот вскипел и успокоился. Слегка подостыв, Имельда начала доставать длинные древесные волокна, как лапша.*\n\nОхотница на монстров (Имельда или Шельма) — Гребнем повторяй за мной. Нам нужно побольше волокон, разравнивай их тщательно, если не успем хватит лишь на один лук, и он будет только мой. — *Она начала расчесывать белые как молоко волокна дерева, подвешивая их стечь на ветки деревьев.*\n\n*Когда в котле не осталось больши длинных волокон, она выкинула длинные и мелочь, то что порвалось, взяла черпак и слегка намочила варевом что вышло чтобы не иссохло пока вы будете плести. Поставив банки с маслом облила их и им, и взяв нити 6ачала плести.*\n\nОхотница на монстров (Имельда или Шельма) — Главное не пытайся за мной успеть, делай качественно, словно плетёшь веревку, где тоньше, где толще я скажу.\n\n*Имельда плела белесую неравномерную верёвку разными видами плетения, эдакое макраме но каждый этап был не таким как прошлые, одни части в будущем должны были сгибалься сильнее, другие почти не гнутся, а середины плечей даже растягиваться немного и быть пустотелыми.*\n\n*Имельда всё время отходила чтобы сделать оббежку по окрестностям, в поисках угроз, оставляя Люпена плести свой лук и следить чтобы не иссохлись ветви, поэтому он поспевал за ней. Тлели угли когда начинало темнеть, Люпен доплетал свою почти двухметровую верёвку и Имельда доделала правильно обрезав лишнее чтобы не расплёлся.*\n\n*После все это кинули в кипящий животный жир на пол часа. Немногт уставшая но довольная Имельда сидела и следила за костром. Да и ветвей она наносила хорошо с разведки, на ночь хватит.*\n\nОхотница на монстров (Имельда или Шельма) — Мне как сплести лук расказал один старый охотник. У него был такой, но лук боится воды, поэтому надо постоянно следить смазывая его жиром и маслом, однажды я не уследила. — *Задумчиво и цстало она произнесла, немного молчала, жевала вяленное мясо.* — Однажды лук что остался от него иссохся и сломался, это не магия, это искусство, зачарованные лукт все еще остаются такими какими их сделали мастера, не ложаться в руку идеально, нельзя натянуть и отпустить тятиву так легко, стрелы не летят так ровно.",185811,null],[186416,"2026-09-02T21:03:45",17,"Люпен повторял и учился. Он старательно пытался запомнить каждое движение. Совершал ошибки, естественно. Но упорно исправлял их. \n\nСперва гребнем создавая волокна, потом размачивал их. \n\n— Никогда бы не подумал, что Луки плетут. Мне отец завещал свой и всегда говорил, \"Орешник ищи и будет тебе добрый лук\"\n\nШельма дала ему поспевать и поправляла там, где он косячил. Люпен был ей за это благодарен но озвучивать не стал. Шельма не любит зти всякие нежности, как он понял. Все понятно без слов. Когда видно как ученик старается.\n\n— Шельма. Расскажи что нибудь у ядах, чем из подручных трав или может быть ядов ползучих змей лучше смазывать острие стрел? Я знаю про паслён и с гадюки суедить могу, но как закрепить смесь на острие, какая доза. В этом я не смыслю",142532,null],[186784,"2026-09-02T22:44:12",9,"Охотница на монстров (Имельда или Шельма) — Я тоже. — *Она усмехнулась, слишклм Люпен её переоценивал. Она делала многое, но не знала всё.* — Всегда трясла алхимиков. Растворы на то, на это, рецепты, мне редко отказывали. А там уже знаешь как — делаешь. Яд без алхимии или на травах долго не живёт.",142532,null],[186795,"2026-09-02T22:47:13",17,"— Хорошо, что есть всегда куда стремиться. Теперь вот хочу найти и научится у алхимика яд варить убойный.",142532,null],[186802,"2026-09-02T22:47:57",17,"— А тетиву обычную ставить будем или тоже какая нибудь хитрая?",142532,null],[186809,"2026-09-02T22:48:29",9,"Охотница на монстров (Имельда или Шельма) — Здесь из алхимиклв только старый дед, и тот не в себе. Камни варит.",186795,null],[186827,"2026-09-02T22:51:04",17,"— Я в Веспираль хочу пойти. Была там?",142532,null],[186858,"2026-09-02T22:56:39",9,"Охотница на монстров (Имельда или Шельма) — Сгодится из сухожилия, хитрых не знаю. — *Она махнула на тебя и посмотрела на сплетённые вами веревки.* — Пора доставать.\n\n*Вынимает их и достаёт свой лук, протно верёвочками эти две верёвки привязывает их к дуге своего лука без тятивы.*\n\nОхотница на монстров (Имельда или Шельма) — Не советую. Это город мертвых. Тебя укусит крыса и умрешь через неделю, проказа и чума. Не считая мертвых. — *Она подвешивает луки над состром и заливает костёр оставшиеся смеси и жир капча будущие дуги, чтобы те слегка подсохли приняв форму, внимательно следит чтобы не пересушить.* — Если не хочешь чтобы тобой пообедал случайный упырь, будучи в Веспирали держись основных оживленных улиц. Улиц по которым не ходят Темные спасители в багровых мантиях.",186802,null],[186923,"2026-09-02T23:12:33",17,"— А кто такие эти спасители?\n\nЛюпен представил себе город как кладбище где между могил ходят багровые мантии, а чуть уйдешь с дороги зомби, вампиры, призраки и прочая нечисть схватит и утащит во тьму\n\n— Говорят там есть воровская картель. Не слышала?",142532,null],[186943,"2026-09-02T23:17:03",9,"Охотница на монстров (Имельда или Шельма) — Раздолье для бандитов. Картель и не одна. — *Она перевернула заготовки другой стороной, те начали уже распрямляться, нужно чтобы равномерно. Белесые волокна почернели в саже и густом дыму.* — На улицах не только возможности, ещё и беззаконие и смерть. Голодные рты опухших от голода людей, они поднимут нож и воткнут в спину за хлеб, лишь бы представился шанс дожить до завтра. Не везде так плохо, оживленные улицы называют верхним городом, но больше всего людей гниют в остальных местах.",186923,null],[186973,"2026-09-02T23:21:36",9,"*После небольшой паузы добавила:*\n\nОхотница на монстров (Имельда или Шельма) — Спасители это безумцы, когда с ними говоришь кружится и болит голова.",142532,null],[187898,"2026-09-03T19:31:31",17,"— Вот как... Я думал место чуть более цивилизованное. \n\nА куда же тут ещё можно  податься?",142532,null],[187911,"2026-09-03T19:36:30",9,"Охотница на монстров (Имельда или Шельма) — Наёмники, держись их. Они станут опорой если ты не убийца или головорез. — *Она слегка усмехнулась.* — Мне стали.\n\n*Она снимает луки и смазывает их еще слоем жира и алхимии.*\n\nОхотница на монстров (Имельда или Шельма) — Почти готовы. Надо ещё извалять в золе а потом промыть в воде. Пусть полежат. — *Она ещё не отвязывал их от своей дуги лука чтобы форма закрепилась.* — Будут хорошие луки. Вялая бяръоза почти нигде не растёт, только в Вальдхейме её можно нати.",142532,null],[187915,"2026-09-03T19:39:09",17,"— Да. Я запомню этот день. \n\nЛюпен сел на травку и задумался\n\n— После этой обработки лук воды бояться не будет?",142532,null],[187920,"2026-09-03T19:40:29",9,"Охотница на монстров (Имельда или Шельма) — Будет, поэтому его надо обрабатывать жиром и маслом. Я покажу.",142532,null],[187921,"2026-09-03T19:40:44",9,"//Настоящие луки вообще дождя боятся, смирись)\n//Хртя скорее тятива, её прятали при дожде под стрелецкой шапкой",142532,null],[187957,"2026-09-03T19:49:50",17,"— Добро. Тогда пойду соберу хвороста ещё, чтоб золы побольше было \n\nЛюпен встал и повернулся на Шельму",142532,null],[187959,"2026-09-03T19:51:09",9,"Охотница на монстров (Имельда или Шельма) — Не ходи далеко, ночь в этих местах опасна.",187957,null],[187965,"2026-09-03T19:52:25",17,"Он кивнул и пошел искать хворост и приключений себе на задницу",142532,null],[188055,"2026-09-03T20:16:50",9,"*Остаток дня прошёл легко, не считая того что Люпена испугала внезапно слетевшая с ветки сова пока он искал хворост. Имельда оставила луки в золе на ночь и достала сети, она их подвесила на ветвях деревьев сделав таким образом гамаки, в них вы и спали.*\n\n*Утром собравшись на всех порах дошли до реки, на камнях где были припрятанны снасти сидел бородатый мужик напоминающий викинга и ловил рыбу, похоже от самый борода.*\n\nОхотница на монстров (Имельда или Шельма) — Иди в лагерь, я быстро умою дуги и прийду следом.",142532,null],[188200,"2026-09-03T21:00:46",17,"Люпен подумал тогда\n\n\"Надо бы с собой сетку тоже искать. Весит меньше чем спальник и без насекомых\"",142532,null],[188202,"2026-09-03T21:01:11",17,"— Ладно, если помощь не нужна, я потопал.",188055,null],[188205,"2026-09-03T21:01:29",17,"Кивнул и пошел в лагерь\n\nИскоса глядя на мужика боковым зрением",142532,null],[188250,"2026-09-03T21:12:25",9,"*Борода увлеченно занимался рыбалкой этим ранним утром. Наверное если бы свиснули его снасти то он реально был бы зол.*\n\n*Топая к лагерю люпен видит знакомых, это те бандюганы, Язык и Коршун.*\n\nТот самый Язык — О иди сюда. — *Он улыбнулся и подозвал к себе.* — Как устроился в лагерес вижу дела идут.\n\n*Он смотрит что Люпен со снаряжением, уже получше собран.*",188205,null],[188268,"2026-09-03T21:14:21",17,"Люпен оглядывается вокруг по привычке\n\n— Напросился вот в охотники. Что то нужно? Помочь?",188250,null],[188280,"2026-09-03T21:17:14",9,"Тот самый Язык — Да. Мы не договорили пртшлый раз, у нас дела свои были. — *Кивает на Коршуна и прищуривает глаза.* — Будешь платить на половину жалования за защиту когда деньжатами присыпет. Братки тебе помогут если в беду встрянешь, не переживай.\n\n*Все же, рн возвращается к той теме что хочет с Люпена регулярно сбивать деньги ни за что.*",188268,null],[188288,"2026-09-03T21:19:13",17,"— А кто тут наехать может?",188280,null],[188297,"2026-09-03T21:21:05",17,"— Или в каком всмысле \"в беду встряну?\"",142532,null],[188326,"2026-09-03T21:27:19",9,"Тот самый Язык — Ну знаешь. — *Он потянулся к кинджалу на поясе и его рука замерла, словно молния Шельма оказалась рядоми уже держала клинок у его горла. Она быстро закончила и нагнала Люпена, все для неё были медлительны.* — Кхм...\n\n*Язык тут же заткнулся почувствовав металл на шее, Коршун хотел уже среагировать, но зассал и поэтому стал боком готовый смотаться в любой момент. Имельду боялись.*\n\nОхотница на монстров (Имельда или Шельма) — Ты слишком наглый, отжимать у других то что они честно заработали. Может стоит срезать пару пальцев с твоих жадных ручёнок, или... острый язык. — *Она угрожала языку.*\n\nТот самый Язык — Н-нет... мы просто болтали... да, Люпен? — *Он стал бдедный как бумага.*",142532,null],[188339,"2026-09-03T21:32:43",17,"— Шельма, да мы... Болтали просто. Спасибо конечно, но переживать не о чем.",142532,null],[188367,"2026-09-03T21:38:20",9,"Охотница на монстров (Имельда или Шельма) — Свали язык. — *Она отпустила бандита и он извиняясь и говоря \"спасибо, спасибо\" посеменил отсюда побыстрому.* — Нельзя давать им спуску. — *Чуть ли не прошипела имельда, похоже именно этих наёмников она недолюбливала.*",142532,null],[188396,"2026-09-03T21:44:21",17,"Когда они отошли Люпен ответил\n\n— Хотел из них вытащить немножко больше сплетен и знаний всяких. Я ж тут новенький. Надо знать кто есть кто. А с меня что взять, пустой как и был",188367,null],[188412,"2026-09-03T21:48:50",9,"Охотница на монстров (Имельда или Шельма) — Что надо свои раскажут. Язык только треплится. — *Она кинула Люпену кибить, дугу лука, белоснежную и красивую, но масноватую.* — Почти готов, полежит несколько дней, закрепнет и можно пробовать. Пошли.\n\n*Она немного расслабиоась, в своих руках она несла такую же дугу, даже чуть чуть длиннее чем у Люпена.*\n\nОхотница на монстров (Имельда или Шельма) — Береги этот лук, чтобы не иссохся как мой прошлый. Такие когда-то плели только ушастые феи.",142532,null],[188424,"2026-09-03T21:51:08",17,"— О как. Жир особый нужен и масло? Чтобы в порядке держать",142532,null],[188425,"2026-09-03T21:51:33",17,"— Красиво вышло. Прямо  шикарно",142532,null],[188429,"2026-09-03T21:52:53",9,"//Я когда то оч давно генерил арт чего то похожего, но походе удалил его, сорян. Сам решишь как он выглядит",142532,null],[188433,"2026-09-03T21:53:23",9,"Охотница на монстров (Имельда или Шельма) — Я покажу. Времени предостаточно.",142532,null],[188440,"2026-09-03T21:54:45",9,"//А теперь сейчас будут концовки если ни у кого ничего особо не осталось, вы сбежали и нашли своё место где пересидеть и кем здесь быть.",142532,null],[188447,"2026-09-03T21:57:02",17,"/ Да, Хард. Спасибо за квест.",142532,null],[188448,"2026-09-03T21:57:17",17,"/ Интересно было",142532,null],[188453,"2026-09-03T21:59:23",9,"@QURTZZ \n\n*Шла вторая неделя тренировок с новичками. Борода скинул на конрада самых что ни на есть проблемных молодых людей, но их спесь была и упорством что двигала их далее.*\n\n*Этим вечером к Конраду пришёл тот полурослик что был под жанкой.*\n\nПолурослик (кларк) — Это твоё. — *Он выложил родовое кольцо которое принадлежало Конраду, и собрался цходить, но перед этим кинул с небольшой усмешкой.* — Я всё знаю.\n\n*Ушёл. Если Конрад спрашивал у бороды на счет этого случая, Кларк параноик и не терпит убийц в стане наемников. Одно дело по делу, а другое. Его смутили награды за ваши головы.*",142532,null],[188466,"2026-09-03T22:06:36",9,"@PaIIasCat \n\n*Обучение шло своим чредом, Сон помогал разобраться с вопросами. Лика баловала мамиными разработками, чертежами, даже удавалось несколько раз пересечься с самой изобретательницей, но поговорить с ней не выходило, она очень часто сорилась с Лазарем по любой мелочи. Лазарь будто игнорировал Гретту, а той не нравилось что он её игнорировал или не понимал. По секрету Лика расказала Рену что маме нравится Лазарь, и так как любовь морьковь у них не клеется Грета очень на него злится.*\n\n*Экспериментируя с заклинаниями у Рена начали получатся первая волшебная стрела, другие заговоры и заклинания. Однажды утром учитель оторвал того от завтрака словами:*\n\nБелобрысый ученый (Лазарь) — Ты уже неплохо освоил основы, сегодня тебе предстоит призвать фамильяра. Я прослежу чтобы все прошло гладко.\n\n*Если не вдаваться в подробности, все пошло не гладко, и вам пришлось убить несколько выскочевших бесов. После оказалось что учитель так наглядно показывал что бывает если не точно работаешь со своими призывами.*",142532,null],[188521,"2026-09-03T22:14:49",20,"/как же мне нравятся мелкие детали с динамикой нпс в этом квесте",188466,null],[188525,"2026-09-03T22:17:01",9,"@dunchev \n\n*Люпен справлялся с охотничьей жизнью. Удалось поработать с разными охотниками и помимо Имельды, тот же ленивый Паскаль о котором говорили. Лук сделанный из Вялыя Бяръозы был выше всяких похвал и без капли магии.*\n\n*Ожнажды удалось поохотится с Димоном, в той охоте Люпен видел наглядно как здоровяк свернул голову медведю голыми руками. Ещё под разорванной одеждой увидел его тело изощренное рцнами. Димон увидел взгляд Люпена и указав на них произнёс: \"Акак Дакан Пол Мукар Сенсорри\", Был в своем настроении так сказать.*\n\n*Как то Люпен возвращался из охоты неся на плечах вепря которого убил уже сам. Его встретила по пути Имельда и хмыкнула: \"на этот раз ты справился сам, охотник\", последнее слово она говорила уже без сарказма.*",142532,null],[188528,"2026-09-03T22:18:32",9,"//Награды раздам чуть позже и скажу план действий, а так квест закончен, я сам напишу отзыв от себя, а потом уже вы, мне не надо стены текста, просто то что вам реально хочется сказать",142532,null]]);
